// 每集摘要（AI 依文字稿整理）：s = 摘要，p = 重點，k = 主題標籤
window.SUMMARIES = {"6094-a26_001":{"s":"本集為單元開場，說明依平實導師《法華經講義》以「演義」而非科判方式解說佛「開示悟入」佛知見，指佛知見以第八識如來藏為中心。並釋經名「妙法」即如來藏，介紹其第一種微妙法性「能生」：十八界皆由如來藏藉緣出生。","p":["佛知見以第八識如來藏為中心而說","引《中阿含》說明明解脫始於親近善知識","《法華經》顯示諸佛真實本質，勿當神話看","經名「妙法」即指如來藏心","如來藏能生：意根、五根、六塵、六識皆由其生"],"k":["如來藏","妙法","能生","開示悟入","八識論","善知識"]},"6106-a26_002":{"s":"本集續說如來藏「能生」之性：十八界具足成人，萬法種子含藏於如來藏，器世間亦由共業有情的如來藏共同成就。並依《中論》破斥一神教造物主屬「他生」、以根塵和合生六識屬「共生」的見解，強調萬法以如來藏為根本因、藉緣而生。","p":["具足十八界方為完整欲界有情","盲人復明：見色功能本在如來藏中","器世間由共業有情如來藏共同成就","造物主之說屬「他生」邪見","根塵和合生六識屬「共生」邪見"],"k":["如來藏","能生","十八界","器世間","共業","中論四句"]},"6109-a26_003":{"s":"本集講如來藏第二種妙性「金剛性」：本來不可壞，非修行而成，十方諸佛合力亦不能壞任一有情之如來藏。以虛空、鏡像為喻，並批評印順無因共生之說、琅琊閣疑見與見取見，以及密宗自稱金剛乘，指只有證如來藏者方得金剛三昧。","p":["如來藏不可壞，如虛空而能生萬法","所生之法不能反壞能生之如來藏","金剛性本來如是，非修而得","證如來藏並轉依者方是金剛三昧","批評密宗自稱金剛乘、雙身法之說"],"k":["金剛性","如來藏","金剛三昧","見取見","聖教量","破邪顯正"]},"6096-a26_004":{"s":"本集續說金剛性，闡釋「聖教量」與「法界現量／定量」：如來藏不可壞是法界中不可改變的事實，故佛法不許有創見。以空相與空性辨正，並以「第八識何時生、何時滅」反詰主張阿賴耶識生滅者，批評印順「大乘非佛說」等創見如盲人摸象。","p":["違背聖教量即違背法界現量","空相指緣起蘊處界，空性指如來藏","法界定量不可改，佛法不許創見","問阿賴耶生滅者：第八識何時生滅","所生之法不能壞能生者，故稱妙法"],"k":["金剛性","法界現量","聖教量","創見","空性","阿賴耶識"]},"6107-a26_005":{"s":"本集講如來藏第三種妙性「本來性」：法爾而有，諸佛宿住隨念智亦推究不出其出生時。依「有生必滅」說明本來不生故不滅，引六祖「將滅止生非佛菩提」辨二乘與佛菩提之別，並以一境四見說明相分由第八識變現，指如來藏是「唯我獨尊」的無二妙法。","p":["如來藏法爾而有，無出生之時","批評「地獄是聖人施設」之說","一境四見：相分由各自第八識變現","二乘將滅止生，佛菩提本來不生","妙法無二，即「唯我獨尊」"],"k":["本來性","如來藏","不生不滅","將滅止生","四種涅槃","唯我獨尊"]},"6115-a26_006":{"s":"本集開講〈序品〉，說明序品記錄結集因緣，逐句解釋「如是我聞」「一時」「王舍城耆闍崛山」及萬二千阿羅漢等法眾。重點闡述比丘四義與阿羅漢斷漏，並舉阿支羅迦葉為例，說明證果者不論在家出家皆為佛所認可的沙門。","p":["「如是我聞」為佛臨終交代，證經可信","用「一時」避免紀年紛爭","沙門以證果論，非以出家相論","比丘四義：乞士、破煩惱、淨持戒、怖魔","四果次第斷見惑思惑而證阿羅漢"],"k":["序品","如是我聞","比丘","沙門","阿羅漢","四沙門果"]},"6121-a26_007":{"s":"本集續講〈序品〉，解釋經文形容阿羅漢「諸漏已盡…心得自在」之義。詳述聲聞以四聖諦、四念處、八正道斷三縛結至五上分結的四果次第，以及緣覺觀十因緣「齊識而還」、十二因緣的觀行，並指二乘未斷習氣與所知障，實未證涅槃，只是佛方便說。","p":["聲聞依四聖諦斷見思惑而入無餘涅槃","三苦八苦與苦集滅道四聖諦","初果至四果所斷結使與證境","緣覺觀十因緣齊識而還、十二因緣可滅","二乘以慧入涅槃，實無人證涅槃"],"k":["阿羅漢","四聖諦","十二因緣","三縛結","無餘涅槃","二乘菩提"]},"6120-a26_008":{"s":"本集續講〈序品〉列名的大阿羅漢，介紹阿若憍陳如因三轉四聖諦法輪最先證阿羅漢、舍利弗與目犍連隨馬勝比丘因緣出家。以鴿入佛影與舍利弗影之事說明阿羅漢習氣未盡、神通有限，並述目犍連救母、度量佛音聲、償宿債，以及迦旃延論議第一，兼及各人受記作佛名號。","p":["憍陳如聞三轉法輪最先證阿羅漢","鴿影故事：阿羅漢習氣未斷、神通有限","目犍連救母為盂蘭盆會由來","目犍連被打而亡：神通敵不過業力","迦旃延以少年法、老年法折服梵志"],"k":["序品","大阿羅漢","舍利弗","目犍連","授記","業力"]},"6134-a26_009":{"s":"本集續介紹〈序品〉中的四位大阿羅漢：阿那律因施辟支佛得無貧，佛為其穿針說明福德為成佛資糧；富樓那答佛之問展現忍辱與為法捨身之志；須菩提因瞋習而成佛最晚，告誡菩薩忌犯瞋；阿難請佛度大愛道出家而有八敬法，並因摩登伽女成為《楞嚴經》緣起。","p":["阿那律失明得天眼，佛示福力最勝","六度前五度培植福德，福不足易退轉","富樓那善修忍辱，願為正法捨身","須菩提瞋習重，成佛最晚，菩薩忌瞋","阿難請度大愛道，比丘尼依八敬法"],"k":["福德","忍辱","瞋習","八敬法","大阿羅漢","授記"]},"6126-a26_010":{"s":"本集講難陀因往昔供養獨覺得三十相，以及佛引其見天宮與地獄而證阿羅漢；接著講經文中八萬菩薩摩訶薩的功德，解釋陀羅尼即總持，並以正覺總持咒為例。再介紹文殊、觀世音為古佛示現，彌勒菩薩當來下生與龍華三會，並以德光論師為例說明我慢障道。","p":["福德應迴向佛道，勿求生天享樂","難陀見天宮與地獄後精進證果","陀羅尼即將法義貫串成偈的總持","文殊、觀音皆為古佛倒駕慈航示現","德光論師我慢不禮彌勒而錯失證果"],"k":["序品","菩薩摩訶薩","陀羅尼","文殊師利菩薩","觀世音菩薩","彌勒菩薩"]},"6118-a26_011":{"s":"本集講〈序品〉中前來法華勝會的天眾，說明諸天與他方菩薩也是此經的證人，並批評印順「佛教只在人間」之說自相矛盾。依序介紹釋提桓因與忉利天三十三天、四大天王六齋日巡察、化樂天與他化自在天、初禪至四禪各天的天主與天眾，並說明無想天依定而無意識、福盡下墮，不值得羨慕。","p":["天人與他方菩薩同為法華經證人","批評「佛教只在人間」的說法","釋提桓因即道教玉皇大帝，護持佛法","化樂天與他化自在天名稱的由來","無想天無意識，福盡易墮畜生"],"k":["序品","天眾","釋提桓因","四大天王","色界四禪","無想天"]},"6136-a26_012":{"s":"本集續介紹法華會上的天龍八部：釋尸棄大梵、光明大梵等色界天王；八大龍王各自名義與典故，如難陀、跋難陀與目犍連鬥法後成歡喜龍王，以及龍化人身的五種限制。並解說四緊那羅王分唱四聖諦、因緣法、六度與三乘總持，四乾闥婆王掌管樂與絃樂，以及婆稚阿修羅王戰敗的故事。","p":["尸棄大梵為二禪天王，光明大梵為三禪天王","八大龍王名義，難陀二龍改名歡喜龍王","龍化人身有五種時節不能保持","四緊那羅王以歌唱誦三乘法義","乾闥婆奏樂；婆稚阿修羅王被般若咒降伏"],"k":["序品","天龍八部","八大龍王","緊那羅","乾闥婆","阿修羅"]},"6150-a26_013":{"s":"本集續介紹法華會眾：毘摩質多羅等阿修羅王因舍脂之事與釋提桓因交戰後和好，一同聽法；四迦樓羅王（金翅鳥）的成因、卵胎濕化四生與食龍的限制。接著以阿闍世王為人證，敘述其受提婆達多唆使弒父、囚母，韋提希因此請佛而有《觀經》，以及阿闍世後來懺悔歸佛、得無根信的經過。","p":["阿修羅王與帝釋恩怨，法會中仍同聽法","大布施卻懷瞋慢，死後生為金翅鳥","金翅鳥與龍皆有四生，各有食與不食之限","阿闍世弒父囚母，韋提希請佛說《觀經》","阿闍世懺悔得無根信，免墮地獄"],"k":["序品","阿修羅","迦樓羅","阿闍世王","韋提希","觀無量壽佛經"]},"6152-a26_014":{"s":"本集講世尊說法華前的安排：佛先為菩薩說《無量義經》，闡明一法（如來藏）含攝無量義，說畢入無量義處三昧，天雨四華、六種震動。說明《無量義經》為《法華經》序經，並解釋五時三教、頓教與圓教之義，指法華將一切法收歸如來藏而「收圓」，最後講佛放眉間白毫光照東方萬八千世界。","p":["《無量義經》說一法即如來藏攝無量義","入無量義處三昧，天雨四華、六種震動","《無量義經》是《法華經》的序經","五時三教：權教、實教、圓教","華嚴頓教先說，法華圓教收圓"],"k":["無量義經","圓教","五時三教","如來藏","白毫相光","序品"]},"6145-a26_015":{"s":"本集續講佛眉間白毫光照東方萬八千世界，上至色究竟天、下至阿鼻地獄，使大眾見他方六道、諸佛說法與菩薩修行，目的在令眾生對十方三世佛教生起信心，並勸以宏觀調伏我慢。接著講彌勒菩薩代大眾起疑，請問文殊師利放光因緣，說明大菩薩配合佛「演戲」作開場，並語譯彌勒問偈前段。","p":["思量自身在萬八千世界中的渺小可伏慢心","放光令見他方六道、諸佛與菩薩","目的在令眾生對十方佛教起信","法華難信，須由大菩薩先問答作序曲","彌勒問文殊：三乘隨根說法、布施迴向佛道"],"k":["白毫相光","序品","彌勒菩薩","文殊師利菩薩","十方佛土","信心"]},"6146-a26_016":{"s":"本集解說彌勒偈頌所見東方佛土菩薩的種種行門：布施寶車、身肉手足乃至頭目，捨王位出家，獨處誦經、入山思惟佛道，離欲修定得五神通。引《大乘本生心地觀經》等說明求無上道須以布施修福為基礎，並強調神通須先離欲，以五通仙人起欲失通為例，批評密宗祖師神通之說。","p":["布施內外財、頭目身體以求佛智慧","不修福德只求證道是妄想","等覺菩薩捨身命修相好福德","菩薩形形色色，不可一概而論","神通須禪定兼離欲，起欲即失通"],"k":["布施波羅蜜","福德","五神通","離欲","禪定","菩薩行"]},"6148-a26_017":{"s":"本集續說偈文：神通須離欲深修禪定，批評喇嘛雙身法不可能得神通；「以千萬偈讚諸法王」，以提婆達多稱「南無」而在地獄得樂為例說明讚佛功德。並解說「智深志固」須見道勝解，「定慧具足」能以無量喻說法，及入地方為能荷擔如來家業的真佛子，警示瞋火與邪見燒功德林。","p":["密宗雙身法無離欲前提，不可能得神通","偈頌讚佛乃至一稱南無皆有功德","瞋火與謗法邪見會燒毀功德林","定慧具足能以無量譬喻為眾說法","入地菩薩方為能荷擔家業的真佛子"],"k":["讚佛功德","定慧具足","佛子","提婆達多","功德林","說法"]},"6147-a26_018":{"s":"本集解說「破魔兵眾，而擊法鼓」，以正覺破斥密宗雙身法為例，說明被罵愈甚表示破邪愈有成效，不顧面子才能擊法鼓。續講菩薩寂然宴默不喜天龍恭敬、林中放光濟地獄苦、經行不眠求道、持戒威儀如寶珠，以及安住忍辱力面對增上慢人辱罵，並語譯下一段布施佛僧的經文。","p":["擊法鼓以正法令眾生我見邪見死去","顧面子即落五陰我所，未斷我見","天龍恭敬不以為喜，放光濟地獄苦","持戒威儀清淨如寶珠以求佛道","弘了義法必遭增上慢人罵，應安忍"],"k":["破魔兵眾","擊法鼓","忍辱","持戒","增上慢","破邪顯正"]},"6160-a26_019":{"s":"本集講「離諸戲笑及癡眷屬，親近智者」：批評只講人天善法或以意識離念靈知為真如屬戲論與癡眷屬，並分說聲聞、緣覺、佛菩提三種智者的教導，強調福慧雙修。續解布施飲食湯藥、衣服、精舍、園林供養佛僧，以及菩薩「說寂滅法」，指菩薩須兼住持二乘菩提，先斷我見再修大乘。","p":["離戲論與癡眷屬，親近智者極重要","以離念靈知為真如即愚癡","三乘智者各教現觀十八界、因緣法、如來藏","以飲食、衣、舍、園林供佛僧集福德","菩薩須兼說二乘寂滅法，先斷我見"],"k":["親近善知識","戲論","離念靈知","福慧雙修","寂滅法","二乘菩提"]},"6162-a26_020":{"s":"本集講「觀諸法性，無有二相，猶如虛空」為諸法攝歸如來藏的實相一相，並以魔波旬化牛擾亂說明心無所著。續解佛滅後供養碎身舍利、造塔廟莊嚴國界，及彌勒請文殊決疑「為說妙法或為授記」。指出放光所示他方菩薩各階修行，即顯釋迦因地所歷，成佛須多世修行。","p":["諸法攝歸如來藏，實相一相如虛空","心無所著以妙慧求無上道，魔擾不住","諸佛多留碎身舍利，便於眾生種福","塔與廟的區別及寺名由來","他方菩薩各階修行即顯佛因地歷程"],"k":["實相","如來藏","舍利","塔廟","彌勒菩薩","文殊師利菩薩"]},"6166-a26_021":{"s":"本集講解〈序品〉中文殊菩薩回答彌勒之問：佛放光後將說大法，並舉過去日月燈明如來為例。先說明故意曲解佛語即成謗法、破法、謗佛三種因果，再逐一解釋佛十號中的應供、正遍知、明行足、善逝、世間解，並對比阿羅漢與佛的差別。","p":["文殊答彌勒：佛現瑞光即將演說大法","曲解佛法而稱佛說，即成謗法、破法、謗佛","應供、正遍知：佛具足世出世間法之知","明行足：阿羅漢三明有限，佛能授記無限劫","善逝、世間解：佛示現受生入滅，遍知世間成因"],"k":["如來十號","日月燈明佛","明行足","謗佛","授記","序品"]},"6165-a26_022":{"s":"本集續講佛十號中的無上士、調御丈夫、天人師、佛、世尊。說明佛以軟語、如實語、雜語、時語及大威德力調御眾生；天人師須度化天人天主；佛即覺者，三寶本質歸於佛；世尊則超越生天、解脫天與第一義天，為三界中最尊。","p":["無上士：佛於諸法門善巧無人能超越","調御丈夫具軟語、如實語、雜語、時語四種語","威德力來自智慧與三大阿僧祇劫福德","天人師須度天人，批評自稱菩薩化身的密宗行者","世尊超越解脫天、第一義天，為三界中尊"],"k":["如來十號","調御丈夫","天人師","第一義天","三寶","增上慢"]},"6168-a26_023":{"s":"本集講解日月燈明如來說法「初善、中善、後善，其義深遠，純一無雜」，指出諸佛所說皆不離如來藏妙義，並批評堆砌名相、無法實證的說法屬像法、末法現象。接著解釋「為求聲聞者說應四諦法」的「應」字，即須先修施論、戒論、生天之論等次法，再說四聖諦而證初果。","p":["諸佛說法初中後善，不會龍頭蛇尾","以堆砌名相為像法、末法之說，批評《妙雲集》","純一無雜：三世諸佛所說皆演如來藏","具足清白梵行，批評雙身法非梵行","應四諦法：先說施戒生天次法，再說四聖諦"],"k":["四聖諦","次法","如來藏","像法末法","清白梵行","布施"]},"6176-a26_024":{"s":"本集講解「為求辟支佛者說應十二因緣法」與「為諸菩薩說應六波羅蜜」。說明相應於十二因緣的前提是識與名色互緣、齊識而還的本識常住，並須先以五停心觀安心；修六波羅蜜則須以八識論、如來藏為前提，否則以六識論修學終將落入斷滅空而退轉。","p":["佛世大阿羅漢亦有辟支佛證量，稱緣覺","應十二因緣法：識緣名色、名色緣識，齊識而還","五停心觀調伏心性，為觀因緣法之前行","六識論修般若會恐懼斷滅而退轉","應六波羅蜜必以如來藏為中心修學"],"k":["十二因緣","六波羅蜜","如來藏","八識論","五停心觀","緣覺"]},"6178-a26_025":{"s":"本集說明以實證如來藏為前提修六度，方能證無上正等正覺並成就一切種智，因一切種子皆含藏於如來藏中，否定如來藏則無從成就種智。接著解說兩萬日月燈明佛同名同姓、最後一佛八王子捨位出家，以及佛說《無量義經》後入無量義處三昧、天雨四花、六種震動的瑞相。","p":["如來藏為無上、正等、正覺之法","一切種子藏於如來藏，否定之則無法成種智","兩萬日月燈明佛同名，諸佛平等說法無別","八王子善根深厚，捨王位隨父出家","《無量義經》之一法無量義即如來藏"],"k":["一切種智","如來藏","日月燈明佛","無量義經","八王子","無量義處三昧"]},"6179-a26_026":{"s":"本集講解日月燈明佛放光照東方佛土、為妙光菩薩說《妙法蓮華經》六十小劫、聽眾感如食頃，以及入滅前授記德藏菩薩成佛。強調授記是諸佛常法，並以此檢驗自稱成佛者與密宗即身成佛說之虛妄；最後介紹妙光弘經八十小劫、八王子成佛及弟子求名貪著利養。","p":["過去佛亦放白毫光照萬八千土，非刻意新創","六十小劫說法如食頃，喻佛威神力","日月燈明佛入滅前授記德藏菩薩","授記為諸佛常法，可檢驗自稱成佛者","妙光弘《法華》，八王子成佛，末為燃燈"],"k":["授記","妙光菩薩","日月燈明佛","即身成佛","燃燈佛","求名菩薩"]},"6186-a26_027":{"s":"本集說明求名菩薩雖貪著名利，仍因種善根而值遇無量諸佛供養，故勸學人以憐愍心看待求名而誹謗者。經文揭曉妙光即文殊、求名即彌勒，顯示彌勒不搶先說、文殊點明不可輕視彌勒的倫理。接著進入重頌偈，並勸應信受經中無量劫之說，區分新學與久學菩薩。","p":["求名者仍須供養無量諸佛才能見道","面對誹謗應生憐愍心而繼續弘法","妙光即文殊、求名即彌勒，顯佛教倫理","大菩薩示現演戲度眾，悟後不應生慢","經中可實證之法可信，疑者為新學菩薩"],"k":["求名菩薩","彌勒菩薩","文殊菩薩","妙光菩薩","重頌","久學菩薩"]},"6184-a26_028":{"s":"本集續解重頌偈，勸學人信受聖教、不輕信選擇性取材的學術考證，並說明菩薩遍布三界六道，批評只限人間的佛教觀。又講諸佛示現眷屬圓滿而後出家，以及諸佛必說大乘法、最後以《無量義經》將一切法收歸如來藏，再說《法華經》圓滿一代時教；最後說明先供養後請法的諸佛常法。","p":["疑見不斷難以證道，應信受經中聖教","批評學術考證先有立場、選擇性取材","菩薩遍布三界六道，天界尤多","諸佛必說大乘法，《無量義經》收歸如來藏","供佛須先供養後請法，佛法不可交易"],"k":["無量義經","如來藏","大乘法","人間佛教","供養","新學菩薩"]},"6185-a26_029":{"s":"本集解說重頌中天雨曼陀華、佛放眉間光照東方萬八千佛土，示眾生生死業報處，以昭因果。強調佛法不只在人間、地球或娑婆，批評「人間佛教」說與解脫道四果天界受生之理自相矛盾，並批評視釋迦佛為偶然成佛、否定十方諸佛的說法。","p":["聽法前先供養，坐位不擋佛前","光照六道業報處，令眾生信因果","諸佛土眾寶莊嚴，佛教遍十方世界","初果至三果生天仍修行，反證天界有佛法","諸佛成佛非偶然，十方不只一佛"],"k":["人間佛教","因果","十方諸佛","佛土","世界海","放光"]},"6188-a26_030":{"s":"本集講解偈頌中佛光所照諸佛土的各類修行者：無數聲聞眾、山林持戒比丘、行施忍辱菩薩、以定為禪者及知法寂滅相的證悟菩薩。說明聲聞性與菩薩性的程度差別，勸未來度眾要攝受並培養弟子的菩薩性；持戒能令心得決定，施忍等雖非見道卻是必要資糧。","p":["聲聞性與菩薩性有程度差別，皆應攝受","度眾應令弟子發起菩薩性，佛土才莊嚴","持戒如護明珠，因戒令心得決定","行施忍辱是見道前資糧，不宜否定","知法寂滅相：諸法攝歸如來藏故寂滅"],"k":["菩薩性","聲聞性","持戒","福德資糧","寂滅相","以定為禪"]},"6198-a26_031":{"s":"本集先整理〈序品〉情節順序：世尊說《無量義經》入三昧放光，文殊憶念日月燈明佛同樣瑞相，預示將說最後最上的《法華經》。接著開始講五時三教：華嚴時為十方大菩薩說法，如日照高山、窮子喻之「旁追」；鹿苑時說阿含解脫道為藏教，如日照幽谷，於《法華》中喻為化城、「二誘」。","p":["《法華經》為諸佛入滅前最後最上之法","五時：華嚴、鹿苑、般若、唯識、法華","華嚴時為大菩薩說，顯佛初成道即圓滿","鹿苑時說阿含解脫道，稱藏教","阿含解脫道喻化城，窮子喻中為二誘"],"k":["五時三教","華嚴時","鹿苑時","窮子喻","化城喻","藏教"]},"6200-a26_032":{"s":"本集續講五時三教。般若時二轉法輪，依如來藏說空有不二，三乘同聽各得其解，稱通教，如日照大地、窮子喻之「體信」；唯識種智時三轉法輪，說一切種智，只攝大心菩薩，稱別教、「領知」；法華時直說如來藏本來成佛，為圓教、「付業」。並整理頓、漸、圓三類與化法四教等名相。","p":["般若時說空有不二，三乘共聞稱通教","批評視大乘空與二乘空相同之說","唯識時說種智，只攝大心菩薩為別教","法華時為圓教，五千增上慢人退席","窮子喻對應旁追、二誘、體信、領知、付業"],"k":["五時三教","般若時","唯識種智","圓教","窮子喻","通教別教"]},"6208-a26_033":{"s":"本集強調五時三教即每位佛弟子從凡夫到成佛的修學次第，《法華經》為終點與地圖，並以此解釋正法、像法、末法的成因。以乳、酪、生酥、熟酥、醍醐比喻五時，說明五時皆是如來藏一味，即一佛乘；唯有真見道者才嚐得此味，並批評未證言證及將《法華》說為神話的說法。","p":["五時三教對應佛弟子修證的次第","正像末三時差別在有無善知識依次第教導","五時如乳酪酥醍醐，皆是如來藏一味","意識理解只是聞慧，未證言證成大妄語","玄奘通宗通教，批評《法華》神話說"],"k":["五時三教","五時一味","一佛乘","醍醐","如來藏","正像末法"]},"6201-a26_034":{"s":"本集勸學人以五時三教檢驗自身修證落處，並說明佛經偈頌與長行的關係：古印度以口誦傳承，偈頌為總持，往往較早。接著解釋無量義三昧：十八界一切法皆有限量，唯真如如來藏能具無量義，即《法華經》的一佛乘；並引《華嚴經》普賢身說明一切法皆在自心如來藏中。","p":["以五時次第檢驗自己修證的落處","古印度口誦傳承，偈頌為總持主體","十八界法皆有限量，不能成就無量義","唯如來藏具無量義，即一佛乘核心","《華嚴》普賢身：修行不離自心如來藏"],"k":["無量義","一佛乘","如來藏","偈頌","普賢身","十八界"]},"6202-a26_035":{"s":"本集講解日月燈明佛讚妙光菩薩為持法者，說明「勝解」須聞思修證具足，警惕未悟言悟。並指出《法華經》重點在諸法實相，批評以緣起性空為實相之說；引《中阿含經》說明佛滅後無人等同於佛，弟子依法不依人。最後進入〈方便品〉開頭，佛告舍利弗如來智慧甚深，唯佛與佛乃能究盡。","p":["勝解須聞思修證具足，非意識理解","說法六十小劫不起於座，暗指如來藏","《法華》重點在諸法實相，非緣起性空想法","佛滅後無人等同佛，弟子依法不依人","〈方便品〉：如來智慧甚深，唯佛與佛乃能究盡"],"k":["諸法實相","勝解","方便品","妙光菩薩","授記","一佛世界唯一佛"]},"6209-a26_036":{"s":"本集講解〈方便品〉偈「世雄不可量……無能知佛者」，說明佛福慧兩足、威德為三界至尊，故稱世雄、大雄。以鴿入佛影不怖、入舍利弗影仍怖說明佛大慈悲與習氣斷盡之別；並引《大乘起信論》「歸命盡十方，普作大饒益，智無限自在，救護世間尊」，解說四智、三智與般若、解脫帶來的自在。","p":["世雄：佛福德智慧威德為三界至尊","鴿入佛影不怖，顯佛大悲與習氣斷盡","歸命盡十方：應歸命十方三世諸佛","智無限：一切種智圓滿、四智圓明","自在源於般若慧與解脫慧；佛為大醫王"],"k":["方便品","世雄","四智圓明","一切種智","大乘起信論","大慈大悲"]},"6216-a26_037":{"s":"本集講解〈方便品〉「佛力無所畏、解脫諸三昧」等偈，列舉佛十力與四無所畏，並說明三昧有禪定三昧與智慧三昧。詳解禪定三三昧（有覺有觀、無覺有觀、無覺無觀）並區別於般若經之離覺觀，再說二乘與大乘的空、無相、無願三昧；最後解釋道場成果與「是法不可示，言辭相寂滅」指如來藏。","p":["佛具十力、四無所畏、三種解脫","三昧分禪定三昧與心得決定的智慧三昧","禪定三三昧：初禪、未到地定、二禪以上","二乘依蘊處界、大乘依如來藏證三解脫門","是法不可示，指離言寂滅的如來藏"],"k":["三三昧","十力","四無所畏","空無相無願","如來藏","方便品"]},"6230-a26_038":{"s":"本集講解〈方便品〉偈：縱使十方遍滿如舍利弗的阿羅漢、辟支佛、新發意菩薩、不退菩薩共同思量，皆不能測佛智。說明分段生死與變易生死的差別，阿羅漢只斷煩惱障現行，所知障須至佛地方斷盡；新發意菩薩已供養無數佛，並引《金剛經》與《瓔珞經》說明福德與善知識攝受的重要，介紹五種不退。","p":["遍滿十方如舍利弗者亦不能測佛智","分段生死依五陰命根，變易生死依種子流注","所知障即無始無明，明心破而佛地斷盡","新發意菩薩已供養無數佛，福德最重要","五種不退：信、位、行、念、究竟不退"],"k":["變易生死","分段生死","所知障","五種不退","新發意菩薩","佛智"]},"6217-a26_039":{"s":"本集續講「不退諸菩薩……亦復不能知」，以明心者無法測見性境界為例，說明眼見佛性須定力、慧力、福德具足，並介紹禪門三關、明心與見性的差別。再解「唯我知是相，十方佛亦然」與「諸佛語無異」，佛佛道同皆證一切種智；最後引《成唯識論》說第八識的心、所知依、種子識、阿賴耶、異熟識、無垢識等異名。","p":["下位菩薩不能測上位境界，何況佛地","眼見佛性須定力、慧力、福德三資糧","明心與見性為如來藏兩面，非一非異","諸佛語無異：佛佛道同，皆證一切種智","第八識隨位立名：阿賴耶、異熟、無垢識"],"k":["眼見佛性","第八識","阿賴耶識","成唯識論","禪門三關","佛佛道同"]},"6218-a26_040":{"s":"本集講解「於佛所說法，當生大信力；世尊法久後，要當說真實」，說明佛先說二乘法建立信心，再說大乘真實法；並解「佛以方便力，示以三乘教」，概述人天乘、二乘化城與五時三教。最後講千二百阿羅漢等四眾生疑，舍利弗代眾請問並以重頌祈請佛說具足道。","p":["對佛所說應生大信力，否則易退轉","佛先說二乘虛相法，再說大乘實相法","以方便力示三乘教，引眾生出離執著","五時三教次第：華嚴、阿含、般若、方廣、法華涅槃","四眾生疑，舍利弗長行與重頌請佛說法"],"k":["方便品","三乘教","五時三教","舍利弗","大信力","一佛乘"]},"6231-a26_041":{"s":"本集承接〈方便品〉「止！止！不須復說……皆當驚疑」經文，說明佛先說《無量義經》以如來藏一法攝無量義，再說《法華經》。並辨正教判：批評將《法華經》判為佛入滅前最後說法之誤，介紹平實導師依玄奘菩薩所立「五時三教」，說明法華時將三乘匯歸一佛乘。","p":["先說《無量義經》，以如來藏一法函蓋無量義","法華後尚有《大般涅槃經》，非臨滅最後說","空有之諍是未悟者戲論，智光三時判教顛倒","五時：華嚴、阿含、般若、種智、法華","三時分以四諦相、隱密相、顯了相轉法輪"],"k":["五時三教","判教","一佛乘","如來藏","無量義經","三轉法輪"]},"6219-a26_042":{"s":"本集講解〈方便品〉舍利弗三度請法、佛三次制止的經文。說明佛擔心增上慢比丘聞法不信、謗法而墮大坑；舍利弗以三明六通見會眾多世曾隨佛受化，故為大眾慇懃請法。並解釋增上慢、「佛長子」與「無上兩足尊」福慧雙足之義。","p":["佛三止：說此事則天人驚疑，增上慢者墜大坑","增上慢即未得謂得、未證謂證，唯地上菩薩不犯","舍利弗見會眾世世隨佛學法，故堅持請法","大乘經賴菩薩結集流傳，舍利弗等是大恩人","兩足尊即福慧雙足，智慧須福德支撐"],"k":["舍利弗請法","增上慢","方便品","福慧雙足","無明"]},"6242-a26_043":{"s":"本集講解〈方便品〉五千增上慢四眾退席，以及佛說「無復枝葉，純有貞實」、「諸佛唯以一大事因緣出現於世」的經文。說明開示悟入佛知見即為宣說如來藏大法；並批評今日有法師主張佛只是普通人、成佛是演化偶然，等同佛即阿羅漢之說。","p":["五千人退席，因罪根深重與增上慢","定性阿羅漢自認與佛同證，亦屬增上慢","「枝葉」「貞實」之喻；法會本是說法聚會","一大事因緣：令眾生開示悟入佛之知見","批評「佛只是普通人、成佛屬演化偶然」之說"],"k":["一大事因緣","開示悟入","增上慢","五千退席","如來藏","阿羅漢不是佛"]},"6250-a26_044":{"s":"本集說明「一佛乘」的「一」有唯一與整體兩義：成佛之法與佛地境界只有一種，且佛法整體不可切割，二乘法只是大乘的一部分，單修二乘只能滅盡五陰入無餘涅槃而無法成佛。並引〈方便品〉「諸佛如來但教化菩薩」「如來但以一佛乘故為眾生說法」經文說明。","p":["「一」有唯一與整體兩義","成佛須三大阿僧祇劫修六度，具足一切種智","二乘法是大乘的一部分，不能抽離而成佛","諸佛如來但教化菩薩，以佛知見示悟眾生","過去諸佛方便說法，皆為一佛乘"],"k":["一佛乘","一切種智","六度波羅蜜","教化菩薩","二乘","無餘涅槃"]},"6243-a26_045":{"s":"本集延續一佛乘主題，說明佛知見的究竟是一切種智，即了知第八識如來藏一切功能差別。講者提到末法有人錯解佛法（舉友人詢問《廣論》為例），強調須辨別正法。並引經文說明佛隨眾生本性，以因緣、譬喻、方便力說法，舉佛帶貪欲弟子觀天宮、地獄的故事為例。","p":["佛知見究竟即一切種智，了知如來藏功能差別","末法有人以外道法或割裂之法為佛法","諸佛但教化菩薩，令眾生入佛之知見","佛隨眾生本性，以因緣譬喻方便說法","舉弟子見天女、見地獄油鍋而回心修行之例"],"k":["佛之知見","一切種智","方便力","一佛乘","如來藏","末法"]},"6244-a26_046":{"s":"本集講解〈方便品〉「十方世界中尚無二乘……於一佛乘分別說三」經文，說明諸佛出於五濁惡世，因眾生垢重而將一佛乘方便分說三乘。二乘解脫道原屬佛法整體，菩薩入初地亦須圓滿阿羅漢果證。並以化城喻說明二乘涅槃只是中途化城，不究竟也不真實。","p":["五濁惡世眾生垢重，佛於一佛乘分別說三","聲聞緣覺法本屬一佛乘整體之內","菩薩入初地前須圓滿阿羅漢果證","化城喻：導師於長路中途化城，休息後化滅","二乘入無餘涅槃只是滅己，非究竟解脫"],"k":["方便說三乘","化城喻","五濁","一佛乘","解脫道","無餘涅槃"]},"6251-a26_047":{"s":"本集續講「佛以方便力，於一佛乘分別說三」，再以化城喻說明二乘法是幻化而成、不究竟的安止處，佛在弟子建立信心後化去化城，引導前往佛道。並指出阿羅漢、辟支佛都聽聞過大乘法，二乘果建立在佛菩提之上；自稱阿羅漢卻不知諸佛教化菩薩之事者，非真佛弟子。","p":["化城即二乘法，幻化而成，不真實也不究竟","佛待眾生建立信心後化滅化城，引向佛道","阿羅漢、辟支佛皆曾聽聞大乘法","二乘果建立在佛菩提之上","先以二乘攝信心不足者，再說大乘法"],"k":["化城喻","方便說三乘","一佛乘","阿羅漢","辟支佛","迴小向大"]},"6245-a26_048":{"s":"本集說明「佛語」即唯一佛乘，佛地果證是究竟了知第八識如來藏的一切功能差別；但此真實法不屬三界境界，難以證知，以燃香、魔術師為喻。並解說〈方便品〉自謂已得阿羅漢而不求無上菩提者是增上慢人的經文，勸勉應「一心信解受持佛語」。","p":["佛語即唯一佛乘，涵攝聲聞乘與緣覺乘","成佛須究竟了知如來藏一切功能差別","真實法非三界境界，以魔術師喻其微細難見","自謂已得阿羅漢、不求菩提者是增上慢","諸佛言無虛妄：無有餘乘，唯一佛乘"],"k":["信解受持","唯一佛乘","增上慢","如來藏","阿羅漢","實相"]},"6258-a26_049":{"s":"本集依平實導師《法華經講義》第三輯，回顧〈序品〉、〈方便品〉，開始探討「阿羅漢不是佛」。舉《法華經》、《大般若經》及阿含經典說明諸佛皆十號具足；阿含中唯有彌勒尊者被宣示未來成佛並授金縷衣，阿羅漢弟子到法華會才被授記，可見阿羅漢不是佛。","p":["諸佛智慧甚深，聲聞辟支佛所不能知","法華中過去佛與受授記弟子皆十號具足","大般若經十方諸佛、阿含經皆說十號具足","中阿含記彌勒未來成佛十號具足，授金縷衣","大迦葉入雞足山待彌勒；阿羅漢至法華方授記"],"k":["阿羅漢不是佛","十號","授記","彌勒菩薩","阿含經","大迦葉"]},"6270-a26_050":{"s":"本集以六念（念佛、法、僧、施、戒、天）中念佛與念僧的差異，續論「阿羅漢不是佛」。說明念住是以智慧觀所念內涵而住，不只是持名；引大乘經論與阿含經說明六念的修法與功用。念佛是憶念如來十號功德，念僧是憶念四雙八輩功德，兩者內涵不同。","p":["六念的念住是以智慧觀察所念而住，非僅持名","大乘經說六念是福德、智慧二莊嚴之因","阿含教在家居士依四不壞淨修六念","念佛憶念十號功德，念僧憶念四雙八輩","念佛與念僧內涵不同，證阿羅漢不是佛"],"k":["六念","念佛","念僧","阿羅漢不是佛","四不壞淨","念住"]},"6259-a26_051":{"s":"本集先說明獨覺所證與阿羅漢同位，故辟支佛也不是佛；再以四念處類推，引《瑜伽師地論》解說「念」與「念住」，並依七種作意解析阿含「學戒多福利、慧為上首、解脫堅固、念為增上」，指出念為增上即觀察作意。最後提出六念同時是修忍，稱為「六念忍」。","p":["獨覺所證同阿羅漢果，辟支佛也不是佛","以四念處類推，說明念與念住的意義","作意心所：警覺心識、引心趣向所緣境","念為增上即觀察作意，貫穿戒定慧修學","修六念須先接受自己未究竟，即六念忍"],"k":["念住","四念處","作意","六念忍","辟支佛","戒定慧三學"]},"6260-a26_052":{"s":"本集略說「六念忍」：引平實導師開示「安忍就是接受」，說明知與忍有差距，能安忍於自己尚未究竟才能增進道業。逐一解說念佛、念法、念僧、念施、念戒、念天如何同時修忍，並指出法華會五千人退席，是因增上慢、我慢與不信而不能安忍。","p":["安忍即接受；知道與安忍之間差距很大","念佛：如以調御丈夫反觀自身煩惱","念法：觀罵者受者皆空、剎那生滅","念僧、念施、念戒、念天皆具修忍之實","五千人退席，因增上慢、我慢與不信"],"k":["六念忍","安忍","增上慢","我慢","菩薩戒","止觀"]},"6272-a26_053":{"s":"本集說明法華會五千人不信「阿羅漢不是佛」的根本原因是我慢與增上慢。依《瑜伽師地論》定義我慢為因我存在而喜樂，並非與人比較的慢，是五上分結中最難斷者；增上慢分世間法未得謂得與出世間法未證言證，大乘增上慢最重。實證阿羅漢而不信法華、不迴心者，也名增上慢人。","p":["我慢是因自我存在而喜樂，非與人比較之慢","我慢為最難斷的上分結，乃至細至非想定中","阿含：五陰非我、不異我、不相在","增上慢分世間法未得謂得、出世間法未證言證","實證阿羅漢而不迴心大乘，亦稱增上慢人"],"k":["我慢","增上慢","阿羅漢不是佛","五上分結","五陰","迴心大乘"]},"6261-a26_054":{"s":"本集回顧〈方便品〉三請、五千人退席與一大事因緣，接著解說偈頌「若人信歸佛……為說實相印」的四個重點。本集講前三點：如來不欺誑眾生，由持菩薩戒而有廣長舌相；如來已斷煩惱障與所知障，菩薩斷障歷程異於二乘；佛出世是令眾生悟入佛菩提，阿含解脫道只是化城。","p":["如來不欺誑，因地持菩薩戒，成佛有廣長舌相","三十二相從初住位開始修集，至佛地圓滿","批評釋印順稱實相不可知、不可證","如來斷盡煩惱障、所知障，菩薩起惑潤生","三轉法輪中，阿含解脫道是方便化城"],"k":["唯一佛乘","實相印","煩惱障","所知障","菩薩戒","化城喻"]},"6282-a26_055":{"s":"本集說明第四個重點「實相印」即一切有情的生命實相，又名如來藏、阿賴耶識，出生五陰與器世間。接著語譯偈頌「舍利弗當知，我本立誓願……來世得作佛」，歸納四個重點，本集講前兩點：佛願眾生皆成佛道、不以小乘化度而墮法慳貪；不能悟入佛菩提者必是福德欠缺。","p":["實相印即如來藏、阿賴耶識，一切有情皆有","二乘滅盡蘊處界，菩薩則親證實相印","佛願眾生如我無異，以小乘化人即墮慳貪","三乘是方便施設，佛本懷令眾生皆成佛","福德是智慧之基，福德欠缺者難悟佛菩提"],"k":["實相印","如來藏","唯一佛乘","福德資糧","法慳貪","阿賴耶識"]},"6278-a26_056":{"s":"本集續講偈頌後兩個重點。第三點談邪見：講者批評台灣四大山頭以意識靈知心為實相，喇嘛教樂空雙運落入受陰與識陰，自續派、應成派中觀墮於斷常二見。第四點說明涅槃不是斷滅空、本來寂靜，以苦之本際與《心經》說明三轉法輪的次第，並批評達賴喇嘛主張三轉法輪前後顛倒。","p":["邪見即取顛倒法堅著不捨，障礙悟入佛菩提","批評以有念、無念、斷際靈知心為實相","批評喇嘛教樂空雙運及兩派中觀","無餘涅槃非斷滅空，有苦之本際存在","以《心經》說明空性心與涅槃寂靜"],"k":["涅槃寂靜","邪見","實相印","心經","斷常二見","三轉法輪"]},"6283-a26_057":{"s":"本集解說偈頌「我有方便力，開示三乘法……助顯第一義」。從佛初成道欲入涅槃、梵天請法談起，依次說明阿含時三轉十二行法輪隱說本際，般若時令聖弟子證悟並修別相智、發十大願、起惑潤生入地，以及唯識種智時的內容。並說明第一義諦即實相印的多種異名，結論是阿羅漢不是佛。","p":["佛初成道欲入涅槃，大梵天請佛住世說法","阿含時三轉十二行法輪，隱說苦之本際","般若時修別相智、發十大願、起惑潤生入初地","第一義諦即實相印：本際、阿賴耶識等異名","解脫德三乘共證但有差異，阿羅漢不是佛"],"k":["方便力","第一義諦","三轉法輪","別相智","實相印","唯一佛乘"]},"6284-a26_058":{"s":"本集解說偈頌「若有眾生類，值諸過去佛……聚沙為佛塔，皆已成佛道」。說明六度萬行是修集福德與智慧，五乘修學皆需福德，發菩提心即攝一切福德；福德足才能遇真善知識而證悟。並舉金天夫婦供僧、老人一句南無佛、貧女難陀燃燈三例，勸人種良善福田，批評喇嘛教為毒田。","p":["六度萬行即修集福德與智慧資糧","人天、二乘、菩薩各乘皆需福德莊嚴","發菩提心攝一切福德，前五度皆修福","菩薩種性難得，福德足方能證悟","金天夫婦、南無佛老人、貧女燃燈三例"],"k":["福德資糧","六度萬行","發菩提心","菩薩種性","福田","聚沙為塔"]},"6280-a26_059":{"s":"本集依〈方便品〉「彩畫作佛像……皆已成佛道」經文，探討家中供養如來聖像能否成就佛道。說明久學菩薩發願值遇諸佛，懂得恭敬供養，與新學菩薩不同；引《瑜伽師地論》卷44，說明供養不現前佛及制多可得無量大福德，並談家中安立佛像的方式與自他共供養。","p":["值遇諸佛並供養，是成就佛道的因緣","發願值遇賢劫未來佛，親隨彌勒尊佛修學","久學菩薩自然恭敬供養，新學菩薩則否","供養不現前佛像、佛塔，亦得無量大福德","條件不足可用小桌供像，並勸他人同供養"],"k":["供養佛像","福德","久學菩薩","瑜伽師地論","彌勒菩薩","自他共供養"]},"6285-a26_060":{"s":"本集依〈方便品〉「歌唄頌佛德，乃至一小音，皆已成佛道」經文，探討梵唄唱誦法會能否成就佛道。說明梵唄法會屬「次法」，可作為契入三乘菩提之緣起，培養五根、五力；講者批評只趕法會而無所證、道場不教隨聞入觀，法會流於積蓄資財。本集先講梵唄成就信根，進根留待下集。","p":["隨喜唱誦乃至一小音，可為成佛緣起","梵唄法會屬次法，藉以契入三乘菩提之法","批評只跑道場趕法會，一生於法無所證","法會應有事上與理上功德，須教隨聞入觀","梵唄讚佛種下信根，講者自述聞鐘鼓感動"],"k":["梵唄","法與次法","五根五力","信根","法會","供養如來"]},"6311-a26_061":{"s":"本集延續探討《法華經》「乃至一小音，皆已成佛道」，說明如法參加梵唄法會可依序成就信、精進、念、定、慧五根五力，並增上戒定慧三無漏學。講者強調須依善知識教導，以無相憶佛淨念隨文入觀、懺悔迴向，並指出真實「法會」是善知識講經說法之會。","p":["信根、信力具足後方能成就精進根","依善知識教導隨文入觀，漸成念、定、慧根力","以無相憶佛淨念禮佛、懺悔並迴向冤親債主","如法參加法會可增上戒定慧及解脫道智慧","真實法會是善知識宣講三乘菩提之會"],"k":["梵唄法會","五根五力","隨文入觀","無相憶佛","懺悔滅罪","三無漏學"]},"6313-a26_062":{"s":"本集依〈方便品〉「但化諸菩薩，度脫無量眾」等偈，說明諸佛示現人間的本懷是以大乘佛菩提道開示悟入如來藏，二乘法只是方便施設，種種法門「其實為一乘」。並引《長阿含經》說明世尊次第說法，批評「大乘非佛說」及印順六識論之說與經義相違。","p":["諸佛但化菩薩，非為教導二乘小法而來","種種法門的實證標的皆為第八識如來藏","不迴心的定性二乘被喻為焦芽敗種","阿含亦先說施論、戒論、生天之論再勸出離","批評大乘非佛說與印順六識論違背經義"],"k":["唯一佛乘","大乘非佛說","如來藏","定性聲聞","五乘佛法","六識論"]},"6308-a26_063":{"s":"本集為此系列最後一集，引印順《印度之佛教》等書文句，指其主張「大乘非佛說」且前後自相矛盾，並以阿含「生天之論」反問其以考據否定肉眼不見的天界與淨土。講者並述平實導師自1995年起破斥此說，認為其見源自應成派中觀六識論，最後總結大乘經典為佛金口所說。","p":["指印順「直趨解脫教人，不令成佛」之說前後矛盾","以眾生有無真如佛性反問六識論者","以世間考據否定天界、淨土等出世間法不能成立","平實導師《念佛三昧修學次第》已破斥此說","結論：大乘經為佛說，六識論與雙身法非正法"],"k":["大乘非佛說","印順","六識論","八識正教","應成派中觀","生天之論"]},"6309-a26_064":{"s":"本集講解〈方便品〉「我始坐道場…云何而可度」至「雖復說三乘，但為教菩薩」，說明世尊成佛後三七日思惟眾生根鈍難度，經諸天請轉法輪，憶念過去佛方便力而決定分說三乘。並說明三轉法輪次第及《無量義經》、《法華經》宣講緣起，強調說三乘目的仍在教化菩薩。","p":["道場指所證無垢識境界及其功德妙用","三七日思惟眾生五根鈍、著樂癡盲難度","諸梵王、帝釋、四天王等請轉法輪","但讚佛乘則眾生不信破法，故依諸佛說三乘","三轉法輪次第，最後講《無量義經》與《法華經》"],"k":["轉法輪","三乘方便","唯一佛乘","三轉法輪","諸天請法","無量義經"]},"6315-a26_065":{"s":"本集講解「我聞聖師子…我常如是說」經文，說明「喜稱南無佛」與「唯我獨尊」不相矛盾，後者指第八識自心如來。並敘述世尊至鹿野苑為五比丘三轉四聖諦十二行法輪，人間始有涅槃音、阿羅漢及法僧之名；諸法因附屬寂滅的如來藏而為寂滅相，難以言宣，故先說聲聞法。","p":["唯我獨尊指自心如來，諸佛皆喜稱南無佛","鹿野苑為憍陳如等五比丘三轉四諦法輪","以玻璃球喻說明諸法附屬如來藏故寂滅","初轉法輪後人間始有真實涅槃音與僧寶","世尊久遠劫來於各世界示現成佛"],"k":["初轉法輪","諸法寂滅相","如來藏","四聖諦","五比丘","唯我獨尊"]},"6310-a26_066":{"s":"本集講解「我見佛子等…但說無上道」經文，說明靈山聽法眾包含諸天鬼神，人數難計，批評以凡夫心「將心比心」把經文推為神話。並說明鈍根小智、著於表相而生憍慢者不能信受唯一佛乘，舉現代禪李元松遭佛教界批評、平實導師被大法師否定等事為例。","p":["聞法眾包含諸天與大力鬼神，非僅人類","以凡夫心境將心比心不適用於佛法實證","眾多曾聞諸佛方便法者來集，正是說佛慧之時","著相者只看出家、在家表相而生憍慢","佛菩提道超出解脫道範圍，故無從論爭"],"k":["唯一佛乘","著相憍慢","鈍根小智","佛菩提道","解脫道"]},"6319-a26_067":{"s":"本集續講「今我喜無畏…正直捨方便，但說無上道」及「千二百羅漢，悉亦當作佛」，指出「正直捨方便」非指直心修行，而是捨人天乘、二乘等方便道而單說唯一佛乘。並說明喜無畏來自三乘菩提皆證，千二百阿羅漢本是菩薩，故於《法華經》授記作佛。","p":["落在意識的直心修行並非正直，方便指方便道","三乘菩提皆通方能歡喜無畏","從施論、戒論、生天之論到四聖諦皆屬方便道","初轉法輪時佛亦私下為菩薩說無上道","千二百阿羅漢本為菩薩，故得授記當作佛"],"k":["無上道","正直捨方便","喜無畏","方便道","授記","迴小向大"]},"6325-a26_068":{"s":"本集講解「如三世諸佛，說法之儀式，我今亦如是，說無分別法」，說明三世諸佛皆以方便次第接引，最終必說無上菩提的無分別法。講者批評宗喀巴《廣論》以方便導向雙身法、以解脫道取代佛菩提道之說，並指出無分別法不是把意識修到不起念，而是以意識找到本來無分別的真如心。","p":["三世諸佛也包括未來成佛的謗法者","五濁世須依三轉法輪次第施設方便","批評《廣論》以方便引人入雙身法","打坐一念不生仍是分別，了了即已分別","證得本來無分別的如來藏才是無分別法"],"k":["無分別法","如來藏","說法儀式","方便施設","菩提道次第廣論"]},"6320-a26_069":{"s":"本集講解〈方便品〉「諸佛興出世，懸遠值遇難…過於優曇花」，說明聽聞無分別法之難：佛出世間隔懸遠、密意不可明說故說法難、眾生得聞與能聽亦難，並以平實導師早期明講密意的經驗為例。最後說明聞法歡喜讚歎乃至一言，即是法供養三世一切佛。","p":["佛出世間隔懸遠，賢劫千佛為大福報","無分別法密意不可明講，須隱覆而說","眾生無量劫中聞法亦難，如優曇花","聞法讚歎一言即法供養三世諸佛","以文字讚歎功德更為久遠廣大"],"k":["諸佛值遇難","無分別法","優曇花","法供養","密意","賢劫千佛"]},"6321-a26_070":{"s":"本集講解「汝等勿有疑，我為諸法王…無聲聞弟子」，說明法王須具一切種智，唯佛堪稱，並批評西藏密宗自稱法王。講者指佛法究竟圓滿，佛門不許創見，「大乘非佛說」屬創新佛法之論；世尊以一乘道教化菩薩，五十位定性聲聞不算佛弟子，並舉須跋陀羅入滅為例。","p":["法王須具一切種智，唯諸佛可稱","佛說究竟圓滿，佛門不許創見","大乘非佛說為創新佛法的錯誤論述","唯以一乘道教化菩薩，無聲聞弟子","須跋陀羅證果即入滅，為聲聞種姓之例"],"k":["唯一佛乘","法王","一切種智","定性聲聞","大乘非佛說"]},"6327-a26_071":{"s":"本集講解「汝等舍利弗…廣讚一乘道」，分三要點：唯一佛乘是諸佛祕要，只傳迴小向大的菩薩，並述四阿含結集與菩薩另行結集大乘經之說；五濁惡世眾生樂著諸欲不求佛道，未來惡人聞一乘不信而破法；應為有慚愧清淨、志求佛道者廣讚一乘。","p":["實相般若是諸佛祕要，不傳定性聲聞","五百結集成四阿含，菩薩另行結集大乘經","解說見濁、煩惱濁、命濁、眾生濁、劫濁","聞一乘不信、謗如來藏者破法墮惡道","有慚有愧者心清淨，應為其廣讚一乘"],"k":["諸佛祕要","唯一佛乘","五濁惡世","慚愧","經典結集"]},"6336-a26_072":{"s":"本集講解〈方便品〉最後一段「諸佛法如是，以萬億方便，隨宜而說法…自知當作佛」，說明諸佛觀察根器因緣，以無量方便說法，最後皆匯歸唯一佛乘。舉阿含中外道次第聽法證果、平實導師早期急於助人明心而受警為例，並批評見樹不見林、以解脫道為成佛之道者。","p":["諸佛觀根器隨宜說法，非隨興而講","阿含記載外道依次第聽法證阿羅漢","種種方便最後皆匯歸佛菩提道","以四聖諦等為全部佛法是見樹不見林","知諸佛方便事而無疑，自知當作佛"],"k":["隨宜說法","方便善巧","唯一佛乘","佛菩提道","方便品"]},"6338-a26_073":{"s":"本集進入〈譬喻品 第3〉首段，講解舍利弗聞佛說「自知當作佛」而踴躍歡喜，自述昔見菩薩受記作佛而己不預、常自剋責，今斷疑悔，知真是佛子。講者說明入地即得授記、未滿三地菩薩有隔陰之迷而請問授記，並指大阿羅漢是世尊特地來度之人。","p":["舍利弗知將受記而心懷踴躍","菩薩入初地時即為諸佛授記","未滿三地有隔陰之迷，故請問往昔授記","舍利弗自責以小乘見度，今斷諸疑悔","今知真是佛子，從法化生，得佛法分"],"k":["授記","譬喻品","舍利弗","隔陰之迷","佛子"]},"6352-a26_074":{"s":"本集探討「無上法輪」，引《大毘婆沙論》釋法輪義，及《法華經講義》說無上法輪首尾相接、法法相通。講者說明佛說法以萬法根源如來藏為核心，故勝一切法、能貫攝諸法而無矛盾，並論深廣並進、梵天請法之意，主張三轉法輪皆佛金口所說，信受此為四不壞淨的基礎。","p":["法輪取輪之動轉不住、摧伏怨敵等義","無上法輪首尾相接無疏漏、法法相通","以如來藏為核心，故勝一切法","修學深與廣成正比，趨向一理通萬理徹","三轉法輪皆佛所說，化緣圓滿方入滅"],"k":["無上法輪","如來藏","四不壞淨","三轉法輪","梵天請法"]},"6339-a26_075":{"s":"本集探討「作意」心所，引《成唯識論》說明其警心引心作用，並據《瑜伽師地論》指菩薩以利益眾生為作意，與阿羅漢厭背生死不同，舉舍利弗自責為例。並介紹解脫道七種作意、菩薩隨攝等作意、不如理作意四相，以及悟後真如作意、七真如與殷重作意。","p":["作意為遍行心所，引導心行","菩薩以眾生饒益為樂，自利利他","解脫道依四聖諦次第生起七種作意","不如理作意引生煩惱、毀壞羞恥","悟後真如作意與殷重作意尤為重要"],"k":["作意","如理作意","真如作意","七真如","菩薩種姓","自利利他"]},"6340-a26_076":{"s":"本集以舍利弗自述未得金色三十二相等經文為引，說明明心見性不等於成佛，亦無即身成佛。講者依經論解說無見頂相、白毫光相源自如來藏與宣說正法，千輻輪等相與孝養尊長有關，梵音聲相來自實語愛語，並說明上品十善業與等覺菩薩百劫修相好。","p":["明心見性非成佛，一悟即至佛地為方便說","無見頂相顯示佛地無垢識功德","白毫光相因無量世宣說真實正法","孝養父母、奉事師長與成就諸相有關","等覺百劫修相好，除最後身菩薩無即身成佛"],"k":["三十二相","百劫修相好","如來藏","即身成佛","十善業","福德"]},"6354-a26_077":{"s":"本集依〈譬喻品〉舍利弗初聞授記疑「將非魔作佛」一段，說明以世尊所說實道與方便善巧判別真佛與天魔。講者引經論介紹得決擇、魔的定義、魔事範圍與四魔，說明天魔因眷屬欲障礙正法、助長憍慢者，並列遠離菩薩魔道四法，強調對治憍慢心。","p":["舍利弗以世尊說實道確認非魔作佛","得決擇：了知修行位階與現觀以免被籠罩","夢中、定中所聞法須以聖教檢驗","奪慧命、退善法皆為魔事，有四魔之分","遠離魔道四法，尤須不生輕慢"],"k":["魔事","四魔","天魔","得決擇","憍慢","授記"]},"6341-a26_078":{"s":"本集依「佛說過去世，無量滅度佛」偈及經論，說明諸佛示現滅度只是應化身，法身無垢識不生不滅，故成佛盡未來際、利樂眾生無窮。講者解說無上正等正覺、佛佛道同、眾生皆有如來藏，並以《長阿含經》如來終不終四句說明，強調如來藏法義是四不壞信的基礎。","p":["滅度者為應化身，法身無垢識不生不滅","佛果圓滿不增不減，持無漏種盡未來際","正等指諸佛所證相同，眾生皆有如來藏","成佛須歷三大阿僧祇劫，非一世可成","如來藏法義為四不壞信的基礎"],"k":["盡未來際","無垢識","應化身","無上正等正覺","如來藏","四不壞信"]},"6372-a26_079":{"s":"本集先介紹〈譬喻品〉佛告舍利弗昔曾教其志願佛道、授記華光如來及其國土等三段經文，並探討舍利弗為何忘失本願。講者依《菩薩瓔珞本業經》舍利弗退住之例，說明未滿三地者有隔陰之迷，須世世重新斷我見、明心，並告誡學人勿以明心為身分榮耀而生慢心。","p":["三段經文：憶本願、授記華光如來、以本願說三乘","舍利弗曾入七住，遇惡因緣而退","三地滿心證意生身前皆有隔陰之迷","明心是責任非榮譽，勿生慢心","須先斷我見、定慧等持，否則明心必退"],"k":["授記","隔陰之迷","斷我見","明心","華光如來","慢心"]},"6364-a26_080":{"s":"本集依《優婆塞戒經》逐一解說如來十號：如來、阿羅呵、三藐三佛陀、明行足、善逝、世間解、調御丈夫、天人師、佛、婆伽婆，並旁及二十五有、兩種世間、《瑜伽師地論》「無上丈夫調御士」合為一號之說及四魔。講者指出阿羅漢只能少分相應，唯佛完全符合十號。","p":["莊嚴地可解為資糧位，具戒定慧而成如來","阿羅漢含無生、殺賊、應供三義","善逝指不復受生於二十五有","世間解了知眾生世界與國土世界","婆伽婆能破四魔，唯佛完全符合"],"k":["如來十號","優婆塞戒經","二十五有","四魔","世間解","調御丈夫"]},"6373-a26_081":{"s":"本集先引《大乘本生心地觀經》講一佛寶具三身：自性身即不生不滅、超時空的第八識如來藏；自受用身為十地滿心於色究竟天成就的真報身，四智圓明；他受用身為地上菩薩說一乘法；變化身具三十二相，為地前與二乘凡夫說三乘法。並引三譯《楞伽經》說明初次成佛必在色究竟天，以此破斥藏密無上瑜伽，最後總結佛寶六種微妙功德。","p":["自性身即受熏持種的如來藏，具八不中道","自受用身是真報身，色究竟天成佛、有始無終","引三譯《楞伽經》破藏密男女雙修成佛之說","他受用身八萬四千相好，只為地上菩薩說一乘法","變化身三十二相，為地前、二乘凡夫說三乘法"],"k":["三身","真報身","如來藏","色究竟天","六種微妙功德","破斥藏密"]},"6374-a26_082":{"s":"本集回到《優婆塞戒經》〈息惡品〉，從大乘實證角度重解如來十號。說「莊嚴地」究竟義是密嚴國土阿賴耶識，如來是乘如實道而來、唯佛能如實語；以舍利弗食不淨食的故事說明阿羅漢習氣未斷；等正覺即具足五分法身、四智圓明；明行足、善逝則須斷二種無明並遠離五陰區宇，並引平實導師《電子報》說明諸地菩薩次第滅除五陰。","p":["莊嚴地究竟指密嚴國土阿賴耶識","唯佛能如實語，故名如來","舍利弗受罰故事顯阿羅漢習氣未盡","等正覺即具足五分法身、四智圓明","善逝除遠離二十五有，還須過五陰區宇"],"k":["如來十號","五分法身","五陰區宇","阿賴耶識","所知障","優婆塞戒經"]},"6366-a26_083":{"s":"本集續講如來十號的大乘義，配合《心地觀經》三身六德與《楞嚴經》「自覺已圓，能覺他者」。說明應供因佛是無上功德田與報恩田；善逝對應解脫，世間解對應解脫知見，以一水四見與「遍計所起色」說明唯佛真知器世間；調御丈夫、天人師屬覺他；佛號表一切種智；最後引窺基《大乘法苑義林章》把四魔分為分段、變易兩類。","p":["應供：佛是無上功德田與報恩田","善逝對應解脫，世間解對應解脫知見","一水四見說明唯佛如實了知器世間","調御丈夫、天人師屬自覺之後的覺他","四魔分煩惱障、所知障兩類"],"k":["如來十號","五分法身","世間解","遍計所起色","四魔","自覺覺他"]},"6375-a26_084":{"s":"本集講《法華經》〈譬喻品〉華光佛壽十二小劫、授記堅滿菩薩為華足安行佛，以及正法、像法各住三十二小劫。重點解釋「多陀阿伽度」本意為如去，依如來藏常住無來去而立名，並引《楞嚴經》、《大智度論》說明諸法實相即如來藏，藉此反駁琅琊閣「第八識是梵我見」的說法；也解釋阿羅訶、三藐三佛陀兩個名號。","p":["華光佛壽十二小劫，授記堅滿菩薩作佛","多陀阿伽度本意如去，如來亦如去","陰處界皆從如來藏出生，諸法實相即如來藏","反駁琅琊閣「如來藏是梵我」之說","正法、像法各三十二小劫，無末法期"],"k":["多陀阿伽度","如來藏","諸法實相","華光如來","授記","琅琊閣"]},"6384-a26_085":{"s":"本集解說〈譬喻品〉授記舍利弗的重頌，描述華光佛離垢國土與其菩薩眾。由偈中「無上道」比較有上道、無上道、有下道、無下道，批評藏密無上瑜伽雙身法實為與阿鼻地獄相應的無下道，引《楞嚴經》十種魔為證；再引《大般涅槃經》、《楞伽經》、《如來藏經》、《大智度論》說明無上道即依如來藏修證涅槃而成佛。","p":["重頌再述華光佛國土、壽命與正像法","無上道相對於辟支佛、阿羅漢的有上道","批評藏密無上瑜伽為無下道","無上士：佛證涅槃法，為眾生中最上","般若波羅蜜即如來藏，依此成無上道"],"k":["無上道","如來藏","無上士","重頌","破斥藏密","涅槃"]},"6399-a26_086":{"s":"本集講四眾天龍見舍利弗受記而歡喜供養、諸天說偈讚佛「今復轉無上最大法輪」一段。說明同修見同儕受記自知亦有分，入初地即是受記之時；勉勵在彌勒下生前先入內門修六度，於龍華三會成為大阿羅漢再入地，才是善學菩薩道；並說波羅奈初轉法輪只是建立聲聞僧團，菩薩僧團早已存在，駁大乘後出之說。","p":["大眾見舍利弗受記，脫衣供佛、諸天說偈","入初地即被授記，退席五千人無分","彌勒下生前應先入內門修六度","初轉法輪只建立聲聞僧團，菩薩僧團早在","法華甚深奧，少有能信者"],"k":["授記","善學菩薩道","龍華三會","菩薩僧團","初轉法輪","譬喻品"]},"6398-a26_087":{"s":"本集解說諸天偈「於一切世間，最尊無有上；佛道叵思議，方便隨宜說」及迴向佛道。說明過去學佛者多誤以緣起性空、人間佛教為佛法，平實導師提出佛菩提二主要道次第表，標明二道並修與修證次第；再引《不增不減經》、《勝鬘經》說明如來藏不可思議、自性清淨而有染汙、兼具有為與無為，以此批評釋印順、琅琊閣的見解。","p":["大乘非佛說等於否定佛為無上正等正覺","佛菩提二主要道次第表：解脫道與佛菩提道並修","證悟後才知佛道難以言說、叵思議","《不增不減經》：眾生界即如來藏即法身","如來藏自性清淨而有染汙，駁琅琊閣之說"],"k":["佛道叵思議","如來藏","二主要道次第","不增不減經","勝鬘經","琅琊閣"]},"6385-a26_088":{"s":"本集開始講〈譬喻品〉火宅喻：長者宅舍朽壞、四面火起，諸子嬉戲不知出離，長者勸說而子不信受。說明世尊說二乘菩提本意在傳佛菩提，須先斷我見我執才能承認並安忍如來藏，成第七住不退；並以火宅比喻當今佛教界執意識常住、貪著五欲，批評學術界與琅琊閣把佛法分系，違背唯一佛乘、佛佛道同之旨。","p":["諸佛種種方便說法，皆為無上正等正覺","先斷我見我執，才能承認如來藏而不退","觀五陰十八界虛妄，成實義菩薩","火宅諸子喻執意識常住、貪五欲的佛教界","分宗立派、分系研究違背唯一佛乘"],"k":["唯一佛乘","火宅喻","斷我見","如來藏","譬喻品","分宗立派"]},"6395-a26_089":{"s":"本集依《法華經講義》第四輯，講長者以羊車、鹿車、牛車誘子出火宅的經文，並說明三車分喻聲聞、緣覺、佛菩提，大白牛車能載眾生與法寶同出。以平實導師之說解釋三界無安：欲界有火災、初禪被火烤、二禪有水災、三禪有風災，四禪與無色界仍有壽盡的無常火；佛以眾生所好施設方便，引導修學三乘菩提。","p":["羊車、鹿車、大白牛車喻三乘菩提","標點斷句影響經文理解","火、水、風三災對應眾生動而不止","四禪、無色界仍有壽盡無常火","佛隨眾生所好施方便，引入三乘"],"k":["火宅喻","三車","三界無安","三災","大白牛車","方便善巧"]},"6393-a26_090":{"s":"本集講長者等心各賜諸子七寶大白牛車、諸子得未曾有的經文。說明大阿羅漢在佛眼中只是幼童：迴心後熏習般若仍屬六住，證悟才入七住，離妙覺尚遠，佛滅後無阿羅漢敢紹繼佛位；佛無偏黨，迴心即全給大白牛車。大白牛車喻真如佛性第八識如來藏，隨從喻禪定、五根五力、十力等功德，須依如來藏修學，並批評謗阿賴耶識者無信根。","p":["長者等心各賜諸子七寶大車","大阿羅漢在佛眼中只是幼童","阿羅漢迴心證悟僅入第七住","大白牛車喻真如佛性第八識如來藏","僕從喻五根、十力等，須依如來藏修"],"k":["大白牛車","如來藏","阿羅漢與佛","菩薩五十二位","一佛乘","五根"]},"6410-a26_091":{"s":"本集講佛問舍利弗「長者等與諸子珍寶大車，寧有虛妄不」，舍利弗答只要救子出火宅即非虛妄。說明佛度聲聞成阿羅漢後再助其證悟佛菩提即是給大白牛車；證悟後未具佛地功德如幼童看不見全車，不算虛妄；並舉有人只要阿羅漢果不要菩薩法為例，批評古今自稱出離火宅卻仍貪著意識境界與雙身法者。","p":["舍利弗答：救子出火宅即非虛妄","證悟如幼童入車，看不見大白牛車全貌","有人只要羊車、不要大白牛車","大白牛車只是見面禮，佛法寶無量","外道與密宗口說出離，實愛樂火宅"],"k":["火宅喻","大白牛車","方便不虛妄","出離三界","佛菩提","破斥藏密"]},"6416-a26_092":{"s":"本集講「如來亦復如是，則為一切世間之父」一段經文。說明如來直接或間接攝受一切眾生，故為世間之父；並以醉象事件、難陀貪習等說明阿羅漢仍有怖畏、憂患與無明習氣，唯如來永盡無餘，因而成就十力、四無所畏及方便、智波羅蜜；如來為度眾生三毒之火而受生三界，教化眾生證得無上正等正覺，即證無分別法第八識如來藏。","p":["如來直接、間接攝受眾生，為世間之父","醉象衝佛事顯如來無畏、阿羅漢有畏","怖畏、衰惱、憂患、無明唯如來永盡","方便、智波羅蜜於七地、十地圓成","無上正等正覺即證第八識如來藏"],"k":["世間之父","無上正等正覺","如來藏","阿羅漢習氣","十力四無所畏","三毒之火"]},"6422-a26_093":{"s":"本集續解如來大慈大悲常無懈惓的原因：眾生被生老病死、憂悲苦惱燒煮而不自知。舉寒山詩、安世高償命、世尊頭痛三天說明因果不爽，並述追求財利五欲之苦、天人五衰與愛別離、人間貧窮苦及愚癡苦，歸為八苦、三苦、五陰熾盛苦；批評大法師暗修雙身法而不求解脫，勉勵菩薩為正法奮鬥、傳揚正見。","p":["眾生被生老病死、憂悲苦惱燒煮不知","寒山詩、安世高償命說明因果律","天人五衰、愛別離、怨憎會之苦","八苦、三苦歸為五陰熾盛苦","批評名師修雙身法、不求解脫"],"k":["三界火宅","八苦","因果律","大慈大悲","五陰熾盛苦","破斥藏密"]},"6418-a26_094":{"s":"本集先回顧〈序品〉日月燈明佛、妙光菩薩，〈方便品〉一大事因緣與五千退席，以及〈譬喻品〉舍利弗受記，再介紹法華七喻中的火宅喻與三乘歸一乘。接著講經文「我為眾生之父，應拔其苦難」及「若捨方便，眾生不能以是得度」，以孩童只信明日玩具為喻，說明眾生難信遙遠的佛果，故如來須隨根性施設方便。","p":["回顧序品、方便品與舍利弗受記","法華七喻：火宅、窮子、藥草、化城等","三乘歸於一大乘，三乘即一乘","若捨方便只讚佛智，眾生不能得度","隨眾生根性施設方便，引入正道"],"k":["火宅喻","三乘歸一乘","法華七喻","方便善巧","一大事因緣","譬喻品"]},"6425-a26_095":{"s":"本集續講「若捨方便只讚如來知見，眾生不能得度」，以飢餓孩童只需麵包為喻，說明須先以聲聞菩提解決眾生眼前的生老病死憂悲苦惱，取得信任後再引入佛菩提，即「先以欲鉤牽，後令入佛道」。並述正覺同修會先教觀行五陰十八界、斷我見再參禪的次第，平實導師著《阿含正義》以建立信心，也提到世尊初成道欲入涅槃、梵天請轉法輪。","p":["眾生距佛地太遠，須先解決眼前苦","阿羅漢不懂七住明心的非知非不知","先以欲鉤牽，後令入佛道","正覺先斷我見再證悟如來藏，較不退轉","先給羊車讓眾生現世可驗證"],"k":["方便善巧","聲聞菩提","斷我見","火宅三車","阿含正義","如來藏"]},"6420-a26_096":{"s":"本集講「如彼長者，雖復身手有力而不用之」至「乘是三乘以無漏根、力、覺、道…而自娛樂」的經文。說明強拉眾生入涅槃無用，須以智慧方便使其自願出離；批評以聲聞菩提取代佛菩提、主張大乘非佛說者，並引《增壹阿含》聲聞乘、辟支佛乘、佛乘證明阿含已說三乘；再述如來保證、勸勤修精進，並依次教羊車、鹿車、大白牛車的法樂。","p":["強拉入涅槃無用，我執種子會再現行","須以智慧方便令眾生自願出離火宅","《增壹阿含》已說三乘，駁大乘非佛說","如來保證「終不虛也」，勸勤修精進","三乘自在無繫，以根力覺道而自娛樂"],"k":["三乘菩提","方便善巧","大乘非佛說","增壹阿含經","火宅三車","無餘涅槃"]},"6443-a26_097":{"s":"本集解說〈譬喻品〉中三乘行者根性之別：內有智性、自求涅槃者為聲聞乘（求羊車）；求自然慧、樂獨善寂、深知諸法因緣者為辟支佛乘（求鹿車）；求一切智、佛智、自然智、無師智、如來知見及力無所畏，並愍念安樂無量眾生者為大乘摩訶薩（求牛車）。並解釋十因緣、四智與自然智、無師智的意涵，強調菩薩須以大悲利樂眾生。","p":["聲聞乘：內有智性，自求涅槃、自知作證","辟支佛乘：求自然慧，深知十因緣","辟支佛僅推知本識出生名色，未實證","一切智、佛智（四智）、自然智、無師智","大乘須愍念安樂無量眾生，名摩訶薩"],"k":["三乘根性","聲聞乘","辟支佛乘","摩訶薩","一切種智","十因緣"]},"6437-a26_098":{"s":"本集講「如彼長者…等以大車而賜諸子」至「諸佛方便力故，於一佛乘分別說三」的經文。說明本無三乘，因眾生根器怯弱才方便分說；眾生出三界苦後，如來平等給予大乘，以如來滅度而滅度之。並分辨二乘滅度是滅盡五陰十八界，如來滅度則不妨世世受生廣度眾生；大白牛車內已含羊車、鹿車，故長者無虛妄之咎。","p":["本無三乘，為根器差別方便分說","出三界後如來平等給予大乘","以如來滅度而滅度，非僅二乘滅度","大白牛車已含羊車、鹿車，無虛妄","眾生不盡能受，故一佛乘分別說三"],"k":["一佛乘","如來滅度","三乘方便","大白牛車","譬喻品","淨妙第一之樂"]},"6432-a26_099":{"s":"本集接續「初說三乘…然後但以大乘而度脫之」，分辨「不盡能受」與「不能盡受」，指出末法時能受持正法者極少，多數人信位不滿、對三寶缺乏恭敬，甚至主張大乘非佛說，故世尊須如分級教學般施設三乘。接著進入火宅喻偈頌，以大宅久故頓弊喻眾生無量劫輪迴的世間（娑婆即堪忍），並述其中惡禽毒蟲、魑魅夜叉之可怖。","p":["「不盡能受」與「不能盡受」之別","末法能受持正法者如金字塔頂端","三寶名相被世俗化，信心不具足","大宅久故頓弊喻無量劫輪迴的世間","惡禽毒蟲、夜叉鬼魅：其舍恐怖變狀"],"k":["火宅喻","偈頌","娑婆世界","三乘方便","三寶信心","末法"]},"6426-a26_100":{"s":"本集續解火宅偈「其舍恐怖變狀如是」。說明末法是佛法將從此人間消失而非世界末日，並引《俱舍論》說明三千大千世界由一佛教化；指出眾生已在三界堂舍住無量劫，不知窮通壽夭；以「業力共同體」與「變狀」說明六道輪迴非固定，引《楞嚴經》四種顛倒成四生、「生從順習，死從變流」及十習因六交報。","p":["末法指正法將離此人間，非世界末日","三千大千世界的構成，由一佛教化","業力共同體：動物前世也可能是人","「變狀」：六道輪迴並非固定一道","《楞嚴經》四種顛倒成卵胎濕化四生"],"k":["三界火宅","六道輪迴","業力共同體","三千大千世界","楞嚴經","四生"]},"6444-a26_101":{"s":"本集依《楞嚴經》卷8「十習因、六交報」，舉貪物、貪色、貪惑三種重罪為例，說明地獄罪畢後轉為鬼、旁生再回人間的果報次第，並以鐵柱套環比喻無始串習難除。進而呼應〈譬喻品〉「其舍恐怖變狀如是」，指出三界無安、生天亦非永遠，勸人諸惡莫作、眾善奉行，從布施起修六度。","p":["十習因造業、受六根六塵交報之苦","貪物成𩲓鬼→梟類→參合頑類","貪色成魃鬼→咎徵異類；貪惑成魅鬼→狐類","串習如鐵柱層層套環，煩惱難除","三界無安，依如來藏方有盡未來際"],"k":["十習因六交報","楞嚴經","三界火宅","習氣","六度","如來藏"]},"6434-a26_102":{"s":"本集講解〈譬喻品〉偈頌「是朽故宅屬于一人，其人近出未久之間」，說明三千大千世界為一佛所化，佛依眾生得度因緣於各處示現成佛，並在三界火起時出世。再從理、事兩面闡釋「今此三界皆是我有」：理上三界皆自心如來藏所變現；事上以電影《間諜遊戲》為喻，顯示世尊以三大阿僧祇劫福德攝受眾生，等視諸子。","p":["三千大千世界為一佛剎","「近出未久」：依得度因緣他處示現","火宅將起時佛出人間","理上：三界皆自心如來藏所變現","事上：佛以無漏福德攝受，眾生皆佛子"],"k":["今此三界皆是我有","三千大千世界","火宅喻","如來藏","佛子","福德"]},"6462-a26_103":{"s":"本集續講火宅偈頌，以「舍宅忽然火起」喻無常，並批評把佛法說成追求幸福快樂的說法。說明長者以羊車、鹿車、牛車引諸子出火宅，即「先以欲勾牽，後令入佛智」；「空地」一語，二乘指蘊處界空，大乘指如來藏空性。再從理、事解釋「唯我一人能為救護」：理上為如來藏真我救護，事上唯佛能究竟救護。","p":["舍宅火起喻無常，眾生惶怖不能出","先以欲勾牽，後令入佛智","空地：二乘證蘊處界空，大乘證空性","證果後仍須隨佛修學，法無所得","唯我能救護：理為真我，事為諸佛"],"k":["火宅喻","三車","空性","一佛乘","如來藏","方便"]},"6456-a26_104":{"s":"本集講解偈頌「以此譬喻說一佛乘，汝等若能信受是語，一切皆當成得佛道」，強調唯一佛乘以如來藏為法界根本，具圓成實性、非斷非常。節目批評密宗金剛乘、密咒大乘與宗喀巴、釋印順的六識論，並引阿含「意、法因緣生」、如來十力、三蘆相依及嗏帝比丘等經證，說明名色之外另有入胎識、一切種子識。","p":["如來本懷：令一切眾生成佛","批評密咒大乘、金剛乘不如理","如來藏為一切法所依，非斷非常","業種須由第八識執藏，否則無種智","三蘆相依：識在名色之外，為入胎識"],"k":["一佛乘","如來藏","八識論","六識論","識緣名色","一切種智"]},"6448-a26_105":{"s":"本集講解偈頌「是乘微妙清淨第一，於諸世間為無有上」，說明佛法是實證法界實相，非思想或玄學，應恭敬持法法師。述及拈花微笑、教外別傳與玄奘菩薩使禪宗興盛；指出所證心體本來無分別，並非打坐修成，批評宗喀巴止觀。另將佛法與其他宗教、西方邏輯與哲學相比，說其皆不出六識生滅。","p":["一佛乘微妙清淨，是實證非思想","應恭敬持如來藏妙法的善知識","拈花微笑、教外別傳與玄奘之功","心體本來無分別，非打坐修成","他教與哲學皆不出六識生滅之思"],"k":["一佛乘","第八識","無分別","教外別傳","涅槃","六識論"]},"6465-a26_106":{"s":"本集講解偈頌「乘此寶乘直至道場…更無餘乘，除佛方便」，說明十方求之別無他乘，三乘與人天乘皆為佛的方便，批評密教乘及聲聞勝於大乘之說。述玄奘曲女城大會破「大乘非佛說」，並引《中阿含》「如來所依識」、「如來是梵」、《長部》「名色之因稱為識」、《雜阿含》「齊識而還」，說明第八識為本有之法；最後勸人受菩薩戒。","p":["乘寶乘直至道場，十方無餘乘","三乘及人天乘皆是佛的方便","玄奘曲女城大會破大乘非佛說","帝釋、自在天求如來所依識不能得","識為名色之因，齊識而還；勸受菩薩戒"],"k":["一佛乘","方便","第八識","大乘是佛說","菩薩戒","玄奘"]},"6458-a26_107":{"s":"本集講解偈頌「汝諸人等，皆是吾子…所化眾生皆是菩薩」，說明二乘只盡分段生死，佛以化城喻方便說三乘，究竟都歸一佛乘。引《大薩遮尼乾子所說經》、《楞伽經》、《央掘魔羅經》等，說明如來藏不同外道神我、能取所取皆空、無我法中有真我，並指出謗法罪重於殺佛，如來視一切眾生如同一子。","p":["二乘但盡分段生死，實不滅度","化城喻：方便說三乘，歸一佛乘","大般涅槃即實相心本自涅槃","如來藏離能取所取，無我中有真我","謗法罪重；佛視眾生猶如一子"],"k":["一佛乘","化城喻","如來藏","大般涅槃","無我","謗法"]},"6460-a26_108":{"s":"本集講解偈頌「若人小智深著愛欲，為此等故說於苦諦」，說明佛為小智眾生方便說四聖諦，教其斷我見、滅貪愛而得二乘解脫。進而指出四聖諦皆不離如，滅諦即心體本來寂滅；引〈如來壽量品〉塵點劫之喻，說法身無垢識常住不滅。並批評應成派、自續派中觀，強調發菩提心、護持正法、如教修行。","p":["為小智眾生方便說苦集滅道","行苦與意識生滅，應斷我見","大乘四聖諦皆不離如","如來壽量久遠，法身無垢識常住","護持正法須臾，功德超淨土一劫"],"k":["四聖諦","方便","法身","真如","如來壽量","護持正法"]},"6480-a26_109":{"s":"本集開始依《法華經講義》第五輯講〈譬喻品〉，先介紹天台五時判教（講者認為般若與方等應互換）及導師講《法華經》的緣起。接著解釋「但離虛妄名為解脫」，指解脫是遠離我見、我執、我所執，阿羅漢習氣仍在，未得一切解脫；並說「我為法王於法自在，安隱眾生」，批評喇嘛自稱法王及密宗雙身法。","p":["天台五時判教，般若方等應互換","解脫即遠離我見、我執、我所執","阿羅漢習氣尚存，未得一切解脫","於法自在方稱法王，批喇嘛自稱","密宗被內外火所燒，不能安隱眾生"],"k":["譬喻品","解脫","阿羅漢","法王","五時三教","密宗"]},"6470-a26_110":{"s":"本集講解〈譬喻品〉「在所遊方勿妄宣傳」，說明此經只為菩薩子說，故五千聲聞凡夫退席時佛未阻止。以「諸子生育甚難」說明十信須一劫至萬劫方生菩薩性，再以六度養育，並把住、行、向位比作年歲。接著解釋「隨喜頂受，當知是人阿鞞跋致」，分述信不退、住不退、位不退、行不退、念不退、究竟不退。","p":["法華妙法只為菩薩子說，勿妄宣傳","十信一劫至萬劫，菩薩子生育甚難","以六度養育；六住如六歲","十迴向滿心如三十歲，可付如來家業","阿鞞跋致不退有多種層次"],"k":["阿鞞跋致","菩薩種性","十信位","六度","五十二位"]},"6474-a26_111":{"s":"本集續講〈譬喻品〉，說明能信受此經的人往昔已曾見佛、聽聞此經，因此修道應重道情過於親情，也不應輕視其他老師。接著講「斯法華經為深智說」，聲聞、辟支佛力所不及，舍利弗也是以信得入。再說明佛囑咐不要對憍慢、懈怠、計我見三種人說此經，並批評「大乘非佛說」的主張。","p":["信受此經者往昔已見佛、聞是法","道情遠勝親情，依法抉擇","勿輕視他班老師，或為往世師","法華為深智說，二乘力所不及","憍慢、懈怠、計我見者莫說此經"],"k":["譬喻品","信受","深智","我見","大乘非佛說"]},"6481-a26_112":{"s":"本集講解「凡夫淺識深著五欲，聞不能解亦勿為說」及「若人不信毀謗此經，則斷一切世間佛種」。講者批評某老法師主張大乘非佛說，並把淨土說成太陽神崇拜，認為這是斷人佛種；也提到佛世時五千人退席，而彌勒佛時不會有人誹謗。並說明謗經者「輕賤憎嫉而懷結恨」，命終入阿鼻地獄無數劫，再經餓鬼道轉入畜生道。","p":["凡夫淺識深著五欲，勿為說此經","大乘非佛說即斷一切世間佛種","彌勒佛時人壽八萬四千歲不謗","謗者輕賤憎嫉持經人而懷結恨","入阿鼻獄無數劫，再轉餓鬼畜生"],"k":["謗法","斷佛種","大乘非佛說","阿鼻地獄","六識論"]},"6472-a26_113":{"s":"本集續講謗經罪報：從地獄、餓鬼出後生為狗、野干一類，身形枯瘦、疥癩，常困飢渴，生受楚毒、死被瓦石，皆因「斷佛種故」。講者批評「佛即阿羅漢」及七、八識為部派創造的說法，認為其中自相矛盾；並強調菩薩應以悲憫說明六識論的過失，救護謗法者懺悔回歸，而不是詛咒他們。","p":["謗經者轉生狗、野干，枯瘦疥癩","生受楚毒死被瓦石，斷佛種故","批「佛即阿羅漢」與部派造經說","應以悲心說明六識論過失救護之","弘法目的在提升知見，不在斂財"],"k":["斷佛種","謗法","六識論","八識論","大悲","畜生道"]},"6476-a26_114":{"s":"本集講解〈譬喻品〉誹謗大乘法的正報與花報：謗經者出地獄、餓鬼後生為駱駝、驢、馬，負重挨打，只念水草；或為疥癩獨眼的野干，再受五百由旬大蟒身，被小蟲唼食。若得為人則諸根闇鈍、身形矬陋，說話無人信受，口臭而鬼魅所著，貧窮多病，行醫反增他疾，自病服良藥反增劇。","p":["生駝驢負重挨打，但念水草","野干疥癩獨眼，被童子打擲","受蟒身五百由旬，小蟲唼食","為人諸根闇鈍、矬陋，言不見信","口臭鬼魅所著，貧病、醫藥反劇"],"k":["正報花報","謗法","畜生道","異熟果報","譬喻品"]},"6496-a26_115":{"s":"本集續講謗經罪報：橫遭反逆、抄劫等罪殃，永不見佛，常生難處、狂聾心亂不聞法，常處地獄如遊園觀；為人則聾盲瘖瘂、病苦纏身。接著就「深著我見增益瞋恚」，說明謗大乘者必我見深重，並解釋我見即認意識常住，分為斷續分別我見與俱生我見，須現觀識陰六識由根、塵、觸三緣所生。","p":["橫羅其殃、永不見佛、常生難處","常處地獄如遊園觀，惡道如舍宅","為人聾盲瘖瘂，以疾病為衣服","謗大乘者必我見深重","我見分斷續分別與俱生；觀識陰虛妄"],"k":["我見","識陰","謗法","正報花報","斷我見","一闡提"]},"6503-a26_116":{"s":"本集續論識陰：引《雜阿含》說執取識陰境界即具足我所貪愛，並指意識雖虛妄，亦能熏習正法、證悟第八識。引《入楞伽經》「如來藏阿梨耶識共七識生」，說明轉相與二法。講者批評宗喀巴主張意識結生相續、某法師立「意識細心常住」，又以「婬欲熾盛不擇禽獸」指密宗雙身法；最後總結謗經罪窮劫不盡，無智人中莫說此經。","p":["執取識陰境界即具我所貪愛","意識亦能熏習正法、證第八識","如來藏阿梨耶識與七識俱生","批意識結生相續、細心常住之說","婬欲熾盛指雙身法；無智人莫說"],"k":["識陰","如來藏","阿賴耶識","我見","見取見","密宗"]},"6500-a26_117":{"s":"本集講解〈譬喻品〉佛說可為演說此經的十種人中，前四種：利根多聞強識求佛道者、曾見億百千佛深心堅固者、精進常修慈心不惜身命者、恭敬無異心獨處山澤者（在家指不攀緣）。接著講後六種中的前兩種：捨惡知識、親近善友者，以及持戒清潔如明珠、專求大乘經者；並說明十信位修行須一劫至一萬大劫。","p":["利根多聞強識求佛道者可為說","曾見億百千佛、深心堅固者","精進修慈心、不惜身命者","恭敬無異心、獨處山澤不攀緣者","捨惡知識親近善友；持戒求大乘經者"],"k":["十種人","譬喻品","多聞","善知識","持戒","十信位"]},"6494-a26_118":{"s":"本集續講可為說《法華經》的六種人中的後四種：無瞋質直柔軟、常愍一切恭敬諸佛者；於大眾中以清淨心、譬喻言辭說法無礙者；比丘為求一切智而四方求法、但樂大乘經者；以及如求佛舍利般求經頂受、不求餘經與外道典籍者。中間引《心地觀經》說菩薩僧、聲聞僧、凡夫僧三種僧，並批評「出家人不可向居士學法」的觀念。","p":["否定大乘者心曲，求大乘者心直","無瞋質直柔軟、恭敬諸佛者","說法無礙者；為一切智但樂大乘者","三種僧：菩薩僧、聲聞僧、凡夫僧","求經如求舍利；肉身舍利與法舍利"],"k":["十種人","一切種智","三種僧","法舍利","大乘經典"]},"6505-a26_119":{"s":"本集開始講〈信解品〉：須菩提、迦旃延、迦葉、目犍連四大弟子聽聞舍利弗受記，歡喜踊躍而欲說譬喻。講者說明此品主旨在於對佛菩提道生起信解極難，阿羅漢得授記後信心具足，才願起惑潤生；並說明「解」分聞解、思解、修解、證解，知道密意不等於開悟，不可洩漏密意。","p":["四大弟子聞舍利弗授記而歡喜","對佛菩提道生起信解極為困難","信具足方願起惑潤生行菩薩道","解有聞解、思解、修解、證解","知密意非開悟，洩密意為大惡業"],"k":["信解品","授記","起惑潤生","證解","密意","能取所取空"]},"6501-a26_120":{"s":"本集續講〈信解品〉的修證次第：十行位滿心有陽焰觀；如夢觀須先有眼見佛性的如幻觀、陽焰觀，並具滿證初禪以上與頂級三果。入地三條件為大福德、三種現觀與永伏性障，再發十無盡願。接著解說經文中四大弟子整衣、偏袒右肩、胡跪合掌的行儀與問訊的本義，以及迦葉代眾稟白的內容。","p":["十行滿心現觀七轉識如陽焰","如夢觀須如幻觀、陽焰觀與禪定","入地：大福德、三現觀、永伏性障","發十無盡願增上意樂方入初地","偏袒右肩、胡跪合掌與問訊本義"],"k":["信解品","如夢觀","陽焰觀","如幻觀","入地","十無盡願"]},"6523-a26_121":{"s":"本集續講〈信解品〉大迦葉稟白「我等居僧之首，年並朽邁；自謂已得涅槃」一段，說明大阿羅漢灰心泯智、聽方廣唯識經疲懈而住空無相無作三昧、對菩薩法心不喜樂的心境；並解釋聽聞聲聞得授記為何「心甚歡喜，得未曾有」，以及授記成佛須具備的條件。","p":["阿羅漢入涅槃作意，故灰心泯智、無心世間","「自謂已得涅槃」：實未知無餘涅槃中是如來藏","聽不懂唯識經而身體疲懈，安住三三昧","批評學者以聲聞結集文獻判斷大乘經","授記為希有之法，須道種智、解脫果與福德"],"k":["信解品","授記","阿羅漢心境","空無相無作三昧","本來自性清淨涅槃","大乘經結集"]},"6515-a26_122":{"s":"本集講解〈信解品〉大阿羅漢知自己亦將被授記而歡喜「無量珍寶不求自得」，並開始大迦葉所說窮子喻：幼年走失的兒子流浪五十年，輾轉來到富甲一方的父親宅舍門外，見長者踞師子床、威德特尊而心生恐懼想逃。逐句解說師子床、寶几承足、白拂、寶帳、華幡、出內取與等經文。","p":["聽聞舍利弗授記，生起增上意樂","大迦葉以譬喻說明授記時節之理，為未悟者說","長者富有、日夜思念走失之子","窮子遙見長者威德，恐被逼迫而欲逃","解說高廣大床與菩薩戒之關係"],"k":["窮子喻","信解品","授記","高廣大床","菩薩戒"]},"6520-a26_123":{"s":"本集續講窮子喻：窮子「疾走而去」反被長者認出，遣人強拉回來，窮子驚怖悶絕，長者知其志意下劣，遂放他離去。講者以此譬喻大阿羅漢以為大乘法是菩薩的事、聽不進去，並對照現今佛教界不信可斷我見、證如來藏的現象，說明攝受眾生須經磨練、待因緣成熟而不強求。","p":["窮子疾走被認出，強牽回而悶絕倒地","長者知子心劣，方便放他「隨意所趣」","世俗人顛倒，以凶事辦喜事","喻阿羅漢及今日佛教界不信能斷我見","度眾先傳播正知見，待緣熟不勉強"],"k":["窮子喻","信解品","方便攝受","斷我見","善根成熟"]},"6517-a26_124":{"s":"本集從〈方便品〉佛說一大事因緣及往昔於二萬億佛所教化舍利弗談起，講述釋迦佛因地為海濟婆羅門時所發大悲願：不以願力取土，而以六波羅蜜攝度五濁惡世難化眾生；並舉慈力王以身血施五夜叉、設頭羅健寧王化大魚、羼提波梨仙人受割截等本生，說明憍陳如五比丘最先得度的因緣。","p":["諸佛唯以一大事因緣出現於世","海濟婆羅門發願於五濁惡世以六度攝眾","對比阿彌陀佛以願力取度眾生","慈力王、大魚、忍辱仙人本生度憍陳如等","應信無數劫來受釋迦佛攝受培植善根"],"k":["大悲願","本生故事","六波羅蜜","憍陳如","一佛乘","五濁惡世"]},"6525-a26_125":{"s":"本集探討「二乘窮子成為佛子之信解」：先回顧火宅三車喻，再完整敘述大迦葉窮子喻中長者換穿粗衣、以四攝法接近窮子、令其除糞二十年、掌管寶藏、臨終宣布父子關係的過程。引《大寶積經》說明大迦葉信佛具足卻不信自己能作佛，並辨聲聞與如來真實佛子之別。","p":["火宅三車喻：以一佛乘分別說三","長者以布施愛語利行同事攝窮子","窮子經手寶藏仍不捨下劣心","大迦葉自謂退於無上菩提，即窮子心境","往來生死利益眾生的菩薩方為真實佛子"],"k":["窮子喻","信解","四攝法","真實佛子","如來藏","大寶積經"]},"6521-a26_126":{"s":"本集講解〈信解品〉「蠲除諸法戲論之糞，得至涅槃一日之價」，說明二乘涅槃只是佛法寶藏的一日之價、是入佛道的方便門。引《大法鼓經》大迦葉僅願護法四十年而被佛訶責之事，並依實相法與虛相法、《大般若經》菩提五義，解釋為何二乘菩提稱為小法。","p":["解脫果僅是入佛道的方便門","《大法鼓經》大迦葉願護法四十年被訶","斷我見我執如除戲論之糞","虛相法無我空與實相法無我空之別","二乘菩提未及真如、實際、法界等義故為小法"],"k":["一日之價","除糞喻","二乘涅槃","實相法","諸法戲論","大法鼓經"]},"6531-a26_127":{"s":"本集探討佛陀以二乘為教化佛子的方便門。引《菩薩瓔珞本業經》說明六住入七住須善知識護念，舉舍利弗六十劫行菩薩道進退、因乞眼事件迴小向大；講者並以正覺同修會四次退轉事件為例。後引《首楞嚴三昧經》四種授記及華光開敷遍身佛之語，說明大迦葉「我等不知真是佛子」之意。","p":["七住不退須值善知識護念","舍利弗六十劫進退，因乞眼退向小乘","菩薩道兩難：遠離惡友、無求攝眾","大迦葉聞未發心授記，於眾生生世尊想","諸佛常以方便分別說三乘"],"k":["方便門","七住不退","舍利弗","授記","真實佛子","退轉"]},"6543-a26_128":{"s":"本集講解大迦葉所說「世尊於佛智慧無所吝惜」，說明佛實以大乘教化聲聞，二乘修道次第亦是菩薩法。以信行為例，比較菩薩直接信入佛知見（如來藏無色受想行識、一切法空）與二乘依四聖諦修學之別，並引《雜阿含經》甚深緣起經文，論證涅槃本際即如來藏，非斷滅空。","p":["佛於菩薩前毀呰聲聞，實以大乘教化","聲聞緣覺所行亦是菩薩法","菩薩信入如來藏無色受想行識之佛知見","四聖諦滅諦之本際即如來藏","甚深緣起指能藉緣現起者，涅槃非斷滅"],"k":["佛智慧","四聖諦","如來藏","甚深緣起","無餘涅槃","大乘非佛說"]},"6539-a26_129":{"s":"本集進入〈信解品〉，說明對佛菩提生起信解之難，大迦葉以長者窮子喻比喻世尊對他們的方便攝受。並探討佛法是有我還是無我：引《父子合集經》外道之問，及《大般涅槃經》佛以乳母餵嬰為喻，說明佛先說無常無我，待弟子堪任再說常樂我淨，以煩惱為薪、智慧為火煮成「涅槃飯」。","p":["阿羅漢未滿六住福德，聞授記方信心具足","長者換破衣、執除糞器方便接近窮子","初轉說無我，二轉以實相心說第一義諦","如餵嬰兒，依根器次第給予法味","涅槃飯之真米即第八識如來藏"],"k":["涅槃飯","信解品","常樂我淨","無我","如來藏","大般涅槃經"]},"6533-a26_130":{"s":"本集續講〈信解品〉除糞之喻，說明學人須先除貪瞋癡等染汙心性，再修參禪功夫，並說阿羅漢因心中無貪而無意承接法寶，佛至《法華經》才總結點交。舉《菩薩瓔珞經》五千正士退席、勇智菩薩往昔為忘恩獅子王被木雀啄眼的故事，說明不信如來三身、誹謗正法的惡種子難以得度。","p":["除糞喻：先除染汙心性再修參禪","阿羅漢心無貪，佛以方便漸轉其心量","五千正士退席不聽如來三身法要","獅子王忘恩、木雀啄眼之本生","誹謗正法惡種子須懺悔方能根除"],"k":["如來三身","除糞喻","菩薩瓔珞經","如來藏","誹謗正法","懺悔"]},"6545-a26_131":{"s":"本集依《大乘本生心地觀經》說明前佛後佛皆依如來寶藏識成佛，並解說佛地四智圓明：轉異熟識成大圓鏡智、轉末那成平等性智、轉意識成妙觀察智、轉前五識成成所作智。再述佛三轉法輪次第轉化阿羅漢心量，並解釋大迦葉「一切諸法皆悉空寂，無生無滅，無大無小，無漏無為」之意。","p":["諸佛皆依根本識如來寶藏識成就","四智圓明為自受用報身","第八識是聚寶盆，人人本具而不知","佛訶不迴心二乘為焦芽敗種","依如來藏現觀一切法無生無滅"],"k":["四智圓明","如來三身","如來藏","三轉法輪","焦芽敗種"]},"6541-a26_132":{"s":"本集從大迦葉說「一切諸法皆悉空寂無生無滅」談起，指出阿羅漢不否定第八識，否定者無法斷我見。引《六度集經》蝨子報恩故事，說明供養持戒比丘勝過供養凡夫；再引《楞伽經》說如來藏不同外道神我，並分辨聲聞依蘊處界的空、無相、無願三昧，與大乘依如來藏的解脫三三昧。","p":["否定第八識者必有內外恐怖，不能證果","蝨子報恩僅供養七日，喻凡夫心量","供養持戒比丘功德勝於凡庶","如來藏不同外道所說之我","聲聞三三昧為表相，依如來藏三三昧為本"],"k":["解脫三三昧","如來藏","第八識","楞伽經","外道神我","六度集經"]},"6547-a26_133":{"s":"本集續引《楞伽經》說如來藏又名離自性、不生不滅、本來寂靜、自性涅槃，並說佛為斷愚夫畏無我句而說離妄想如來藏門，不同神我、梵我。後講〈信解品〉大迦葉「於無漏法得清淨眼」「法王法中久修梵行，今得無漏無上大果」及「世尊大恩，無量億劫誰能報者」，說明二乘與大乘法眼淨之別及佛恩難報。","p":["涅槃是真如別名，非斷滅空無","如來藏離自性、本來寂靜、自性涅槃","佛說如來藏，令外道離我見入三解脫門","大乘清淨眼指入地，阿羅漢只欠十無盡願","證量愈高愈知佛恩無量難報"],"k":["如來藏","自性涅槃","法眼淨","佛恩","信解品","楞伽經"]},"6564-a26_134":{"s":"本集開始「勝難希有不可思議諸佛」主題，說明眾生不敬佛或妄稱成佛，是因不了解成佛須三大阿僧祇劫。從時間角度引《長阿含經》說佛出世如優曇缽華難遇；再以命濁、眾生濁、煩惱濁、見濁、劫濁五濁說明釋迦佛於娑婆成佛之難，並在見濁中批評藏密喇嘛教雙身法。","p":["不知成佛歷程，故妄稱成佛造大妄語","佛難值遇如優曇缽華，賢劫釋迦為第四佛","命濁、眾生濁、煩惱濁之相","見濁：批評雙身法非佛法","劫濁：刀兵、疾疫、飢饉"],"k":["五濁惡世","諸佛希有","優曇缽華","大妄語","雙身法批判"]},"6559-a26_135":{"s":"本集續講「勝難希有不可思議諸佛」，以佛菩提道五十二位階說明成佛之難：分遠、近、大、圓滿四種波羅蜜多，詳述十信、十住六度修集、六住斷我見、四加行到七住明心，再說十住眼見佛性成就如幻觀、十行陽焰觀、十迴向如夢觀，並提及十迴向應進修的唯識增上慧學。","p":["成佛須經五十二位、十種現觀、三種意生身","批評即身成佛之說，強調次第實修","六住斷我見，七住證悟本來自性清淨涅槃","十住眼見佛性成就世界如幻觀","十行陽焰觀、十迴向如夢觀"],"k":["五十二位階","十種現觀","如幻觀","陽焰觀","如夢觀","眼見佛性"]},"6551-a26_136":{"s":"本集續講菩薩修證歷程：如夢觀須先發起初禪、於定中夢中相應過去世修行，以對治意根遍計執、性障永伏如阿羅漢。三種現觀圓滿並具增上慧學、十無盡願，加上諸佛加持得大乘照明三昧而入初地；再說初地鏡像觀、二地光影觀與持戒、三地修四禪八定成就谷響觀及無漏妙定意生身。","p":["如夢觀須初禪證量，對治意根染汙","三種現觀圓滿發起聖種性","入地須增上慧學、十無盡願、諸佛加持","初地鏡像觀、二地光影觀與持戒","三地修禪定神通，成谷響觀與意生身"],"k":["十種現觀","如夢觀","初地","意根","鏡像觀","意生身"]},"6565-a26_137":{"s":"本集續講三地滿心無漏妙定意生身可破隔陰之迷，並以此批評喇嘛教活佛認證之說。接著解說谷響觀、四地依大乘安立諦十六品心細觀四聖諦並成就水中月觀、五地以無生法忍觀十二因緣而成變化所成觀，以及六地細觀十二有支成似有非有觀，自然證滅盡定成俱解脫大乘無學。","p":["三地滿心意生身無隔陰之迷","批評活佛轉世認證之說","四地觀安立諦十六品心，成水中月觀","五地斷下乘涅槃貪，成變化所成觀","六地似有非有觀，不由加行證滅盡定"],"k":["十種現觀","意生身","隔陰之迷","四聖諦十六品心","十二因緣","滅盡定"]},"6560-a26_138":{"s":"本集講完菩薩道後段：七地念念入滅盡定，佛授引發如來無量妙智三昧，成犍闥婆城觀；八地於相於土自在並專修願波羅蜜，九地修四無礙辯成善慧地，十地受十方諸佛灌頂成法雲地受職菩薩，等覺百劫修相好，妙覺待緣下生成佛。最後略述佛地四智、十力等功德，勸勿妄稱成佛。","p":["七地念念入滅盡定，佛授妙智三昧","八地相土自在，證三種意生身","九地法、義、詞、樂說四無礙辯","十地受職灌頂為法王子","等覺百劫修相好，妙覺待緣成佛"],"k":["菩薩十地","等覺妙覺","四無礙辯","意生身","四智圓明","諸佛希有"]},"6567-a26_139":{"s":"本集開始「唯一佛乘」主題，引〈方便品〉三世諸佛皆以一佛乘說法、究竟得一切種智，說明三乘皆依如來藏方便建立。再講〈藥草喻品〉「如來說法一相一味，所謂解脫相、離相、滅相」，指阿含之名即顯成佛之道；並以誦經、稱佛名、老人喊「南無佛」得出家因緣為例，說明受持讀誦有功德而自不覺知。","p":["佛以一佛乘析分三乘應眾生根性","一切種智為成佛必備，依如來藏證知","一相一味即解脫相、離相、滅相","阿含意為成佛之道，然未說悟入如來藏","受持讀誦經典功德自不覺知"],"k":["一佛乘","一切種智","一相一味","藥草喻品","如來藏","阿含"]},"6576-a26_140":{"s":"本集續講〈藥草喻品〉，解釋如來知一相一味之法終歸於空，觀眾生心欲而將護之，故不即說一切種智；說明眾生根性因緣不同，如來無所不知，猶如卉木藥草不自知上中下性。並述佛先令人證阿羅漢以建立信心，再漸說般若；最後解說「破有法王出現世間」偈中大雲普雨之喻。","p":["佛觀眾生心欲將護，不即說一切種智","眾生念思修各異，唯如來如實照見","一切種智即如來藏所含種子之圓滿證知","先令證阿羅漢建立信心再漸說深法","大雲普雨喻佛法平等滋潤眾生"],"k":["藥草喻品","一相一味","一切種智","隨宜說法","大雲喻","根性差別"]},"6579-a26_141":{"s":"本集續講〈藥草喻品〉偈頌，說明「破有法王出現世間，隨眾生欲種種說法」：佛陀出世專破外道落於三界有的假阿羅漢，並因如來尊重、智慧深遠而「久默斯要」，隨眾生根力說法。再以大雲普雨之喻，配合五時三教（華嚴、阿含、般若、唯識種智、法華）說明法雨普潤三乘根性。","p":["佛為破有法王，專破落於三界有的外道","隨眾生欲先說解脫，久默斯要不務速說","有智聞則信解，無智疑悔則永失","大雲慧雨普潤卉木藥草大小諸樹","以五時三教說明如來次第施設法雨"],"k":["破有法王","藥草喻","五時三教","三乘菩提","如來藏"]},"6568-a26_142":{"s":"本集講解偈頌「其雲所出一味之水，草木叢林隨分受潤」至「常為大乘而作因緣」，說明佛如大雲以一味法雨平等普潤，眾生隨根器各得生長。重點闡釋「諸法之實」：以五陰非無因生、自生、共生、他生，推知其由如來藏所生，緣起性空不是如來出世本懷；並批評「開悟者不應自稱開悟」之說。","p":["一味之雨隨草木大小各得滋茂","佛出世為眾生分別演說諸法之實","五陰不能自生、他生、共生、無因生","五陰由各自如來藏所生，上帝亦然","緣起性空非佛本懷；批評開悟不可自稱之說"],"k":["諸法之實","如來藏","緣起性空","一味法雨","藥草喻","五陰"]},"6578-a26_143":{"s":"本集續講「我為如來兩足之尊」及「為大眾說甘露淨法，其法一味解脫涅槃」等偈，說明如來宣示自身證量是為利益人天、防止眾生誹謗造業。講解甘露淨法之義，指佛法只有二乘菩提與佛菩提兩大甘露法門，並批評藏密明光大手印、雙修及所謂甘露；強調如來本懷是唯一佛乘而非緣起性空。","p":["阿羅漢、如來宣示證量是隨俗利眾","佛為福慧兩足尊，令得世間樂及涅槃樂","批評藏密以一念不生為成佛、雙修為法","甘露喻清淨法，佛法只有兩大甘露法門","其法一味指佛地解脫涅槃，本懷唯一佛乘"],"k":["甘露淨法","唯一佛乘","兩足尊","解脫涅槃","破斥密宗"]},"6581-a26_144":{"s":"本集開講〈藥草喻品〉偈頌「我觀一切普皆平等」至「釋梵諸王是小藥草」（講義第七輯第31頁起），說明如來無愛憎、無限礙，恆為一切眾生平等說法。指出平等法即一切有情同具的第八識如來藏，緣起性空不是平等法；眾生隨根性領受不同，並以人天、轉輪聖王、釋梵諸王為小藥草。","p":["如來觀眾生平等，本意令一切人成佛","批評大乘非佛說，阿含僅記大乘名相","佛說法不限聽眾，四眾隨根領受","平等法是如來藏，非緣起性空","人天、輪王、釋梵諸王為小藥草"],"k":["藥草喻品","平等說法","如來藏","小藥草","大乘非佛說"]},"6587-a26_145":{"s":"本集講解〈藥草喻品〉偈頌「知無漏法能得涅槃」至「如彼草木所稟各異」，界定其餘四類聞法根性：證涅槃、三明六通及緣覺果者為中藥草，發願作佛並行精進定者為上藥草，專心佛道、常行慈悲至三地滿心前者為小樹，能起意生身、安住神通轉不退輪者為大樹。並說明阿含經典是聲聞人依自身稟性結集，勉勵擴大心量、護持正法修集福德。","p":["阿羅漢乃至緣覺聖者皆屬中藥草","求作佛且有定心所、精進不退為上藥草","證悟至三地滿心前常行慈悲為小樹","三地滿心起意生身度眾者為大樹","聲聞結集大乘經成阿含；護法修福"],"k":["藥草喻品","三草二木","大樹菩薩","意生身","菩薩種姓","護持正法"]},"6603-a26_146":{"s":"本集講解偈頌「佛以此喻方便開示」至「是名小樹而得增長」（講義第七輯第66頁起），說明佛以種種言辭只演說佛菩提一法。引《大薩遮尼乾子所說經》指三乘之說是示地、法相、人之差別而非乘差別；強調法隨法行、漸次修行皆得道果，並說明聲聞緣覺聞法得果、證悟後智慧堅固的小樹菩薩如何增長。","p":["佛所說法如海一渧，只是唯一佛乘","三乘是地、法相、人之別，非乘差別","法隨法行，一味之法隨力修行","五乘法皆須漸次修行方得道果","七住至三地滿心前智慧堅固為小樹"],"k":["唯一佛乘","法隨法行","藥草喻品","漸次修行","小樹","如來藏"]},"6600-a26_147":{"s":"本集講解偈頌「復有住禪得神通力，聞諸法空心大歡喜」至「潤於人華各得成實」（講義第七輯第84頁起），說明三地滿心菩薩以無生法忍、道種智成就猶如谷響現觀並起意生身，成為能住持十方佛法的大樹。並引《瑜伽師地論》勸對甚深法先信受不誹謗，檢討三草二木的成就條件，勉勵由上藥草轉為小樹、謹言慎行。","p":["三地滿心成猶如谷響現觀，名為大樹","大樹菩薩能以化身度十方眾生","對未證甚深法應仰推如來、不誹謗","錯誤的二乘法如毒草，非中藥草","小樹勿自滿，業種皆存於如來藏"],"k":["藥草喻品","大樹菩薩","三地滿心","意生身","菩薩性","如來藏"]},"6588-a26_148":{"s":"本集講解〈藥草喻品〉偈頌結尾「今為汝等說最實事：諸聲聞眾皆非滅度；汝等所行是菩薩道，漸漸修學悉當成佛」（講義第七輯第104頁起）。說明三乘是方便施設、本唯一佛乘，引《不退轉法輪經》指釋迦佛因娑婆眾生下劣而分別說三、引入一乘；並總結五種根性，強調依止諸佛與善知識，如來本懷是佛地究竟解脫。","p":["種種因緣譬喻開示佛道皆是方便","聲聞所證非真滅度，所行是菩薩道","引《不退轉法輪經》說分別說三、引入一乘","佛法不演變，三乘根源同一如來藏","二乘解脫是化城，佛地解脫方究竟"],"k":["唯一佛乘","藥草喻品","三乘方便","化城","發菩提心","究竟解脫"]},"6605-a26_149":{"s":"本集以專題方式說明《法華經》所標示的佛教正法即是成佛之法：引「十方佛土中，唯有一乘法」指二乘是方便、須附屬於佛菩提方為佛法，大乘法依涅槃如來藏而說，並批評「大乘非佛說」為謗佛謗法。後段引〈藥王菩薩本事品〉、〈普賢菩薩勸發品〉及印光大師語，介紹聞持《法華經》的功德與感應事例。","p":["佛法分世間、出世間、世出世間法","十方佛土唯一乘法，二乘是方便化城","以〈正覺總持咒〉檢驗說法是否圓滿","大乘依如來藏，因果須如來藏執行","聞持《法華經》一偈一句功德無量"],"k":["唯一佛乘","大乘非佛說","涅槃如來藏","成佛之道","法華功德"]},"6602-a26_150":{"s":"本集說明《法華經》標明行菩薩道者會被授記成佛：從五千增上慢人退席談起，列舉四大弟子授記名號及《法華論》所說六種授記。闡釋「為實施權、開權顯實」，以三車與化城之喻說明會三歸一、勸二乘迴小向大，並強調大乘因果法則與一切眾生皆有佛性；最後講述兩則《法華經》感應故事。","p":["五千增上慢人退席，不堪授記","四大弟子授記名號與六種授記","為實施權、開權顯實，會三歸一","二乘止於化城，佛勸迴小向大","眾生皆有佛性；法華感應事例"],"k":["授記","開權顯實","化城喻","迴小向大","佛性"]},"6616-a27_001":{"s":"本集進入〈授記品〉大目犍連授記段落，先回顧迦葉、須菩提、迦旃延三人的授記，再介紹大目犍連的過往。引《如來不思議祕密大乘經》目犍連度量佛音至光明幢世界的事蹟、《大智度論》鴿入佛影與舍利弗影之事，說明阿羅漢神通遠不及佛；並以琉璃王滅釋迦族、目犍連被執杖梵志打死，說明神通敵不過業力、菩薩畏因。","p":["佛先授記迦葉、須菩提、迦旃延","目犍連測佛音聲，至光明幢世界而懺悔","鴿入舍利弗影仍恐懼，因三毒習氣未盡","琉璃王滅釋迦族，神通敵不過業力","目犍連臨終償宿債；菩薩畏因"],"k":["授記品","大目犍連","神通","業力","習氣種子","菩薩畏因"]},"6627-a27_002":{"s":"本集講解〈授記品〉世尊為大目犍連授記的長行經文：先供養八千佛、再供養二百萬億佛後成佛，號多摩羅跋栴檀香如來。引《舊雜譬喻經》說明目犍連因道眼見八千佛世界起慢，故須先供養八千佛以消慢心，並勸菩薩不宜過早修神通；接著解說佛十號中的「應供」與「正遍知」，佐以拔提布施燋木、舍利弗教錯觀法等事例。","p":["目犍連授記：號多摩羅跋栴檀香如來","因見八千佛世界起慢，須先供養八千佛","菩薩宜至三地將滿心時修禪定神通","應供：供佛福德無量，應迴向求解脫成佛","正遍知：佛知眾生根性而因材施教"],"k":["授記品","大目犍連","如來十號","慢心","神通","布施迴向"]},"6631-a27_003":{"s":"本集續講如來十號，依序解說明行足、善逝、世間解、無上士、調御丈夫、天人師、佛、世尊的意涵，引苦得外道死後為食吐鬼、地神聞法證初果等事例，並批評主張上師勝佛者為大妄語。最後講解大目犍連授記的重頌，指出佛國淨土與成佛者的願力及相應有情有關，舉目犍連國多三明六通聲聞、迦旃延國無阿修羅為例。","p":["明行足、善逝：佛知眾生死因與去向","世間解：了知五陰世間及器世間","無上士、調御丈夫、天人師之義","佛為三覺圓滿者，世尊為凡聖所尊","重頌授記；佛國淨土與願力相應有情相關"],"k":["如來十號","大目犍連","授記品","佛國淨土","三覺圓滿"]},"6620-a27_004":{"s":"本集進入〈化城喻品〉，先說明化城是佛從唯一佛乘析出二乘解脫道，作為二乘人暫時止息處。講解大通智勝如來的長行與重頌：以三千大千世界磨墨點塵之喻形容其滅度久遠，說明世尊威神之力可推知無量劫事（舉老人一句「南無佛」得度、鴿子因緣），並說三轉法輪次第、虛空無盡故佛國淨土無量，以及如來藏無始不生不滅。","p":["化城：二乘法是佛菩提中暫歇處","大通智勝佛滅度久遠，以磨墨點塵為喻","老人一句南無佛種善根，佛知而度之","三轉法輪次第，終令開示悟入佛知見","虛空無盡，佛國淨土無量；如來藏無始"],"k":["化城喻品","大通智勝佛","唯一佛乘","三轉法輪","佛國淨土","如來藏"]},"6622-a27_005":{"s":"本集續講〈化城喻品〉大通智勝佛坐道場十小劫而佛法不現前、諸天雨華擊鼓供養，以及十六王子讚佛請轉法輪的經文。說明十小劫佛法不現前，是因明心後尚未眼見佛性、成所作智未現，並區分明心與眼見佛性；指出成佛前最後供養為最殊勝供養之一。另解釋「大威德」源於福慧與慈悲，批評喇嘛教大威德金剛，並說有佛出世應請轉法輪。","p":["大通智勝佛十小劫佛法不現在前","因未眼見佛性，成所作智未現前","明心與眼見佛性不同","成佛前及入滅前最後供養最殊勝","大威德源於福慧；十六王子請轉法輪"],"k":["化城喻品","大通智勝佛","眼見佛性","成所作智","請轉法輪","十六王子"]},"6633-a27_006":{"s":"本集講解〈化城喻品〉大通智勝佛成道時十方各五百萬億佛世界六種震動、幽冥之處皆大明，以及東方梵天宮殿光明倍常、救一切梵天王說偈共議其因的經文。以天文學與蓮華藏世界海對照，批評大乘非佛說者隨意否定經典；說明六種震動用以警覺大眾、大光明使幽冥眾生互見，並解釋初禪三天及天主有生必滅。","p":["十方各五百萬億佛世界六種震動","以蓮華藏世界海對照天文學所知","判經真偽須依三量，不知者仰推佛菩薩","六種震動警覺大眾，大光照幽冥處","初禪三天；梵王推測天生或佛出世"],"k":["化城喻品","六種震動","大通智勝佛","大梵天王","大乘非佛說","蓮華藏世界海"]},"6641-a27_007":{"s":"本集講解東方五百萬億國土諸梵天王攜宮殿與天華西行，供養大通智勝如來、奉獻宮殿並說偈讚佛的經文。說明供養佛具田勝、施主勝、供物勝、法勝，福德廣大；從大通智勝佛十劫坐道場說明諸佛難值遇，但如理修學者常蒙佛護念，並提及彌勒龍華三會之保證，以及提婆達多在地獄受佛護念之事。","p":["梵天王與宮殿俱來，散華供養佛","供佛具田勝、施主勝、供物勝、法勝","諸佛難值遇，十劫坐道場方成佛","如理修學者蒙佛護念，悟緣有時","佛具無量功德能救護一切，為天人師"],"k":["化城喻品","供養","大梵天王","諸佛難值","佛護念","大通智勝佛"]},"6653-a27_008":{"s":"本集講解東方諸梵天王偈請大通智勝如來轉法輪、如來默然許之，以及東南方五百萬億國土大梵天王見宮殿光明、大悲梵天王說偈並西北而來供佛獻宮殿的經文。說明佛以大慈悲力出世度眾，批評「佛爭一爐香」等說法；解釋佛默然即是應許，並指十方梵王實為同時受光而來，供佛具福田、施者、供物三勝。","p":["梵天王請佛轉法輪，開涅槃道","佛以大慈悲力出世，非爭供養","佛默然即應許，舉居士請佛受供為例","東南方梵王由大悲梵王帶領尋光而來","十方梵王同時受光；供佛具三種殊勝"],"k":["化城喻品","請轉法輪","大梵天王","大慈悲力","供養","大通智勝佛"]},"6648-a27_009":{"s":"本集講解東南方諸梵天王讚大通智勝佛的偈頌：「一百八十劫空過無有佛，三惡道充滿，諸天眾減少；今佛出於世，為眾生作眼，世間所歸趣」。說明無佛時三惡道增、天眾減的道理，佛為人天眼目、能救護一切而為世間所歸趣，越深證越知佛尊貴；並以民間稱神為「爺公」對比「眾生之父」，強調佛不與外道爭，說法如實不是爭。","p":["一百八十劫無佛，三惡道充滿天眾少","佛為眾生作眼，即人天眼目","四聖六凡皆應歸趣如來","如來交代之事應毫不懷疑承擔","佛為眾生之父；如實說法不是爭"],"k":["化城喻品","世間所歸趣","人天眼目","大梵天王","大通智勝佛"]},"6666-a27_010":{"s":"本集講解東南方梵天王偈請「大聖轉法輪，顯示諸法相」及南方五百萬億國土諸梵天王北行供佛、讚「世尊甚難見，破諸煩惱者」的經文。說明唯有如來堪稱大聖，法相須歸八識心王、不可捨離；區分佛法中得道與生天，並解釋見惑、思惑、無始無明、塵沙惑及所知障等煩惱內涵，指佛如優曇缽花難得值遇。","p":["唯如來可稱大聖，借齊天大聖為喻","顯示諸法相，法相皆歸八識心王","得道須三乘實證，生天只是異熟果","破諸煩惱：見思惑、無始無明、塵沙惑","南方梵王百三十劫方見佛，如優曇缽花"],"k":["化城喻品","大聖轉法輪","法相唯識","破諸煩惱","所知障","大梵天王"]},"6650-a27_011":{"s":"本集講解〈化城喻品〉南方梵天王偈請大通智勝如來「轉無上法輪、擊大法鼓」。說明外道與二乘皆非真「安隱」，唯證不生滅的佛菩提心得安隱；區分二乘法輪與無上法輪，並以塗毒鼓、趙州「好殺」說明擊大法鼓即殺盡我見、破無始無明。","p":["外道意識境界生滅，二乘滅盡五陰，皆非真安隱","證佛菩提不生滅法，五陰現前而心得安隱","讀《法華》須明佛說經的時空背景","唯佛菩提道法輪稱無上法輪，二乘非無上","大法鼓塗法毒殺我見，並能破無始無明"],"k":["無上法輪","大法鼓","安隱","我見","佛菩提","大通智勝如來"]},"6668-a27_012":{"s":"本集講解梵天王請佛「吹大法螺、普雨大法雨、度無量眾生、演深遠音」。說明人天善法、二乘與佛菩提法螺的層次，批評誤解禪定與自稱成佛者；指出大菩薩皆仰推如來而無慢，二乘度眾有限，唯佛菩提為深遠音。","p":["人天善法法螺如四禪次第，末法已難得","批評先得四禪、離念即無想定等誤解","能吹大法螺者皆仰推如來，不敢自稱成佛","大法雨須五乘具足；二乘度眾有限易失傳","深遠音唯指須三大阿僧祇劫的佛菩提"],"k":["大法螺","大法雨","五乘","禪定","慢心","度無量眾生"]},"6660-a27_013":{"s":"本集講解上方梵天王尸棄等推尋光明、供養宮殿，並以偈讚大通智勝佛為「救世之聖尊」。講者以三界層次檢視一神教救世主的瞋、慢、血食而判屬欲界鬼神；指出真救世者須能教眾生出三界乃至成佛。","p":["上方梵天王見宮殿光明，下尋見佛並散華供養","偈讚佛能於三界獄中救出眾生、開甘露門","批評一神教救世主瞋慢重、愛血食屬欲界","真救世須教五戒十善、離欲乃至出離三界","能教眾生破無始無明而成佛者方為聖尊"],"k":["救世之聖尊","三界","梵天王","一神教","出離三界"]},"6670-a27_014":{"s":"本集續講「能開甘露門，廣度於一切」，說明成佛之道只有二大甘露法門：解脫道與佛菩提道，並以此檢驗是否證悟或成佛。講者批評假藏傳佛教自稱有佛未說之法；並解釋「無量劫空過無佛，十方暗冥」時惡道增長，佛為世間眼。","p":["救世聖尊不可自稱，大妄語可公開懺悔","二大甘露門：解脫道與佛菩提道，函蓋一切","解脫道如化城，令人確信可出三界再受授記","批評密宗自稱佛未說法、甘露丸等","無佛時三惡道增、阿修羅盛，佛為世間眼"],"k":["甘露門","解脫道","佛菩提道","大妄語","密宗","佛為世間眼"]},"6673-a27_015":{"s":"本集講解上方梵天王迴向「皆共成佛道」及請佛轉法輪、擊甘露法鼓、開示涅槃道之偈。說明真正轉法輪是演說三乘菩提使人斷我見，批評轉經輪之說；闡釋涅槃不生不死、不可演變，四種涅槃，以及「敷演」與「無量劫習法」之義。","p":["梵天王迴向一切共成佛道，顯菩薩種性","轉經輪無人斷我見，演說佛法才是轉法輪","甘露法鼓只毒死黑品法，令我見無明死","涅槃本來不生不死，不可演變","敷是鋪陳、演是解說，須哀愍而敷演"],"k":["轉法輪","涅槃","甘露法鼓","四種涅槃","敷演","總持"]},"6672-a27_016":{"s":"本集講解大通智勝如來受請「三轉十二行法輪」及廣說十二因緣的經文。說明《佛說三轉法輪經》僅講四聖諦，不是指整個成佛之道的三轉法輪；以佛度五比丘為例，解說示轉、勸轉、證轉三次，各具苦集滅道四行，合為十二行。","p":["諸佛初轉法輪必先三轉十二行法輪","《三轉法輪經》僅指四聖諦，非否定大乘","第一轉釋義示現，第二轉勸修：知斷證修","第三轉自我檢驗已知、已斷、已證、已修","成阿羅漢尚缺緣覺功德，須再說十二因緣"],"k":["三轉十二行法輪","四聖諦","十二因緣","五比丘","阿羅漢"]},"6675-a27_017":{"s":"本集探討十二因緣中的「無明」。由老死逆推至無明，說明無明不只是執著五陰，還包括不知名色從何而來；依龍樹八不中道與「諸法不自生、不他生、不共不無因」，論證名色非物生、非上帝生、非根塵共生，而是第八識如來藏所生。","p":["十二因緣逆推：老死、生、有、取、愛至無明","無明含執著五陰，及不知名色所從來","依八不中道與四不生檢驗名色出生之因","名色非物、上帝、虛空或根塵所生，為第八識","斷三縛結見道後，次第斷欲漏、有漏、無明漏"],"k":["無明","十二因緣","名色","八不中道","如來藏","三漏"]},"6677-a27_018":{"s":"本集解說「於諸漏心得解脫」：欲漏以發起初禪為斷除的驗證，有漏以二禪推知上二界而斷五下分結，無明漏即對微細意識自我的我慢。並講三明六通、八解脫與「不受一切法」，以及十六王子童子出家為沙彌、請佛說無上正等正覺法。","p":["二果薄貪瞋癡；斷欲漏須以初禪現前為證","有漏斷除可推知色無色界有，斷五下分結","無明漏即我慢，斷盡則五上分結盡","須不受一切法，方於諸漏心得解脫","十六王子出家為沙彌，請佛說無上菩提法"],"k":["欲漏","有漏","無明漏","心得解脫","十六王子","八解脫"]},"6698-a27_019":{"s":"本集講解大通智勝佛受十六沙彌請，二萬劫後說《妙法蓮華經》，「教菩薩法，佛所護念」，說經八千劫後入定八萬四千劫，由十六沙彌昇座廣說。說明說《法華》前須先講般若與種智，並勸供養諸佛修福，以釋迦答應魔王三月後入涅槃為例。","p":["二萬劫中先說般若、種智，後說《法華》","供養諸佛福德最大，如給孤獨、菴婆婆梨女","阿羅漢信大乘而不解，餘眾生皆生疑惑","佛入定八萬四千劫，待法傳無虞方入涅槃","十六沙彌廣說分別，示教利喜發菩提心"],"k":["教菩薩法","佛所護念","十六沙彌","供養諸佛","入涅槃","福德"]},"6686-a27_020":{"s":"本集講解大通智勝佛出定讚歎十六菩薩沙彌稀有，勸眾親近供養；並說十六沙彌所化眾生世世相隨，如今十六人皆已在十方成佛，包括阿閦佛、阿彌陀佛與釋迦牟尼佛。講者藉銀河系、世界海說明宇宙廣大，勸人放大心量、包容利生。","p":["佛出定讚十六沙彌，令大眾生仰信親近","所化眾生世世與菩薩俱，值四萬億佛","十六沙彌已於八方成佛，第十六為釋迦佛","以銀河系、世界海層次說明宇宙廣大","勸放大心量，除護法外凡事包容"],"k":["十六沙彌","法緣","阿彌陀佛","阿閦佛","世界海","心量"]},"6694-a27_021":{"s":"本集講解釋迦佛為沙彌時所化眾生今仍住聲聞地，須以聲聞法接引而漸入佛道，因「如來智慧難信難解」。說明不知、不覺菩薩所行者會生滅度想；並解釋「我於餘國作佛，更有異名」，指出只有本尊如來才演說《法華經》。","p":["先以聲聞法實證，再對照說佛地境界","各階位不知上位，如來智慧難信難解","實證者知自身定位而不生慢心","知、覺菩薩所行須證實相般若、明五十二位","佛有化身於餘國，唯本尊如來講《法華》"],"k":["如來智慧","聲聞地","菩薩所行","滅度想","化身佛","一佛乘"]},"6700-a27_022":{"s":"本集講解如來示現入涅槃的四個條件：眾清淨、信解堅固、了達空法、深入禪定，具足時才集眾說《法華經》，顯示唯一佛乘得滅度。並說對志樂小法、深著五欲者先說二乘涅槃；最後開講化城喻的「五百由旬險難惡道」。","p":["如來入涅槃四條件，具足方說《法華》","說《法華》令眾知二乘與菩薩的定位","聽聞《法華》種子終令聲聞回入菩薩道","對樂小法、著五欲者先說苦集滅道","成佛之道如險難惡道，以大妄語者為例"],"k":["入涅槃","唯一佛乘","化城喻","二乘涅槃","險難惡道","大妄語"]},"6687-a27_023":{"s":"本集續講化城喻：以悟錯堅持、誤入密宗、只行善不學佛等說明成佛之道「曠絕無人怖畏」，須互相扶持。導師見眾中路懈退，於三百由旬處化作大城，此城即譬喻阿羅漢解脫果；入城後仍須回頭收拾路上珍寶，即斷習氣種子與所知障。","p":["悟錯不改、誤入密宗，顯成佛之道險難","成佛之道少人行，須互相扶持勿作自了漢","如來為導師，善知險道通塞之相","三百由旬處化城，譬喻阿羅漢解脫果","阿羅漢須從初地補修習氣與所知障"],"k":["化城喻","解脫果","阿羅漢","險難惡道","習氣種子","相似佛法"]},"6696-a27_024":{"s":"本集講解導師見眾止息後「即滅化城」，告以寶處在近，說明二乘涅槃是如來方便施設，真正解脫在八地乃至佛地。佛在二轉、三轉法輪為阿羅漢講般若與唯識，猶如所給寶物；並解釋眾生若只聞一佛乘便生怯弱，故「於一佛乘分別說三」。","p":["滅化城：阿羅漢果非究竟，須從初地再修","二轉講般若、三轉講唯識，如佛所給寶物","阿羅漢至授記時才知珍惜這些寶物","弘法難，須方便善巧、善觀時節因緣","眾生怯弱，故佛於一佛乘分別說三乘"],"k":["化城喻","方便施設","三乘菩提","一佛乘","二乘涅槃","般若"]},"6712-a27_025":{"s":"本集說明本來只有一佛乘，三乘是方便。須先令眾實證二乘，再以《法華》授記使人信受。論證二乘無餘涅槃中無人證涅槃，故不真實；明心證本來自性清淨涅槃與八地亦未究竟，唯佛地四智圓明的無住處涅槃為真實。並說不能想像不等於不存在。","p":["弘法須有實證結果，再以授記堅固信心","無餘涅槃中無能觀者，故二乘涅槃不真實","明心、八地所證涅槃仍非究竟","佛地四智圓明、無住處涅槃才是真實涅槃","舉地圓說、日心說，說明難想像不等於不存在"],"k":["一佛乘","真實涅槃","無住處涅槃","二乘涅槃","授記","四智圓明"]},"6702-a27_026":{"s":"本集進入〈化城喻品〉末偈頌，說明偈頌即總持陀羅尼，原為古印度口傳背誦的記憶方便。舉道安、義淨、護法手抄本、《十誦律》譯事對照中印傳承差異；並以《心經》咒依玄奘「五不翻」之祕密故不譯、《實相般若經》的「底唎」，點出陀羅尼可含經文密意。","p":["偈頌是總持陀羅尼，扼要重述前段經文","中國早用統一文字，印度以師誦弟習為主","舉道安、義淨、護法、十誦律說明口傳","陀羅尼原義是濃縮經文以便記憶","《心經》咒依祕密故不翻，含經文密意"],"k":["陀羅尼","總持","偈頌","心經","五不翻","口傳"]},"6723-a27_027":{"s":"本集先提醒後期密教咒語可能借用印度教含義而背離佛法；再批評部分學界與教界據殘本主張《法華經》晚出、「大乘非佛說」，引季羨林、辛島靜志研究指出《法華經》不晚於其他文獻、漢譯早於梵本。並介紹品名梵文意為「往世因緣」，提出大通智勝佛十小劫佛法不現前的問題。","p":["密教化咒語可能暗含性意涵，須慎辨","學術推論隨新證據修正，不宜奉為定論","辛島靜志：《法華》不晚出，漢譯早於梵本","本品梵名意為往世因緣，羅什譯為化城喻","大通智勝佛坐道場十小劫佛法不現前"],"k":["大乘非佛說","學術研究","辛島靜志","化城喻品","大通智勝佛","陀羅尼"]},"6726-a27_028":{"s":"本集續談大通智勝佛十劫坐道場而佛法不現前。引太虛大師解釋為「大道難成」、非眾生可測，評其不知即說不知為保守；批評隨學界主張大乘非佛說的出家人，並述慈航法師與印順法師的分歧及平實導師的辨正。最後說明修證有次第須證轉，圜悟、大慧曾以此題考問天下。","p":["坐道場表示功德圓滿，本應即得四智圓明","太虛大師釋為大道難成，不知即說不知","學術結論常被修正，不應據以謗大乘","慈航駁印順，後由平實導師著書辨正","圜悟、大慧以十劫坐道場考問而無人能答"],"k":["十劫坐道場","大乘非佛說","太虛大師","印順","四智圓明","修證次第"]},"6706-a27_029":{"s":"本集解釋「十劫坐道場佛法不現前」，指出這屬於真見道、十住如幻觀以上才能窺知的境界。說明轉識成智分下、中、上品轉，六七因中轉、五八果上轉；大通智勝佛大圓鏡智已成就而成所作智未現起，十劫後才四智圓明。並說明心與見性不同，見性須善知識、福德與定慧等持。","p":["十劫不現前須真見道、十住如幻觀方能窺見","轉識成智有下、中、上品轉的次第","明心對應大圓鏡智，眼見佛性對應成所作智","大通智勝佛成所作智未現起，十劫後方圓明","明心為體、見性為用，見性須定慧等持"],"k":["眼見佛性","轉識成智","四智圓明","明心","十劫坐道場","成所作智"]},"6703-a27_030":{"s":"本集引《大般涅槃經》師子吼菩薩問佛性，說明十住菩薩可眼見佛性、九地仍有聞見，批評竄改「十住」為「十地」者。接著敘述宋代士大夫入禪及克勤、大慧接引居士，大慧以看話禪起疑情，並嚴斥宏智默照禪令人落入禪寂。最後引平實導師開示：不知佛性境界即無法答十劫坐道場之問。","p":["涅槃經：十住眼見佛性，九地仍屬聞見","宋代士大夫普遍入禪，克勤、大慧廣攝居士","大慧看話禪以疑情為先，參究話頭","大慧斥默照禪為邪禪，宏智僅有初關","不知佛性境界，無法通達十劫坐道場"],"k":["默照禪","看話禪","大慧宗杲","眼見佛性","宏智正覺","十劫坐道場"]},"6727-a27_031":{"s":"本集從平實導師《法華經講義》第八輯開講〈五百弟子受記品〉，解說富樓那聽聞佛說法、授記及宿世因緣後心淨踊躍的經文。並引《佛藏經》、《雜阿含經》、《觀經》介紹富樓那說法第一、往輸盧那弘法的忍辱及為頻婆娑羅王說法等事蹟，最後引《佛藏經》說明釋迦菩薩因住於有所得而未獲諸佛授記。","p":["富樓那聞授記與宿世因緣，心淨踊躍禮佛","《佛藏經》讚富樓那清淨說法、法師第一","大阿羅漢的證量不只如阿含部所顯","富樓那願赴輸盧那弘法，展現忍辱","釋迦菩薩供養無數佛，因有所得未得授記"],"k":["五百弟子受記品","富樓那","授記","有所得","佛藏經","忍辱"]},"6729-a27_032":{"s":"本集續講〈五百弟子受記品〉，依《佛藏經》說明不被授記的癥結在於不能通達諸法實相、貪著計我的有所得見。講者解釋諸法實相即一切法從如來藏出生、歸於如來藏，區分二乘與大乘無生忍，說明釋迦菩薩證無生忍後得錠光佛授記，並介紹顯授記、密授記，且以佛十號檢驗自稱成佛者。","p":["不被授記因不通實相、貪著計我有所得","諸法實相：一切法從如來藏生、歸如來藏","二乘無生忍與大乘無生忍的差別","證大乘無生忍乃得錠光佛授記","授記分顯授記、密授記，各有兩種"],"k":["授記","大乘無生忍","諸法實相","如來藏","無所得","密授記"]},"6731-a27_033":{"s":"本集解說〈五百弟子受記品〉中世尊讚歎富樓那的經文：富樓那於過去九十億佛、七佛及賢劫諸佛座下皆說法第一，內行菩薩道而外現聲聞相，以方便度眾迴小向大。世尊授記其成佛號法明如來，講者說明其國土莊嚴及法喜食、禪悅食，並強調菩薩道須次第修學，批評即身成佛之說。","p":["佛讚富樓那護持助宣佛法、說法第一","富樓那示現聲聞，引眾迴小向大","未來護持無量無邊諸佛之法，心量廣大","授記成佛號法明如來，國名善淨","法喜食、禪悅食；菩薩道須次第而修"],"k":["富樓那","法明如來","授記","法喜食","禪悅食","菩薩道次第"]},"6735-a27_034":{"s":"本集續述法明如來國土的廣大境界，講者據此說明學佛應有遍及十方三世的眼界，批評把佛教侷限於地球的狹義人間佛教，並說明三地滿心後的度眾範圍與歸依十方諸佛。接著解說重頌「內祕菩薩行，外現是聲聞」，說明菩薩以示現三毒、邪見等方便度眾，以及最後身菩薩示現從凡夫修行成佛的用意。","p":["法明如來國土境界非人間所能有","批評把佛教侷限於地球的人間佛教觀","學佛應歸依十方諸佛、放大眼界","重頌：內祕菩薩行，外現是聲聞","佛示現凡夫成佛，為令眾生生信"],"k":["內祕菩薩行外現聲聞","富樓那","人間佛教","十方諸佛","方便示現","法明如來"]},"6737-a27_035":{"s":"本集解說世尊為千二百阿羅漢授記，先授記憍陳如將供養六萬二千億佛後成佛，號普明如來，並引《賢愚經》羼提波梨忍辱仙人與迦梨王的往世因緣，說明其最先得度的緣由。接著講五百阿羅漢同號普明、轉次授記，以及衣裏繫珠之喻，指出他們本是菩薩，聲聞緣覺道只是從一佛乘方便分出。","p":["千二百阿羅漢希望如大弟子般得授記","憍陳如供養六萬二千億佛後成普明如來","忍辱仙人往世因緣，說明憍陳如最先得度","五百阿羅漢同號普明，前佛為後佛授記","衣裏繫珠喻：本是菩薩，得少為足"],"k":["憍陳如","普明如來","衣珠喻","忍辱仙人","一佛乘","授記"]},"6736-a27_036":{"s":"本集概說菩薩與聲聞的差異：聲聞弟子經《法華經》授記，才知自己所證的涅槃只是少分，實際上並未證得本來自性清淨涅槃。講者說明聲聞依四聖諦、八正道修行至四果，滅五陰不再受生，但阿羅漢果在佛菩提道上並非究竟，並以化城喻及憍陳如「得少涅槃分」偈說明唯有成佛才是究竟。","p":["授記使聲聞知所證涅槃只是少分","聲聞依四聖諦、八正道修證四果","阿羅漢果只暫滅五陰受生，並非究竟","化城喻：中途安止，尚未到寶所","憍陳如偈：得少涅槃分，便自以為足"],"k":["聲聞","四聖諦","阿羅漢","化城喻","本來自性清淨涅槃","授記"]},"6739-a27_037":{"s":"本集續談菩薩與聲聞，從憍陳如、阿難的授記說明成佛時劫極為長遠。講者區分真實法與虛妄法：能出生三界一切法的根源是真實法，無常生滅的現象界法是虛妄法；未證真實法即如處長夜，須依佛菩薩慈悲教化。並解說《法華經》偈「世尊於長夜，常愍見教化，令種無上願」的意涵。","p":["成佛須供養無數佛，時劫極為長遠","真實法是三界一切法的根源","現象界法無常生滅，是虛妄法","未證真實法，如生於漫漫長夜","佛於長夜慈愍教化，令弟子種無上願"],"k":["真實法","現象界","長夜","慈悲教化","無上願","授記"]},"6747-a27_038":{"s":"本集說明阿難受授記供養六十二億佛即成佛、時劫較短的兩個原因：慈悲攝受眾生，以及發願憶持諸佛法藏，讓佛法得以結集流傳。講者解說阿難成佛號山海慧自在通王佛的經文，指出法藏是修學與印證的依據，可使眾生信受第八識如來藏真實法，並勉勵菩薩為眾生宣講佛法。","p":["阿難成佛時劫短，因慈悲與持法藏","阿難憶持佛法，使經典結集流傳後世","授記成佛號山海慧自在通王佛","法藏是印證所悟、令眾生信受的依據","菩薩應以佛法利益眾生、為眾宣講"],"k":["阿難","持法藏","山海慧自在通王佛","授記","如來藏","弘法利生"]},"6740-a27_039":{"s":"本集開講〈法師品〉，依《雜阿含經》說明聲聞法中的法師是為人說五陰應生厭、離欲、滅盡、寂靜者，契合三法印，不一定是出家人。講者批評主張意識或離念靈知常住者不符法師定義，並說明儀式主法不說法、或僅持戒而不說法也不算法師，再引《長阿含經》〈梵動經〉說明持戒只是小緣，佛的甚深大法能照破六十二見。","p":["《雜阿含》：說五陰生厭離欲者名法師","五陰無常正觀，對應三法印","主張意識常住者違背聖教，非法師","持戒是基礎，但不說法不算法師","〈梵動經〉：戒行是小緣，大法破六十二見"],"k":["法師品","法師","五陰","三法印","持戒","六十二見"]},"6744-a27_040":{"s":"本集說明為何講大乘〈法師品〉要先強調聲聞法的法師定義：三法印與實相印並不衝突，五陰攝歸如來藏時即離常與無常二邊，並引鏡與影像之喻說明。講者指出阿含已隱說本識，如「齊識而還」；修佛菩提須先斷我見，批評六識論者同時落入增益執與損減執，並說明一切種智與無餘涅槃都依如來藏而成立。","p":["三法印印小乘，實相印印大乘，不相違","鏡影喻：五陰攝歸如來藏即離二邊","阿含已說本識，如「齊識而還」","不斷我見而求明心，必落入意識","六識論者雙具增益、損減二執"],"k":["三法印","實相印","如來藏","斷我見","六識論","一切種智"]},"6755-a27_041":{"s":"本集說明大乘法師所說須契合實相印，並依平實導師講義指出〈法師品〉的法師是佛滅後能為人解說《法華經》者。講者歸納第一個條件：聽聞《法華經》一偈一句乃至一念隨喜，即得佛授記，並引《瑜伽師地論》法印與隨喜得聖財之說，說明隨喜代表菩薩種性已發起，也略述《法華經》會三歸一的主旨。","p":["大乘法師所說法義須契合實相印","〈法師品〉法師：佛滅後解說《法華》者","第一條件：聞《法華經》一念隨喜","隨喜即種下佛菩提種子、發起菩薩種性","《法華經》主旨在會三乘方便入一乘"],"k":["法師品","一念隨喜","菩薩種性","實相印","授記","會三歸一"]},"6746-a27_042":{"s":"本集先依《瑜伽師地論》歸依四緣，比較三歸依所發的菩提心與聽聞《法華經》隨喜而發起菩薩種性在層次上的差異。接著講法師的第二個條件：受持、讀誦、解說、書寫《妙法華經》，對照《金剛經》相近經文，說明「此經」指第八識如來藏，此類法師通常已證悟。最後檢討釋印順把「此經」解為般若性空法門，講者認為有母女互生的矛盾。","p":["三歸依發心與隨喜發起菩薩種性層次不同","第二條件：受持讀誦解說書寫《法華》","《金剛經》亦說受持此經功德無量","「此經」指第八識如來藏，通常須證悟","批評釋印順以般若性空法門解「此經」"],"k":["受持讀誦","此經","如來藏","三歸依","金剛經","釋印順"]},"6759-a27_043":{"s":"本集續論法師第二條件，引平實導師講義及《大法鼓經講義》自序，說明受持以實證為前提，諸經所說「此經」多指第八識如來藏。講者以《大乘起信論》本覺、始覺、究竟覺之說，駁斥把釋印順「老般若」等同如來藏的類比，並引《大寶積經》「勿說此經」證明「此經」並非指經典文字，最後提到凡夫講《法華經》也應隨喜讚歎。","p":["受持以勝解為前提，勝解源自實證","諸經所說「此經」多指第八識如來藏","《起信論》：始覺、究竟覺皆不離本覺","駁以「老般若」比附如來藏的說法","凡夫講《法華經》亦應隨喜讚歎"],"k":["此經","如來藏","本覺","大乘起信論","釋印順","法師"]},"6761-a27_044":{"s":"本集講〈法師品〉佛滅後說《法華經》的三個條件：入如來室、著如來衣、坐如來座，講者指出不可依文解義理解為出家登座即可。「時時令說法者得見我身」是指見法身如來藏，而非幻見的佛身、定中化身或報身；如來室即大慈悲心，如來衣即柔和忍辱心，如來座即一切法空，其真實義留待下集。","p":["說《法華》三要件：如來室、衣、座","依文解義理解三要件，恐誤導眾生","「得見我身」即見法身如來藏","如來室：對不信者亦起大慈悲心","如來衣：柔和忍辱，破邪而不起瞋"],"k":["如來室","如來衣","如來座","法身","一切法空","法師品"]},"6757-a27_045":{"s":"本集解說「如來座者，一切法空是」：法空分二種，二乘從現象法界觀緣起性空，大乘菩薩證實相法界的如來藏。講者引《大般若經》「真如雖生諸法而真如不生」說明法身與真如之義，指出否定本識的緣起性空會成為斷滅空，並引阿含「齊識而還」、「有因有緣集世間」，批評釋印順與琅琊閣的六識論見解。","p":["法空分二乘現象界與大乘實相界兩種","真如雖生諸法而不生，名為法身","大乘一切法空：諸法攝歸如來藏","否定本識的緣起性空即成斷滅空","阿含說「齊識而還」，本識為諸法根本因"],"k":["一切法空","真如","緣起性空","本識","斷滅空","六識論"]},"6749-a27_046":{"s":"本集續講一切法空的真實義，講者批評釋印順否定第八識後，緣起性空變成等同外道的緣生性空斷滅見。依其解釋，「若見緣起便見法」的見法，是見諸法本源的第八識；緣起性空只是所顯法，不能生法。講者並說明中道與眾生平等應依如來藏而說，評述印順「大乘非佛說」對當代及南傳法師的影響。","p":["否定第八識的緣起性空即成緣生性空","「見緣起便見法」的法指第八識如來藏","緣起性空是所顯法，不能出生諸法","中道、眾生平等皆依如來藏而說","批評印順「大乘非佛說」的影響"],"k":["緣起性空","見緣起即見法","大乘非佛說","釋印順","眾生平等","如來藏"]},"6754-a27_047":{"s":"本集解說偈頌「是經難得聞，信受者亦難」，講者指出「是經」是如來藏妙法即第一義諦，難在值遇能依此妙法說《法華》的真善知識，且信眾多以出家身相簡擇，致使信受者少。並引《長阿含經》說明佛先說施論、戒論、生天之論再說四聖諦的次第說法，以穿鑿高原求水之喻說明漸近法水，勸人親近真善知識。","p":["「是經」指如來藏妙法，即第一義諦","難遇能依如來藏說《法華》的善知識","信眾多以出家身相簡擇，故信受者難","佛次第說法：施論、戒論、生天之論","穿鑿求水喻：見濕土知近法水"],"k":["是經難得聞","如來藏","第一義諦","次第說法","穿鑿求水喻","真善知識"]},"6750-a27_048":{"s":"本集解說「不聞《法華經》，去佛智甚遠；若聞是深經，決了聲聞法」，說明三乘五乘皆從一佛乘分出，菩薩證如來藏後於相見道完成諸現觀，入地前即具大乘阿羅漢果證，而二乘阿羅漢離佛智仍遠。講者對比四宏誓願、十無盡願與二乘心量，批評「大乘非佛說」與密宗之說，並引玄奘《成唯識論》「實我若無」破斷滅空見。","p":["三乘、五乘皆從唯一佛乘分析而出","證此經可決了聲聞法，漸次通達","阿羅漢不證如來藏，離佛智甚遠","菩薩發四宏誓願、十無盡願度眾","玄奘：實我若無，何有憶識恩怨"],"k":["決了聲聞法","實我","一切法空","十無盡願","大乘非佛說","成唯識論"]},"6763-a27_049":{"s":"本集開講〈見寶塔品〉，先說明佛出生、得道、初轉法輪、入涅槃四處建塔的因緣，再逐句解說七寶塔從地踊出的經文義理。講者以塔高五百由旬表佛法崇高，縱廣表廣大，從地踊出表佛法依三界境界相建立，住在空中表非凡夫所及且無所住，五千欄楯表菩薩五大階段，龕室千萬表果德無量，幢幡表福德。","p":["建塔四因緣：出生、得道、轉法輪、涅槃","塔高五百由旬，表佛法深妙崇高","從地踊出：佛法依三界境界相建立","五千欄楯表十信至十地五大階段","龕室表果德無量，幢幡表福德圓滿"],"k":["見寶塔品","七寶塔","多寶如來","菩薩階位","福德莊嚴","建塔因緣"]},"6770-a27_050":{"s":"本集續解〈見寶塔品〉：瓔珞表菩薩本業，寶鈴表法音引十方菩薩，栴檀香表戒德功德香；三十三天表三賢三十心與三類聖位，曼陀羅華表赤誠之心。講者解釋多寶如來讚歎世尊「以平等大慧教菩薩法」，平等法即真如，說明《法華經》是菩薩法，並指寶塔出現為證前啟後，也隱喻各人身中的多寶如來，證悟即得親見。","p":["瓔珞表菩薩本業，寶鈴表法音遠播","栴檀香表戒香，能逆風遍飄世界","三十三天表三賢三十心及三類聖位","平等大慧即真如，《法華》是菩薩法","寶塔證前啟後，喻身中多寶如來"],"k":["見寶塔品","多寶如來","平等大慧","真如","證前啟後","瓔珞"]},"6768-a27_051":{"s":"本集講解〈見寶塔品〉四眾見寶塔住空、大樂說菩薩請問寶塔從地踊出及發聲因緣一段。講者以理解釋：「地」指境界，寶塔從地踊出喻破無始無明而見如來藏，「住在空中」表分明不再遮隱；並以能仁、寂靜解釋「釋迦牟尼」為自心真如的體性。","p":["「從地踊出」喻如來藏從自身境界中顯現","破無始無明後，寶塔「住在空中」分明現前","初悟者「怪未曾有」，推究不出如來藏源頭","如來藏不可增損，故只能「卻住一面」","釋迦牟尼即能仁、寂靜，喻自心真如"],"k":["七寶塔","多寶如來","如來藏","無始無明","大樂說菩薩","見寶塔品"]},"6775-a27_052":{"s":"本集講解佛答大樂說菩薩：寶塔中有多寶如來全身，其因地發願凡十方說《法華經》處，寶塔必踊現作證並讚善哉。講者依序說明三問的答覆，並以理解釋菩薩每世依「地」（三界境界相）重建七寶塔（五陰身心），如來藏全身住於其中；大樂說請見佛身，則引出見多寶如來需有條件。","p":["多寶如來因地發願：說法華處寶塔必踊現作證","臨滅度囑起大塔，為七寶塔由來","菩薩世世依地重建、莊嚴自己的七寶塔","每人如來藏皆「全身」住於五陰塔中","大樂說請見佛身，見多寶如來需有條件"],"k":["多寶如來","誓願","七寶塔","如來藏","五陰","見寶塔品"]},"6773-a27_053":{"s":"本集講解多寶佛深重願：欲示其身，說法華之佛須召集十方分身諸佛，以及佛放白毫光照見十方諸佛來集。講者說明值佛、聞法華等諸難；以理解釋參禪須收攝一切心所、不向外攀緣，方能見自心多寶如來；並據此說明說法華者是應身佛，化身佛不說此經。","p":["多寶佛願：分身諸佛全集方現全身","值佛、聞法華、能讚歎等皆極難","白毫光照十方國土，喻種子流注清淨莊嚴","參禪須收攝一切心所，不向外攀緣","說法華者是應身佛，化身佛不說此經"],"k":["多寶如來","分身諸佛","應身佛","化身佛","參禪","白毫相光"]},"6764-a27_054":{"s":"本集講解娑婆世界變為清淨、諸佛各至寶樹下師子座，及釋迦佛八方更變國土以容分身諸佛的經文。講者以譬喻解釋：釋迦牟尼佛喻五蘊，多寶如來喻如來藏，寶樹喻法聚，化身佛喻心所法，黃金為繩界八道喻八正道；並說明悟後須令各類法聚清淨、除惡道種子，是悟後進修之道。","p":["經中譬喻：五蘊、如來藏、法聚、心所法","黃金為繩界八道，喻成佛唯八正道","成佛境界中無世界、無有情的莊嚴相","寶樹高五百由旬，喻諸法聚平等","變化清淨國土，喻除惡道種子、悟後進修"],"k":["譬喻","如來藏","法聚","八正道","心所法","悟後進修"]},"6785-a27_055":{"s":"本集講解釋迦佛為諸佛當來坐復變八方國土、十方分身諸佛來集坐於八方、遣侍者問訊並請開寶塔一段，先釋經文字義，再說隱含譬喻。講者以八方喻七識加色身，化佛全集喻如來藏一切功能差別具足現行；並說明化身佛遣侍者問訊，顯示化身佛的尊貴。","p":["再變八方國土，皆清淨無三惡道與阿修羅","十方化身佛來集，坐寶樹下師子座","八方喻七識加色身，再加上下為十方","化佛全集喻如來藏一切功能差別現行","遣侍者捧寶華問訊，顯化身佛尊貴"],"k":["分身諸佛","化身佛","八方","如來藏","功能差別","譬喻"]},"6777-a27_056":{"s":"本集續講化身諸佛遣侍者問訊「少病、少惱，氣力安樂」並請開寶塔一段的譬喻。講者引《維摩詰經》說明應身如來因感應五濁眾生受生而示現病惱，並批評以「憐愍故病」解釋的說法；又以合集化佛開塔喻成佛時統合一切心、心所觀察無垢識，指出經文顯示諸佛有分身、滅度非斷滅空。","p":["化佛遣侍者供養，喻悟後以心所朝禮法身","應身佛感應五濁眾生受生，故示現病惱","問訊座下菩薩、聲聞，顯其尊貴","同開寶塔，喻成佛時合集心所觀無垢識","古佛今佛互證：諸佛有分身、非斷滅"],"k":["化身佛","應身佛","維摩詰經","無垢識","斷滅空","分身諸佛"]},"6783-a27_057":{"s":"本集講解釋迦佛住虛空以右指開七寶塔戶，眾見多寶如來全身不散如入禪定、二佛分座，及佛問誰能於娑婆廣說此經一段。講者引六祖「開示悟入」，說明開塔喻參禪理合而破參、一剎那全體見如來藏；「如入禪定」則喻如來藏不出不入，非世間禪定。","p":["經文字義：開塔、讚善哉、分半座、付囑","六祖以開示悟入概括法華要旨","以右指開塔戶，喻參禪理合即開悟","見如來藏是一剎那全體同見","「如入禪定」：如來藏不出不入，非四禪八定"],"k":["開七寶塔","多寶如來","開示悟入","參禪","如來藏","禪定"]},"6781-a27_058":{"s":"本集續講多寶如來讚釋迦佛快說法華、開塔分座及接眾至虛空等經文的譬喻。講者以釋迦牟尼佛喻自己的五陰（能仁、寂靜至佛地方圓滿），多寶如來喻本來涅槃的如來藏；並以開塔見多寶如來對應「開佛知見」，二佛同座、接眾入虛空對應「示佛知見」。","p":["釋迦牟尼喻五陰，多寶如來喻如來藏","能仁屬五陰，絕對寂靜須至佛地","如來藏本無生死，即久已滅度之佛","開塔見多寶如來為「開佛知見」","分半座、接眾入虛空為「示佛知見」"],"k":["開佛知見","示佛知見","開示悟入","五陰","如來藏","無垢識"]},"6788-a27_059":{"s":"本集探討「諸法因緣不雜亂」，說明諸法皆由如來藏直接或間接出生，故能正確解釋因緣果報與法住法位。講者引《入楞伽經》、《瑜伽師地論》、《成唯識論》說明非無因說、能取可取皆自心所現、「定異」無雜亂性，唯異熟第八識能建立染淨因果；並批評六識論及造物主、冥性等說。","p":["如來藏難信，禪宗公案並非無頭公案","依根本因如來藏說緣起，不無因、不雜亂","能取、可取皆自心所現，無真實體性","法住法位、定異：諸法依因果各安其位","唯異熟第八識能持種、建立染淨因果"],"k":["如來藏","因緣","法住法位","異熟識","八識論","因果"]},"6778-a27_060":{"s":"本集探討「他圓滿」，說明修學佛法除自身努力外，外在環境亦極重要。講者引《法華經講義》「化長劫入短劫」及《瑜伽師地論》，解說諸佛出世、說正法教、法教久住、法住隨轉、他所哀愍五項，強調須依有實證的善知識受教授教誡；並介紹五濁惡世修學的六種方便善巧，勸珍惜現代聞法因緣。","p":["值遇善知識可化長劫入短劫","多劫無佛出世，正法難聞應珍惜","他圓滿五項：諸佛出世至他所哀愍","法住隨轉須證正法者教授教誡","依內修證佛法的六種方便善巧"],"k":["他圓滿","善知識","正法久住","方便善巧","瑜伽師地論","五濁惡世"]},"6791-a27_061":{"s":"本集探討「發願令正法久住」，指出令此經久住的第一步是自己先實證。講者引《大般若經》發菩提心、護持正法、如教修行「三事最為無上」，說明穢土護法功德大，並介紹初地十無盡願與增上意樂清淨；又強調須以抉擇慧分辨正說與邪說，並引《大智度論》「願如御者」說明發願的重要。","p":["令正法久住，第一步要自己先實證","發菩提心、護持正法、如教修行三事無上","穢土須臾護法，勝淨土一劫功德","初地十無盡願須增上意樂清淨","須抉擇所護持者是否正法；願如御者"],"k":["發願","護持正法","十無盡願","增上意樂","菩提心","正法久住"]},"6795-a27_062":{"s":"本集探討「修學安忍方便」。講者引《法華經講義》以猛風吹小樹成大樹，喻菩薩應接受磨練，並主張對落入邪見者應方便指正、不可姑息；說明以五陰無我、無我所及內相分觀行修忍，並須數數觀行轉變意根；指出憍慢、瞋、癡為修忍障礙，法上之忍是「忍可」而非強忍。","p":["菩薩如小樹須經猛風，才成棟梁","對邪見者應方便指正，不可鄉愿姑息","觀五陰無我及內相分，於諸塵無所傷","意根煩惱須數數觀行，漸次轉變","憍慢瞋癡為障礙；法忍為忍可非強忍"],"k":["忍辱度","安忍","五陰無我","內相分","意根","法忍"]},"6800-a27_063":{"s":"本集探討「分辨邪正」。講者引《大乘廣百論釋論》「智與愚異謂識是非」、「應以大乘摧邪立正」，說明須把正邪對比講清楚才能救護眾生，且須以親證如來藏為依據；並引經論說明邪見成因與善知識守護之德，指出障礙破邪顯正將招愚鈍報、與無明相應。","p":["智愚之別在能辨是非，應摧邪立正","錯說法義難辨，須明確對比正邪","破邪顯正須以證空性如來藏為依據","邪見由親近惡知識、不如理作意而起","障礙破邪顯正將招愚鈍報"],"k":["破邪顯正","邪見","善知識","無明","愚鈍報","如來藏"]},"6792-a27_064":{"s":"本集先回顧〈見寶塔品〉前段，再語譯世尊重宣偈：多寶佛常遊十方為是經故，及佛滅後於惡世說、書、讀、持此經為難等。講者歸納四個重點，本集說明第一點：多寶如來即有情真心，在五陰七寶塔中流轉三界；並引《楞伽經》、《華嚴經》等說明真心與佛地無垢識自性無別，唯因地有染。","p":["回顧寶塔踊出、化佛來集、開塔分座","偈頌語譯：諸難事中說持此經最難","四重點：真心流轉、供佛、發願、說法華","真心名號雖多，與佛地無垢識無別","眾生煩惱身中有如來藏，自性清淨而有染"],"k":["見寶塔品","多寶如來","真心","如來藏","心佛眾生三無差別","無垢識"]},"6789-a27_065":{"s":"本集續講〈見寶塔品〉偈頌第二重點：供養諸佛稀有難得，可培大福德。講者以優曇缽花、過去七佛說明佛世難遇，引《優婆塞戒經》說佛為無量報福田；並從十信位起，說明菩薩依次修布施、持戒、忍辱、精進、禪定各度所需福德，並提及無相憶佛拜佛的動中定。","p":["佛出世如優曇缽花，供佛應具恭敬心","供佛得無量報，佛為大福田","十信位須經一劫至萬劫方成就","布施四利益；菩薩種性由善業因緣成就","持戒、忍辱、精進、禪定依次圓滿"],"k":["供養諸佛","福德","十信位","六度","菩薩種性","動中定"]},"6798-a27_066":{"s":"本集續講菩薩各階位修行與福德：具足三資糧後依善知識參禪，找到第八識並以《心經》印證，轉依成第七住明心菩薩，並以退轉者為例說明疑見未斷之害。接著說明眼見佛性所需定、慧、福德及如幻觀，十行位陽焰觀、十迴向位如夢觀，以及入初地前的阿羅漢證量與勇發十大願。","p":["具足福德、定力、慧力三資糧方能證悟","證第八識，以《心經》現觀非一非異","未心得決定者易退轉，評論正法成謗業","眼見佛性須更深定力與廣大福德","十行陽焰觀、十迴向如夢觀，發十大願入初地"],"k":["明心","眼見佛性","般若度","如幻觀","陽焰觀","如夢觀"]},"6807-a27_067":{"s":"本集續說菩薩從初地至十地、等覺、妙覺的修行歷程，說明各地所行波羅蜜、所斷隨眠及所證現觀，如鏡像、光影、谷響、水中月、變化所成、似有非有、犍闥婆城，以及意生身、滅盡定等。講者藉此說明每一階位皆須修集更廣大福德，等覺百劫修相好，故佛是大福田。","p":["初地至十地各行一波羅蜜並斷隨眠","各地現觀：鏡像、光影、谷響、水中月等","七地滿心佛授引發如來無量妙智三昧","十地受職灌頂，等覺百劫修相好","佛一毛功德即等於眾生功德總和"],"k":["十地","現觀","道種智","意生身","福德","大福田"]},"6802-a27_068":{"s":"本集講〈見寶塔品〉偈頌第三、四重點。第三，菩薩應發通願與成佛別願，舉阿彌陀佛、釋迦如來、彌勒、地藏、迦旃延、富樓那的本願為例。第四，菩薩應發願宣講《法華經》，講者逐一解釋演說、暫讀、受持、解義趣、奉持五難，並批評六識論者與「大乘非佛說」的主張。","p":["通願即四宏誓願，別願為成佛本願","舉阿彌陀、釋迦、彌勒、地藏等本願","願越廣，佛國越大、所需時劫越長","法華五難：演說、暫讀、受持、解義、奉持","發願宣講法華，福德速集、成佛較快"],"k":["發願","本願","法華五難","佛國淨土","四宏誓願","見寶塔品"]},"6811-a27_069":{"s":"本集講解〈見寶塔品〉重頌結尾「此經難持，若暫持者……是則勇猛，是則精進」。講者說明受持此經即受持如來藏，勇猛、精進是不畏生死、世世以四攝法攝受眾生；引《大寶積經》、阿難誓願、《說無垢稱經》說明攝受眾生即攝受佛土，並以三個建築工人的故事作譬喻。","p":["暫持此經，諸佛歡喜讚歎","真受持非依文解義，乃受持如來藏","以四攝法長劫攝受眾生即菩提道","攝受眾生即攝受佛土，不必急於成佛","菩薩不畏世世生死，異於定性聲聞"],"k":["勇猛精進","攝受佛土","四攝法","受持法華","如來藏","定性聲聞"]},"6809-a27_070":{"s":"本集續講受持《法華經》者為何是持戒、行頭陀者。講者舉光明婆羅門以大悲心娶伽吒的本生故事，說明先利眾生、後成就自己，並指成佛最難修集的是福德；又從理上說明依真如、佛性受持此經，懂戒相開遮、忍受被誤解，即真持戒與頭陀行，能解其義者為「諸天人世間之眼」。","p":["光明婆羅門本生：以大悲心成滿眾生","成佛最難修集的是福德而非智慧","依真如佛性受持，堅持不退為勇猛","懂戒相開遮，不被戒相綁死為真持戒","能解此經真義者是諸天人世間之眼"],"k":["持戒","頭陀行","攝受眾生","真如","佛性","開遮"]},"6801-a27_071":{"s":"本集說明受持《法華經》即是受持「此經」如來藏，並總持一切佛法。引《楞伽經》、《金剛經》、《華嚴經》、《大寶積經》等，指出大乘經典以如來藏為貫串主軸；依《大般若經》〈付囑品〉解說受持此經的十種法，並批評釋印順把讀誦受持「神祕化」及大乘分系之說。","p":["諸經所說「此經」多指如來藏法義","一切菩薩無上正等正覺皆屬此經","受持此經十法：書寫、供養至修習","法供養為最第一的供養","批評大乘三系、四系及大乘非佛說"],"k":["如來藏","受持此經","十種受持法","法供養","大乘非佛說","釋印順"]},"6803-a27_072":{"s":"本集講解〈提婆達多品〉開頭經文：釋迦往昔為國王，捨位奉事仙人千年以求《妙法蓮華經》。並依《增壹阿含》、律部、《大方便佛報恩經》等敘述提婆達多出佛身血、破僧、墮無間地獄卻如三禪樂，說明他是示現因果與「禪定神通非解脫」的逆行菩薩，前身即為佛說法華的仙人。","p":["釋迦往昔為王，捨國奉仙人千年求法","提婆達多與阿闍世謀新佛新王","地獄中如三禪樂，示現惡業必報","示現四禪五通不能免生死與惡業","千年講法華的仙人即提婆達多前身"],"k":["提婆達多","逆行菩薩","提婆達多品","因果業報","禪定神通","求法"]},"6817-a27_073":{"s":"本集講解〈提婆達多品〉重頌：國王不貪五欲，為眾生求大法而奉事阿私仙。說明唯有《妙法蓮華經》才是真正的「大法」，因其顯示佛地境界與授記等佛不共菩薩之處；聽聞如實演說的法華，可知成佛不易，未來證悟時不致自認成佛而犯大妄語。","p":["國王為眾生而非為己求大法","《金剛經》、般若、種智皆未足稱大法","法華顯示佛地境界，如授記與多寶證明","阿私仙意為無比仙、莊嚴仙","聽法華種下知佛地遙遠的種子"],"k":["大法","佛地境界","授記","阿私仙","大妄語","即身成佛"]},"6815-a27_074":{"s":"本集講解提婆達多為佛之善知識、被授記為天王如來的經文，及聞〈提婆達多品〉淨心信敬可不墮三惡道。重點說明「具足六波羅蜜」：六度須次第修學，不可只修般若；以早期學人未修前五度即開悟而退轉為例，並指出成佛所需功德極多，批評自稱成佛、四地菩薩者。","p":["因提婆達多善知識，佛具足六度諸功德","授記提婆達多成天王如來","六度須次第修，不能只修般若","前五度未具足而開悟易退轉、生慢","三地滿心猶如谷響觀，駁自稱地上菩薩"],"k":["六波羅蜜","提婆達多品","天王如來","淨心信敬","退轉","次第修行"]},"6821-a27_075":{"s":"本集續講〈提婆達多品〉，說明圓滿六度入地後仍須修四無量心、等覺百劫修相好方成正等覺，提婆達多的逆行真相須到法華時才揭曉。以法難促成《燈影》為例說逆行者的作用，並解析天王如來二十中劫住世、天道世界、恆河沙眾得阿羅漢、無量眾不退轉等授記內容。","p":["三地滿心須四無量心，等覺百劫修相好","逆行菩薩真相須最後才揭曉","法難促成《燈影》及八識論的楷定","提婆達多一無量劫可成佛，顯其證量","天王佛住世及正法各二十中劫"],"k":["逆行菩薩","天王如來","百劫修相好","授記","四無量心","八識論"]},"6824-a27_076":{"s":"本集說明聞〈提婆達多品〉淨心信敬不疑者，生生不墮三惡道、生十方佛前、蓮華化生。接講智積菩薩請多寶佛還歸本土、文殊師利從龍宮踊出一段，討論多寶如來「滅度」實為無住處涅槃，並說明應身佛四種不可思議尚未示現完畢，故留多寶佛；千葉蓮華唯佛方坐，顯文殊非等閒。","p":["淨心信敬不疑者永離三惡道","多寶如來滅度與否：無住處涅槃","引《央掘魔羅經》說釋迦永不滅度","四種不可思議：佛、法、僧、佛土","文殊坐千葉蓮華，先禮二世尊"],"k":["淨心信敬","無住處涅槃","四種不可思議","文殊師利","多寶如來","千葉蓮華"]},"6813-a27_077":{"s":"本集以文殊不能令女人出定、罔明菩薩一彈指即出定的典故，說明眾生須與相應層次的菩薩親近。接著解說智積問文殊所化眾生數目、無數菩薩從海踊出，他們已滿六度至少為七地菩薩；智積偈讚「演暢實相義，開闡一乘法」，顯示菩薩僧與佛土不可思議，並將三乘歸結於唯一佛乘。","p":["文殊與罔明菩薩出女人定的典故","凡夫較易親近初地菩薩","從海踊出菩薩已滿六度，至少七地","讚文殊即讚釋迦，喻如水漲船高","三乘、五乘皆歸一佛乘"],"k":["文殊師利","智積菩薩","一佛乘","菩薩僧不可思議","六度波羅蜜","罔明菩薩"]},"6819-a27_078":{"s":"本集說明佛陀先說施論、戒論、生天之論再說四聖諦的說法次第，指出唯一佛乘不易宣說。接講文殊言於海中唯說《法華經》，智積問有無修此經速成佛者，文殊舉八歲龍女，逐句解說其利根、得陀羅尼（以粽子綱喻總持）、慈念眾生如赤子、慈悲仁讓、志意和雅等功德。","p":["施論、戒論、生天之論的說法次第","文殊於海中唯說《法華經》","陀羅尼即總持，旋陀羅尼能運轉","慈念如赤子、仁讓不爭，駁佛爭供養說","佛不妄笑；文殊說龍女能至菩提"],"k":["龍女","陀羅尼","一佛乘","文殊師利","慈悲仁讓","施論戒論生天之論"]},"6826-a27_079":{"s":"本集開講龍女成佛：智積不信龍女須臾成佛，龍女現前以偈讚佛並自言成菩提唯佛證知。講者提醒此品示現四種不可思議，批評以龍女成佛否定法華或轉為男女平等議題者；並回顧從〈方便品〉至〈提婆達多品〉的經文脈絡，說明文殊再度出現的因緣及《妙法蓮華經》甚深微妙。","p":["智積質疑，龍女現前偈讚佛","批評否定法華及男女平等式解讀","地上菩薩可隨願示現女身","回顧〈方便品〉至〈提婆達多品〉要旨","妙法蓮華喻如來藏能生萬法"],"k":["龍女成佛","四種不可思議","提婆達多品","大乘非佛說","如來藏","一佛乘"]},"6835-a27_080":{"s":"本集續講文殊「我於海中唯常宣說《妙法華經》」，說明「常」為始終如此，藉龍宮無數大菩薩顯示釋迦佛土與法不可思議，娑婆非僅穢土。接著解說龍女「善知眾生諸根行業」，引《瑜伽師地論》說善、惡、無記業；並詳述禪定、未到地定、根本定及安住、引發、辦事三種靜慮。","p":["「唯常宣說」指始終只說法華","龍宮菩薩顯釋迦佛土不可思議","智積與文殊一問一答共演大戲","善、惡、無記三業與工巧處業","未到地定、根本定與三種靜慮"],"k":["佛土不可思議","龍女","三種靜慮","未到地定","善惡無記業","瑜伽師地論"]},"6840-a27_081":{"s":"本集解說龍女「深入禪定」至「能至菩提」諸功德：依《伽耶山頂經》判其屬一生補處發心，慈念眾生如赤子、心念口演、慈悲仁讓，顯為妙覺勝義菩薩僧。接講智積「釋迦如來無量劫難行苦行、積功累德」，說明積功為自受用、累德為他受用，並舉捨身飼虎、度外道等難行苦行。","p":["龍女屬一生補處菩薩發心","慈念赤子、四無礙辯等功德","龍女顯示勝義菩薩僧不可思議","積功為自受用，累德為他受用","菩薩難行苦行非外道苦行"],"k":["龍女","積功累德","難行苦行","勝義菩薩僧","一生補處","慈悲"]},"6830-a27_082":{"s":"本集講解智積「無有如芥子許非是菩薩捨身命處」及「不信此女須臾成佛」，以劫數計算說明三大阿僧祇劫捨身之多與成佛之難，證量越高越覺佛地難思。接講龍女偈讚「深達罪福相，遍照於十方」，解為豎窮種智與廣通權智，並引《楞嚴經》十習因六交報說罪福相，強調須深信因果與如來藏。","p":["三千大千世界無處非捨身命處","先說成佛之難才顯龍女可貴","深達罪福相為豎窮種智","《楞嚴經》十習因、地獄鬼畜報","遍照十方為廣通權智"],"k":["深達罪福相","一切種智","三大阿僧祇劫","因果","龍女","如來藏"]},"6832-a27_083":{"s":"本集講解龍女讚佛「微妙淨法身，具相三十二，以八十種好莊嚴法身」：法身指第八識無垢識，並說明阿賴耶識、異熟識、無垢識的階位差別，批評自稱成佛的喇嘛及意識常住之見。再依《大智度論》說相好攝受眾生、福德為證菩提基礎；最後解「我闡大乘教」，顯示龍女即將成佛的勝義菩薩不可思議。","p":["法身即無垢識，非色身音聲可見","阿賴耶、異熟、無垢識的階位","批評意識常住及自稱成佛者","三十二相由百劫修福德而顯","龍女自言闡大乘教度苦眾生"],"k":["無垢識","法身","三十二相","八十種好","龍女","福德"]},"6827-a27_084":{"s":"本集說明文殊為七佛之師、示現輔佐釋迦，龍女為其所度；舍利弗出面質疑「女身垢穢，非是法器」。講者批評以重男輕女或密教「毀謗婦女慧自性」解讀此段，指出一切人實由自心如來所生；並依《瑜伽師地論》說欲界天男女欲漸淡、梵天無男女相，及三十三天五百天女侍一天子，說明女身五障乃法爾如是。","p":["文殊為七佛之師，龍女為其所化","舍利弗質疑女身非法器","批評密教十四根本墮及抱身佛說","欲界諸天男女欲漸淡，梵天無男女相","天主有眾天女奉侍，屬法爾如是"],"k":["女身五障","舍利弗","龍女","欲界天","密教批判","如來藏"]},"6846-a27_085":{"s":"本集續講女身五障：帝釋、魔王為欲界天主必現男相；轉輪聖王七寶中有玉女寶，故以男身示現；佛三十二相有陰藏相，故於人間以男身成佛。講者說明五障非重男輕女，障礙在於內在由貪著五欲形成的「女人性」，並述大愛道出家與八敬法因緣，及觀世音菩薩隨應示現女相。","p":["帝釋、魔王不以女身示現","轉輪聖王七寶有玉女寶","佛三十二相中有陰藏相","障礙在內在的女人性，相由心生","大愛道出家、八敬法與八十四態"],"k":["女身五障","轉輪聖王","陰藏相","八敬法","大愛道","觀世音菩薩"]},"6842-a27_086":{"s":"本集以《維摩詰經》天女轉舍利弗身為例，說明八地以上菩薩於相自在，一切諸法非男非女，龍女示現女身無可質難；不宜只從外相論斷。接講舍利弗「佛道懸曠，經無量劫勤苦積行」，以四宏誓願、佛有百億萬名號、《佛說十號經》「正等覺」及一切種智說明佛道懸曠，並批評大乘非佛說、以解脫道取代佛菩提道者。","p":["天女轉舍利弗身：諸法非男非女","不應只從外相論斷證量","四宏誓願與佛道懸曠","佛於娑婆有百億萬名號","批評以解脫道取代佛菩提道"],"k":["佛道懸曠","一切種智","四宏誓願","非男非女","大乘非佛說","本際"]},"6838-a27_087":{"s":"本集續說「佛道懸曠」：菩薩亦須證二乘一切智，仍要平等開覺眾生並令起大乘作意。講者以世間共享成果之樂對比佛法的此世樂、來世樂，說明世尊以三乘方便度眾，阿羅漢實為久受菩薩教導者；阿含時須提諸法本母、本際才能斷我見。並以「為什麼要學佛」引出離苦得樂與一切法苦的觀察。","p":["菩薩也要證二乘一切智","須令眾生起大乘作意","世間樂與佛法此世樂、他世樂","不提本際則難斷我見","「為什麼學佛」與一切法苦"],"k":["大乘作意","佛道懸曠","一切智","本際","一切法苦","三乘方便"]},"6856-a27_088":{"s":"本集說明苦、空、無我的觀察若只停於蘊處界，學人將趣向無餘涅槃；菩薩進一步顯示一切法匯歸如來藏，故本然解脫。接講〈勸持品〉藥王、大樂說菩薩誓願於惡世受持說此經，講者列十點勉勵自他於娑婆度眾，並說明須先分證解脫道、離五欲，樂住生死同時讚歎遠離生死。","p":["蘊處界觀察：一切法苦、空、無我","一切法匯歸如來藏則本然解脫","藥王等菩薩誓於惡世說此經","十點勉勵：於娑婆度眾不作逃兵","樂住生死亦讚歎遠離生死"],"k":["如來藏","勸持品","佛道懸曠","解脫道","樂住生死","四聖諦"]},"6836-a27_089":{"s":"本集講解〈勸持品〉五百阿羅漢及學無學八千人誓願於他國土廣說此經，因娑婆眾生弊惡、增上慢。說明娑婆為堪忍世界，菩薩攝受眾生即攝受佛土；並引經論計算娑婆修行、護持正法功德遠勝極樂世界，指出如來藏功德與佛無異、心佛眾生三無差別。","p":["阿羅漢誓於他方廣說此經","娑婆得名堪忍世界之由","菩薩不畏惡世，留此護持正法","娑婆護法一須臾勝極樂一大劫","心佛眾生三無差別，指如來藏心"],"k":["勸持品","娑婆世界","護持正法","如來藏","攝受佛土","極樂世界"]},"6844-a27_090":{"s":"本集說明護持正法可加速經歷三大阿僧祇劫，以阿難、迦旃延樂於利樂眾生而成佛速為例；並指出實相心如來藏只有一個。講者敘述佛滅五百年後二乘證者漸少、外道興起而大乘菩薩出世，引《中阿含》說二乘涅槃為施設、依本際而說，二乘涅槃為化城；最後批評釋印順六識論之說。","p":["護持正法可快速經歷三大劫","攝受眾生即攝受佛土","每一有情只有一個實相心","二乘涅槃為施設之化城，依本際","批評釋印順視七八識為意識細分"],"k":["護持正法","如來藏","化城喻","二乘涅槃","八識論","釋印順"]},"6852-a27_091":{"s":"本集講解《法華經》卷4佛為姨母摩訶波闍波提及六千有學、無學比丘尼授記的經文，佛號一切眾生喜見如來，六千人次第相續成佛；並說明授記有初發心授記、現前授記、未發心授記、密授記與廣授記等差別。後半駁斥「佛滅後五百年無大乘經流傳」之說，指部派對如來壽量、真如、心性本淨的激烈爭論，顯示當時已有大乘經。","p":["佛為大愛道及六千比丘尼授記，次第相續成佛","授記有初發心、現前、未發心授記之別","密授記與廣授記（一合掌皆已成佛道）","部派於二乘法義本無異味，分裂另有原因","部派爭論佛壽、真如、心性本淨，可證有大乘經"],"k":["授記","摩訶波闍波提","部派佛教","大乘非佛說","心性本淨","無生法忍"]},"6868-a27_092":{"s":"本集以「摧邪顯正」為題，先剖析一貫道「老母娘」源自斗母（北斗）信仰，又經密宗摩利支天女附會而成，屬求世間吉凶的宗教。再以《成唯識論述記》曾失傳為例，批評歐美學者以流傳記載判定大乘經後出並不可靠；並說明識為生死所依的十因緣法，依《攝大乘論》駁斥釋印順以意識為本、等同阿陀那識的六識論說法。","p":["眾生信邪不信正，護持正法不易","一貫道老母娘出自斗母與摩利支天附會","以《述記》失傳為例，駁歐美學者考證","十因緣法：本識為生死所依與本際","《攝大乘論》分說五識與意識，破印順曲解"],"k":["摧邪顯正","六識論","釋印順","第八識","一貫道","十因緣法"]},"6848-a27_093":{"s":"本集講解羅睺羅母耶輸陀羅受記為具足千萬光相如來、佛壽無量阿僧祇劫，以及諸比丘尼願於他方廣宣此經的經文，勉勵學人應在此土弘揚如來藏妙義。並說明化城、三車、龍女成佛皆指如來藏，報身壽量長遠而法身無生，佛法以無所得為方便；後半批判密宗金剛薩埵、天根信仰及蓮花生、那洛巴、密勒日巴、達賴等雙身法傳承非佛法。","p":["耶輸陀羅獨自受記，佛壽無量阿僧祇劫","化城、三車、龍女成佛皆指此經如來藏","釋迦報身壽量七百阿僧祇劫，示現八十歲","有所得為魔眷屬，佛法以無所得為方便","批判密宗金剛薩埵與雙身法傳承"],"k":["耶輸陀羅","佛壽","如來藏","無所得","密宗雙身法","法身"]},"6859-a27_094":{"s":"本集進入〈勸持品〉（依《法華經講義》第十一輯），說明「勸持」是勸大眾受持、讀誦、廣說此經使其流傳不絕。前三批受記者皆願於他方弘經，世尊乃視八十萬億那由他菩薩；講者依「得諸陀羅尼」判其為九地菩薩，並解說「佛今默然」表菩薩應自行抉擇、承擔果報，以及其獅子吼誓願於惡世十方世界宣說此經、忍受辱罵刀杖。","p":["勸持即勸受持、讀誦、廣說此經","八十萬億那由他菩薩得陀羅尼，為九地菩薩","佛默然：菩薩須自有智慧判斷並承擔","獅子吼：知真實義仍願於惡世十方弘經","偈頌重說以鼓勵心量未廣的菩薩"],"k":["勸持品","獅子吼","陀羅尼","九地菩薩","五濁惡世","忍辱"]},"6854-a27_095":{"s":"本集解說〈勸持品〉偈頌「惡世中比丘，邪智心諂曲，未得謂為得，我慢心充滿」等句。講者以「坐、請坐、請上座」對聯說明諂媚與慢心源於名聞利養，舉趙州三等接待檀越的方便作對照，並對比正覺不分功德主等級、法不買賣；再解釋假阿練若外示清高、實貪利養而為白衣說法，求人視如六通羅漢。","p":["諂曲源於貪財利，對施主分等接待","未得謂得、未證謂證以求供養","趙州三等接待是為正法的方便","正覺不分功德主等級，法不賣","假阿練若自命清高，實為名聞利養"],"k":["勸持品","未得謂得","名聞利養","增上慢","阿練若","諂曲"]},"6849-a27_096":{"s":"本集續講〈勸持品〉偈頌，說明「假名阿練若」的惡比丘為何好出弘經菩薩之過，誣其說外道論議、自作經典。講者指《法華經》所說「此經」即如來藏，批評身受菩薩戒卻倡「大乘非佛說」者為獅子身中蟲，並反駁《法華經》為神話之說，勉勵學人效法諸菩薩安忍誹謗、不求回報而護持正法。","p":["講如來藏者常被罵為外道神我","阿羅漢迴心至入地，距佛地尚遠","受菩薩戒卻倡大乘非佛說，為獅子身中蟲","法華經非後人所能編造，亦非神話","被誹謗仍安忍，只求正法久住"],"k":["勸持品","大乘非佛說","如來藏","安忍","誹謗正法","印順"]},"6860-a27_097":{"s":"本集續講〈勸持品〉，說明佛門最大邪見是把五陰、意識當作真如佛性，而弘揚第八識妙法者反被誣為邪見人；並解釋「汝等皆是佛」為譏諷之語，批評隨意自稱入地者為輕率妄語。接著進入「濁劫惡世中」偈頌，解說五濁以見濁為起因，依次形成煩惱濁、眾生濁、命濁與劫濁，並提及世尊是捨苦行參究實相而成佛。","p":["大邪見：以五陰意識為真如佛性","「汝等皆是佛」是譏諷說法者大妄語","自稱入地卻不解法華真義，即屬輕率","五濁由見濁起，次第成劫濁","世尊捨六年苦行，參究實相而成佛"],"k":["勸持品","五濁惡世","邪見","大妄語","見濁","如來藏"]},"6869-a27_098":{"s":"本集講完〈勸持品〉。先說明五濁之世水、火、風等劫災的成因，勉勵不造惡業共業便無須恐懼；再解釋「惡鬼入其身」、「當著忍辱鎧」、「我不愛身命，但惜無上道」、「數數見擯出」等偈，指弘揚如來藏者常被辱罵、擯出塔寺，應安忍而不故意挑釁；最後以菩薩自稱世尊使、佛自知我心作結，勸誡勿謗三寶。","p":["水劫及二禪、風劫及三禪，欲界有火劫","不造惡業共業，不必恐懼天災","著忍辱鎧，惜無上道而不故入難處","認同如來藏者常被擯出塔寺","我是世尊使，處眾無畏；慎勿謗三寶"],"k":["勸持品","忍辱鎧","無上道","五濁惡世","擯出","護持正法"]},"6866-a27_099":{"s":"本集開始講〈安樂行品〉：文殊菩薩請問後惡世如何說此經，佛答應安住四法，首為菩薩行處及親近處。講者先白話解釋整段經文，說明此處主要指三賢位中已悟的出家菩薩；並詳解「住忍辱地」須以智慧了知「眾生本來如是」而不生氣，同時仍應詳細說明對方錯處以救護之，方具生忍與法忍。","p":["安樂行：後惡世如何弘經而長久利生","文殊請法，佛說應安住四法","所指主要為三賢位已悟出家菩薩","住忍辱地：信受眾生本來如是","忍辱不等於不作為，仍須辨正救護"],"k":["安樂行品","菩薩行處","住忍辱地","親近處","文殊師利","生忍法忍"]},"6862-a27_100":{"s":"本集續講菩薩行處，解說「柔和善順而不卒暴，心亦不驚」應依四攝法的愛語、隨順學人心性，並具足膽與識。再闡釋「於法無所行，而觀諸法如實相」唯證如來藏者能作到，批評應成派的緣起性空實同共生；並說明「亦不行不分別」：無分別的是第八識，覺知心悟後仍須分別，才能救護眾生、護持正法。","p":["柔和善順、不卒暴，重愛語與口德","心亦不驚：有膽有識，仍須提防","三界諸法皆有所行，唯如來藏無所行","緣起須有因，根塵只是緣","無分別是第八識，覺知心不應不分別"],"k":["菩薩行處","於法無所行","如實相","不行不分別","緣起性空","如來藏"]},"6872-a27_101":{"s":"本集先總結菩薩行處的兩部分，再進入親近處：說明不親近國王大臣，舉禪師令皇帝先歸依受戒、慧忠國師以「無縫塔」不輕傳法為例；不親近外道梵志、尼揵子及以文筆讚詠外書者，以免眾生誤認。並詳解「路伽耶陀」順世外道，舉氣功、求長壽、生天、密宗，以及主張意識、細意識或離念靈知常住等說。","p":["菩薩行處：心性轉變與悟後不行不分別","不親近國王大臣；禪師不輕傳法","不親近外道及讚詠外書者，免眾生誤認","順世外道：氣功、長壽、生天、密宗","主張意識或離念靈知常住亦屬順世"],"k":["親近處","順世外道","路伽耶陀","意識常住","離念靈知","慧忠國師"]},"6864-a27_102":{"s":"本集續談順世外道後，解說「逆路伽耶陀」反順世外道，舉老莊無為的消極之說與死後斷滅的斷見論為例，並批評以滅相為真如、又改稱細意識為結生相續識之說承襲宗喀巴；依《瑜伽師地論》指結生相續識為阿賴耶識。講者強調弘法華者不可和稀泥，最後解釋「兇戲、相扠相撲、那羅」等不應親近。","p":["不靠兩邊的老好人中道，亦屬順世","反順世外道：老莊無為與斷見論","《瑜伽師地論》：結生相續識即阿賴耶","斷見論者深心仍執常見","兇戲、相扠、相撲、那羅皆不應親近"],"k":["逆路伽耶陀","斷見","結生相續識","阿賴耶識","宗喀巴","親近處"]},"6875-a27_103":{"s":"本集講完菩薩行處與第一親近處。說明「那羅」角力及「變現之戲」魔術屬障眼欺騙，與誠實執行因果的如來藏相違；不親近屠夫、畜養豬羊雞狗與畋獵漁捕等惡律儀者，但其來訪仍應說法而無所悕望。又解釋不親近求聲聞四眾、亦不問訊之理，並依五種種性說明應觀察對方而隨宜說法。","p":["那羅角力與魔術皆不應親近","如來藏秉公執行因果，從不欺誑","惡律儀者來訪，仍說法而無所悕望","不親近求聲聞四眾，亦不問訊","依種性觀察，隨宜說大乘法"],"k":["親近處","惡律儀","聲聞種性","隨宜說法","五種種性","如來藏"]},"6877-a27_104":{"s":"本集說明末法惡世弘揚如來藏須先安住菩薩行處：除六度作意外，最重要是以實證如來藏所轉依的真如法性為行處，以無所住心行六度。講者引《雜譬喻經》道俗相反，說明如實說法必遭世俗化教界反彈；並引《大般若經》善現答「行在勝義諦，能取所取不可得」及《心經》，闡釋行深般若即轉依無所得的真如。","p":["菩薩行處：轉依如來藏真如法性行六度","道俗相反，如實說法必遭教界反彈","聽聞正法方具信根，能得諸善法","行深般若在勝義諦，無能取所取","悟後未轉依，仍非真正菩薩行處"],"k":["菩薩行處","真如法性","無所得","行深般若","轉依","心經"]},"6891-a27_105":{"s":"本集說明佛對出家實義菩薩的親近處遮止，如不親近權貴、外道、惡律儀者，並避免與女人親密，以免末法眾生誤解。講者將初親近處「常好坐禪，在於閑處修攝其心」對照《大寶積經》三處依止與《維摩詰經》宴坐之義，指真正坐禪是轉依真如；再說明第二親近處須觀一切法空如實相，即諸法自相空、五蘊為如來藏所現。","p":["親近處遮止：權貴、外道、與女人親密","《大寶積經》：住阿蘭若、諍息滅、佛菩提處","維摩詰：不於三界現身意是為宴坐","二乘無常空只是一切法空的表相","五蘊自相空，如大海生聚沫水泡"],"k":["親近處","宴坐","自相空","一切法空","維摩詰","如來藏"]},"6879-a27_106":{"s":"本集續講第二親近處，解說經文「觀一切法空如實相，不顛倒、不動、不退、不轉，如虛空」及「一切語言道斷，不生不出不起，無名無相」。講者指一切法空非斷滅，而是能生萬法的如來藏體性如虛空；並以顯境名言與表義名言說明六識覺知不離語言道，唯如來藏言語道斷；最後說明佛以假名相說法不壞法性，菩薩說如來藏而無所執著。","p":["一切法空非斷滅，指如來藏空性","五蘊有生滅起退，是顛倒有所得法","顯境名言、表義名言：六識不離語言道","夢幻泡影須有如來藏為所依","假名相說法不壞法性，說真如非執著"],"k":["一切法空","如實相","語言道斷","顯境名言","無所有性","如來藏"]},"6880-a27_107":{"s":"本集講〈安樂行品〉重頌「若有菩薩於後惡世，無怖畏心欲說是經」，白話說明應遠離國王、兇險戲者、增上慢人、貪著小乘者、破戒比丘等，若其好心來聽則不懷悕望為說。講者舉網路上達賴喇嘛「佛教應隨科學改變」、「信不信輪迴不重要」等言論加以批評，引《楞嚴經》、《大般涅槃經》說明，並指依法實證方能無怖畏說此經。","p":["重頌重申菩薩行處與應遠離之人","後末世如實說法華必遭反對誹謗","批評達賴「佛教應隨科學改變」之說","《涅槃經》：身雖丈夫，行同畜生","依法實證，方能無怖畏說此經"],"k":["安樂行品","無怖畏心","親近處","達賴喇嘛","我見我執","如來藏"]},"6895-a27_108":{"s":"本集說明「此經」如來藏雖為常住法，卻依《楞伽經》不同於外道之我，並比較聲聞與大乘的空、無相、無願三三昧。接著解說偈中不親近增上慢人與「貪著小乘三藏學者」，引《心地觀經》說親近善友為第一，批評日本學者及其呼應者倡大乘非佛說、尊阿含貶大乘，並區分一世受持的聲聞律與依如來藏盡未來際的菩薩戒。","p":["如來藏非外道神我，引《楞伽經》","聲聞三三昧依蘊處界，大乘依藏識空性","增上慢：未證言證、未悟言悟、錯判果位","貪著小乘三藏者以阿含排斥大乘","聲聞律只一世，菩薩戒依如來藏永受"],"k":["貪著小乘三藏","增上慢","菩薩戒","三三昧","大乘非佛說","如來藏"]},"6887-a27_109":{"s":"本集續說聲聞戒僅盡形壽、菩薩戒依根本方便成已判定罪福，並將遠離「貪著小乘三藏學者」歸結為遠離僧衣崇拜。再解說應遠離破戒比丘、名字羅漢、好戲笑比丘尼及深著五欲求現滅度的優婆夷，若其好心來則不懷悕望為說；並釋「不行上中下法…不分別是男是女」，引《大薩遮尼乾子所說經》說三乘無乘差別，終歸一佛乘。","p":["聲聞戒盡形壽，捨壽後受戒不成","菩薩戒依根本、方便、成已判罪福","貪著小乘三藏即僧衣崇拜","否定七八識即成謗菩薩藏重罪","不行上中下法；三乘無乘差別歸一佛乘"],"k":["菩薩戒","僧衣崇拜","菩薩行處","一佛乘","謗菩薩藏","不分別男女"]},"6897-a27_110":{"s":"本集先回顧初親近處，如不親近寡女、處女、非男及屠夫等，並不行上中下法、不分別男女；再進入第二「法親近處」偈頌「一切諸法空無所有，無有常住亦無起滅」。講者說明佛法可實證而異於宗教與哲學玄想，指空無所有是就蘊處界生滅法而言，生滅法須依不生滅的如來藏而存在，故從如來藏看諸法亦無起滅。","p":["初親近處：避免令人誤會的親近關係","不行上中下法，一體看待眾生","佛法可實證，異於宗教信仰與哲學","生滅法依不生滅法，有為住於無為","諸法本是如來藏中法，故亦無起滅"],"k":["法親近處","一切法空","如來藏","初親近處","生滅法","不生滅法"]},"6883-a27_111":{"s":"本集續講安樂行品「法親近處」，以明珠映現胡人漢人影像為喻，說明五陰諸法空無所有、無有常住，但攝歸如來藏時則無起無滅。並解釋「顛倒分別諸法有無」，舉能量說、造物主等為增益執，並批評印順否定第七、八識為損減執，又立細意識常住而落入增益執。","p":["明珠映像喻：五陰影像歸屬如來藏明珠","諸法空無所有，攝歸如來藏則無起滅","菩薩須先實證，方能如實為人說法","增益執：能量、造物主等虛妄建立為實有","損減執：否定意根與如來藏，再立細意識常住"],"k":["法親近處","如來藏","增益執","損減執","五陰","安樂行品"]},"6889-a27_112":{"s":"本集講「是實非實、是生非生」的顛倒分別，批評六識論者以「性空唯名」判般若，指出般若諸經所說是真實心如來藏；又反駁「阿賴耶識是生滅法」之說，說明真如是第八識體性所顯，舉花與美麗為喻。並解釋「觀一切法皆無所有，猶如虛空無有堅固」，說明虛空是色邊色、有為法住於無為法中。","p":["批評「性空唯名」把般若說成戲論","般若所說非心心、無住心即如來藏","阿賴耶識本有不生滅，離念靈知非真如","真如是第八識所顯性，如花與美麗","虛空依色法邊際施設，有為法住如來藏中"],"k":["顛倒分別","真如","阿賴耶識","性空唯名","般若","法親近處"]},"6894-a27_113":{"s":"本集辨析緣起法與緣生法：緣起法須有如來藏為根本因，藉緣生起諸法；六識論者所說緣起性空實為緣生性空，並以細意識常住落入增益執。接著以明珠影像解釋「不生」，以本住法界大定解釋「不出」，再從位退、行退、念退說明退轉的原因在於心動搖、未得決定。","p":["緣起法以如來藏為因，藉緣生諸法；緣生法只說結果","否定第八識即成無因唯緣的斷滅見","意識粗細皆是意法因緣生","不出：如來藏本住法界大定，不入不出","退有位退、行退、念退，因心動搖"],"k":["緣起性空","緣生法","如來藏","法界大定","不退轉","細意識"]},"6885-a27_114":{"s":"本集說明不退轉的關鍵在心得決定，而心得決定來自親自經歷參究與觀行的過程；區分「了知」與「觀見」，並以佛世時隨聞入觀斷我見證初果為例，強調現量觀行與定力。再從理上說如來藏對一切法從不動心，才是真實的不動不退、常住一相，具足二種親近處方可為人演說此經。","p":["心得決定才能不動、不退轉","參究觀行過程使智慧出生；了知異於觀見","隨聞入觀、具定力方能斷我見得法眼淨","如來藏從不動心，才是真不動不退","常住一相，智慧展開而攝受佛土"],"k":["不動不退","現觀","心得決定","隨聞入觀","常住一相","法親近處"]},"6899-a27_115":{"s":"本集進入安樂行品第二安樂行，說明末法時欲說《法華經》應先住安樂行，經文要求不樂說人及經典過、不輕慢諸餘法師等。講者強調此是對佛門內部而言，對外道及相似像法則須破邪顯正，引《雜阿含》偽寶喻說相似像法流行則正法漸沒；並說明說法時不當眾指人過失，真經各有因緣不應指其不圓滿。","p":["末法說《法華經》須先修安樂行","第二安樂行：不樂說人及經典過","此規範對教內，對外道須破邪顯正","相似像法流行則正法漸沒；辨正非批評人","真經各有因緣，無一部能圓滿三乘"],"k":["安樂行","破邪顯正","相似像法","安樂行品","法義辨正"]},"6905-a27_116":{"s":"本集續講第二安樂行「不樂說經典過」，說明佛依眾生因緣次第說法，先說《華嚴》再說阿含、般若、唯識，最後以《法華經》收攝為圓教，故不應尋真經過失；但偽經須破斥，舉《天地八陽神咒經》及密教經典為例。並講「不輕慢諸餘法師，不說他人好惡長短」，闡釋「僧讚僧，佛法興」的前提與法師的定義。","p":["佛依藏通別圓次第說法，終以法華收圓","真經不應尋過，偽經則須舉證破斥","不說他人好惡長短，不作人身攻擊","僧讚僧的前提是法義正確、不壞正法","說五陰虛妄應厭離者，方為法師"],"k":["安樂行","判教","圓教","偽經","僧讚僧","法師"]},"6907-a27_117":{"s":"本集講第二安樂行中對聲聞人「不稱名說其過惡、不稱名讚歎其美、不生怨嫌」，並批評宗喀巴、印順等主張意識常住為相似像法，說明二乘與大乘中真正法師的條件。講者說初果、二果仍有貪瞋屬正常，不應議論以免謗僧；又說弘菩薩道者不讚歎阿羅漢，答難時以大乘法解說，令得一切種智。","p":["主張意識常住者屬相似像法","依文解義但護正法者應包容讚歎","初果、二果仍有貪瞋，議論其過屬謗僧","不稱名讚歎聲聞，以免引人走羅漢道","答難不以小乘法，但以大乘解說"],"k":["安樂行","聲聞","謗僧","相似像法","一切種智","焦芽敗種"]},"6901-a27_118":{"s":"本集續說「不以小乘法答，但以大乘解說」的用意，舉七葉窟內外結集說明聲聞法不等於成佛之道，定性聲聞被稱焦芽敗種，但菩薩仍可供養阿羅漢以種福田。並總結第二安樂行只針對演述正法者，仿冒佛法者仍須破斥；再解釋偈頌「安隱說法、於清淨地而施床座、澡浴塵穢、著新淨衣、和顏為說」等說法威儀。","p":["七葉窟結集顯示聲聞法非成佛之道","供養阿羅漢：施者、施物、福田三勝","幫弟子發菩薩性勝於幫證阿羅漢","第二安樂行不及於仿冒佛法者","安隱說法：高座、淨身淨衣、和顏說妙義"],"k":["安樂行","焦芽敗種","結集","安隱說法","說法威儀","一切種智"]},"6921-a27_119":{"s":"本集講第二安樂行偈頌：遇難問應隨義而答，以因緣、譬喻、敷演、分別層層解說，方便使人發菩提心、漸入佛道。並說講《法華經》者須除嬾惰意、懈怠想，離諸憂惱，慈心說法，常說無上道教，對衣食供養無所悕望；且須安住生忍、法忍、慈忍以離橫逆，其功德千萬億劫說不能盡。","p":["隨義而答，不答非所問，不知則直言","因緣、譬喻、敷演、分別層層說明","發心即歸依三寶、發四宏誓願","除嬾惰懈怠、離憂惱、慈心說無上道","安住生忍、法忍、慈忍以離橫逆"],"k":["安樂行","因緣譬喻","發菩提心","慈心說法","安忍","無上道"]},"6902-a27_120":{"s":"本集開講〈安樂行品〉第三安樂行，先回顧前兩種安樂行，再解說經文：末世受持此經者無懷嫉妒諂誑之心、勿輕罵學佛道者、勿惱人令其疑悔。講者認為在無了義正法時即同末法，批評相似像法、應成派中觀及以能見能聞為佛性之說；並以平實導師親身經歷說明疑悔障道，強調不輕未學、不輕新學。","p":["無了義正法、只剩表相佛法即是末法","真密教是如來藏密意，批評顯密之分","受持此經者無嫉妒、諂媚、欺誑之心","輕視學人會令其疑悔，疑悔障道甚深","不輕未學、不輕新學，因有隔陰之迷"],"k":["第三安樂行","安樂行品","疑悔","相似像法","不輕新學","嫉妒諂誑"]},"6915-a27_121":{"s":"本集續講第三安樂行，說明不可對學人說「汝等去道甚遠、終不能得一切種智」，因人有隔陰之迷，舉不識字老菩薩開悟與六祖慧能為例。又講「不應戲論諸法、有所諍競」，批評狂禪以輕語說如來，說明有諍競心表示異生性未斷。最後解釋「於一切眾生起大悲想」，對照第四安樂行的大慈心，並引《大智度論》區分小悲與大悲。","p":["勿斷言他人無望開悟，人有隔陰之迷","舉不識字老菩薩與六祖慧能為例","不應戲論諸法，狂禪輕語說如來不足取","有諍競心表示異生性未斷，真悟者不諍","對世俗眾生起大悲；大悲能令脫苦"],"k":["第三安樂行","不輕新學","戲論","諍競","大悲","隔陰之迷"]},"6917-a27_122":{"s":"本集講第三安樂行「於諸如來起慈父想、於諸菩薩起大師想」。說明菩薩階位越高越知不了如來境界，乃至一生補處菩薩亦起慈父想；起大師想前須先定義菩薩，分凡夫、名義、勝義菩薩與菩薩摩訶薩，不應對否定正法者起大師想。並說歸依應歸依十方常住菩薩僧，平等說法須隨順根機、不多不少。","p":["如來恩逾慈母，應起慈父想","階位越高越覺不知如來境界","菩薩分凡夫、名義、勝義菩薩及摩訶薩","歸依十方常住菩薩僧，而非個人","平等說法：觀根機，不多不少"],"k":["第三安樂行","慈父想","大師想","菩薩摩訶薩","歸依十方僧","隨機說法"]},"6913-a27_123":{"s":"本集續講「平等說法、不多不少」，依《楞伽經》五種種姓說明對無種姓者說人天善法或因果，並舉阿含中佛先說施論、戒論、生天之論；強調平等是依立足點而非齊頭式平等，深愛法者亦不為多說。接著總結第三安樂行，解說成就者無能惱亂及偈頌要旨：捨嫉恚慢、恭敬三寶、慈悲一切，並批評訶佛罵祖之狂禪。","p":["五種種姓，各依其性說適宜之法","無種姓者說人天善法或因果律","佛對外道先說施論、戒論、生天之論","平等非齊頭式；深愛法者亦不多說","對上恭敬三寶，對下起大悲，避狂禪"],"k":["第三安樂行","五種種姓","人天善法","平等說法","恭敬三寶","狂禪"]},"6909-a27_124":{"s":"本集總結第三安樂行，強調所恭敬的是大乘佛法與十方菩薩僧；說法者有大悲心並恭敬三寶，即使有錯聽眾也不惱亂。解釋「得好同學共讀誦是經」，同學如來藏則不分裂，舉部派佛教分裂為對照，並談福慧雙修。再解說偈頌：捨嫉恚慢與諂誑邪偽、常修質直行、不輕蔑於人、不戲論法、不令他疑悔說「汝不得佛」。","p":["恭敬大乘三寶，歸依十方菩薩僧","有大悲心、敬三寶，說法無人惱亂","得好同學則同見同行；部派因異學分裂","福慧如金翅鳥雙翼，須同時增長","不輕蔑人、不戲論法、不洩密意"],"k":["第三安樂行","好同學","質直行","法毘奈耶","福慧雙修","部派佛教"]},"6919-a27_125":{"s":"本集開講〈授記品〉，說明學佛的大目標是成佛而非只求解脫，成佛需長劫修行，批評即身成佛等說法；並解釋授記的意義。接著講佛授記摩訶迦葉當供養三百萬億佛而成光明如來，國名光德，國土莊嚴、魔民皆護法；又講目犍連等請求授記，須菩提受記為名相如來，並依平實導師之說以須菩提瞋習與好住空性說明其成佛較慢，勸勿起瞋。","p":["學佛大目標是成佛，非只求解脫","授記：佛預告成佛時、國土與名號","摩訶迦葉授記為光明如來，國名光德","須菩提授記為名相如來","須菩提因瞋習與好空性而成佛較慢"],"k":["授記品","授記","摩訶迦葉","須菩提","成佛之道","瞋習"]},"6911-a27_126":{"s":"本集續講〈授記品〉，解說大迦旃延供養諸佛、起七寶塔廟，當成閻浮那提金光如來，國土平正、無四惡道，講者以其心性柔和、重人情、行四攝法說明國土依報。再講大目犍連當成多摩羅跋栴檀香如來，劫名喜滿、國名意樂，並以其神通生慢的故事說明慢心障道。最後提到五百弟子皆當授記，勸勉勿起瞋慢、廣結善緣。","p":["大迦旃延當成閻浮那提金光如來","心性柔和、行四攝感得國土平正無惡道","目犍連當成多摩羅跋栴檀香如來","目犍連神通生慢，慢心障道","五百弟子皆當授記，勸勿起瞋慢"],"k":["授記品","大迦旃延","目犍連","四攝法","慢心","佛國淨土"]},"6923-a27_127":{"s":"本集講〈安樂行品〉中《法華經》的珍貴：化身佛不講此經，唯應身佛示現成佛時才說，故無量國中難聞其名。解說髻中明珠喻：鐵輪王依戰功賞賜而不予髻中明珠，如來以禪定、智慧力王於三界，魔王不服，賢聖弟子與五陰魔、煩惱魔、死魔、天魔作法戰。並引《不退轉法輪經》佛答魔王「度眾生而眾生未得度」的故事。","p":["化身佛不講《法華經》，唯應身佛說","髻中明珠喻：鐵輪王不以髻珠賞賜","如來以禪定、智慧力王於三界為法王","「度眾生而未得度」：如來藏本在彼岸","賢聖諸將斷煩惱，與無形四魔作戰"],"k":["髻中明珠","安樂行品","法王","天魔","四魔","應身佛"]},"6931-a27_128":{"s":"本集續講「如來賢聖諸將與魔共戰」，說明賢聖弟子以法義辨正救護眾生，並詳析離念靈知屬意識心、與五別境心所相應、以意根與六塵為俱有依，非第八識真如。又說明天魔不干擾只修欲界善法者，唯對證初禪而不離欲界度眾的菩薩干擾，以大地主與牛羊喻說明；魔考即五欲之繩，斷三縛結即令魔宮震動。","p":["賢聖弟子摧邪顯正，即是與魔共戰","離念靈知是意識心所，非真如","天魔只干擾證初禪而留欲界度眾者","大地主與牛羊喻；魔考即五欲之繩","有人斷三縛結證初果，魔宮即震動"],"k":["與魔共戰","離念靈知","天魔","魔考","初禪","三縛結"]},"6925-a27_129":{"s":"本集講如來對與魔共戰有功者賜以禪定、解脫、無漏根力及諸法之財，最後才賜《法華經》。講者以正覺同修會學人經驗說明修學次第清楚，依阿含自檢初果至四果的斷結內涵；並說菩薩證如來藏真如而知本來自性清淨涅槃，以與阿羅漢問答說明本際即異熟識。再談菩薩禪定與外道不同，及信根所依的三寶意涵。","p":["如來賜禪定、解脫、無漏根力、法財","《法華經》是最後賜與的最勝法財","依阿含自檢初果至四果的斷結","菩薩證真如，知本來自性清淨涅槃","菩薩禪定增益無漏根力；信根依三寶"],"k":["無漏根力","解脫道","本來自性清淨涅槃","五根五力","三寶","禪定"]},"6927-a27_130":{"s":"本集續講五根五力：信根圓滿生信力，以種子生根發芽為喻。引《大乘本生心地觀經》修勝道四法要：親近善友、聽聞正法、如理思量、如法修證，並引《華嚴經》說真善知識難遇，依《瑜伽師地論》說明以算數、稱量行相思惟諸法。最後說明念根念力、定根定力、慧根慧力依次增長，至斷三縛結證初果，再求明心見性。","p":["信根圓滿方生信力，如根穩方發芽","四法要：親近善友、聽聞正法等","如理思量：算數行相與稱量行相","如法修證：法隨法行、尋思伺察","念、定、慧根力漸增，至證初果"],"k":["五根五力","四法要","善知識","如理作意","法隨法行","三縛結"]},"6929-a27_131":{"s":"本集續講〈安樂行品〉如來賞賜弟子的法財，說明「諸法之財」即聲聞、緣覺、佛菩提三乘諸法，並解釋「又復賜與涅槃之城，言得滅度」一段經文。講者區分二乘的有餘、無餘涅槃與大乘四種涅槃，指出本來自性清淨涅槃非修得亦非不修得，並說明佛要等弟子各種條件具足後才演說《法華經》。","p":["諸法之財即聲聞、緣覺、佛菩提三乘諸法","二乘須斷盡煩惱才證有餘、無餘涅槃","大乘四種涅槃，其中兩種不共二乘","本來自性清淨涅槃本有，非修得非不修得","菩薩留惑潤生，條件具足後佛才說法華"],"k":["涅槃","諸法之財","本來自性清淨涅槃","無住處涅槃","留惑潤生","三乘菩提"]},"6933-a28_001":{"s":"本集講〈安樂行品〉轉輪聖王解髻中明珠賞賜大功者之喻，說明如來見弟子與五陰魔、煩惱魔、死魔戰有功，最後才演說祕藏的《法華經》。講者把經意分為四個重點，本集先講第一點：轉輪聖王有金、銀、銅、鐵四種，並介紹金輪王的七寶、四德、王四天下、千子具足，以及賢劫千佛的由來與頂生王的故事。","p":["髻中明珠喻：法華經是諸佛祕密之藏，最後才說","經意分四重點：輪王、四魔、一切種智、善巧方便","金輪王具七寶、四德、王四天下、千子具足","賢劫千佛由來；頂生王貪五欲而墮落命終","經中動兵征戰的轉輪聖王是鐵輪王"],"k":["安樂行品","轉輪聖王","髻中明珠","賢劫千佛","七寶","頂生王"]},"6942-a28_002":{"s":"本集續講〈安樂行品〉第二個重點：魔有四種。先說明魔能奪眾生法身慧命、障礙修行，再依次講五陰魔（以聚沫、泡、燄、芭蕉、幻來比喻五陰生滅）、煩惱魔、死魔（喪子婦人聞法證初果）與天魔波旬，並舉同修會退轉事件、新書發表受阻等例，勸人提高警覺，別讓天魔有機可乘。","p":["魔能奪眾生法身慧命，障礙破壞修行","五陰皆生滅法；一念不生仍落在想陰","煩惱魔：貪瞋癡及謗真善知識造成無明","死魔：喪子婦人知死而證初果","天魔波旬阻撓修行人與正法弘傳"],"k":["四魔","五陰魔","煩惱魔","死魔","天魔","無餘涅槃"]},"6947-a28_003":{"s":"本集講〈安樂行品〉第三個重點：一切種智的內涵。講者從明心證如來藏入第七住開始講起，說明解脫德、法身德、般若德三德，再講相見道的後得無分別智與如幻、陽焰、如夢三種現觀，然後是入地的增上意樂、諸地現觀，一直到妙覺成佛時四智圓明。講者強調一切種智以真見道為基礎，沒有明心而自稱活佛、法王就是大妄語。","p":["一切種智為佛地，道種智屬地上菩薩","明心入七住，發起解脫、法身、般若三德","相見道別相智：如幻、陽焰、如夢三觀","發十大願、增上意樂清淨後才入初地","歷經諸地至妙覺，四智圓明成一切種智"],"k":["一切種智","道種智","明心","根本無分別智","後得無分別智","非安立諦三品心"]},"6953-a28_004":{"s":"本集講〈安樂行品〉第四個重點：佛度眾生的善巧方便。講者先說明華嚴、阿含、般若、方等、法華涅槃五時與藏、通、別三教，再講四悉檀中的三種：世界悉檀（五陰世間與器世間，以及施論、戒論、生天之論的說法次第）、為人悉檀（隨根器三轉法輪）、對治悉檀（舍利弗教錯方法、難陀貪戀美色的故事）。第一義悉檀留到下集再講。","p":["佛說法四十九年，匯歸五時三教","世界悉檀：二種世間皆阿賴耶識所變現","施論、戒論、生天之論是諸佛常用的說法次第","為人悉檀：依眾生根器三轉法輪","對治悉檀：依煩惱施教，如二比丘與難陀"],"k":["四悉檀","五時三教","善巧方便","世界悉檀","對治悉檀","為人悉檀"]},"6938-a28_005":{"s":"本集講第一義悉檀：佛在初轉法輪時隱說涅槃本際，以「名色緣識」顯示二乘入無餘涅槃不是斷滅，但二乘人並未證得本際；二轉般若時旁開別教，讓弟子證悟真心，之後依三大阿僧祇劫的次第修行。接著解說「此經為尊」偈中讀誦、演說《法華經》的功德與好夢，並批評喇嘛教把五方佛配上各種顏色，主張佛的常光、身光是金色。","p":["初轉隱說本際，名色緣識顯示涅槃非斷滅","二乘人未證本際；菩薩證之不可思議","般若時旁開別教，菩薩悟後依次第修行","演說法華經者得種種功德與好夢","佛身光為金色，批評喇嘛教五佛配色"],"k":["第一義悉檀","無餘涅槃本際","名色緣識","佛身金色","喇嘛教","三大阿僧祇劫"]},"6944-a28_006":{"s":"本集解說〈安樂行品〉偈「佛為四眾說無上法……得陀羅尼，證不退智」。講者說明佛所說都是無上法，二乘菩提本是佛菩提的一部分，只是依次第鋪陳；夢中合掌讚佛是瑞相。接著談供佛的功德田與報恩田，並解釋法、義、咒、忍四種陀羅尼的意涵，指出每一個修證階位各有這四種陀羅尼。","p":["佛說皆無上法，二乘菩提屬佛菩提一部分","排斥大乘時，所說二乘法就不是佛法","夢中合掌讚佛、聞法供養屬於好相","供佛是功德田兼報恩田","法、義、咒、忍四種陀羅尼，各階位皆有"],"k":["陀羅尼","不退智","無上法","供佛","四悉檀","安樂行品"]},"6949-a28_007":{"s":"本集續講夢中或定中見佛聞法時，應如實勝解並作供養，以得陀羅尼與不退智。講者指出退轉者缺少義、咒、忍陀羅尼，不肯受持阿賴耶識；並說明不退智的層次、授記的具體內容與密授記。接著解說「諸佛身金色……常有是好夢」，強調要依四安樂行及兩種親近處演說《法華經》，不可用二乘法解經，也不可自讚毀他。","p":["聞法要勝解、供養，得陀羅尼證不退智","退轉者缺義、咒、忍陀羅尼，不受持阿賴耶識","不退分信、位、行、念、究竟不退","授記有具體內容；定中密授記不宜外說","依四安樂行、二親近處如實演說法華"],"k":["不退智","授記","陀羅尼","四安樂行","親近處","夢中見佛"]},"6955-a28_008":{"s":"本集解說〈安樂行品〉偈「又夢作國王，捨宮殿眷屬……如煙盡燈滅」。講者以石崇、和珅說明國王所享的上妙五欲，並講菩提樹與師子座的名稱由來、釋迦如來六年苦行後改行中道而成佛。講者也說明夢中成佛度眾、長劫入短劫的道理，「如煙盡燈滅」並不是斷滅；最後勸大眾發願在未來世如實宣講《法華經》。","p":["國王的上妙五欲是人間最勝，菩薩能捨","菩提樹因佛在樹下成道而得名","釋迦六年苦行後改行中道，夜睹明星成佛","夢中也能度眾；如煙盡燈滅不是斷滅","惡世說第一法得大利，應發願講法華"],"k":["安樂行品","上妙五欲","菩提樹","夢中成佛","如煙盡燈滅","發願"]},"6940-a28_009":{"s":"本集開講第十五品〈從地踊出品〉：他方來的八恆河沙菩薩請求在佛滅後護持此經，佛制止他們，說娑婆世界自有六萬恆河沙菩薩，各帶六萬恆河沙眷屬。講者談在此土如實演講《法華經》之難、菩薩應感恩戴德、度眾不起慢心，並解釋三千大千世界、地裂與「下方虛空」的意思，以及「唱導之首」的含義。","p":["他方菩薩願護持此經，佛止之","娑婆自有六萬恆河沙菩薩及眷屬","如實演講法華難，真菩薩必感恩戴德","與諸佛所度相比，度眾不應起慢心","娑婆是三千大千世界，菩薩住下方虛空"],"k":["從地踊出品","六萬恆河沙菩薩","三千大千世界","唱導之首","護持法華","慢心"]},"6952-a28_010":{"s":"本集解說從地踊出的菩薩們禮拜多寶如來與釋迦牟尼佛，讚歎經過五十小劫，佛以神力令大眾覺得如同半日。講者以平實導師夢中蒙世尊召見、呈現前世一事，說明時間是相對的，長劫可入短劫；並依《解深密經》說修行的劫數隨精進程度而不同。講者也談末那識的習氣、判別夢境的方法，以及尚未證得不等於不存在。","p":["菩薩禮讚二世尊五十小劫，佛力令如半日","時間是相對的，長劫入短劫非神話","依精進程度不同，一劫可短至一剎那","末那遍緣一切法，習氣須長時轉變","判別夢境；未親證不等於不存在"],"k":["從地踊出品","長劫入短劫","時間","末那識","夢境","多寶如來"]},"6963-a28_011":{"s":"本集講從地踊出菩薩眾中的四位上首唱導之師：上行、無邊行、淨行、安立行，以及他們向世尊問訊「少病少惱、安樂行不」。講者逐一說明四位菩薩分工所教：上行教一切佛法往上修，無邊行教種種菩薩行與次法，淨行教斷三界愛的現行與習氣種子，安立行教如何施設五時三教等權巧方便；並以五十三層樓為喻說明修行階位。","p":["四導師：上行、無邊行、淨行、安立行","上行教一切佛法，無邊行教無量次法","淨行：先斷我見我執現行，再斷習氣種子","安立行：施設五時三教等方便，安立不虛妄","以五十三層樓喻說明成佛階位"],"k":["四大菩薩","唱導之師","安立行","淨行","五時三教","次法"]},"6967-a28_012":{"s":"本集解說四大菩薩的問訊：為何不問「遊步輕利」，而問「少病少惱、安樂行不」，以及應身佛為何也會生病、需要密跡金剛護持，並比較五濁惡世與人壽八萬四千歲度眾的難易。世尊回答眾生容易化度，是因為他們世世受佛教化，只有學小乘者例外。講者指出「此經」就是如來藏，不容易聽聞，並舉「聽無」公案，說明《金剛經》不是講一切法空。","p":["下方菩薩住虛空，故不問遊步輕利","應身佛隨眾生而有病，需密跡金剛護持","五濁惡世度眾辛苦，故須問訊安樂行","所化眾生世世受教，易度；學小乘者難","此經即如來藏，難以真正聽聞"],"k":["此經","如來藏","應身佛","五濁惡世","問訊","從地踊出品"]},"6957-a28_013":{"s":"本集解說四大菩薩以「善哉善哉大雄世尊」讚佛，以及世尊稱許他們能發隨喜心。講者說明諸佛的報身、意生身、法身都沒有人能傷害，所以稱「大雄」；說「易可化度」指的是那些大菩薩，而非人類。講者並以阿那律穿針的故事勸人隨喜、不起嫉妒。之後彌勒菩薩代表大眾以偈請問：這些菩薩從何處來、因什麼因緣聚集。","p":["實證此經後讀金剛經，才算入於佛慧","諸佛三身不可傷，故稱大雄世尊","易可化度指下方大菩薩，非人類","應隨喜不嫉妒；阿那律穿針喻福德不嫌多","彌勒代眾請問踊出菩薩的來處與因緣"],"k":["大雄世尊","隨喜","入於佛慧","密跡金剛","彌勒菩薩","從地踊出品"]},"6973-a28_014":{"s":"本集續解彌勒菩薩的請問偈：踊出菩薩的眷屬數量多到用竹籌計算恆沙劫也數不完，並問是誰教化他們、從誰初發心、修什麼經，分身諸佛的侍者也同樣發問。世尊讚歎阿逸多後，表示將宣示諸佛的智慧、自在神通、師子奮迅、威猛大勢四種力量。講者批評六識論者與釋印順把阿羅漢當作佛，強調佛智不可思議，自稱成佛者必是凡夫。","p":["踊出菩薩無量，行籌數經恆沙劫仍不能盡","彌勒問誰為說法、從誰發心、修何佛道","分身佛侍者亦問，佛令待彌勒問答","佛將宣示智慧、神通、奮迅、威猛四力","佛智叵思議，批評以羅漢為佛之說"],"k":["佛智叵思議","彌勒菩薩","釋印順","六識論","分身諸佛","從地踊出品"]},"6962-a28_015":{"s":"本集說明大阿羅漢一世證果其實是方便說，因為他們多劫以來就隨佛修學；也提到正覺不急於取證阿羅漢的門風。接著闡釋佛將宣示的四力：自在力（應身之外的報身、自受用身、他受用身無人能害）、神通力、師子奮迅三昧（從未到地定、初禪到四禪八定的深淺與難度），以及由智慧、自在、神通、禪定與廣大福德匯成的威猛大勢之力。","p":["大阿羅漢一世證果是方便說，多劫已修","菩薩不急取解脫果，入地前才斷五下分結","諸佛三身自在，唯應身需密跡金剛護持","師子奮迅三昧：禪定順逆往返迅速自在","威猛大勢力由智慧、神通、禪定、福德成"],"k":["師子奮迅三昧","威猛大勢之力","自在神通","阿羅漢","禪定","福德"]},"6965-a28_016":{"s":"本集解說世尊偈「當精進一心……佛智叵思議」：講者說明聽聞佛境界時容易生起的疑與掉悔，以及實證佛法的條件（除性障、修福德、鍊定力、熏般若知見）；又說「出信力，住於忍善」，佛四十九年所說有限，佛無不實語。講者批評「大乘非佛說」，並解說世尊宣告踊出菩薩是成道後教化、住下方虛空，再以三地滿心菩薩意生身說明佛化度之廣。","p":["聞佛境界勿疑勿悔，佛智叵思議","實證須除性障、修福德、鍊定力、熏知見","四十九年所說有限，佛無不實語","批評大乘非佛說；證量越高越知佛智難測","三地滿心意生身度眾，何況諸佛"],"k":["佛智叵思議","疑悔","信力","大乘非佛說","意生身","從地踊出品"]},"6969-a28_017":{"s":"本集從「此諸菩薩，皆於是娑婆世界之下此界虛空中住」講到諸佛的淨土，說明四種佛土：凡聖同居土、方便有餘土、實報莊嚴土、常寂光淨土，並以極樂世界上、中、下三品往生者為例，指出四土依智慧心境施設，不是分層居住。講者認為儀器、學術無法檢驗證悟，應以至信、仰信信受佛語；並解說菩薩「讀誦通利、思惟分別、正憶念」。","p":["娑婆不只有人間這種穢土","四土：凡聖同居、方便有餘、實報莊嚴、常寂光","極樂三品往生分住三土，依心境而非分層","儀器與學術無法檢驗證悟，應信受佛語","讀誦通利、思惟分別、正憶念源於勝解"],"k":["四種淨土","實報莊嚴土","方便有餘土","極樂世界","凡聖同居土","正憶念"]},"6959-a28_018":{"s":"本集解說踊出菩薩修道的樣子：不樂在大眾中多說話、常樂靜處勤行精進、不依止人天而住、愛樂深智，以及二乘法為何只在人間演說。接著講世尊重宣偈「阿逸汝當知」：這些菩薩是佛無數劫來所化，令發大道心；講者說明如來藏金剛心是成佛標的，佛稱為「我子」者至少已入地，並說明捨憒鬧、常行頭陀與入地所需的過程。","p":["不樂在眾多說，離攀緣，常樂靜處精進","下方虛空淨土菩薩樂諸佛法，不求二乘","二乘法適合人間說，諸天不易相應","如來藏金剛心不可壞，為成佛標的","被佛稱為我子者至少已入地"],"k":["捨憒鬧","精進","佛子","大道心","如來藏","頭陀行"]},"6976-a28_019":{"s":"本集解說「學習我道法」中的道與法。講者比較世間道與天道（以一貫道、基督教的天堂為例，評其仍不出欲界），說明佛所傳的是聲聞道、緣覺道、菩薩道三道及各自的法門，佛菩提道兼含通教與別教。講者又以道德與方術的關係，指出用三乘菩提謀取名利是有術無道，批評密宗收費傳咒，並強調法與次法都要傳、都要修。","p":["世間道、天道仍在欲界，不及解脫道","佛傳聲聞、緣覺、菩薩三道，各有其法","入地前須通達三乘，入地後明確授記","有術無道者以三乘謀名利，是退轉","傳法須兼傳次法；批評密宗收費傳咒"],"k":["道與法","法與次法","菩薩道","三乘菩提","授記","天道"]},"6972-a28_020":{"s":"本集講解〈從地踊出品〉偈頌「晝夜常精進」至「我從久遠來，教化是等眾」，說明下方空中住的菩薩精進求佛道、志念力堅固、說法無畏，至少為地上菩薩。並述世尊於菩提樹下參究成佛、三轉四聖諦法輪度五比丘之艱難，預告彌勒將代眾請問。","p":["精進為求佛道，精進必有佛菩薩感應","下方空中住為方便施設的實報莊嚴土","志念力堅固源於勝解具足與重法之心","世尊於菩提樹下參究成佛，非靠入定","三轉十二行法輪，此等菩薩久遠受教化"],"k":["從地踊出品","精進","三轉法輪","四聖諦","地上菩薩","念力"]},"6985-a28_021":{"s":"本集講解〈從地踊出品〉彌勒菩薩與大眾生疑、以「二十五歲人指百歲人為子」為喻請問世尊的經文。講者指出不可因儀器無法檢驗或自己未證就否定如來藏等唯證乃知之事；有所不解應歸於自己智慧未到，不可懷疑真經，並批評否定如來藏者與六字大明咒所依的偽經。","p":["彌勒代眾請問：成佛四十餘年何能化無量菩薩","父少子老之喻，世所難信","儀器檢驗不了心，如來藏唯證乃知","未知之事應歸己智淺，不可疑佛所說","妙覺菩薩尚且請問，凡夫勿謗法華為神話"],"k":["從地踊出品","彌勒請問","父少子老喻","如來藏","唯證乃知","偽經"]},"6977-a28_022":{"s":"本集續講彌勒請問的經文，說明六萬恆河沙菩薩眾的數量與證量，指出此問只是依世間表相而發。講者以平實導師此世學佛五年、參禪半小時即明心見性為例，說明往世證悟種子今世現行；又述世尊示現一夜成佛，並辨正「人中之寶」（仁波切）須斷我見且證實相，批評密宗濫用此名。","p":["從地踊出菩薩數量無量，皆有意生身","彌勒明知故問，為大眾請問釋疑","導師半小時明心見性，乃往世種子現行","世尊示現一夜成佛，前事皆為示現","人中之寶須斷我見並證法界實相"],"k":["從地踊出品","表相","往世種子","明心見性","人中之寶","仁波切"]},"6981-a28_023":{"s":"本集語譯〈從地踊出品〉彌勒菩薩重宣的偈頌，並講述悉達多太子降生說「天上天下唯我獨尊」、相師預言、淨飯王建四季宮殿留太子等示現因緣。講者指出唯我獨尊是指人人本有之心，人身可以成佛、佛法非宿命論；佛菩提道須三大阿僧祇劫，世尊成佛實為示現。","p":["彌勒以偈重問，恐後世生疑墮惡道","唯我獨尊指每人身中本有的真心","人間為六道樞紐，佛法非宿命論","相師預言太子必出家成佛","佛道須三大阿僧祇劫，非一世成就"],"k":["從地踊出品","彌勒偈頌","三大阿僧祇劫","示現成佛","唯我獨尊","宿命論"]},"6990-a28_024":{"s":"本集解釋偈中「忍辱心決定」，指出一般只談眾生忍，真正困難的是法忍。聲聞法忍在於接受覺知心、識陰虛妄，智慧上的心得決定遠勝禪定之力；並依《阿含正義》說明修因緣法須先懂十因緣「名色緣識、齊識而還」，批評執細意識、離念靈知為真如者未斷我見，指出無明死後存於如來藏。","p":["忍辱不只眾生忍，法忍更難","聲聞法忍：接受覺知心與識陰虛妄","智慧的心得決定勝於非想非非想定","不懂十因緣，因緣法無法成就","執細意識為真如，仍落名色未斷我見"],"k":["忍辱心決定","法忍","十因緣","識陰虛妄","名色","我見"]},"7004-a28_025":{"s":"本集續說三乘的「忍辱心決定」：依十因緣推知名色由本識如來藏所生，修十二因緣便不怕斷滅而能成辟支佛，此為緣覺法忍；通教菩薩再求證名色所緣之識，得大乘真見道的忍辱心。並說明真見道、相見道至初地通達位的次第，以《金剛經》被輕賤仍不退為例，說明實相智慧令忍辱心決定。","p":["名色由本識所生，齊識而還不能過彼","知有本識不墮斷滅，因緣觀方能成就","通教菩薩須證本識方入大乘見道","真見道、相見道至初地方為通達位","被輕賤仍不退轉，即大乘忍辱心決定"],"k":["忍辱心決定","十因緣","十二因緣","緣覺","真見道","相見道"]},"6987-a28_026":{"s":"本集導讀《法華經講義》第十四輯「忍辱心決定」一句，指出忍辱不是表面強忍或和稀泥。講者對照鳩摩羅什譯本與黃寶生新譯，認為此段說的是久學菩薩應有的修證與菩薩修行位階，批評太虛大師僅作字面解釋；並指出華文佛教界少有人講五十二階位，因講者自身未證解脫，無從宣說解脫知見。","p":["強壓怒氣、和稀泥並非真忍辱","唯四雙八輩才是佛的賢聖弟子","對照新舊譯，此段說菩薩修行位階","一字一拜拜法華，對道業助益有限","未得解脫者無法教人解脫知見"],"k":["忍辱心決定","五十二階位","久學菩薩","解脫知見","四雙八輩"]},"6980-a28_027":{"s":"本集說明「忍辱心決定」是對所證之法得決定忍，以法智忍、法智、類智忍、類智解釋修證完成的過程。講者指出初地之前皆可能退轉，二乘三果前亦有退分，引《中阿含》十八學人、九無學人與《菩薩瓔珞本業經》舍利弗等退轉之例，並以《經律異相》初果人退失後精進證三果的彩畫瓶故事為證。","p":["安忍即真正接受安住，於法得決定","法智忍、法智、類智忍、類智的次第","福德不足常致證悟後退轉","初地方為行不退，七住以前名退分","彩畫瓶喻：初果人重拾修證至三果"],"k":["忍辱心決定","法智忍","退轉","四向四果","行不退","福德"]},"6983-a28_028":{"s":"本集先引《雜阿含》與《瑜伽師地論》說明涅槃是內證法，不能僅靠信解思惟，每一位階都有應完成的忍辱心決定。接著介紹十信位的六堅（堅信、堅法、堅修、堅德、堅頂、堅覺）與初住至六住的信忍、法忍、修忍、正忍，以新手父親漸漸接受孩子為喻說明安忍，並強調六住斷我見、修四加行的重要。","p":["涅槃須實證，不能僅由信與思惟得","五十二位階各有應完成的心決定","十信位須完成六種堅固","安忍如新手父親漸漸接受孩子","六住正忍：斷我見、修四加行"],"k":["五十二階位","十信位","十住位","安忍","斷我見","四加行"]},"6992-a28_029":{"s":"本集續講菩薩位階，引《菩薩瓔珞本業經》說明七住以前為退分，得善知識護持方能入七住位不退。依序介紹七住無垢忍（證如來藏）、八至十住一切智忍（十住眼見佛性、世界如幻觀）、十行位聞慧至寂照慧（牢關），以及十迴向位習相定、性定至正觀定，並說明銅、銀、金寶瓔珞的差別。","p":["七住以前名退分，須善知識護持","七住無垢忍：現觀如來藏，真見道","十住眼見佛性，具世界如幻觀","十行位由聞慧至寂照慧，過牢關","十迴向修習相定至正觀定，準備入地"],"k":["七住位","眼見佛性","十行位","十迴向","菩薩瓔珞本業經","位不退"]},"7009-a28_030":{"s":"本集講入地後的十地位階與六觀。先以世親菩薩由五百部小乘論迴小向大、因曾謗大乘而僅鄰於初地的事蹟，說明入地之難，並批評「唯識三年，俱舍八年」之說。接著介紹初至三地住觀、四地行觀、五地向觀、六地重觀、七地無相觀、八至十地一切種智觀與等覺妙覺，最後指出法忍難成多因福德不足。","p":["世親謗大乘後迴心，僅鄰於初地","批評「唯識三年，俱舍八年」之說","初至三地住觀，三地發起意生身","五地向觀、七地無相觀、八地一切種智觀","法忍難成，多因福德不足、心性難轉"],"k":["十地","地上菩薩","世親菩薩","一切種智","無相觀","法忍"]},"6999-a28_031":{"s":"本集概說〈從地踊出品〉：先回顧〈安樂行品〉四安樂行，再敘述他方菩薩請求護持此經，佛答娑婆已有六萬恆河沙菩薩，隨即大地震裂、無量菩薩從地踊出，禮讚諸佛歷五十小劫。並述四位上首導師、彌勒請問菩薩來處、世尊答以皆其久遠所化，以及大眾以父少子老喻生疑，待〈如來壽量品〉解答。","p":["四安樂行：親近處、不自讚毀他、敬三寶、慈悲","他方菩薩請護經，佛言娑婆自有菩薩","菩薩從地踊出，禮讚諸佛經五十小劫","世尊言此等菩薩皆久遠以來所教化","彌勒為未來眾生請問，待壽量品解答"],"k":["從地踊出品","安樂行品","四安樂行","地涌菩薩","彌勒請問"]},"6993-a28_032":{"s":"本集說明從地踊出之事顯示佛道非一世可成，釋迦如來是古佛再來，為圓滿千兄弟次第成佛之願而示現為賢劫第四佛。接著依七種性介紹五十二位階：十信位凡夫性、十住位習種性（七住明心、十住見性）、十行位性種性（陽焰觀）、十迴向位道種性（破邪顯正的金剛行、如夢觀），至十地聖種性。","p":["釋迦如來古佛再來，為賢劫第四佛","十信位須深信因果、信受八識論","十住習種性：六住加行，七住明心","十行性種性須證陽焰觀","十迴向道種性破邪顯正，證如夢觀"],"k":["五十二階位","七種性","古佛再來","十信位","十迴向","八識論"]},"7011-a28_033":{"s":"本集依《法華經講義》第十五輯概說禪定：四禪八定須先修未到地定，依煩惱以不淨觀、慈心觀、數息觀、因緣觀對治，正覺則以無相念佛鍛鍊動中定力。並介紹欲界定、初禪須離欲界愛而非靠打坐、初禪善根發的三種情形；說明禪定皆是意識境界，不等於開悟，菩薩於三地滿心前須具足四禪八定與五神通。","p":["四禪八定前須先證未到地定","依煩惱選用不淨、慈心、數息、因緣觀","離欲界愛後，初禪自然發起","禪定屬意識境界，不能說是開悟","三地滿心前須具足四禪八定與五神通"],"k":["四禪八定","未到地定","初禪","無相念佛","四無量心","五神通"]},"7006-a28_034":{"s":"本集開講〈如來壽量品〉，說明從地踊出菩薩引起大眾信心危機，故世尊三誡信解誠諦之語。講者引《阿彌陀經》、《長阿含》七佛壽量、《佛名經》與《華嚴經》各佛剎時間差異，說明諸佛示現壽量差距極大，乃隨眾生因緣與諸佛因地別願；並以阿彌陀佛四十八願成就極樂世界為例，預告探討釋迦如來為何於五濁惡世成佛。","p":["世尊三誡信解，因大眾生信心危機","七佛壽量隨當時人壽而示現","各佛剎時間長短不同，壽量差異極大","淨土由大願善根生，穢土由業煩惱生","阿彌陀佛四十八願成就極樂世界"],"k":["如來壽量品","諸佛壽量","別願","四宏誓願","阿彌陀佛","淨土"]},"7017-a28_035":{"s":"本集依《悲華經》說明諸佛取淨土或穢土皆依本願，世尊因成就大悲而於五濁惡世成佛。講述世尊因地為寶海梵志，以「先歸依三寶、發菩提心才受施」度化閻浮提眾生，並供養寶藏如來七年；梵志夢見三種景象，寶藏如來解說轉輪聖王等以三福業求人天果報乃久受生死之相，梵志遂勸聖王發菩提心。","p":["諸佛以願力取淨土或五濁惡土","世尊因成就大悲，於穢土成佛","寶海梵志要人歸依三寶發心方受施","三夢之一：聖王諸子求人天果報之相","只求人天果報如癡嬰兒，唯菩提心離苦"],"k":["悲華經","寶海梵志","大悲","五濁惡世","發菩提心","三福業"]},"7001-a28_036":{"s":"本集續講《悲華經》：轉輪聖王初愛樂生死，見寶藏如來顯現諸佛世界後，發願於無三惡道的清淨世界成佛，千王子等亦求淨土。梵志八十子發願於不淨世界成佛，觀世音、普賢發願於穢土救護眾生；梵志說明心向菩提而行布施、持戒、多聞、思惟方為助菩提法，三億弟子多願於此界成佛，婆由比紐願於五濁惡世成佛。","p":["轉輪聖王回心，願於清淨世界成佛","成就大悲者方取不清淨世界","觀世音、普賢發願在穢土救護眾生","心向菩提而行布施等，方為助菩提法","婆由比紐發願於五濁惡世成佛"],"k":["悲華經","寶海梵志","淨土與穢土","助菩提法","大悲願","轉輪聖王"]},"6995-a28_037":{"s":"本集續述《悲華經》梵志弟子的發願與授記：婆由比紐授記為金山王如來，九百九十九人於賢劫成佛，迦葉佛於初入五濁時成佛，持力捷疾為樓至如來。寶海梵志感慨眾菩薩多捨五濁眾生，遂發願於賢劫人壽一百二十歲以下的五濁惡世成佛，不惜入地獄受苦以攝受眾生，共發五百大悲願，十方菩薩來三讚歎。","p":["娑婆名忍土，賢劫有千佛大悲出世","賢劫諸佛未必都在五濁惡世成佛","梵志不捨被諸佛世界擯棄的惡世眾生","願於人壽百二十歲以下時下生成佛","五百大悲願，感十方菩薩三讚歎"],"k":["悲華經","寶海梵志","五百大願","賢劫千佛","五濁惡世","授記"]},"7013-a28_038":{"s":"本集總結《悲華經》：寶藏佛授記寶海梵志於五濁惡世成佛；世尊攝受眾生首先勸令「歸依三寶、發阿耨多羅三藐三菩提心」，再勸住六波羅蜜行菩薩道。講者說明依止佛才是究竟歸依、菩薩性非本有，並以《悲華經》十方諸佛多是世尊昔日勸發心者，佐證〈如來壽量品〉「我實成佛已來無量無邊百千萬億那由他劫」。","p":["寶藏佛授記梵志於五濁惡世成佛","先由佛調伏，方能歸依法與僧","菩薩性非本有，須有因緣促發","十方諸佛多為世尊昔日勸發心者","淨土與穢土成佛是諸佛默契分工"],"k":["如來壽量品","悲華經","歸依三寶","發菩提心","六波羅蜜","菩薩性"]},"7007-a28_039":{"s":"本集講〈如來壽量品〉「如來如實知見三界之相，無有生死若退若出」，說明如來具一切種智與死生智力，所說皆實不虛。如來依佛眼見眾生本具的第八識如來藏真實我，本無生死；凡夫執五陰為我而怖畏生死，或厭世或縱欲。講者以生死大事為檢驗善知識的照妖鏡，舉廣欽老和尚「沒來沒去沒代誌」為例，勸學人向所依止者問明。","p":["如來是真語者，如實知見三界之相","依第八識真實我，有情本無生死","凡夫執五陰為我，或厭世或縱欲造惡","一神教永生之說不能解決生死","生死大事可作檢驗善知識的照妖鏡"],"k":["如來壽量品","生死大事","如來藏","真實我","善知識","五陰"]},"6997-a28_040":{"s":"本集為「如何看待生死大事？」第二集，先依《大乘入楞伽經》說明聲聞、緣覺、如來、不定、無種性五種種性，指出許多信眾只修人天善法、尚未探究生死大事。接著點名批評廣論團體以布施行善包裝宗喀巴《廣論》與喇嘛教六識論、雙修之法，並指其領導者金真如名為真如而未證真如。","p":["《楞伽經》五種種性與探究生死大事的關係","無種性者以人天善法為佛法全部","修三福淨業者已入十信位、長養信根","廣論團體以人天善法包裝喇嘛教邪見","金真如名真如卻未證第八識真如心"],"k":["生死大事","五種種性","人天善法","廣論團體","六識論","真如"]},"7032-a28_041":{"s":"本集引金真如〈給武漢同學的一封信〉所說「心上無自性、證得無自性即離輪迴苦」，對照達賴「萬法畢竟無自性」，逐一追問所說是哪個心、哪個我會去後世，論其墮入斷滅空見。並指雙修樂受屬六識了知六塵、眠熟即斷，非真如心；引《佛藏經》「身未證法而在高座」說明法義辨正的用意。","p":["檢視金女士無自性、證空性的說法","追問：是哪個心、哪個我去到下一世","捨報即無則成斷滅空外道見","雙修樂受屬六識，眠熟即滅，非真如","引《佛藏經》說未證而教人之過失"],"k":["無自性","斷滅空","六識論","真如心","佛藏經","雙身法"]},"7024-a28_042":{"s":"本集引《佛藏經》「比丘說法雜外道義，善比丘應從座去」，勸廣論信眾離開。說明佛法探究生命本源、超越世間哲學；佛世前外道已有斷滅見，外於第八識如來藏修道即屬外道。並以眼識能見之性為例，解釋現象諸法依因緣和合而有，故說無自性，凡夫執六識身為我即是身見。","p":["《佛藏經》：說法雜外道義應從座去","佛法究明生死根本，非世間哲學","外於如來藏言修道即屬外道、墮斷滅","無餘涅槃是第八識獨住境界","眼識自性因緣和合假有，故無自性"],"k":["無自性","如來藏","斷滅空","身見","無餘涅槃","佛藏經"]},"7029-a28_043":{"s":"本集為「如何看待生死大事？」完結篇，依三轉法輪說明正確的諸法無自性空：阿含觀行蘊處界無常而斷三縛結至四果，阿羅漢不懼涅槃因有本際；阿含以入胎識等隱說第八識。大乘無自性依空性如來藏的圓成實性而說，勝義無自性性為八地以上所證；批評達賴「空性哲學」，並以《法華經》「無有生死」作總結。","p":["阿含觀行諸法無自性空、次第證四果","《雜阿含》法住法空法如法爾指真實法","阿含以入胎識、齊識而還隱說第八識","大乘依如來藏真實自性說諸法無自性","總結：有情真實我本無生死"],"k":["無自性","空性如來藏","三轉法輪","圓成實性","無餘涅槃","勝義無自性性"]},"7034-a28_044":{"s":"本集講解〈如來壽量品〉「我本行菩薩道所成壽命，今猶未盡，復倍上數」至「如來難可得見」一段。說明如來報身壽命依因果必定無盡，唱言滅度只是方便；因五濁惡世薄德之人見佛常在會起憍恣厭怠，故以優曇缽華、過去七佛間隔等說明佛難值遇，令眾生生起難遭之想與恭敬心。","p":["行菩薩道所成報身壽命無盡","唱言滅度是教化眾生的方便","五濁薄德者見佛常住會生憍恣厭怠","優曇缽華、過去七佛喻佛難值遇","生難遭之想才會恭敬親近"],"k":["如來壽量品","如來難可值遇","方便示現滅度","報身壽命","優曇缽華","五濁惡世"]},"7040-a28_045":{"s":"本集續講「如來難可得見」，指出諸佛比父母更應恭敬，薄德者可能無量劫不見佛。批評一般佛教徒只參加法會，以及主張大乘非佛說、如來藏是外道神我者罪重如一闡提。說明佛宣告三月後入滅，令自負外道與眾生生戀慕渴仰而種善根，同時示現五陰終滅、勸斷我見我執。","p":["諸佛如來比生身父母更值得恭敬","薄德之人可經無量劫不遇佛","謗大乘、謗如來藏者斷善根罪重","宣告入滅令眾生戀慕渴仰而種善根","示現滅度亦教人不執著五陰"],"k":["如來難可值遇","種善根","一闡提","大乘非佛說","示現滅度","如來壽量品"]},"7026-a28_046":{"s":"本集白話解說〈如來壽量品〉良醫喻全段，並開始講解：良醫出遠門、諸子誤飲毒藥，有失本心與不失本心者。失本心喻退轉者，誤信一念不生、離念靈知、如來藏是外道神我等而正邪不分；「依諸經方，求好藥草」喻諸對治法，「擣篩和合」喻統整為五乘法，大良藥即法與次法。","p":["良醫喻經文白話語譯","諸佛示現滅度如良醫不能長伴諸子","失本心喻退轉、正邪不分之人","擣篩和合喻統整為五乘法","大良藥即法與次法具足"],"k":["良醫喻","如來壽量品","失本心","法與次法","五乘法","退轉"]},"7030-a28_047":{"s":"本集續講良醫喻：不失心者喻三賢位不退、願具修法與次法者；失心者我見我執深重，不肯依法實修。父親示現死亡後諸子醒悟服藥，喻弟子在佛滅後自行修法與次法、降伏煩惱，名聞、財物、眷屬、權力最難除；煩惱漸輕時如來再來示現，弟子便能速成阿羅漢乃至入地，故良醫無虛妄之過。","p":["不失心者具修法與次法而病除","失心者我見我執深，不肯服藥","佛滅後弟子醒悟，依法藥自修","欲界愛中名財眷屬權力最難除","煩惱除後如來再現，速證果入地"],"k":["良醫喻","法與次法","失本心","性障","如來壽量品","方便示現滅度"]},"7038-a28_048":{"s":"本集講解〈如來壽量品〉重頌「自我得佛來」至「但謂我滅度」。說明諸佛因十無盡願常住，世人只見悉達多成佛的表相；如來留碎身舍利，讓信根未具者藉供養舍利維持信心。眾生質直柔軟、一心欲見佛時，佛便出現說法，如阿闍世王見佛得無根信；並指如來必說完大乘無上法才示現涅槃。","p":["偈頌重宣：成佛久遠、常住靈鷲山","十無盡願故諸佛不入滅","碎身舍利令眾生維持信心","質直意柔軟、一心欲見佛時佛現","如來必說大乘無上法方示涅槃"],"k":["如來壽量品","常住靈鷲山","舍利","十無盡願","無根信","無上法"]},"7054-a28_049":{"s":"本集依《法華經講義》講解「我見諸眾生，沒在於苦惱，故不為現身，令其生渴仰；因其心戀慕，乃出為說法」。說明佛不常現身是因物以稀為貴；舉平實導師早年勸同修不被相信、願者上鉤為例，以佛法精品店喻如來藏妙法需七聖財。並說佛菩薩依眾生因緣安排受生與接引。","p":["佛不常現身，令眾生生渴仰","平實導師早年勸法不被信的例子","如來藏妙法如精品，須七聖財","渴仰戀慕成熟，佛才出現說法","佛菩薩依因緣安排受生與接引"],"k":["如來壽量品","渴仰心","如來藏","七聖財","佛難值遇"]},"7044-a28_050":{"s":"本集講解偈頌「神通力如是」至「速成就佛身」，重點說明釋迦如來的四種淨土：常寂光土、實報莊嚴土、方便有餘土、凡聖同居土，並舉大迦葉住方便有餘土、通教菩薩往生該土為例。從理上說每人自身也有四土；強調未見不等於不存在，劫火不燒淨土；謗法具根本、方便、成已三罪者即一闡提。","p":["釋迦如來亦有四種淨土","大迦葉、通教菩薩住方便有餘土","理上每人自身亦具四種淨土","未見不等於不存在，劫火不燒淨土","謗法具三罪者久不聞三寶名"],"k":["四種淨土","如來壽量品","凡聖同居土","通教菩薩","一闡提","謗法"]},"7056-a28_051":{"s":"本集講解「諸有修功德，柔和質直者，則皆見我身」以下偈頌。說明修功德、柔和質直者能值遇諸佛，供養應身佛功德最大；對菩薩性具足者說佛壽無量，對根淺者說佛難值、勸念佛往生極樂，作為對治方便。並勸留在娑婆值遇賢劫千佛，續釋「我智力如是」「如醫善方便」等句。","p":["柔和質直、修功德者能見佛","賢劫千佛應一一承事供養","對不同根性說佛壽無量或佛難值","念佛往生極樂是對治的方便","佛語實不虛，良醫喻再申明"],"k":["佛難值遇","佛壽無量","柔和質直","念佛法門","賢劫千佛","如來壽量品"]},"7060-a28_052":{"s":"本集講解「以常見我故，而生憍恣心，放逸著五欲，墮於惡道中」。批評有人斥正覺為阿賴耶外道，指若然則諸地菩薩皆成外道。並詳述佛世鸚鵡摩納都提因對佛起憍慢而墮為白狗、其子先起惡心後懺悔的故事，說明對佛起善心或惡心果報差距極大，應對佛生恭敬。","p":["常見佛者易生憍恣、放逸五欲","反駁稱實證阿賴耶識為外道的說法","鸚鵡摩納都提墮為白狗的故事","對佛善心生天，惡心墮惡道","佛為利生取人身，本質非凡人"],"k":["恭敬心","憍慢","阿賴耶識","因果業報","如來壽量品"]},"7046-a28_053":{"s":"本集講解「我常知眾生，行道不行道，隨所應可度，為說種種法」，以佛用火堆譬喻勸誡出家人、六十比丘證果與六十比丘還俗為例；並解「速成就佛身」為三身，結束〈如來壽量品〉。接著進入〈分別功德品〉，說明聞佛壽長遠得大饒益，並解釋無生法忍、聞持陀羅尼、樂說無礙辯才、旋陀羅尼對應的菩薩地位。","p":["佛觀眾生根性，隨所應度說法","火堆喻：六十比丘證果、六十還俗","以何令眾生速成就三身佛","〈分別功德品〉：聞佛壽長遠得大饒益","無生法忍、陀羅尼、無礙辯對應諸地"],"k":["分別功德品","如來壽量品","無生法忍","陀羅尼","樂說無礙辯","善巧方便"]},"7050-a28_054":{"s":"本集探討培植福德，引《法華經講義》說外道猖狂時護持正法福德最大，但須以八識論判別正法以免種於毒田。引《成唯識論》說明第八識持種使因果不失，並說天魔亦修福、破戒樂施者墮惡道仍飽滿。依《瑜伽師地論》說福依智起、福慧缺一不能成佛，六度須全修，否則只成乾慧。","p":["外道猖狂時護持正法福德最大","以八識論抉擇正法，避免種毒田","第八識持種，因果昭然不失","福慧須雙修，六度不可只修般若","菩薩二作意：悟入所知、利益眾生"],"k":["培植福德","護持正法","八識論","福慧雙修","六度","種子識"]},"7058-a28_055":{"s":"本集探討「佛名聞十方，廣饒益眾生」：諸佛互相讚歎，釋迦讚阿彌陀佛，十方佛亦讚娑婆修行快速。引《悲華經》等說明釋迦因地大悲菩薩的願眼，名號意為能仁、寂靜。並以十號中的正遍知、佛佛道同說明諸佛本質，萬法源於如來藏，須依八識論理解；彌勒成佛前此世界無人成佛。","p":["諸佛互相讚歎，應不同眾生根性","釋迦因地大悲菩薩發大悲願眼","釋迦牟尼意為能仁與寂靜","正遍知與佛佛道同，皆依如來藏","彌勒成佛前，自稱成佛者皆誤"],"k":["佛名號","大悲願","正遍知","八識論","佛壽無量","諸佛本質"]},"7062-a28_056":{"s":"本集探討修學般若波羅蜜，依《法華經》「於八十萬億那由他劫數，行五波羅蜜」，指許多人因師說落在意識與現象界，只修前五度及表相般若。分析意識與五別境心所相應而易被誤認為真我；說明般若即親證常住真心第八識而真見道，第一義諦為非安立諦，並以三種流轉、錠光佛授記說明其重要。","p":["無真善知識者多劫只修前五度","表相般若以意識當作實證標的","意識與五別境相應，易被執為我","親證第八識常住真心方有般若","三種流轉須依八識論方能解釋"],"k":["般若波羅蜜","如來藏","第一義諦","六度","意識","真見道"]},"7048-a28_057":{"s":"本集探討「多聞聖弟子」，說明智慧從多聞而生，須經聞思修並由善知識指導，引《心地觀經》親近善友為第一。依《瑜伽師地論》說具足多聞的十相：說法者五種、聽法者五種；並引《大智度論》、《楞嚴經》「清淨在音聞」、《月燈三昧經》多聞利益，最後勸以四攝法與同修廣結善緣。","p":["智慧從多聞熏習、融會貫通而生","親近善友為修學第一步","具足多聞須說者與聽者各五條件","多聞與智慧須兼具，如燈與目","以四攝法與同修廣結善緣"],"k":["多聞","善知識","聞思修","親近善友","四攝法"]},"7051-a28_058":{"s":"本集探討「多聞能總持，隨義解佛語」，說明總持即總綱憶持，如〈正覺總持咒〉。二乘總持為斷我見、我執，且須信有本際；大乘總持為真如與佛性，即明心見性，再次第證七真如、十地真如至一切種智。並引篤補巴《山法》基道果，以及《心地觀經》教理行果四種法寶，作為掌握法義的架構。","p":["總持是掌握佛法綱要的方便","二乘總持：斷我見與我執","大乘總持：真如與佛性、明心見性","《山法》基道果與成佛要旨一致","教理行果四面向理解法寶"],"k":["總持","真如佛性","明心見性","斷我見","教理行果","正覺總持咒"]},"7064-a28_059":{"s":"本集講解〈分別功德品〉「若有聞佛壽命長遠，解其言趣……能生一切種智」。說明「解其言趣」須實證此經如來藏，知有情自心如來不生不滅，非僅知報身壽無量；並依次解釋廣聞是經、教人聞、自持教人持、自書教人書的功德。強調經教是證明如來藏的依據、宗門與教門一致，並批評印順大乘非佛說、如來藏梵我說。","p":["解其言趣須實證此經如來藏","悟後應廣聞諸菩薩演說《法華經》","教人受持此經功德勝度萬阿羅漢","書寫保存經教，作為法義依據","宗門與教門所證同為如來藏"],"k":["分別功德品","佛壽命長遠","如來藏","宗門與教門","受持經典","大乘非佛說"]},"7070-a28_060":{"s":"本集接續〈如來壽量品〉，說明解其言趣、聽聞、受持、書寫此經的功德為何無有限量：功是自受用、德是他受用，須以證得此經如來藏為基礎，並舉梁武帝與達摩的對話區分福德與功德。又說以香花等供養經卷也是功德無量，但前提是先在正法道場聽聞了義法，並以一行三昧須先聞般若為例說明。","p":["功是自受用、德是他受用，無形不可限量","梁武帝造寺度僧只得人天有漏福報","供養經卷前須先聽聞了義正法","一行三昧須先聞般若波羅蜜","一切種智的根源在證如來藏"],"k":["功德","福德","如來藏","一行三昧","供養經卷","一切種智"]},"7066-a28_061":{"s":"本集講解〈分別功德品〉「聞我說壽命長遠，深心信解，則為見佛常在耆闍崛山」一段。說明深心信解須實證如來藏且不退轉，靈鷲山即指如來藏，並批評釋印順否定佛壽長遠與大乘佛說。再以極樂世界三輩往生為例，論證諸佛皆有四種淨土，釋迦如來也有方便有餘土與實報莊嚴土。","p":["深心信解須實證且不退轉","批評釋印順視大乘為對佛的永恆懷念","四阿含已說三乘，證大乘是佛說","常在靈鷲山的靈鷲山即如來藏","諸佛皆具四種淨土，釋迦如來亦然"],"k":["四種淨土","深心信解","如來壽量","如來藏","大乘是佛說","分別功德品"]},"7080-a28_062":{"s":"本集續說釋迦如來的淨土：往生其方便有餘土、實報莊嚴土至少須斷三縛結或已開悟，並與往生極樂、琉璃世界的條件對比；同時批評釋印順「大乘經出於對佛永恆懷念」之說自相矛盾。接著解釋聞經不毀訾、起隨喜心即是深信解相，讀誦受持則為頂戴如來，並以趙州轉經公案說明真正的讀誦。","p":["知見心量廣闊則福德智慧增長快","往生釋迦淨土至少須斷三縛結或開悟","批評「永恆懷念」說無法立足","聞經不毀訾而隨喜即深信解相","頂戴如來者，如來盡量教授"],"k":["四種淨土","深信解相","頂戴如來","讀誦受持","釋印順批評","轉經"]},"7074-a28_063":{"s":"本集講解〈分別功德品〉「不須為我復起塔寺……則為以佛舍利起七寶塔，高廣漸小至于梵天」經文。說明深心信解並讀誦受持此經者，功德勝過造寺供僧，因為正法存續比寺廟表相更重要；並區分碎身舍利與法舍利，以在眾生心中建法舍利七寶塔、以三十七道品為莊嚴來解釋經義。","p":["頂戴如來須具足深信解等四條件","受持此經即等同起塔造僧坊供眾僧","正法存在比寺院表相更重要","法舍利即如來所傳三乘菩提妙法","七寶塔漸小至梵天，喻實證者次第上生"],"k":["頂戴如來","法舍利","七寶塔","供養眾僧","分別功德品","三十七道品"]},"7083-a28_064":{"s":"本集依《法華經講義》第十六輯，講解〈分別功德品〉「精進勇猛攝諸善法」與「常貴坐禪得諸深定」。說明在正覺修學悟前悟後都很辛苦，菩薩乃至成佛也不輕鬆，還須忍受辱罵；勸勉勿忘「法門無量誓願學」。又說末法時深定難得，至少須達離五塵的二禪，能具足這些功德者必是利根。","p":["悟前悟後修福、除性障都辛苦","世尊成佛後度眾、制戒亦不輕鬆","菩薩受辱罵可消先世罪業","莫忘四宏誓願「法門無量誓願學」","深定至少須離五塵，具諸德者必利根"],"k":["精進勇猛","深定","四宏誓願","忍辱","利根","分別功德品"]},"7086-a28_065":{"s":"本集說明「利根智慧善答問難」：利根菩薩不是世間聰明伶俐的人，而是無心世法、願為眾生與正法吃虧付出的人，所以能斷三縛結。接著講「已趣道場，近阿耨多羅三藐三菩提，坐道樹下」及「若坐若立若行處，此中便應起塔」，並回顧正覺二十餘年著書弘揚此經如來藏的艱辛。","p":["世間聰明者在出世間法上反是鈍根","願為眾生、正法吃虧者道業進展快","末法弘揚此經如來藏極為困難","已趣道場指入地、邁向佛地","坐道樹下即能為眾廣說種種法"],"k":["利根","善答問難","已趣道場","如來藏","弘法艱辛","起塔供養"]},"7072-a28_066":{"s":"本集續講「若坐若立若行處，此中便應起塔」，說明其根源在於智慧，即《解深密經》所說七真如的實證與無生法忍。接著語譯、釋義〈分別功德品〉重頌「若我滅度後，能奉持此經，斯人福無量」，指出末法眾生執著離念靈知等內我所，受持此經如來藏而不退極難，所以福德無量，並以稀有黑珍珠為喻。","p":["功德歸根於智慧，即七真如的實證","奉持此經即為起七寶塔供養","大師教人「把握自己」是執著內我所","末法受持此經如稀有黑珍珠","被罵可消先世罪業，反能攝受對方"],"k":["七真如","起塔供養","此經如來藏","末法受持","離念靈知","重頌"]},"7068-a28_067":{"s":"本集語譯〈分別功德品〉重頌「若能持此經，則如佛現在，以牛頭栴檀，起僧坊供養」等段，說明受持此經如來藏勝過建造三十二堂僧坊供養，因為此經是三乘菩提的根本。並批評「緣起性空、大乘非佛說」等是相似像法，述及天竺大乘正法被密教排擠而滅，最後說明真正受持、讀誦、書寫此經的意涵。","p":["受持此經勝過造僧坊供養僧眾","佛教根本在法，不在寺院與僧數","相似像法廣弘則了義正法隱沒","天竺「密教興而佛教亡」","真書寫此經是為人書寫如來藏妙法"],"k":["受持讀誦書寫","如來藏","相似像法","僧坊供養","密教興佛教亡","重頌"]},"7078-a28_068":{"s":"本集續說受持、讀誦、書寫此經的真義，舉捧經過頂、向虛空一勾等例，並提醒證悟者與野狐大師都可能如此表現。說明證悟者從實際理地供養經卷，功德福德勝過凡夫的豐盛供養；介紹須曼、瞻蔔、阿提目多伽、薰油等供品，並批評密宗用動物酥油。接著講「兼布施持戒……遠離自高心」，勸悟後勿起慢心而應一味平懷。","p":["總持讀誦、虛空書寫，須辨證悟與野狐","證悟者依實際理地供養，功德更大","解釋善攝意花、薰香草、薰油等供品","悟後須除自高心，修非安立諦三品心","遇出家人合掌，崇隆表相僧寶"],"k":["受持讀誦書寫","供養經卷","遠離自高心","一味平懷","實際理地","野狐大師"]},"7077-a28_069":{"s":"本集講解〈分別功德品〉重頌「有問難不瞋，隨順為解說」及「若見此法師……生心如佛想」等句。說明菩薩犯瞋罪重，應把問難視為請法並隨根性解說，以攝受眾生與佛土；分析「況復」二字所顯示三種人的功德層次，依《雜阿含經》定義法師，批評以離念靈知為開悟者不是法師，並解釋「應起塔」是在心中恭敬這位法師。","p":["菩薩犯瞋罪重，惡緣令眾生不隨學","把問難當作誠懇請法，隨根性解說","「況復」顯示三種人功德遞增","依《雜阿含》，說五陰厭離滅盡者名法師","起塔指心中恭敬法師的五蘊七寶塔"],"k":["有問難不瞋","法師","攝受佛土","四攝法","離念靈知","分別功德品"]},"7085-a28_070":{"s":"本集說明重頌「其所住止處……是中應起塔」之所以要如此供養，是因為這位法師證得七真如，並區分二乘法師、大乘法師與此處法師的層次。接著依《解深密經》、《成唯識論》、《瑜伽師地論》解說七真如中的邪行真如（集諦實性，含惡行、外道邪行與佛門三學邪行）及流轉真如（一切行流轉中真如無先後地顯示）。","p":["法師須證七真如方值得起塔供養","二乘法師與大乘法師的說法內涵不同","列出七真如的名目","邪行真如即集諦的實性","流轉真如：一切行流轉中真如無先後"],"k":["七真如","邪行真如","流轉真如","法師","集諦","解深密經"]},"7092-a28_071":{"s":"本集續講七真如中的了別真如、相真如與安立真如。了別真如指一切有情了別的過程（率爾心、尋求心、決定心等）中剎那顯示第八識真如性；相真如指從人無我、法無我的法相中顯示真如；安立真如則依苦聖諦，為三界六道一切有苦的有情安立種種真如。","p":["一切有情皆有了別，了別過程即行陰","了別真如：一切行唯是識性","相真如是二無我所顯的實性","三界有情沒有純樂無苦者","安立真如依苦聖諦而安立"],"k":["了別真如","相真如","安立真如","七真如","二無我","苦聖諦"]},"7088-a28_072":{"s":"本集講解七真如中的清淨真如：二乘以滅聖諦為清淨，初果到阿羅漢的清淨層次各不相同，阿羅漢也不是究竟清淨。入地菩薩須依勝鬘夫人所說無作、無量四聖諦，依本來無生而修，斷盡現行與習氣種子，度過變易生死，到佛地才是究竟清淨真如；並描述三地滿心色陰盡等五陰盡的境界。","p":["二乘的清淨真如即滅聖諦","初果到阿羅漢清淨程度不同","菩薩依無作四聖諦、本來無生而修","斷盡習氣種子與變易生死才究竟清淨","色陰盡在三地滿心，識陰盡在佛地"],"k":["清淨真如","七真如","大乘四聖諦","五陰盡","變易生死","滅聖諦"]},"7102-a28_073":{"s":"本集講解七真如最後的正行真如，即道諦實性：二乘雖行八正道但未證真如，大乘須先證此經如來藏，依本來無生修八正道，到妙覺位才圓滿。並以趙州「胡來胡現」與明鏡為喻，說一切法攝歸如來藏本來無生；強調法師只看實證、不論身相；最後說「是中應起塔」是在心中起塔、行法供養，「佛子住此地，則是佛受用」指入地菩薩受用此經。","p":["正行真如即道聖諦的實性","大乘無生是本來無生，非將滅止生","胡來胡現喻一切法攝歸如來藏不生","法師不論身相，只看有無實證","心中起塔，以護持正法為法供養"],"k":["正行真如","本來無生","八正道","七真如","法供養","法師"]},"7106-a28_074":{"s":"本集接續〈分別功德品〉「能奉持此經，斯人福無量」，從世俗角度談為何修學真正的佛法很重要。說明上香求平安財富只是民間信仰，學佛至少要與解脫道相應，進而走上佛菩提道；以貧富差距、天災、生死等世間無解的問題，質疑「萬能創造者」之說；並引《悲華經》說明娑婆即堪忍之義與賢劫千佛的因緣。","p":["上香求世俗願只是民間信仰","學佛至少須與聲聞解脫道相應","世間法無法解決病死、天災等問題","質疑創造者為何讓人先生人間受苦","《悲華經》說娑婆名忍土、賢劫千佛"],"k":["真正學佛","奉持此經","娑婆世界","民間信仰","賢劫千佛","解脫道"]},"7096-a28_075":{"s":"本集續談奉持此經福德無量的原因，從「若世間沒有真正佛法住世」來設想：三乘菩提才是真正的佛法，人天乘之法與外道共通；末法時佛法只剩名相與表相，偏重名聞利養，人天善法也會隨之變質。並比較其他宗教標榜唯一、未能令人出離生死，引《八十華嚴經》發心住，說明佛菩薩多劫示現護持學人建立信心。","p":["真正佛法是三乘菩提，人天乘共外道","無正法住世，佛教只剩表相","人天善法也將隨之變質","其他宗教未能助人出離生死","佛菩薩多劫示現，助學人發菩提心"],"k":["三乘菩提","末法","奉持此經","發心住","人天善法","三世因果"]},"7100-a28_076":{"s":"本集先引《增壹阿含經》迦葉尊者授記末法比丘貪著衣食、經法凋落，說明末法佛法表面興盛而多求世間福。接著進入〈隨喜功德品〉，說明「聞是經隨喜轉教，展轉至第五十」功德不可思議，「此經」即每一有情身中的真心如來藏；並引《大般若經》較量，教一人趣向無上菩提勝過令全洲有情證獨覺，因能令世間佛眼不斷。","p":["末法借佛法名相謀利者眾多","迦葉授記比丘貪衣食致經法凋落","此經即有情身中的真心如來藏","第五十人隨喜功德勝過大施主","教一人趣無上菩提，令佛眼不斷"],"k":["隨喜功德","如來藏","第五十人","奉持此經","末法","大般若經"]},"7094-a28_077":{"s":"本集說明此經之法須有更多人奉持才能在世間弘傳，並分析不能奉持此經的人：只高唱「明天會更好」而不求出離者，以及自以為能救眾生卻貪名利者。舉世尊降伏六師外道、玄奘菩薩造《成唯識論》破外道為例，指出依此經受持才是佛道；批評醫學、哲學、AI誤計萬法本因，並解說「四依四不依」其實是一，都是依是否受持此經而說。","p":["不求出離者不可能奉持此經","世尊、玄奘皆以善巧降伏外道","依此經受持名佛道，此外名外道","醫學、哲學、AI皆誤計萬法本因","四依四不依其實是一"],"k":["四依四不依","外道","奉持此經","玄奘","萬法本因","依法不依人"]},"7090-a28_078":{"s":"本集為「不思議福」系列的總結，從「信為道元功德母」談佛法所說的信：先對佛法僧生清淨信、信自身有本際，並持五戒成就四不壞信，才能分證解脫道；發菩提心進入初住位則需要更深的信。並引《分別布施經》、《八十華嚴經》、《摩訶般若波羅蜜經》，說明學般若如說行勝過供養無量諸佛，歸結奉持此經福德無量。","p":["佛法的信不同於世間與哲學的信","分證三乘須先於佛法僧生清淨信","歸依並持戒，成就四不壞信","發菩提心入初住，須信自己可成佛","學般若如說行，福勝供養無數佛"],"k":["清淨信","四不壞信","發菩提心","般若波羅蜜","奉持此經","本際"]},"7104-a28_079":{"s":"本集講解〈隨喜功德品〉：勸人聽講《法華經》，來世可與持陀羅尼的九地菩薩共會，口齒健康、相貌端嚴；輾轉隨喜到第五十人，功德仍勝過廣施無量世界眾生並令成阿羅漢的大施主。也說往詣聽法、分座勸坐的天人果報；後段說明二乘涅槃是滅盡五陰而實無人入涅槃，涅槃本際即第八識如來藏，大乘涅槃是如來藏自住境界。","p":["勸人聽法華經，來世與九地菩薩共會","第五十人隨喜功德勝過大施主","往詣聽法、分座勸坐皆得天人果報","二乘涅槃是滅盡五陰，實無人入涅槃","涅槃即如來藏的自住境界"],"k":["隨喜功德","涅槃","如來藏","第五十人","一佛乘","勸人聽法"]},"7098-a28_080":{"s":"本集說明真正的「法師」須有學有證、不排斥大乘並能親證實相。講者指離念靈知仍是六識心，無法去到後世；引《佛說法印經》「諸蘊本空，由心所生」及《雜阿含經》，說明五陰由如來藏出生，如來藏無記、離見聞覺知，能容受善惡種子，是生死與涅槃共同的所依。","p":["法師須有學有證，不排斥大乘並親證實相","離念靈知仍屬六識心，無法去到後世","諸蘊由心所生，五陰依如來藏流注種子而有","如來藏無記性，能容受一切善惡種子","二乘法亦說法不離如，阿羅漢滅不了本識"],"k":["法師","如來藏","五陰","離念靈知","二乘聖教","無記性"]},"7112-a28_081":{"s":"本集引《雜阿含經》「法住、法空、法如、法爾；法不離如，法不異如」，說明緣起諸法皆攝歸本住法如來藏，顯示阿含中已有大乘法。再以「識緣名色」「齊識而還，不能過彼」說明名色之外有不可滅的本識（第八識），十二因緣所滅的是無明而非本識；並引《中阿含經》說如來所依識。","p":["法住、法空、法如、法爾皆攝歸如來藏","識緣名色：名色之外有本識即第八識","齊識而還：本識是源頭，不生不滅","十二因緣滅的是無明，不是滅第八識","中阿含：諸天求如來所依識而不可得"],"k":["二乘聖教","本識","第八識","十因緣","十二因緣","真如"]},"7120-a28_082":{"s":"本集講受持《法華經》者得六根功德，說明眼根有侷限為八百功德、耳根周遍為一千二百功德，並述三地滿心色陰盡時能以肉眼觀眾生因緣業報。另談《楞嚴經》五陰盡與六根互通、明心與眼見佛性兩階段，以六即佛說明修證次第，最後勸法師領眾應心懷慈愍。","p":["眼根八百、耳根一千二百功德的差別","三地滿心色陰盡，肉眼能觀眾生業報","楞嚴經說五陰盡與六根互通，非偽經","六即佛：從理即佛到究竟即佛的次第","法師領眾不宜絕情，應慈愍弟子"],"k":["六根功德","色陰盡","楞嚴經","六即佛","明心見性","法師"]},"7115-a28_083":{"s":"本集批評密宗為相似佛法，指其雙身法、金剛薩埵、灌頂、輪座等違背須離欲方得初禪的法理，並批評月輪觀、五方佛、誅殺法、時輪續及以歸依金剛上師為首的四歸依。講者也談一貫道斗姥與摩利支天密續的關聯，勸清淨法師遠離密宗、剔除相關儀軌。","p":["雙身法違背須離欲界愛方得初禪之理","批評金剛薩埵、灌頂與輪座等說法","批評月輪觀、五方佛與誅殺法","四歸依將金剛上師置於三寶之前","一貫道斗姥與摩利支天密續的關聯"],"k":["密宗","雙身法","金剛薩埵","四歸依","初禪","一貫道"]},"7108-a28_084":{"s":"本集講〈法師功德品〉耳根一千二百功德經文。理上說一切聲皆由如來藏所發，並以《楞嚴經》耳根圓通「入流亡所」說明須聽聞善知識正法、放流五陰我見；事上指三地滿心色陰盡者不需天耳即能以父母所生耳聽聞。並解說象馬牛車、啼哭愁嘆、螺鼓、鐘鈴等聲的意涵。","p":["受持此經得耳根一千二百功德","理上一切聲皆是如來藏聲","入流亡所：聽聞正法、放流五陰我見","三地滿心色陰盡，不需天耳即能聽聞","啼、哭、愁嘆之別及鐘鈴用途不同"],"k":["耳根功德","耳根圓通","入流亡所","如來藏聲","色陰盡","法師功德品"]},"7118-a28_085":{"s":"本集續講耳根功德經文中各種聲音：笑聲語聲、男女聲、童子童女聲、法聲與非法聲、苦樂聲、凡夫聲與聖人聲、喜與不喜聲。並說明天龍八部的聲音特徵，詳述阿修羅遍於五趣、金翅鳥依層次食龍及受八關齋戒的例外，最後談三惡道聲及餓鬼與大力鬼之別。","p":["從笑聲語聲可知眾生心行","依說話內涵分辨凡夫聲與聖人聲","天龍八部各類眾生的聲音特徵","阿修羅遍於五趣，修羅類鬼神性暴烈","金翅鳥依層次食龍，受八關齋戒則不可食"],"k":["耳根功德","天龍八部","阿修羅","金翅鳥","凡夫聲聖人聲","餓鬼"]},"7124-a28_086":{"s":"本集說明比丘比丘尼聲（未斷我見的凡夫僧）、聲聞聲、辟支佛聲、菩薩聲與佛聲的分辨，並誦讀耳根功德重頌。講者解釋「清淨常耳」屬三地滿心色陰盡後的境界，理上一切聲皆是如來藏聲，故「聽之而不著」；並解說諸天聲、迦陵頻伽與命命鳥、地獄、餓鬼及阿修羅之聲。","p":["比丘聲指未斷我見的凡夫僧說法聲","辟支佛先說十因緣，再說十二因緣","佛聲不需擴音，遠近皆能聽清","一切聲皆如來藏聲，故聽之而不著","迦陵頻伽、命命鳥與餓鬼求食聲"],"k":["清淨常耳","如來藏聲","辟支佛","色陰盡","重頌","餓鬼"]},"7122-a28_087":{"s":"本集續解耳根重頌：說法者遙聞阿修羅大聲而不壞耳根，能聞十方禽獸及梵天至有頂天之聲，並能分辨凡夫比丘、證果沙門、菩薩撰集註解與諸佛說法之聲。講者強調分辨音聲須慧眼、法眼配合，批評將耳根圓通解為聽聲的說法，指「聞所聞盡」是實證空性如來藏的智慧。","p":["耳根清淨又為人宣說法華，故不壞耳根","證初果即名沙門，在家出家無別","能講如來藏經典者方是菩薩聲","分辨音聲須慧眼、法眼配合","聞所聞盡依證空性如來藏，非聽聲法"],"k":["耳根圓通","清淨常耳","沙門果","慧眼法眼","聞所聞盡","如來藏"]},"7117-a28_088":{"s":"本集講〈法師功德品〉鼻根八百功德經文並作白話解說。前提是受持了義《法華經》且鼻根清淨：事上嗅所當嗅、不執著香塵，理上觀一切香（含臭）皆是如來藏香。講者說明清淨約為三地滿心色陰盡的證境，解釋常精進之名的意涵，並逐一解說各種花香、樹香與檀香。","p":["鼻根清淨須嗅所當嗅、不執香塵","理上一切香塵皆是如來藏香","常精進之名：精進方得六根清淨","色陰盡屬三地滿心，另需禪定等功德","解說各種花香、樹香與檀香木差別"],"k":["鼻根功德","如來藏香","常精進","色陰盡","法師功德品"]},"7111-a28_089":{"s":"本集續講鼻根功德經文，說明沈香的形成與種植、牛頭栴檀、多摩羅跋與多伽羅，以及末香、丸香、塗香三類和香與塗香供佛的用法。接著說明眾生身香與天香：忉利天圓生樹、拘鞞陀羅樹、曼陀羅與曼殊沙華、釋提桓因勝殿與妙法堂之香，以及空居天、色界天身香越上越淡。","p":["沈香的形成、分級與人工種植","和香分末香、丸香、塗香三類","忉利天圓生樹、拘鞞陀羅樹等天香","空居天淫欲漸淡，身香亦漸淡","欲界有情皆有臭味，越往下越臭"],"k":["鼻根功德","沈香","忉利天","釋提桓因","空居天","天香"]},"7126-a28_090":{"s":"本集說明色界天以禪悅為食、無鼻識舌識，身香因定境不同而異，諸天所燒之香僅限欲界。講者解釋聲聞香、辟支佛香、菩薩香、諸佛身香屬法香，差別在於有無慢心、恐懼及福慧是否圓滿；並誦讀鼻根重頌與白話譯文，涵蓋轉輪王、伏藏、懷妊、男女心念與忉利天宮殿等。","p":["色界天以禪悅為食，無鼻識舌識","色界身香因定境不同而異","獨覺有慢，身香與聲聞緣覺不同","菩薩無恐懼，諸佛福慧圓滿","重頌：聞香知懷妊、心念與伏藏"],"k":["鼻根功德","法香","色界天","辟支佛","重頌","禪悅"]},"7130-a28_091":{"s":"本集續解鼻根重頌，說明持經者聞香能知入出禪者、精進比丘、菩薩與諸佛說法之所在。講者解釋六根互通原是如來藏整體功能，因執著被分割成六結，須次第解結，並提醒勿妄想境界；又指《法華經》對象不限人類。後段詳述四種轉輪王、七寶與千子，及釋迦如來排行第四的因緣。","p":["六根本是如來藏功能，因執著成六結","六根清淨須次第解結，勿妄想境界","法華、華嚴不能只以人類為前提理解","四種轉輪王及輪寶等七寶","轉輪王千子與賢劫千佛的因緣"],"k":["六根互通","轉輪聖王","六結","鼻根功德","賢劫千佛"]},"7137-a28_092":{"s":"本集說明釋迦如來早已成佛，因與千兄弟約定而於賢劫示現成佛，並指轉輪王必教人民受五戒、修十善。接著逐句解說鼻根重頌：聞香知轉輪王眷屬珍寶、諸天行坐神變、阿修羅、懷妊與順產、男女心念、伏藏與瓔珞貴賤、忉利天圓生樹、宮殿與天衣，乃至色界入禪出禪者。","p":["釋迦如來早已成佛，賢劫為示現","轉輪王必教人民受五戒、修十善","聞香知懷妊、男女心念與伏藏","忉利天圓生樹、宮殿、天衣之香","色界稱梵世，入禪出禪香味不同"],"k":["鼻根功德","轉輪聖王","忉利天","重頌","梵世"]},"7141-a28_093":{"s":"本集從《法華經》一佛乘、授記與佛壽無量的主旨，說明演述《法華經》的菩薩須具阿羅漢解脫證量、實證如來藏並達初地以上。講者以五分法身為道德之香，引《雜阿含經》說戒香逆風而熏，並述聞如來戒香得鼻根清淨的修學次第；後舉摩那祇謗佛為例，並批評琅琊閣等人的指控。","p":["法華主旨：一佛乘、授記、佛壽無量","演述法華須具解脫證量並證如來藏","五分法身是道德之香，戒香逆風而熏","聞如來戒香得鼻根清淨，須次第修學","四不壞信得法鏡，舉摩那祇謗佛為例"],"k":["戒香","五分法身","鼻根清淨","一佛乘","四不壞信","法鏡"]},"7134-a28_094":{"s":"本集講舌根功德，說明佛的上味相源於因地口業的修集，指未證言證、未得禪定言得的大妄語使舌根不清淨。引「真諦之妙說，是則味之上」，以聚沫、浮泡、陽燄、芭蕉、幻化之喻說五蘊虛妄假施設，並引《般若經》說真法界即如來藏、非心心，批評六識論的相似像法。","p":["上味相源於因地口業的善法修集","大妄語使舌根不能清淨","真諦之妙說即是味之上","五蘊如聚沫浮泡等，虛妄假施設","如來藏是非心心，否定者落相似像法"],"k":["舌根功德","大妄語","五蘊","非心心","如來藏","相似像法"]},"7136-a28_095":{"s":"本集說明菩薩法師以舌根宣說如來藏正法、摧邪顯正，其深妙聲能入人心；舉佛食馬麥仍為上味、世親以舌謗大乘後依無著教誨造論弘揚大乘為例。講者說明修清淨舌根須行如實語、質直語、依法語，批評琅琊閣等人言論，並引《長阿含經》說入胎識即涅槃本際、十二因緣甚深。","p":["深妙聲能入大眾心，令皆歡喜","佛食馬麥仍是上味相","世親以舌謗大乘，後以解說大乘懺罪","修如實語、質直語、依法語等善語","入胎識即涅槃本際，十二因緣甚深"],"k":["舌根功德","法布施","世親菩薩","如實語","入胎識","十二因緣"]},"7152-a28_096":{"s":"本集續講舌根偈「舌根淨，終不受惡味」，說明舌根清淨須長劫不大妄語、不依佛法欺誑眾生，說法者能以因緣與譬喻引導眾生且心無所懼，聞法者應設上供養。接著談天龍夜叉來聽法，說明好施而嗜酒肉者成地行夜叉，並引《舍利弗問經》說天龍八部因善惡二業成人非人，警惕性障。","p":["舌根淨須不大妄語、不欺誑眾生","以因緣、譬喻引導眾生心","弟子應恭敬供養說法之師","好施而嗜酒肉者將生為地行夜叉","天龍八部因善惡二業成人非人"],"k":["天龍八部","舌根清淨","夜叉","性障","人非人","舍利弗問經"]},"7128-a28_097":{"s":"本集續說三種夜叉：急性好快者成空行夜叉、好比較爭勝者生須彌山腰，並指密宗空行母、勇父屬夜叉層次，提醒布施須作意清淨、遠離酒肉。接著解釋天界阿修羅又名無酒，並引《大方等大集經》述弗沙耶若為度八弟千年苦行，八弟含彌勒、魔波旬、提婆達多與四阿修羅王，說明有漏心修行的果報。","p":["空行夜叉與山腰夜叉的成因","密宗空行母、勇父屬夜叉層次","布施時心須調柔，遠離瞋嫉與酒肉","阿修羅脾氣暴躁，又名無酒","弗沙耶若千年苦行度八弟的本生"],"k":["夜叉","阿修羅","布施作意","魔波旬","大方等大集經","天龍八部"]},"7132-a28_098":{"s":"本集先解舌根偈：梵天王、魔王等常來聽法，諸佛及弟子護念說法者。接著講身根八百功德經文「得清淨身如淨琉璃」，說明受持「此經」即證如來藏且轉依，讀、誦、解說、書寫各有層次；身根因不能如舌根全方位演繹故只八百功德，並說如來藏清淨身無取捨，一切世間皆於其中顯現。","p":["諸天常來聽法，諸佛護念說法者","受持此經即證如來藏且轉依不退","讀此經是悟後觀察如來藏自性","身根不能全方位演繹，故八百功德","一切世間皆於如來藏清淨身中現"],"k":["身根功德","如來藏","此經","清淨身","讀誦解說書寫"]},"7139-a28_099":{"s":"本集說明器世間由有情如來藏依業以「不可知執受」變現，如來藏非色非非色、具大種性自性，故能生色身與器世間。解偈「唯獨自明了，餘人所不見」為菩薩所獨證；並引《楞伽經》說種性、非種與心量，引《大般若經》說菩薩種性超越聲聞獨覺，也說明世尊晚說《法華》與五千人退席。","p":["器世間由有情如來藏依業變現","如來藏非色非非色，具大種性自性","唯獨自明了：二乘亦不見此清淨身","楞伽經：種性、非種與心量","菩薩種性超越聲聞獨覺，故稱尊貴"],"k":["菩薩種性","如來藏","大種性自性","器世間","楞伽經","清淨身"]},"7143-a28_100":{"s":"本集引《楞嚴經》說明十二類有情的本覺心體與諸佛無二無別，並辨正這不是眾生共有一個如來藏；眾生因迷理、癡愛而有虛空與世界生起。接著解說〈法師功德品〉身根清淨重頌「諸天宮殿…皆於身中現」，配合《楞伽經》藏識海喻，勉勵行者具足菩薩種性。","p":["眾生與佛心體無二無別，非共一大我","迷理癡愛而有虛空與世界生起","虛空依色法邊際假名施設，名色邊色","諸天宮殿山海皆於如來藏清淨身中現","藏識海與七識浪喻，萬法唯識"],"k":["如來藏","清淨身","楞嚴經","楞伽經","萬法唯識","菩薩種性"]},"7145-a28_101":{"s":"本集講〈法師功德品〉八百身功德。先界定「法師」須於三乘菩提有實證、依如來藏演說《法華經》，並說明受持、讀、誦、解說、書寫「此經」的真義。再解釋偈頌「雖未得無漏，法性之妙身，以清淨常體，一切於中現」，論證清淨常體是第八識如來藏，而不是五蘊身。","p":["法師須於三乘菩提有實證","六根功德皆依如來藏妙真如性而有","受持是悟後心得決定、轉依不退","讀誦解說書寫此經的實義","清淨常體能現一切，即如來藏非五蘊"],"k":["法師功德品","八百身功德","清淨身","受持讀誦","如來藏","轉依"]},"7157-a28_102":{"s":"本集解說〈法師功德品〉意根清淨得千二百功德的經文，說明讀、誦、解說、書寫自身「此經」的意義，其中書寫包括著書流布與主持禪三。再以鏡體與鏡像為喻，說明從如來藏看一切法本不生滅，與解脫道觀生滅的角度不同；最後說染汙意根處處作主，須轉依如來藏才能清淨。","p":["讀此經是悟後不斷觀察如來藏","書寫：著書流布與主持禪三","解脫道觀生滅，實相觀法本不生滅","鏡體鏡像喻、螞蟻五陰喻","染汙意根因取捨而處處作主"],"k":["意根清淨","千二百意功德","一切法本不生滅","鏡像喻","無量義","轉依"]},"7161-a28_103":{"s":"本集複習受持、讀、誦、解說、書寫「此經」的內涵，再依《楞嚴經》說明六根功德為何有八百與一千二百之別：眼根前明後暗，三分缺一故八百；耳根周聽十方無遺故千二百；鼻根出入息中交有闕故八百；舌根言有方分而理無窮盡，故千二百。","p":["受持：證悟後對此經心得決定不改","讀經要讀透經背、讀自身法華經","眼根前明後暗，僅八百功德","耳根周聽十方無遺，圓滿千二百","鼻根闕中交八百，舌根理無窮盡千二百"],"k":["六根功德","楞嚴經","法師功德品","耳根","受持讀誦"]},"7166-a28_104":{"s":"本集續講六根功德差別：身根合時能覺、離中不知，闕一分故八百功德；經中所說的根是含攝五識、意識的功能，不是扶塵根。重點解說意根「默容十方三世一切世間出世間法」：意根了別慧差、不起語言卻作決定，默容往世種子，故具千二百功德，修行到後來須從意根入手。","p":["身根合時能覺離中不知，八百功德","根指功能，非扶塵根或勝義根","意根默容十方三世一切法","意根不起語言，看意識處理後作決定","往世善惡緣、夢見往世皆意根相應"],"k":["意根","默容","六根功德","身根","種子","楞嚴經"]},"7160-a28_105":{"s":"本集續談意根「惟聖與凡，無不包容」，舉初學佛時似曾相識、夢見往世等例，說明意根默容往世所熏種子，緣熟時便相應。並說眠熟時睡的是意根，六識運作都不離意根；意根千二百功德不能取代前五根，須到成佛四智圓明才圓滿，法與次法具足修證即可證清淨意根。","p":["意根默容四聖六凡十法界種子","似曾相識、夢見往世等例證","菩薩世世不捨七轉識，藉意根淨化","眠熟位：意識斷而意根仍在","意根功德到成佛時才圓滿"],"k":["意根","惟聖與凡無不包容","眠熟位","四智","種子","法與次法"]},"7155-a28_106":{"s":"本集解說意根清淨者能知六趣眾生心行，所說世間法亦順正法。以龍樹《中論》為例，說明用八識論解釋則外道質疑也成正法，用六識論的應成、自續派中觀解釋則成邪法，並述龍樹與提婆的試驗典故，批評釋印順。再說意根清淨的層次，以荷花「花果同時」比喻開悟時如來藏種子本已具足。","p":["正人說邪法，邪法亦隨正","《中論》須以八識論解才通","批評應成派中觀與釋印順六識論","意根清淨由不貪五欲到離欲得禪","荷花花果同時喻開悟見如來藏種子"],"k":["意根清淨","八識論","中論","應成派中觀","花果同時","妙法蓮華"]},"7147-a28_107":{"s":"本集以往生極樂時蓮苞開敷為例續講「花果同時」，說明意根清淨有不同層次：從不貪額外五欲、離欲界貪，到俱解脫、三明六通，所知眾生心行隨之增多，到佛地才圓滿。並依八識心王現行多寡，觀察人、畜生、鬼神、地獄及三界諸天眾生的「心之所行」，說明悟後能「皆悉知之」。","p":["極樂蓮苞開敷喻花果同時","意根清淨分層次，佛地圓滿知之","意根時時作主，如見香腸攤之例","眾生八識現行多寡，最少剩三識","三界六道心之所行可比量了知"],"k":["意根清淨","八識心王","心之所行","花果同時","三界六道","極樂淨土"]},"7149-a28_108":{"s":"本集解說「雖未得無漏智慧，而其意根清淨如此」：意根第一分清淨是悟後轉依如來藏、不再認五陰為真我，並批評「要當自己、把握自己」是我見的美化。說明此菩薩思惟籌量言說皆是佛法、同於先佛所說，因佛佛道同、實相唯一；再解讀重頌，說五根清淨皆依意根清淨。","p":["意根第一分清淨：不再執五陰為真","「把握自己」是我見我執的美化","佛佛道同，實相只有一種","八萬四千法門同入一個大殿","五根清淨皆依意根，意根統攝諸法"],"k":["意根清淨","佛佛道同","我見","實相唯一","先佛所說"]},"7163-a28_109":{"s":"本集解說重頌「以此妙意根，知上中下法；乃至聞一偈，通達無量義」，說明通達須知諸法在佛菩提道中的位階（法住法位），並具解脫道四果及大乘真見道、相見道功德。以「涅槃」「真如」為例，示範由一法貫串四種涅槃、施戒生天之論、十因緣與十二因緣，說明通達者能從一法說盡佛法。","p":["意根清淨使意識專注第一義諦","通達須知法住法位、諸法位階","未通達而自稱入地是大妄語","由涅槃一詞演說四種涅槃至成佛","由真如貫串世間法、聲聞、緣覺"],"k":["通達無量義","法住法位","四種涅槃","十因緣","真如","意根清淨"]},"7168-a28_110":{"s":"本集續說真如與佛菩提五十二位階的關聯，強調「法住法位，法爾如是」不可改變，說主張佛法演變者是凡夫；並解說「次第如法說」，指出見地通達才能摧邪顯正。再解「所念若干種，一時皆悉知」：眾生總念是我、別念在我所，皆緣真如而有；並說攝受眾生即攝受佛土。","p":["真如貫串菩薩種性與五十二位階","法住法位法爾如是，不可演變","次第說、如法說，見地通達可摧邪","眾生總念是我，別念是我所","利益攝受眾生即攝受佛土"],"k":["法住法位","法爾如是","通達","眾生心念","攝受佛土","意根清淨"]},"7173-a28_111":{"s":"本集先總結〈法師功德品〉六根功德與意根清淨，再講偈頌「十方無數佛，百福莊嚴相」。引《增壹阿含經》三乘之教，批評六識論者說大乘由懷念佛陀演化而來是謗佛謗法，並論十方有無數佛。再引經論說明三十二大人相每一相都具百福，百福來自十善業各有前後十思、合為百思。","p":["意根清淨統攝五根清淨","阿含說三乘之教，駁大乘非佛說","佛示現涅槃後於他方續示現","三十二相一一相皆具百福","十善業各十思，合為百思百福"],"k":["百福莊嚴相","三十二相","大乘非佛說","十善業","三乘之教"]},"7182-a28_112":{"s":"本集具體說明百思的修法：依《大毘婆沙論》，十善業每一業先作離殺、勸道、讚美、隨喜、迴向五思，事後再作加行淨、根本淨、後起淨、離尋伺害、念攝受五思。以被問「你悟了沒有」如何得體回答為例逐一解釋，並說攝受是利益對方而非拉眷屬，福德是實證智慧的支撐。","p":["每一善業前五思、後五思共十思","前五思：離殺勸道讚美隨喜迴向","以回答「悟了沒有」為例說明","後五思：加行淨根本淨後起淨等","念攝受是利益他人，非拉眷屬"],"k":["百福莊嚴相","十善業","前五思後五思","福德","攝受"]},"7169-a28_113":{"s":"本集說明以百思修百福的利益：言語不帶酸諂嫉妒、去除暴戾之氣、快速修除性障乃至取證三果，未來受彌勒佛授記的層次更高。並引《優婆塞戒經》說佛的三十二相具百福，轉輪聖王相則不明了；善業夾帶不淨會使福德流失。最後說諸佛以百福莊嚴相攝受眾生，故聞法者能受持。","p":["百思使言語清淨、去除暴戾之氣","快速除性障，利於彌勒授記","佛相具百福，與轉輪王相不同","善業夾雜不淨，福德會流失打折","百福莊嚴相令眾生信受所說"],"k":["百福","性障","三十二相","轉輪聖王","授記","福德"]},"7177-a28_114":{"s":"本集解說重頌「思惟無量義，說法亦無量；終始不忘錯，以持法華故」，說明真見道是相見道與通達位的基礎，通達後一法可思惟無量義，且依現觀而說，所以前後不矛盾。再解「悉知諸法相，隨義識次第」，批評佛法演變之說；並說「此人有所說，皆是先佛法」，佛法沒有創見，故於眾無所畏。","p":["真見道證真如是通達的基礎","依現觀而說，終始不忘錯不矛盾","諸法次第位階不可改變","一切法收圓於法華唯一佛乘","所說皆先佛法，佛法無創見"],"k":["通達無量義","真見道","終始不忘錯","法住法位","先佛所說","唯一佛乘"]},"7189-a28_115":{"s":"本集解說「持法花經者，意根淨若斯；雖未得無漏，先有如是相」，說明見地通達至少要證三果並通達般若，並起惑潤生、世世受生。再解「是人持此經，安住希有地…分別而說法」，說三轉法輪諸經皆依如來藏而說，並舉平實導師弘法、寫《狂密與真密》為例，說明受持如來藏才能安住希有地、善巧說法。","p":["意根淨：起惑潤生，不入無餘涅槃","三轉法輪諸經皆依此經如來藏說","安住希有地，外道不能推翻","施設方便譬喻，分別而說法","無量義經開演，法華收歸一法"],"k":["意根清淨","安住希有地","善巧方便","唯一佛乘","無量義經","如來藏"]},"7179-a28_116":{"s":"本集說明明心與見性都是頓悟、沒有漸悟，悟後須次第漸修。引《楞嚴經》「理則頓悟，乘悟併銷；事非頓除，因次第盡」，說六根清淨分見地與事修。並區分明心與眼見佛性，批評觀想中脈明點及「捨識用根」之說，以劫波羅巾六結喻說明須根識合作、次第解結，選耳根圓通入手。","p":["明心見性皆一念相應頓悟","理則頓悟，事非頓除因次第盡","明心與眼見佛性的差別","批評觀想明點、捨識用根之說","劫波羅巾六結：根識合作次第解"],"k":["頓悟漸修","楞嚴經","六根清淨","眼見佛性","解結","耳根圓通"]},"7175-a28_117":{"s":"本集解說《楞嚴經》觀世音菩薩「從聞思修入三摩地；初於聞中，入流亡所」的意義：所聞是善知識所說的如來藏正法而非聲塵，三摩地是佛菩提智慧心得決定而非禪定。說明入流亡所、所入既寂、動靜二相了然不生，以耳根聞正法流亡邪見、親證如來藏即入流成正覺，末談常不輕、常精進。","p":["聞思修所聞是正法，非聽聲音","三摩地是智慧決定境界，非禪定","入流亡所、動靜二相了然不生","耳根聞正法，流亡五蘊真實邪見","常不輕、常精進可化長劫入短劫"],"k":["耳根圓通","觀音法門","入流亡所","聞思修","三摩地","化長劫入短劫"]},"7184-a28_118":{"s":"本集說明六根清淨分見地上（通達位完成）與事修上（初地起次第進修至等覺），清淨意根須先清淨意識，並批評捨識用根、宗喀巴《菩提道次第廣論》及即身成佛之說。接著進入〈常不輕菩薩品〉，解說謗持法華者獲大罪報的經文，介紹得大勢菩薩與極樂三聖紹繼佛位，比較極樂與娑婆修行的長短劫。","p":["六根清淨分見地與事修兩層","意根清淨須靠意識修行與取捨","批評宗喀巴廣論與即身成佛","〈常不輕菩薩品〉：謗者獲大罪報","得大勢菩薩與極樂佛位紹繼"],"k":["六根清淨","常不輕菩薩品","捨識用根","得大勢菩薩","極樂世界","宗喀巴"]},"7171-a28_119":{"s":"本集說明娑婆修行屬短劫，因修福易成、慧學快速、賢劫千佛出世，並勸修信、精進、念、定、慧五根轉成五力。再解說〈常不輕菩薩品〉謗持法華者獲大罪報：依根本、方便、成已三事及被謗者證量，罪報從小地獄到阿鼻地獄不等，並說「劫盡更生」，以及受邪教導誤以如來藏為神我而誹謗的情形。","p":["娑婆修福修慧快速，化長劫入短劫","五根轉為五力的修行次第","根本、方便、成已決定罪報輕重","謗法重者入阿鼻地獄劫盡更生","受邪教導誤謗如來藏為神我"],"k":["化長劫入短劫","誹謗正法","根本方便成已","地獄罪報","五根五力","常不輕菩薩品"]},"7193-a28_120":{"s":"本集進入〈常不輕菩薩品〉，先說誹謗「妙法蓮華」如來藏者歷經地獄、畜生，再生人間貧賤、橫禍不斷且不聞正法的長劫罪報，與受持者得六根清淨作對比；再解說威音王如來、離衰劫、大成國的經文，並闡釋「應四諦法」中「應」字的意義。","p":["謗如來藏者墮地獄，再轉生牛馬蟒蛇，歷劫久遠","還生人間五根缺陷、貧賤橫禍、不聞正法","受持妙法蓮華者得六根清淨功德","威音王如來為最初佛，釋離衰劫、大成國之名","所學須與四聖諦相應；阿闍世王僅得無根信"],"k":["常不輕菩薩品","誹謗正法罪報","威音王如來","應四諦法","六根清淨","如來藏"]},"7195-a28_121":{"s":"本集說明佛陀開示四聖諦前，先講施論、戒論、生天之論及欲為不淨等次法，並依根性教導五停心觀作為「應四諦法」，現代則以無相念佛為之；又說阿含中增說因緣法即「應十二因緣法」，並指十二因緣每一支背後皆以阿賴耶識為根本因。","p":["先說施論戒論生天論，再說欲為不淨、上漏為患","不淨觀、數息、慈心、因緣觀、界差別觀各有對治","念佛觀與因材施教；無相念佛為現代應四諦法","增說因緣法是為使聽者與十二因緣相應","十二因緣每一支皆依阿賴耶識根本因而有"],"k":["應四諦法","五停心觀","十二因緣","無相念佛","阿賴耶識","界差別觀"]},"7200-a28_122":{"s":"本集從佛教主張眾生皆可成佛談起，說明《法華經》所講的成佛「如是因」即實證般若、證第八識如來藏，並須以菩薩道五十二階位為「如是緣」。講者批評以緣起性空為佛法核心的無因唯緣論，並以如來藏說明三寶常住、往生「去則實不去」及因果業報。","p":["佛教與一神教不同：願一切眾生皆成佛","成佛之因為證如來藏，須五十二階位為緣","有因有緣集世間，其因即第八識如來藏","批評把緣起性空當佛法核心的無因唯緣論","三寶常住、去則實不去皆依如來藏而說"],"k":["如是因","如來藏","緣起性空","無因唯緣論","般若","三寶"]},"7185-a28_123":{"s":"本集說明《法華經》是佛特意宣講、為開示悟入成佛之道的經典。講者批評清朝以來喇嘛教被當作佛教，以及2016年版《中華電子佛典》於《大藏經補編》收錄宗喀巴等著作，呼籲將其擯除或另立標題；最後說佛法核心是如來藏，佛意難知。","p":["法華經非隨宜說法，乃佛特意宣講","清朝皇室崇奉喇嘛教，致如來藏妙義難弘","批評CBETA大藏經補編收錄宗喀巴著作","編修藏經應揀擇真偽，不應淪為學術集成","心經密意即如來藏；學佛究竟在成佛道"],"k":["法華經","大藏經編修","喇嘛教","宗喀巴","如來藏","開示悟入"]},"7204-a28_124":{"s":"本集解說〈方便品〉中五千聲聞增上慢退席的原因：他們以為解脫生死即學佛究竟、阿羅漢等同佛。講者藉舍利弗三請與「止止不須說」經文，說明阿羅漢涅槃與佛地常樂我淨、無住處涅槃不同，並批評印順以涅槃寂靜為究極理想的說法。","p":["五千人以為解脫生死即學佛畢業，故退席","舍利弗三請，佛說止止不須說、我法妙難思","增上慢即未證言證、未得謂得","阿羅漢涅槃非常樂我淨，唯佛地無垢識是","二乘法須依大乘如來藏方能成立"],"k":["增上慢","五千退席","方便品","常樂我淨","無住處涅槃","二乘與佛乘"]},"7191-a28_125":{"s":"本集講「諸佛唯以一大事因緣出現於世」，說明此大事是令眾生成佛，而非僅解脫生死；並解釋開、示、悟、入佛之知見，強調宗不離教、教不離宗，佛之知見即證悟如來藏的真如與佛性，明心與見性為兩關。講者也批評以離念靈知為開悟等錯誤修行。","p":["一大事因緣是令眾生成就佛道","二乘法是於一佛乘分別說三的方便","開示悟入佛知見；宗門與教門須互相配合","佛之知見即如來藏真如與佛性，明心見性兩關","一念不生、離念靈知仍屬意識境界"],"k":["一大事因緣","開示悟入","佛之知見","一佛乘","明心見性","真如"]},"7208-a28_126":{"s":"本集從如是相、性、體、力、作、因、緣、果、報等面向說明成佛的法華：成佛之報為常樂我淨，依大乘法涅槃以如來藏為體，成佛以三乘菩提實證為因、菩薩道五十二階位為次第。講者批評六識論者的無因唯緣論，並引〈方便品〉偈說明佛智不可測度。","p":["成佛須有七世清淨父母等如是緣","成佛以三乘菩提為因，其報為常樂我淨","依大乘法，涅槃以如來藏為體","批評六識論者之無因唯緣論","開悟僅七住位，佛智不可測量"],"k":["成佛之道","如是因緣果報","常樂我淨","涅槃","菩薩五十二階位","八識論"]},"7198-a28_127":{"s":"本集解說〈常不輕菩薩品〉經文：威音王佛像法時期，常不輕比丘禮拜四眾說「汝等皆當作佛」，遭罵詈打擲仍不改。講者說明常不輕即釋迦牟尼佛前身，引《大悲經》摩竭大魚聞佛名得度的故事，並說他依所證如來藏禮拜以滅慢心與往昔罪業，臨終聞《法華經》而六根清淨。","p":["常不輕比丘禮拜四眾：我不敢輕於汝等","大悲經：摩竭大魚聞佛名，終證阿羅漢","像法時期增上慢比丘有大勢力","只對行菩薩道的佛門四眾禮拜讚歎","禮拜滅慢心習氣與罪業，臨終得六根清淨"],"k":["常不輕菩薩","增上慢","威音王佛","滅罪","慢心","六根清淨"]},"7202-a28_128":{"s":"本集講常不輕菩薩六根清淨增壽後，廣說《法華經》（即如來藏經），以大神通力、樂說辯力、大善寂力令增上慢四眾信伏，並值遇日月燈明佛、雲自在燈王佛。講者說明見取見使意識不淨，引《大般若經》說壞正法業重於五無間，及輕賤者二百億劫不值三寶的果報。","p":["六根清淨後增壽二百萬億那由他歲廣說此經","大神通力、樂說辯力、大善寂力三種功德","先後值遇二千億日月燈明佛、雲自在燈王佛","見取見以鬥爭為業，致意識與諸根不淨","壞正法業重於五無間；以得大勢為緣起人"],"k":["常不輕菩薩","四無礙辯","見取見","謗法罪業","得大勢菩薩","法華經"]},"7187-a28_129":{"s":"本集講「則我身是」：常不輕菩薩即釋迦牟尼佛，因世世受持、讀誦、為人演說此經如來藏而疾得菩提。講者說明真實僧寶的定義，引《雜阿含》「斧在口中生」與《大般若經》匱正法業歷經地獄、傍生、餓鬼的長劫苦報，說明一千五百位輕賤者的後果，勸人勿輕易評論善知識。","p":["常不輕菩薩即釋迦如來，因受持此經疾得成佛","此經即如來藏，亦即金剛經、心經","僧寶須明心不退，所說須符八識論","斧在口中生；匱正法業長劫輪轉三惡道","無法眼慧眼時應謹言慎行，勿隨意評論"],"k":["謗法罪報","常不輕菩薩","如來藏","僧寶","口業","匱正法業"]},"7206-a28_130":{"s":"本集解說「常應受持、讀誦、解說、書寫是經」：受持、讀誦為自利，即悟後現觀如來藏；解說、書寫為利他與流傳後世。講者引《賢愚經》說阿難總持的因緣，並依偈頌說明眾生皆有無始無明、無人無始成佛，故必有最初的威音王佛；並釋「計著於法」，勉勵延續正法、破邪顯正。","p":["受持讀誦為自己，解說書寫為有緣人與後世","阿難往昔供養小沙彌，故得總持不忘","阿難是諸大阿羅漢中最快成佛者","眾生皆有無始無明，無人無始成佛","計著於法者未證言證，須破邪顯正救護"],"k":["受持讀誦解說書寫","總持","阿難","無始無明","二障","計著於法"]},"7222-a28_131":{"s":"本集說明常不輕菩薩說「我不輕汝，汝等皆當作佛」是有所本：一切有情皆有此經如來藏，理上本是佛，並非僅因有善根。他依實相具足生忍與法忍，長時安忍打罵以最快速滅罪，未來得眷屬和合；罪畢臨終得聞此經而六根清淨、增益壽命，再廣說此經。","p":["悟後見蚊蠅亦有此經，故不敢輕視他人","一低頭、一舉手皆已成佛道，理上本是佛","生忍與法忍：依實相現觀而能長時安忍","被輕賤打罵即滅先世罪業，金剛經亦有此說","罪畢得聞此經六根清淨，增壽廣說此經"],"k":["常不輕菩薩","安忍","生忍法忍","滅罪","如來藏","眷屬和合"]},"7210-a29_001":{"s":"本集概述〈常不輕菩薩品〉：此品講娑婆世界佛教的由來，並勉勵悟後回頭提攜有緣眾生。講者重述誹謗受持者的罪報、威音王佛事蹟、常不輕菩薩禮拜四眾至臨終聞經六根清淨、增壽說法，及輕賤者的果報；最後說明受持、讀誦為自度，解說、書寫為度人與流傳後世。","p":["悟後應回頭提昇有緣法眾，不當自了漢","誹謗受持法華者墮三塗，輪轉無有了期","威音王佛與常不輕菩薩事蹟概述","輕賤者二百億劫不值三寶、千劫受苦阿鼻","受持讀誦為自度，解說書寫為度人傳後世"],"k":["常不輕菩薩品","威音王佛","受持讀誦解說書寫","誹謗罪報","如來藏"]},"7219-a29_002":{"s":"本集續講〈常不輕菩薩品〉：此經是每人本具的如來藏，常不輕菩薩依此經教化諸著法眾，值無量佛而早成佛。講者勉勵悟後勿起慢心、勿否定第八識，對誹謗者也不放棄而為其種下正法種子；並串連〈如來壽量品〉、〈法師功德品〉與本品，指出一切歸結於此經如來藏。","p":["此經即人人本具的如來藏經、妙法蓮華","九百九十九兄弟之願，示現千佛次第成佛","悟後勿起慢心、勿輕易否定第八識","對謗法者不放棄，先為其種下正法種子","壽量品、法師功德品與本品前後聯結"],"k":["常不輕菩薩品","如來藏","攝受謗法者","如來壽量品","法師功德品","慢心"]},"7216-a29_003":{"s":"本集開講〈如來神力品〉，說明釋迦如來久遠已成佛，從地踊出的菩薩誓願於分身佛滅度處廣說《法華經》，並說只有應身佛能講此經。講者解釋四種涅槃與佛地常樂我淨的「真淨大法」，批評以一念不生為不生的錯誤，並說明因地如來藏心體雖常而種子仍在變異。","p":["從地踊出菩薩誓願於佛滅後廣說此經","唯應身佛能講法華經，化身佛不能","四種涅槃具足者方為大般涅槃","一念不生是將滅止生，非真不生不滅","因地如來藏體常而種子變異，佛地方究竟常"],"k":["如來神力品","常樂我淨","四種涅槃","應身佛","變易生死","無垢識"]},"7228-a29_004":{"s":"本集續講佛地常樂我淨：樂是斷盡二種生死、證無住處涅槃；我是佛地第八識與五別境、善十一心所相應並有證自證分；淨是心體與種子內外俱淨。講者說明二乘只說非常非樂非我非淨，菩薩未斷塵沙惑仍未究竟；並說佛將弘經機會留給從地踊出的嫡傳弟子，及解說能教學相長。","p":["樂：斷分段與變易生死，證無住處涅槃","我：佛地第八識具五別境等心所與證自證分","淨：心體與所含種子內外俱淨","二乘觀蘊處界皆非常非樂非我非淨","弘經機會留給從地踊出菩薩；解說教學相長"],"k":["常樂我淨","無住處涅槃","塵沙惑","無垢識","從地踊出菩薩","如來神力品"]},"7244-a29_005":{"s":"本集說明以受持、讀誦、解說、書寫四種方式供養《妙法蓮華經》，強調解說能教學相長、攝受佛土，書寫則可對治相似像法的流行。講者批評密教部諸經為偽經，並解說〈如來神力品〉「出廣長舌上至梵世」與「一切毛孔放無量色光遍照十方」的意涵。","p":["解說利他亦自利，助眾成長即攝受佛土","不書寫則相似像法遍滿，正法將滅沒","名為法華經講義，表所講為真實義","廣長舌上至梵世：法音警覺至色界諸天","毛孔放無量色光，顯十方諸佛佛佛道同"],"k":["供養法華經","書寫","相似像法","廣長舌","如來神力品","破邪顯正"]},"7232-a29_006":{"s":"本集續解〈如來神力品〉：分身諸佛同現廣長舌、放光百千歲後謦欬彈指，十方大地六種震動，眾生皆見娑婆諸佛及釋迦、多寶二佛同坐寶塔，諸天唱言勸禮，供物化為寶帳，十方如一佛土。講者從密意說十方世界皆是如來藏世界，佛佛道同。","p":["分身諸佛同出廣長舌放光，後謦欬彈指","釋迦與多寶二佛同坐寶塔乃是特例","十方眾生遙散供物，化為寶帳覆諸佛上","密意：十方皆如來藏世界，故如一佛土","諸佛所傳同一心，非夜夜斷滅的離念靈知"],"k":["如來神力品","如一佛土","多寶如來","佛佛道同","如來藏","分身佛"]},"7214-a29_007":{"s":"本集解說世尊告上行等菩薩：以神力於無量劫說此經功德猶不能盡，因如來一切所有之法、自在神力、祕要之藏、甚深之事皆於此經宣說。講者說明上行菩薩指證悟者，此經即真心如來藏，一切法、業種與福德皆在其中，如來藏為萬法總樞紐。","p":["此段對證悟的上行菩薩說，退回識陰者為下行","諸佛神力是智慧，故無量無邊不可稱量","此經即如來藏，故久劫說之亦不能盡","自在神力源於福德與四無所畏，皆依此經","如來藏為萬法根源，如樹之根盤"],"k":["如來神力品","如來藏","上行菩薩","祕要之藏","四無所畏","此經功德"]},"7230-a29_008":{"s":"本集續講「如來一切祕要之藏」：人間十八界具足，如來藏妙法蓮華在人間最圓滿；如來囑咐隱覆說義，以免未熟者生疑謗法。講者舉眼見佛性的如幻觀等現觀與處非處智力，說明祕要與甚深之事皆歸此經，並釋「一心受持……如說修行」，勉勵證悟者自知彌足尊貴、協助摧邪顯正。","p":["人間十八界具足，妙法蓮華在人間最圓滿","須隱覆說義，令學人親自參究","如幻觀等現觀唯證乃知，屬祕要之藏","處非處智力知眾生輾轉受報，為甚深之事","佛滅後應一心依此經修行；證悟者彌足尊貴"],"k":["祕要之藏","隱覆密意","如幻觀","眼見佛性","處非處智力","一心受持"]},"7226-a29_009":{"s":"本集講解〈如來神力品〉中佛滅後應一心受持、讀誦、解說、書寫此經的意涵。受持讀誦為自利，指證悟後於如來藏體性上觀行，才是讀佛門內典；並舉文殊、童女迦葉、維摩詰為例，說明大乘依證量而非聲聞戒定位勝義僧，菩薩戒為正解脫戒；解說書寫則為利益當代與後世。","p":["受持讀誦為自利，解說書寫為利他","真正讀經是觀行如來藏，依文解義如讀外典","大乘依法上證量定位勝義僧，不依聲聞戒","菩薩戒為正解脫戒，聲聞戒為別解脫戒","宗義上如法受持須實證如來藏，不以解脫道為成佛之道"],"k":["受持讀誦解說書寫","如來藏","勝義僧","菩薩戒","如來神力品"]},"7234-a29_010":{"s":"本集續講〈如來神力品〉「當知是處即是道場」一段，說明證悟後見到自身「妙法蓮華經」經卷所在即可起塔供養，重在實質不在表相；證此經不分僧俗貴賤，眾生如來藏平等。諸佛得菩提、轉法輪、般涅槃皆不離第八識，眾生生死亦在如來藏中；並批評否定如來藏為謗法，強調此經不能依文解義。","p":["起塔供養方式無量，重實質不重表相","證此經不分僧俗男女貴賤，如來藏平等","諸佛於此經中得菩提、轉法輪、般涅槃","生死不離如來藏，明此即了生脫死","否定如來藏為謗法，此經不可依文解義"],"k":["道場","起塔供養","如來藏","般涅槃","轉法輪","依文解義"]},"7235-a29_011":{"s":"本集進入〈如來神力品〉重頌，引平實導師語譯說明偈意，並解釋長行後再說重頌的用意。重點辨析「救世者」與世間「救世主」：醫者、仙道、生天之教等救護皆有侷限，不出三界；佛證人無我、法無我而不以主自居，故稱救世者。並批評釋印順以如來為外道思想之說，及指喇嘛教非佛教。","p":["重頌為加深印象並補充長行未說之義","世間種種救世主之救護皆不出三界生死","佛證人無我與法無我，不自居為主故稱救世者","佛出世前外道自稱阿羅漢、如來皆是因中說果","批評釋印順「如來即外道思想」之說及喇嘛教"],"k":["救世者","人無我","法無我","重頌","如來神力品","喇嘛教"]},"7237-a29_012":{"s":"本集續講重頌「諸佛救世者，住於大神通」等句。說明佛度眾先說施論、戒論、生天之論等次法再說四聖諦，能度人超越分段與變易二種生死方稱大醫王；辨析神通層次與佛的宿住隨念智力，示現神通只為度眾。並從理上解釋廣長舌相、謦欬彈指與六種震動即六根震動，及讚美受持者功德說不盡。","p":["佛先說次法再說四聖諦，度人出三界","超越二種生死方為究竟大醫王、救世者","佛具宿住隨念智力，神通為度眾非炫耀","大地六種動於理上指證悟時六根震動","受持此經者功德無盡，以三輪體空布施為例"],"k":["大神通","次法","二種生死","六種震動","廣長舌相","三輪體空"]},"7224-a29_013":{"s":"本集依〈如來神力品〉「讚美受持者」偈，說明能持此經者即實證第八識、傳承正法的大乘菩薩，故稀有難得。進而講佛法修學次第：五乘佛法中人天善法為次法，即施論、戒論、生天之論與欲為不淨、上漏為患、出要為上的三論六學，並介紹四種悉檀與世界悉檀，指次法只是趣入三乘菩提的前方便。","p":["能持此經的證悟菩薩代代傳承如來正法","學佛不知次第，易退失初發菩提心","五乘佛法中人天善法為趣入三乘之次法","三論六學的內涵，三界皆不離生死","四種悉檀，三論主修世界悉檀"],"k":["修學次第","次法","三論六學","四種悉檀","五乘佛法"]},"7241-a29_014":{"s":"本集續說次法圓滿後進入三乘菩提之「法」，以對治、為人、第一義三悉檀對應三轉法輪。闡釋「則為已見我」非見報身或應身色相，而是見無形無相的第八識法身；並說明聲聞四聖諦、緣覺十因緣與十二因緣的教授次第，引《菩薩瓔珞本業經》述十信、十住至七住不退的歷程，最後總結修學階段。","p":["三種悉檀對應三轉法輪的教授內涵","「已見我」是見無形無相的第八識法身","聲聞四聖諦與緣覺十因緣、十二因緣次第","十信圓滿入十住，六住後證悟入七住不退","總結從人天善法到大乘六度的修學次第"],"k":["已見我","第八識","修學次第","十住位","菩薩瓔珞本業經","十二因緣"]},"7247-a29_015":{"s":"本集說明證第八識而入七住不退者即「能持是經者，則為已見我」，為始覺位、相似即佛，並列舉入住位所需條件，如擇法、五根五力、依法不依人。以「諸佛坐道場所得祕要法」說明所證非六識或離念靈知，而是本具如來智慧德相的第八識；並引玄奘《成唯識論》第八識執持流轉與還滅法種為教證。","p":["證此經入七住為始覺位、相似即佛","入住位需擇法、五根五力、依法不依人","諸佛所得祕要法是第八識，非離念靈知","證悟後漸轉識成智，能隨義如實說","引成唯識論：第八識執持流轉與還滅法種"],"k":["已見我","第八識","成唯識論","玄奘","七住位","六即佛"]},"7249-a29_016":{"s":"本集引玄奘《成唯識論》說明第八識隨義立名：心、阿陀那、所知依、種子識通一切位，阿賴耶、異熟識、無垢識則依階位不同，見如來即見此同一心。並引論文破斥經部師等六識論，指無第八識持種則因果相續不成；批評應成派與釋印順「大乘非佛說」，並舉彌勒七因證大乘真是佛說。","p":["已入見道菩薩能證解阿賴耶識","第八識隨階位立阿賴耶、異熟、無垢等名","無第八識持種，則因果相續不能成立","批評應成派與釋印順否定第八識、大乘非佛說","彌勒以七種因證大乘經真是佛說"],"k":["第八識","成唯識論","阿賴耶識","異熟識","無垢識","大乘非佛說"]},"7239-a29_017":{"s":"本集講〈如來神力品〉偈「知佛所說經，因緣及次第，隨義如實說」。說明五濁惡世見濁深重，佛須先以人天次法、二乘菩提為基礎，再引入佛菩提，最後收攝於《法華經》圓教。辨析權教與實教：次法與二乘屬善權方便，實教為第一義悉檀與六度、十度的成佛之道；並以今人不願否定意識說明次法熏習不足。","p":["佛示現人間是為教導實證佛菩提","須依次第弘法，不能一開始直說真實義","人天次法與二乘菩提屬權教","不願承認意識虛妄，顯示次法熏習不足","實教為第一義悉檀、六度十度成佛之道"],"k":["權教","實教","次法","斷我見","第一義悉檀","五濁惡世"]},"7246-a29_018":{"s":"本集說明佛法有頓教與漸教、始教與終教之分。二乘菩提只有漸教，「善來比丘」頓成阿羅漢實為菩薩再來；佛菩提的明心、見性、過牢關皆一念頓悟，但成佛過程仍須漸修。先說《華嚴》為始教，《法華》等為終教即圓教，合為五時三教；後解釋偈中「如日月光明」及「應受持斯經」等句。","p":["二乘菩提只有漸教，善來比丘乃菩薩再來","佛菩提見道皆一念頓悟，成佛仍須漸修","先講《華嚴》為始教，以免眾生疑佛","五時三教缺一不可，《法華》為終教圓教","受持斯經涵蓋如來藏總相及整體佛法"],"k":["頓教","漸教","始教","終教","五時三教","圓教"]},"7251-a29_019":{"s":"本集進入〈囑累品〉，講世尊現大神力三摩無量菩薩頂，付囑流布無上正等正覺法。指出世尊修道歷「無量百千萬億阿僧祇劫」，因最初無佛可依須自行摸索；引平實導師之說論證如來藏雖無始本有，佛地並非本有，最初威音王佛亦須斷二障成佛，否則違平等法。並解釋「一心流布」「廣宣此法」。","p":["世尊同時為無量菩薩摩頂，是如來大神力","世尊修道歷無量百千萬億阿僧祇劫","如來藏無始本有，但無本來成佛之佛","威音王佛後自稱無師成佛者為自然外道","一心流布、廣宣此法，令眾生普得聞知"],"k":["囑累品","本初佛","威音王佛","二障","摩頂付囑"]},"7258-a29_020":{"s":"本集承上集，說今人依佛修學只需三大阿僧祇劫，應感念佛恩師恩；並說明廣宣此法時自己亦須受持讀誦，自他兩利。由世尊說明付囑原因引申，強調學佛須先探究「為何學佛」，舉念佛三年佛在西天為例，並詳述平實導師從念佛、打坐到看話頭而破參的經歷，結論學佛是為成佛，須求開悟。","p":["依佛修學只需三大阿僧祇劫，應感念佛恩","廣宣此法的同時須自己受持讀誦","凡事有因，學佛應探究為何學佛","平實導師從念佛、打坐到看話頭悟入的經歷","學佛為成佛，不求開悟只是修集見道資糧"],"k":["學佛目的","廣宣此法","看話頭","開悟明心","紹隆佛種"]},"7260-a29_021":{"s":"本集講〈囑累品〉「如來有大慈悲，無諸慳悋，亦無所畏」。說明世尊於人壽百歲困苦時示現、教導三乘、財法無吝即大慈悲；並闡釋四無所畏：如來於煩惱障現行與習氣種子、所知障與上煩惱皆已斷盡，且具知對治之法。舉鴿入佛影無怖、阿羅漢抖蛇之例說明習氣，並述通達與入地條件。","p":["佛於困苦時節示現並教三乘，是大慈悲","財物與佛法上皆無慳吝","煩惱障分現行與習氣種子，以鴿影為喻","通達須廣修福德、永伏性障、進修般若","煩惱障與所知障各二無所畏，合為四無所畏"],"k":["四無所畏","大慈悲","煩惱障","所知障","習氣種子","十無盡願"]},"7263-a29_022":{"s":"本集解釋如來所施三種智慧。佛之智慧即一切種智，具足證知如來藏所含一切種子（功能差別），並以共業如來藏變生食物、《起世經》地肥粳米為例；如來智慧指初地至十地修道所證的道種智；自然智慧則是證得本有第八識的實相般若，有別於把離念覺知心當真心及自然外道，又稱無師智。","p":["佛之智慧即一切種智，證知如來藏一切種子","種子即功能差別，共業如來藏變生器世間","如來智慧為初地至十地的道種智","離念覺知心是有生之法，非自然智慧","自然智慧為證本有第八識之實相般若、無師智"],"k":["一切種智","道種智","自然智慧","種子","如來藏","自然外道"]},"7253-a29_023":{"s":"本集說明如來以究竟法施利益眾生，故為一切眾生之大施主，勉菩薩隨學勿慳。解釋「若有善男子、善女人信如來智慧者，當為演說此《法華經》」：引《雜阿含》界定不善男子為行十不善者，並指信如來智慧者才合格；批評六識論者等同佛與阿羅漢，依意根、十八界與涅槃本際說明二乘亦依八識論，末述別教與通教。","p":["法布施最勝，佛為三界最大施主","《雜阿含》：行十不善業者為不善男子","信受如來智慧者才宜為說《法華經》","意根與涅槃本際顯示二乘亦依八識論","別教不共二乘，通教菩薩終將信如來智慧"],"k":["大施主","法布施","善男子善女人","八識論","涅槃本際","通教別教"]},"7266-a29_024":{"s":"本集續講「若有眾生不信受者，當於如來餘深法中示教利喜」。說明對不信如來智慧者，先依八識論說真正二乘菩提，由五陰十八界、意根與涅槃本際導其接受八識；若連三界因果都不信，則先說世界悉檀與次法。信受後再說六度等餘深法乃至此經；依根器如法說法即報諸佛恩，並引彌勒說此為諸佛密意。","p":["二乘菩提對凡夫而言也是如來餘深法","由五陰十八界、意根、本際引入八識論","不信因果者先說世界悉檀與次法","前五度為佛菩提次法，六度圓滿方能實證","依根器如法說法即是報諸佛恩"],"k":["如來餘深法","示教利喜","八識論","方便善巧","報佛恩","囑累品"]},"7269-a29_025":{"s":"本集講〈囑累品〉末段：菩薩摩訶薩聞付囑後遍身歡喜，曲躬低頭合掌三度承諾奉行，世尊遂令分身諸佛各還本土、多寶塔復原。說明多寶如來敬重此經因一切法由此經出生，世尊視菩薩如獨子；並述末法魔子混入佛門之憂，勉弟子承擔護持正法、破斥密宗外道之任，以送真黃金為喻說難能可貴。","p":["多寶如來尊重此經，因一切法由此經生","世尊視菩薩如獨子，殷勤付囑","菩薩曲躬合掌三度承諾如敕奉行","末法魔子混入佛門，須防密教興而佛教亡","難能而為方可貴，勉眾承擔正法"],"k":["囑累品","多寶如來","付囑","護持正法","密宗"]},"7265-a29_026":{"s":"本集進入〈藥王菩薩本事品〉，宿王華菩薩為眾請問藥王菩薩本生因緣，世尊說過去日月淨明德如來及其淨土。說明世尊初提一佛必說十號，是為提示成佛應具功德，免人自稱成佛犯大妄語；並解釋大菩薩摩訶薩、大聲聞的定義，比較淨土與三界諸天之異，及此土無女人、三惡道與諸難的莊嚴。","p":["宿王華菩薩為大眾請問藥王本生因緣","初提一佛必說十號，防自稱成佛大妄語","大菩薩摩訶薩約指八地以上","淨土依諸佛別願成就，不同於三界諸天","《法華經》涵蓋三乘一切佛法"],"k":["藥王菩薩本事品","如來十號","日月淨明德佛","淨土","大妄語"]},"7259-a29_027":{"s":"本集說日月淨明德佛座下大聲聞實為菩薩，讀經不可依文解義。引經講一切眾生喜見菩薩樂習苦行、精進經行，得現一切色身三昧，以神力及燃身供養佛與《法華經》。說明正覺主張制心一處、念念於法的「心苦行」而非身苦行；並解釋迷事與迷理無明，及從理上觀一切色身同由如來藏所生的普現色身三昧。","p":["大聲聞眾現聲聞相，本質為菩薩","喜見菩薩樂習苦行，燃身作法供養","正覺主張心苦行而非身苦行","迷事無明與迷理無明之別","理上觀己身、佛身、眾生身同一如來藏"],"k":["一切眾生喜見菩薩","現一切色身三昧","心苦行","迷理無明","法供養"]},"7255-a29_028":{"s":"本集續說理上的現一切色身三昧：有情無量世輪轉天人、人、三惡道，各世色身皆由如來藏普門示現，現觀而心得決定即是此三昧，亦可生平等心；喜見菩薩則因身根清淨能於事上隨意示現。並說長劫苦行而得明心仍然值得，勉人日常供佛、供衣並作意供養自身如來藏，強調法供養勝於世間供養。","p":["有情世世色身皆是如來藏普門示現","理上現觀而心得決定即現一切色身三昧","喜見菩薩身根清淨，能於事上隨意示現","長劫苦行而得明心仍然值得","日常供佛並作意供養自身如來藏，重法供養"],"k":["現一切色身三昧","普門示現","如來藏","法供養","明心","供佛"]},"7282-a29_029":{"s":"本集講解〈藥王菩薩本事品〉：一切眾生喜見菩薩因聞《法華經》得現一切色身三昧，以三昧力雨下寶華與海此岸栴檀供佛，再服香、塗香油、纏天衣燃身供佛一千二百歲，諸佛讚為真法供養。講者說明施者、福田、施物皆勝而得無量報，並提醒此苦行以證量與報恩為前提，不可盲目效法。","p":["喜見菩薩聞《法華經》得現一切色身三昧","以三昧力雨華香供佛，海此岸栴檀極珍貴","服香塗油燃身，光照八十億恆河沙世界","施主、福田、施物三者皆勝，得無量報","須先衡量自身證量，勿妄效苦行"],"k":["法供養","燃身供佛","現一切色身三昧","一切眾生喜見菩薩","苦行"]},"7288-a29_030":{"s":"本集講喜見菩薩命終後於淨德王家結跏趺坐化生，無胎昧即說偈向父王說明來歷，並於法供養後不求自得解一切眾生語言陀羅尼。講者說明莊嚴菩提心要靠如法修行與報恩供養，而非觀想月輪種子字；又講見佛先讚佛再稟身分的禮儀，及日月淨明德佛告知涅槃時至、令安施床座。","p":["喜見菩薩化生王家，無胎昧即說偈","法供養後不求自得解一切眾生語言陀羅尼","莊嚴菩提心靠如法修行，非觀想月輪","見佛先讚佛再稟身分，是菩薩禮儀","佛示涅槃須安施床座，安詳示寂"],"k":["解一切眾生語言陀羅尼","法供養","菩提心","胎昧","般涅槃"]},"7273-a29_031":{"s":"本集講日月淨明德佛臨入涅槃，將佛法與成佛之道、七寶世界及給侍諸天付囑喜見菩薩與諸菩薩大弟子，並付囑舍利廣起千塔。講者說明付囑對象須具能力與願力；碎身舍利為讓眾生種福田（多寶如來例外），駁舍利為結石之說，強調供養法舍利功德更勝；並述師子奮迅三昧入涅槃及釋迦如來北首之義。","p":["佛法須付囑有能力、願力的菩薩大弟子","付囑含三賢十地成佛之道，不只明心","碎身舍利為眾生種福田，多寶如來例外","駁舍利為吃豆腐結石之說；法舍利功德更勝","諸佛以師子奮迅三昧入涅槃，北首表法北傳"],"k":["付囑","舍利","法舍利","師子奮迅三昧","福田","多寶如來"]},"7286-a29_032":{"s":"本集延續北首之義，講大乘法北傳中國：達摩以《楞伽經》印證宗門所悟即第八識如來藏，開悟唯有頓悟、道不屬修，並以爬樹嚐果為喻；玄奘譯經使禪門得聖教依據而一花五葉。接著講喜見菩薩起八萬四千寶塔、燃臂七萬二千歲供舍利並立誓雙臂還復，勉勵以住持正法、紹隆佛種報恩為真法供養。","p":["達摩以《楞伽經》印證，所悟為第八識","開悟唯頓悟，以爬樹嚐果喻修與悟","玄奘譯經使禪宗得聖教依據，一花五葉","喜見菩薩起八萬四千塔，燃臂七萬二千歲","住持正法、紹隆佛種才是真法供養"],"k":["頓悟","如來藏","燃臂供佛","法供養","玄奘","禪宗"]},"7280-a29_033":{"s":"本集講喜見菩薩以海此岸栴檀荼毘佛身、收舍利起八萬四千塔，並對照釋迦如來舍利由八王均分的故事。喜見菩薩令大眾一心隨喜後燃百福莊嚴臂七萬二千歲，使無量聲聞迴心證現一切色身三昧。講者強調凡夫不可燃指效法，批評濫慈悲與包容相似像法，並評論達賴喇嘛鼓動自焚。","p":["釋迦舍利由婆羅門調停八王均分","喜見菩薩令大眾一心念，得隨喜功德","燃臂度無量聲聞迴心，證現一切色身三昧","凡夫燃指發誓不能還復，恐謗經成罪","慈悲須有智慧，不可容許相似像法"],"k":["燃臂供佛","燃指供佛","現一切色身三昧","迴小向大","舍利","相似像法"]},"7271-a29_034":{"s":"本集說明燃臂供佛的理與事：從如來藏立場燒亦非燒，有事有理功德遠勝；喜見菩薩已過九地、住淨土、具願力與多劫苦行功德，故雙臂能還復，人間凡夫不應燃指，菩薩身根應莊嚴。經文揭示喜見菩薩即今藥王菩薩、捨身無量；講者並述平實導師定中見覺囊派往事，說明如來藏記錄往世經歷。","p":["從如來藏看燒臂非燒，有事有理功德大","證量、願力、環境不同，凡夫勿效燃指","菩薩身根應莊嚴，十指不全令眾生生惱","一切眾生喜見菩薩即今藥王菩薩","定中見覺囊派往事，如來藏記錄往世"],"k":["燃臂供佛","藥王菩薩","如來藏","福德淳厚","捨身布施","覺囊派"]},"7284-a29_035":{"s":"本集講經文的功德較量：燃一指供佛塔勝於以國城妻子及三千大千世界珍寶供養；以七寶滿三千大千世界供養四聖，不如受持《法華經》乃至一四句偈。講者引導觀眾自行較量，指出受持此經是第一義智慧並伴隨大福德，菩薩應護身為道器；並解「海為第一」喻，說大乘諸經皆依如來藏而說，批評印順的判教。","p":["燃一指供佛塔勝於以三千大千世界供養","受持《法華經》乃至一四句偈福德最多","受持此經屬第一義智慧，非僅世間福德","菩薩戒不故入難處，色身是道器","此經如大海，大乘諸經皆依如來藏說"],"k":["功德較量","受持法華經","四句偈","如來藏","燃指供佛","性空唯名"]},"7277-a29_036":{"s":"本集解說須彌山、月天子、日天子三喻：《法華經》如須彌山於諸經最為其上，如月於諸經最為照明（證此經方能讀懂大乘經），如日能破一切不善之闇。講者分析欲界的不善之闇，包括一神教上帝的瞋心與行善只求生天享樂，說明證如來藏現觀業種不失可破之；並論色界天人與大梵天王信徒誤以永生為不死的邪見。","p":["須彌山喻：此經於諸經最為其上","月天子喻：證此經才有讀經的照明智慧","日天子喻：此經能破一切不善之闇","行善只求生天享樂，屬善法之闇","色界天人自認永生不死，是其不善之闇"],"k":["不善之闇","須彌山","照明","欲界","色界","大梵天王"]},"7287-a29_037":{"s":"本集續說三界的不善之闇：欲界求生天享福、色界執永生、四禪無想天誤認無想定為涅槃、無色界四空定誤以為出三界，皆屬不善之闇。進而說俱解脫阿羅漢不知名色緣識、緣覺不知無餘涅槃中境界，二乘雖非凡仍名為愚；七住明心菩薩即能知無餘涅槃境界，須依如來藏才能破除。","p":["欲界行善求生天享福為不善之闇","無想天誤為無餘涅槃，壽盡仍下墮","四空定仍有壽命，並未出三界","阿羅漢不知名色緣識，須學十因緣","緣覺不知涅槃中境界，七住菩薩能知"],"k":["不善之闇","無想天","四空定","十因緣","無餘涅槃","上漏為患"]},"7293-a29_038":{"s":"本集講大乘的不善之闇：七住明心仍不知十住如幻觀與眼見佛性，乃至妙覺不知佛地，皆依「此經」如來藏次第滅除，「此經」非指經卷。接著解轉輪聖王喻，述四種輪王與七寶，說明此經於眾經最為其尊：外道經典與三乘經典的撰寫、結集都依如來藏，二乘、般若、唯識諸經皆圍繞如來藏說，未悟研讀唯識無益。","p":["明心後仍有不善之闇，至成佛方滅盡","「此經」指如來藏，非課誦的經卷","四種轉輪聖王與七寶，喻此經最尊","外道與三乘經典皆依如來藏才能寫出","唯識經悟後方懂，不識本心學法無益"],"k":["不善之闇","轉輪聖王","如來藏","阿賴耶識","般若","唯識"]},"7298-a29_039":{"s":"本集說明此經為諸經中王：唯識諸經若抽離如來藏則不知所云，二乘若無本識則成無因唯緣的外道論。講者解帝釋為三十三天王之喻（並說韋陀菩薩非帝釋化身）與大梵天王喻，說此經是一切學、無學及發菩薩心者之父；辨析學與無學的層次，並指出初果須信有涅槃本際才能斷我見，五千退席者即不信此經。","p":["虛妄唯識門須依真實唯識門成立","帝釋為三十三天王，喻此經為諸經中王","韋陀菩薩為賢劫最後一佛，非帝釋化身","學與無學有層次，菩薩轉依如來藏本無學","初果須信涅槃有本際，才敢斷我見"],"k":["諸經中王","學無學","帝釋","初果","斷我見","如來藏"]},"7301-a29_040":{"s":"本集續說此經為三乘有學、無學之父：五千退席聲聞怕落斷滅而不能斷我見，初果至四果皆因知無餘涅槃有本際而證果。緣覺須懂十因緣與十二因緣的關係及「齊識而還，不能過彼」，最大無明即不懂此義；名色從識生，此識即如來藏。大乘見道證真如即證此經，故也是菩薩與發菩薩心者之父。","p":["五千退席聲聞怕斷滅，不能證初果","初果至四果皆依涅槃本際而證","「齊識而還，不能過彼」為因緣觀關鍵","十二因緣不是十因緣的增說","大乘見道證真如，即實證此經"],"k":["十因緣","齊識而還","聲聞四果","緣覺","證真如","名色"]},"7305-a29_041":{"s":"本集解「凡夫中四果、辟支佛為第一」之喻：講者認為一神教天主乃至大梵天王皆不知名色虛妄，初果人即勝於他們；此經於如來、菩薩、聲聞所說諸經法中最為第一，聲聞若無如來藏則不願斷盡我執。並說受持此經者於眾生中第一，以三歸依實義說明歸依法身佛與法身如來藏，證悟者為勝義僧而不應起慢。","p":["講者評一神教天主屬鬼神類，不知名色虛妄","初果人為一切凡夫中第一","聲聞無如來藏則不願斷盡我執","正覺法義始終依如來藏而說","證法身如來藏為勝義僧，是真歸依僧"],"k":["最為第一","三歸依","勝義僧","法身","初果","如來藏"]},"7291-a29_042":{"s":"本集解「聲聞辟支佛中菩薩第一」與「如佛為諸法王，此經諸經中王」兩喻：皇帝天子層次遠低於聲聞，二、三轉法輪皆說如來藏，《法華經》總其成。講者批評密宗四大法王為大凡夫，說佛為法王不涉政治，述阿闍世王見佛故事；並論證意根與六識皆不能住胎造身，引《阿含經》識入母胎問答，證入胎識即第八識。","p":["天子僅為忉利天主之子，不入聖流","菩薩為三乘中第一，此經諸經法第一","究竟通達一切法方為法王，佛不涉政治","阿闍世王疑懼見佛，終得無根信","意根不能住胎，入胎識即第八識"],"k":["法王","入胎識","意根","三轉法輪","密宗","阿闍世王"]},"7295-a29_043":{"s":"本集說明此經不只是三乘經王，也是外道經論之王，因一切經論都由如來藏所生的名色造作；藥王菩薩之名來自布施治生死病的妙法。接著引「此經能救一切眾生」一段經文，解「離諸苦惱」：此經指如來藏而非經卷，轉依後世間計較減少而離苦惱；又說證此經能「充滿其願」，以未來世受生自在為例。","p":["此經也是外道經論之王","藥王之名來自布施治生死病的妙法","此經是如來藏，非拜經求保佑","轉依如來藏後減少計較，離諸苦惱","證此經未來受生自在，能充滿其願"],"k":["諸經中王","藥王菩薩","離諸苦惱","轉依","充滿其願","如來藏"]},"7299-a29_044":{"s":"本集解「如清涼池」「如寒者得火」「如裸者得衣」三喻：學佛多年不得其門如渴乏者，證得如來藏如遇清涼池；學佛退心如心寒，證悟得智慧之火，並警示勿近密宗唐卡的邪火；學佛多年未悟者羞於被問，證悟後如裸者得衣，並從如來藏本無慚愧說明真慚愧。","p":["清涼池喻：證如來藏解學佛的渴乏","寒者得火：證悟得智慧之火，滅除無明","勿近密宗邪火，免燒壞佛菩提種","裸者得衣：證悟後不再羞於被問開悟","如來藏本無慚愧，懂此方是真慚愧"],"k":["清涼池","寒者得火","裸者得衣","證悟","如來藏","抉擇分"]},"7304-a29_045":{"s":"本集重述「此經能救一切眾生」經文及九種譬喻，說明此經即第八識如來藏，轉依後煩惱漸減，「還是舊時人，不是舊行履」。講者說般若智慧是意識證悟如來藏後所得，如來藏本身無智亦無得；證悟是一念相應慧，須具定慧福德、除性障並轉依成功才是七住不退；並提醒擇真善知識，勿以定為禪。","p":["此經指第八識如來藏，非經卷","般若智慧屬意識所得，如來藏無智亦無得","證悟為一念相應慧，三地滿心前有胎昧","真悟須轉依，有解脫與智慧正受","勿以定為禪，離世覓菩提如求兔角"],"k":["如來藏","轉依","一念相應慧","根本無分別智","胎昧","善知識"]},"7307-a29_046":{"s":"本集解「如商人得主」：以古天竺商隊須有商主帶領為喻，說明修學大乘須親近真善知識，引《華嚴經》善知識八難及《放光般若經》，強調要隨學法與次法。講者批評以觀想中脈明點或一念不生冒充如來藏者為邪主、愚迷之主，並指應成派與自續派中觀源於六識論凡夫論師，真正中觀依八識論。","p":["商主喻：修學大乘須依真善知識","《華嚴經》所說值遇善知識的八難","須隨善知識修學法與次法","觀想明點、一念不生並非如來藏","中觀依八識論；應成、自續屬六識論"],"k":["善知識","商人得主","中觀","八識論","次法","密宗"]},"7309-a29_047":{"s":"本集解「如子得母」「如渡得船」「如病得醫」「如闇得燈」「如貧得寶」五喻：如來藏是《阿含經》所說諸法本母，離念靈知非真如。菩薩證如來藏不捨五蘊即在彼岸，阿羅漢能入涅槃而未證涅槃；諸佛以真如為藥、六度為藥引治生死病；證此經如一燈破千年闇室，法身慧命全現如貧得寶。","p":["如子得母：如來藏是諸法本母","離念靈知非真如，勿認錯母親","如渡得船：菩薩不捨五蘊即在彼岸","如病得醫：真如為藥，六度為藥引","如闇得燈、如貧得寶皆指證此經"],"k":["諸法本母","如渡得船","真如","六度波羅蜜","離念靈知","次法"]},"7319-a29_048":{"s":"本集解「如民得王」：先說藥王菩薩之名源於布施治生死病的此經，再述各類王與轉輪聖王，引《方廣大莊嚴經》說明唯能轉法輪者為法王。講者指出諸法之王即如來藏，能生一切法而於諸法自在，意識夜斷不能為王；證悟時是我見祂而祂不見六塵，開悟只是入門仍須進修，並提醒勿誤信喇嘛法王。","p":["藥王菩薩布施的治生死藥即是此經","轉輪聖王以十善治化，佛轉法輪為法王","如來藏能生諸法、於法自在，是真法王","證悟時我見祂，祂不見六塵","開悟只是入門，勿信自稱法王的喇嘛"],"k":["如民得王","法王","如來藏","轉法輪","轉輪聖王","諸法本母"]},"7323-a29_049":{"s":"本集依〈藥王菩薩本事品〉（講義第二十一輯178頁起）講解「如賈客得海、如炬除闇」。以商賈得海喻證得此經如來藏即能遨遊自身本具的法性大海，以火炬除千年暗室喻實證如來藏能照破無始無明；並批評緣起性空的斷見與意識常住的常見，強調證此經即是見道、得慧眼而能讀懂經典。","p":["法性大海本在自身，入海鑰匙是此經妙法蓮花","批評斷見與意識常住常見，喻為「黑暗海」","聲聞智慧如螢火，大乘實相智慧如火炬","證此經即真見道，得慧眼能轉經、宗教不二","修學前須理智分辨，唯一入手是證如來藏"],"k":["如來藏","法性大海","無始無明","見道","藥王菩薩本事品","常見與斷見"]},"7313-a29_050":{"s":"本集講解〈藥王菩薩本事品〉「能令眾生離一切苦一切病痛，能解一切生死之縛」。指出依文解義者讀經再虔誠也不解其義；此經如來藏離六塵見聞覺知、不受苦痛，轉依祂即無苦無病。並說明法智忍、法智、類智忍、類智的次第，以及證此經自然斷我見、解開生死繫縛，悟後須能安忍才不退轉。","p":["依文解義誤解經文，問題在缺乏正知見","如來藏離見聞覺知，不受苦與病痛","禪門道「不審」：真我從不審察六塵","法智忍、法智、類智忍、類智四種智慧","證此經即斷我見，漸解分段與變易生死縛"],"k":["如來藏","離苦","法智忍","類智","斷我見","生死繫縛"]},"7315-a29_051":{"s":"本集講解〈藥王菩薩本事品〉「若自書，若使人書」功德不可籌量（講義第二十一輯215頁起）。說明「自書」不是抄經，而是禪師所說的「轉經」、日常中運轉此經如來藏；以麻谷公案警示落入五陰、自以為悟的過失。「使人書」更難，同修會分工合作以擴大功德；最後說明事相上抄經並以華香、瓔珞、幡蓋等供養亦得無量功德。","p":["真懂書寫者日常起居皆在書寫此經","麻谷公案：落五陰是風力所轉，終成敗壞","自書即轉經，捧經課誦反被經轉","使人書極難，同修會分工共同度眾","事相抄經並以華香燈等供養亦功德無量"],"k":["書寫此經","轉經","如來藏","功德","供養","禪宗公案"]},"7311-a29_052":{"s":"本集續講〈藥王菩薩本事品〉（講義第二十一輯224頁起），說明聞此品者功德無量、女人受持不復受女身，並引《六度集經》賣膏油女轉成男身得授記的故事。解釋宿王華名義，指出藥王菩薩歷劫修苦行而得「現一切色身三昧」：離放逸行則易與此經相應，先得理上的此三昧，再進至八地於相於土自在的事上境界。","p":["供養經卷引人探究，令此經妙法弘揚","此經即第八識妙法蓮花，為圓教之法","《六度集經》賣膏油女轉男身得授記","苦行易與此經相應，放逸行則心向外散","理上現一切色身三昧：觀往世色身皆由此經生"],"k":["現一切色身三昧","藥王菩薩本事品","苦行","放逸行","宿王華菩薩","轉女成男"]},"7321-a29_053":{"s":"本集解說〈藥王菩薩本事品〉「盡是女身，後不復受」的真義：受持即證得理上的現一切色身三昧，從如來藏看一切有情，所見無非如來藏，便無女身可見。引《佛說未曾有正法經》文殊隱身、摩伽陀王不見一法為證。再講末後五百歲女人如說修行往生極樂，生蓮華寶座上，超越貪瞋癡所對應的三界境界。","p":["區分「女人」與「女身」，不可依文解義","受持即證理上現一切色身三昧","文殊隱身：真如境界不見自他、無能所施","末法女人如說修行，往生極樂上品上生","得無生法忍超越欲界、色界、無色界"],"k":["如來藏","受持","女身","極樂世界","無生法忍","上品上生"]},"7325-a29_054":{"s":"本集講解〈藥王菩薩本事品〉「得是忍已，眼根清淨」，見七百萬二千億那由他恒河沙諸佛。說明往生者斷隨煩惱、得三地滿心的菩薩神通，非想定之樂如地獄苦；引舍利弗與目連比神足的故事，說明神通隨智慧自在。並以七覺支、七聖財解釋「七百萬」的理上含義，說明猗覺支即初禪，以及依阿彌陀佛願力上品上生的道理。","p":["得菩薩神通表示已滿足三地心","非想非非想定之樂如地獄苦，屬愚癡","舍利弗衣帶故事：心神足隨智慧自在","眼根清淨隨欲所見，見無量諸佛","七覺支為根基，猗覺支以初禪為驗證"],"k":["眼根清淨","菩薩神通","七覺支","無生法忍","極樂世界","藥王菩薩本事品"]},"7317-a29_055":{"s":"本集講解〈藥王菩薩本事品〉諸佛遙讚「受持讀誦思惟是經，為他人說」福德無量，「火不能焚，水不能漂」，千佛共說不能盡。說明受持、讀誦、思惟的次第，以及如來藏能仁寂靜的境界；再解釋「破諸魔賊，壞生死軍」：四魔、十八界為法賊、無記異熟種子為「諸餘怨敵」，並引補寺壁孔延命的故事說明福田。","p":["受持、讀誦、思惟、為人說有其次第","如來藏能仁寂靜，永不起惡心、無六塵","功德存於如來藏，瞋火愛水不能損","四魔與十八界法賊，破之須超越五陰","十地滿心受職，百千諸佛共守護"],"k":["功德","受持讀誦","四魔","十八界","如來藏","藥王菩薩本事品"]},"7327-a29_056":{"s":"本集講解〈藥王菩薩本事品〉末段：宿王華名義、口出青蓮華香等十地功德，世尊囑咐宿王華在南閻浮提流傳此經、以神通力守護。強調佛法是心地法門，從凡夫到資糧位都要修心、汰換染汙種子；並說明《央掘魔羅經》被編入阿含部的原因、窺基破斥圓測，以及八萬四千菩薩得解一切眾生語言陀羅尼、多寶如來讚歎。","p":["佛法是心地法門，各階位皆須修心轉依","宿王華表如來藏本住自在，久修此法","囑咐流傳此經，勿令破法者得便","《央掘魔羅經》說如來藏而入阿含部","擊法鼓破邪顯正，舉窺基駁圓測為例"],"k":["宿王華菩薩","心地法門","如來藏","央掘魔羅經","破邪顯正","轉依"]},"7340-a29_057":{"s":"本集說明此經如來藏與無餘涅槃的關係。二乘人未證真如，阿羅漢滅盡十八界後並非斷滅，因為有阿羅漢滅不了的本有法；無餘涅槃是依第八識獨存的寂滅境界而施設。引阿含「滅諦不離如」、「如來所依識」、「齊識而還」等說明真如即第八識，並批評南傳《尼柯耶》多一字的理解，談如來藏有無量名。","p":["意識與意根皆生滅，只是工具非真我","阿羅漢滅十八界，焰摩迦比丘斷滅見有誤","無餘涅槃依本有法第八識而施設","滅諦不離如，「如來所依識」即第八識","第八識自流注，終出無餘涅槃迴小向大"],"k":["無餘涅槃","如來藏","第八識","真如","齊識而還","二乘"]},"7333-a29_058":{"s":"本集說明此經如來藏即第八識，成佛時改名無垢識。勸人對成佛具信心，並解釋意根為何稱第七識、第八識為何稱第八；說明第八識含藏種子、隨緣流注、與名色七識互緣，出生器世間與五陰，果報分毫不差。另說明依第八識施設四種涅槃，以及阿賴耶識、異熟識之名與分段、變易生死的關係。","p":["如來藏、第八識、真如是同一心","意根有了別性，故稱第七識","第八識含藏種子，隨順緣起出生萬法","第八識以大種性自性出生器世間","阿賴耶與異熟識之名，分段與變易生死"],"k":["第八識","如來藏","無垢識","意根","種子","異熟識"]},"7344-a29_059":{"s":"本集闡述「此經」如來藏的體性：如來藏的功德從不失去，三歸依實為自歸依。講者以「阿里不達」等俚語批評藏密雙身法及一神教。說明如來藏是萬法根本因與所知依，性如金剛不可合併分割，無為法性而具有為功德，是真實我，到佛地成為常樂我淨；並勸人相信小低頭皆已成佛道。","p":["如來藏功德常在，不因輪迴惡法改易","三歸依即自歸依自身如來、法藏、僧寶","以俚語諧音批評藏密雙身法與一神教","如來藏性如金剛，不能合併也不能分割","如來藏無為而具有為功德，是真實我"],"k":["如來藏","所知依","真實我","三自歸","藏密批判","因果"]},"7330-a29_060":{"s":"本集依《成唯識論》卷三「若不摧邪，難以顯正」，說明正法、像法、末法三時的弘法現象，月光菩薩與《無量壽經》住世百年，以及比丘尼僧團使正法減為五百年、部派分裂。再界定常見外道（以意識為常）、斷見外道（否定第八識），並具體批評四大山頭、自續與應成派中觀、宗喀巴、達賴喇嘛、印順等人。","p":["正法、像法、末法三時漸漸消滅","相似像法出世間後，正法則滅","女眾出家使正法由千年減為五百年","常見外道以離念靈知等意識為常住","批評宗喀巴、達賴、印順否定第八識"],"k":["摧邪顯正","成唯識論","常見外道","斷見外道","末法","六識論"]},"7337-a29_061":{"s":"本集續講「若不摧邪，難以顯正」，以玄奘菩薩生平說明《成唯識論》的由來：幼年知禮、十三歲出家發願、明心見性、西行取經、戒賢論師忍病等待、曲女城無遮大會立「真唯識量」、回唐譯經七十四部。並說明窺基「有義」建議與《述記》的得失，勉勵菩薩效法摧邪顯正。","p":["玄奘十三歲出家發願「遠紹如來，近光遺法」","發願分通願與別願，成佛須發大願","戒賢論師忍病等待玄奘，業報須坦然承受","曲女城無遮大會立「真唯識量」","窺基「有義」與《述記》未能彰顯破邪效果"],"k":["玄奘菩薩","成唯識論","摧邪顯正","真唯識量","窺基","發願"]},"7342-a29_062":{"s":"本集講「唯一佛乘」上篇：世尊說五乘佛法，人天乘、二乘皆從唯一佛乘析出，引《勝鬘經》證二乘依大乘而增長。依阿含說明次第說法：施論、戒論、生天之論，再說四聖諦。並論證二乘無餘涅槃不是斷滅空，而有本際、如如、真實我；緣覺以十因緣「齊識而還」確認此識，故緣覺勝於聲聞。","p":["五乘佛法中，四乘是唯一佛乘的局部","世尊次第說法：施論、戒論、生天之論","聲聞依四聖諦斷三縛結至五上分結","無餘涅槃非斷滅，有本際如如獨存","十因緣「齊識而還」與十二因緣之識不同"],"k":["唯一佛乘","五乘佛法","四聖諦","無餘涅槃","十因緣","次法"]},"7335-a29_063":{"s":"本集講「唯一佛乘」下篇：二乘法只是世尊在唯一佛乘中化現的化城，以拈花教外別傳令阿羅漢證悟般若，再轉第二、第三轉法輪，最終導歸一佛乘，並引化城喻經文。批評印順、達賴對三轉法輪的主張；接著進入〈妙音菩薩品〉經文語譯，重點說明佛白毫相的殊勝功德。","p":["二乘菩提是唯一佛乘中化現的化城","拈花教外別傳，令阿羅漢證悟般若","三轉法輪：阿含、般若、唯識種智","化城喻：止息後滅化城，導向寶所","白毫相功德須累積無量功德方成"],"k":["唯一佛乘","化城喻","三轉法輪","妙音菩薩品","白毫相","般若"]},"7332-a29_064":{"s":"本集依講義第二十二輯解說〈妙音菩薩品〉的「無緣三昧」與「智印三昧」。先區分智慧三昧與禪定三昧；無緣三昧在三賢位指現觀如來藏於六塵無所緣，初地後轉依真如而不貪三界法，至妙覺圓滿。智印三昧以實相般若印定世間、出世間、世出世間法，須依八識論並親證三自性。最後說明解一切眾生語言三昧與四無礙辯。","p":["三昧分智慧心得決定與禪定兩類","三賢位無緣三昧：如來藏於六塵無所緣","初地以上轉依真如，不貪三界諸法","智印三昧印定世間、出世間、世出世間法","解一切眾生語言三昧與四無礙辯、譯經"],"k":["無緣三昧","智印三昧","妙音菩薩品","三自性","八識論","解一切眾生語言三昧"]},"7355-a29_065":{"s":"本集解說「集一切功德三昧」與「清淨三昧」。依《瑜伽師地論》說明功德與過失，功為自受用、德為他受用；一切功德種子由不生滅的第八識種子識集藏，如來藏有出生名色與共生器世間兩大功德，引《大悲經》說明世界非梵天所造。清淨三昧是現觀如來藏本來自性清淨，並依初地、七地、妙覺分層次。","p":["修行應修集功德、遠離雜染過失","功是自受用，德是他受用","第八識種子識集藏一切功德種子","如來藏出生名色並共生器世間","清淨三昧：現觀如來藏本來自性清淨"],"k":["集一切功德三昧","清淨三昧","種子識","如來藏","功德","器世間"]},"7350-a29_066":{"s":"本集解說「慧炬三昧」：實證此經妙法蓮花即得第一分慧炬三昧，「千年暗室一燈能破」，七住不退可得佛授記。強調智慧火須不受境界風動搖，引經說明觀察瞋心生滅而安忍。並說明菩薩慧通達如所有性、菩薩智通達盡所有性，三地、四地、五地的智慧增上，以及惡見是染慧、世智辯聰屬八難。","p":["證此經得第一分慧炬三昧，照破無明","七住位不退，佛即可為之授記","智慧火須穩定，安忍不隨境界風動","菩薩慧通如所有性，菩薩智通盡所有性","惡見屬染慧，須善知識正確教導"],"k":["慧炬三昧","般若智慧","授記","安忍","惡見","菩薩十地"]},"7353-a29_067":{"s":"本集解說「莊嚴王三昧」與「淨光明三昧」。說明福德莊嚴與智慧莊嚴互攝，六度即菩薩六種印，菩薩性有大悲、大信、大忍、大行四相；菩薩真正的莊嚴是依此經實證而來的智慧，故稱「王」。淨光明三昧指大乘實證並轉依成功後智慧的顯現，非二乘可及；並引《楞嚴經》「性淨明體」，強調心性是道業關鍵。","p":["福德莊嚴與智慧莊嚴互攝，皆由六度成就","菩薩性四相：大悲、大信、大忍、大行","莊嚴王三昧須依此經實證而得","淨光明三昧須大乘實證並轉依成功","如來藏是性淨明體，心性為道業關鍵"],"k":["莊嚴王三昧","淨光明三昧","福德莊嚴","智慧莊嚴","菩薩性","轉依"]},"7346-a29_068":{"s":"本集進入〈妙音菩薩品〉的「淨藏三昧」與「不共三昧」。淨藏指此經如來藏本來清淨、含藏一切清淨法藏，聲聞、緣覺乃至大乘見道修道的清淨法藏皆依之成立，七住得初分、八地以上為大三昧。不共三昧從布施禪定共外道講起，說明聲聞菩提不共，須先具足施論、戒論、生天之論，並批評誤以離念靈知為涅槃。","p":["淨藏：本來清淨的此經含藏一切清淨法藏","二乘清淨法藏亦須依如來藏方能成立","七住得初分淨藏三昧，八地起為大三昧","布施、禪定為共外道法，佛菩提為不共","次法不彰致誤以離念靈知為無餘涅槃"],"k":["淨藏三昧","不共三昧","妙音菩薩品","如來藏","次法","聲聞菩提"]},"7360-a29_069":{"s":"本集續講〈妙音菩薩品〉所列三昧：以聲聞、緣覺到佛菩提的次第說明「不共三昧」，上位所證不共下位；再說「日旋三昧」是悟後智慧如日周旋、不吝法而永續攝受眾生。並解說淨華宿王智佛囑妙音菩薩「莫輕彼國，生下劣想」，顯示佛法遍十方而不侷限於人間。","p":["佛法次第：聲聞、緣覺、佛菩提層層不共","七住證真如、十住見佛性，上位不共下位","日旋三昧：悟後說法如日周旋，不應吝法","三昧是心得決定，非僅指禪定境界","淨華宿王智佛囑妙音菩薩莫輕娑婆國土"],"k":["不共三昧","日旋三昧","妙音菩薩","如來藏","攝受佛土","心得決定"]},"7363-a29_070":{"s":"本集說明「汝莫輕彼國」實為告誡妙音菩薩的隨行眾，並談大菩薩各有法眷屬，無私心即非結黨。接著講諸佛淨土各有事上、理上四土，指娑婆的方便有餘土因五蓋與定障而難恢復，強調斷我見須有未到地定；末說十方世界與劫數之廣，非凡夫所能思議。","p":["「莫輕彼國」實為告誡隨行菩薩","法眷屬源自宿世因緣，無私心即非結黨","諸佛淨土各有事上、理上四土","五蓋與定障障礙入地及斷我見證初果","十方世界與時劫之廣，唯佛能知"],"k":["四土","法眷屬","定障","五蓋","未到地定","十方世界"]},"7352-a29_071":{"s":"本集舉例說明《法華經》背後涵攝他經少說的道理：三賢與諸地各階現觀、聲聞戒嚴而不開緣與菩薩戒多開緣的原因、謗三寶及謗菩薩藏不開緣、佛地四智與三界關聯等。指出《法華經》把一代時教收攝回歸「此經」如來藏，故稱圓教、「一圓一切圓」。","p":["三賢位與諸地各有應證的現觀","聲聞戒為出三界而嚴，菩薩戒為攝眾生多開緣","謗三寶、謗菩薩藏原則上不開緣","聲聞戒為別解脫戒，出家菩薩以菩薩戒為主","法華收攝一代時教歸如來藏，稱為圓教"],"k":["圓教","菩薩戒","聲聞戒","開緣","如來藏","一圓一切圓"]},"7357-a29_072":{"s":"本集講妙音菩薩稟白往詣娑婆「皆是如來之力、神通遊戲、功德智慧莊嚴」，並入三昧於靈鷲山化現八萬四千寶蓮華、文殊菩薩代眾請問一段。說明此「如來」指自心如來第八識，並以閻浮檀金莖喻通三界的般若智慧、白銀葉喻三昧、金剛鬚喻如來藏功德外護、甄叔迦寶臺喻佛菩提莊嚴。","p":["妙音菩薩言往娑婆皆如來之力，非溢美之詞","此「如來」指自心如來第八識如來藏","閻浮檀金為莖：般若實相智慧通三界","白銀為葉喻三昧，金剛為鬚喻如來藏外護","文殊菩薩明知而為大眾請問瑞相因緣"],"k":["妙音菩薩","自心如來","如來藏","三昧","寶蓮華","文殊菩薩"]},"7348-a29_073":{"s":"本集講世尊告文殊：妙音菩薩將率八萬四千菩薩來供養並聽《法華經》，及文殊問「種何善本、修何功德、行何三昧」一段。說明福德為三昧的前方便，須修「現一切色身三昧」，並舉喜見菩薩聞法華得此三昧；又說文殊早已成佛而為眾請問，藉妙音菩薩身量之大彰顯世尊威德與「此經」之重要。","p":["文殊問善本、功德、三昧三個面向","福德是智慧與三昧的基礎與前方便","現一切色身三昧，喜見菩薩聞法華而得","文殊早已成佛，倒駕慈航為眾請問","遠來聽受顯此經重要，學人應心量廣大"],"k":["現一切色身三昧","善本","福德","文殊菩薩","十無盡願","此經"]},"7367-a29_074":{"s":"本集講多寶如來召喚妙音菩薩，其與八萬四千菩薩所經諸國六種震動、雨七寶蓮華、天樂自鳴。說明釋迦如來讓多寶如來召喚以顯賓主互敬，依第八識的心念不受時空限制，所經之處亦成佛事；並解說青蓮華目、面如滿月、真金色身、威德熾盛與那羅延堅固之身，及菩薩在五濁世應忍眾生羞辱。","p":["釋迦如來讓多寶如來召喚妙音，顯賓主互敬","依第八識運作的心念不受時空限制","所經佛國震動、雨華、天樂，廣作佛事","妙音菩薩相好威德來自多劫修福","那羅延堅固之身喻四禪天主堅固身"],"k":["多寶如來","妙音菩薩","六種震動","威德","那羅延堅固之身","福德"]},"7365-a29_075":{"s":"本集續說菩薩威德力層級，指妙音菩薩為妙覺菩薩，而佛地境界非妙覺所能想像，故以好話讚佛並無過失。接著講妙音菩薩到靈鷲山代淨華宿王智佛問訊，說明他方菩薩問訊禮儀；解釋「少病」指世尊取人身故會病，批評以「眾生病故我病」為故意示病之說；「少惱」則舉因事制戒、飢荒托缽等事相煩擾。","p":["無生法忍、十地、最後身菩薩威德力層層倍增","佛地境界連妙覺菩薩亦不能想像","往謁他方佛須表明本師世尊之問訊","「眾生病故我病」指取人身故會病","少惱：因事制戒、飢荒托缽等事相煩擾"],"k":["問訊","妙覺菩薩","威德力","維摩詰經","因事制戒","五濁惡世"]},"7370-a29_076":{"s":"本集續解妙音菩薩的問訊：「起居輕利」、「安樂行」、「四大調和」關乎人身老化；「世事可忍」指佛以人身處世仍有俗務與天人求法；「眾生易度」以彌勒時代對比五濁惡世眾生難辨真假善知識。進而說明貪欲、瞋恚、愚癡代表三界，並以色界天無財色名食之貪為例。","p":["起居輕利、安樂行、四大調和皆因人身老化","四大不調是老化現象，與生病不同","世事可忍：佛以人身處世，俗務與求法者多","五濁世眾生難度，彌勒時代人壽長而易度","貪瞋癡代表三界，色界天已無五欲之貪"],"k":["問訊","貪瞋癡","三界","五濁惡世","色界天","四大調和"]},"7376-a29_077":{"s":"本集續講三界：色界無貪而有瞋，四空定離瞋仍有愚癡，愚癡主在錯認覺知心為真我。再說慢、慳、嫉妒障礙佛菩提道，以及不孝父母的常見；並依《阿含經》定義沙門須證初果或初果向，反駁外道以出家人犯戒批評佛教，引「有犯名菩薩，無犯名外道」。","p":["愚癡通三界，主在錯認見聞覺知心為我","慢源於我見等，障礙開悟","慳心重者難修六度與菩薩道","嫉妒為障道惡心所，不孝父母亦常見","依阿含定義，沙門須證初果或初果向"],"k":["沙門","沙門果","慳慢","嫉妒","愚癡","菩薩戒"]},"7373-a29_078":{"s":"本集說明敢當面向佛挑戰的外道多直爽，論後常斷我見、出家速證阿羅漢；只敢放話者多不可度。依阿含定義，修學正確解脫道者方屬沙門，修雙身法或持六識論否定如來藏者非真沙門。接著講「邪見」主要是把生滅的三界法當作常住，舉一神教永生、跳崖求生天、甘露丸等為例。","p":["當面挑戰佛的外道多直爽，常得法眼淨","廣義沙門：修學正確解脫道的出家人","修雙身法或持六識論者非真正沙門","對沙門應恭敬，對假沙門應辨正","邪見：以生滅三界法為常住不壞"],"k":["沙門","邪見","六識論","法眼淨","自性見","問訊"]},"7379-a29_079":{"s":"本集續解問訊「無不善心不」，以天界不善心漸少對比人間，指「心好就好」者仍對畜生不善，並說否定如來藏、毀謗證真如菩薩者必是凡夫而有不善心。再釋「攝五情」為收攝五根而不攝第六情，「降伏魔怨」至少須降伏五陰魔；末講先向法主稟告再見多寶如來的禮儀。","p":["天界不善心漸少，人間不善心普遍","證初果者不會否定如來藏，否定者為凡夫","攝五情：收攝五根，不攝第六情","降伏魔怨至少須在見地上降伏五陰魔","先向法主釋迦如來稟告，再見多寶如來"],"k":["不善心","攝五情","降伏魔怨","如來藏","多寶如來","問訊"]},"7369-a29_080":{"s":"本集從理上解說妙音菩薩：往娑婆「皆是如來之力」，事上如彌陀願力，理上是自心如來藏妙真如性所成。引《勝鬘經》空如來藏與不空如來藏、《般若經》五蘊實相即如來藏；並說妙音菩薩現種種身說《法華經》，理上即一切有情的如來藏隨業變現五陰、救護眾生。","p":["往娑婆皆如來之力：有事說與理說兩層","五蘊是空相，其本質為如來藏空性","《勝鬘經》說空如來藏與不空如來藏","妙音菩薩現種種身說法，理上即如來藏","如來藏依業種變現六道身而離我我所"],"k":["如來藏","妙音菩薩","空如來藏","不空如來藏","五蘊實相","妙真如性"]},"7378-a29_081":{"s":"本集回顧《法華經》以一佛乘分說三乘、火宅喻、化城喻與授記諸聲聞，說明多寶佛七寶塔依本願踊出為釋迦佛作證，並證諸佛涅槃只是示現、依十無盡願常住，批評釋印順「佛被理想化」之說。接著依《金光明經》講第二個七寶塔：摩訶薩埵王子捨身餵虎，其舍利塔應佛神力踊出。","p":["以一佛乘分說三乘，二乘涅槃如化城","多寶佛本願：有說法華處即踊塔作證","佛入涅槃只是示現，依十無盡願常住","批評釋印順視佛為理想化的說法","摩訶薩埵捨身餵虎，其舍利塔踊出"],"k":["七寶塔","多寶佛","一佛乘","捨身餵虎","十無盡願","本生"]},"7381-a29_082":{"s":"本集依《大方便佛報恩經》講第三個七寶塔：六師外道謗佛不孝，佛說忍辱太子捨眼髓救父王的本生，寶塔隨即踊出。並舉獼猴王救母、割肉奉親、睒摩迦孝養盲父母、救拔五百世之母迦旦遮羅等事蹟，勸菩薩慈忍孝順；並批評釋印順視本生為傳說，強調三乘修證建立在八識上。","p":["外道謗佛不孝，佛以忍辱太子本生回應","寶塔踊出顯佛孝養父母而成佛","割肉奉親、睒摩迦孝養盲父母等本生","救拔五百世之母迦旦遮羅證阿羅漢","批評釋印順以本生為傳說，應信受奉行"],"k":["七寶塔","孝養父母","本生經","知恩報恩","報恩經","八識"]},"7389-a29_083":{"s":"本集指出《法華經》以佛知見開示悟入，須有真如佛性方是佛知見，非僅二乘菩提；佛法有空性如來藏與空相蘊處界，菩薩不離生死而證涅槃。揭示妙音菩薩即每人身中說法的第八識如來藏，批評安慧將阿賴耶識列入識蘊、慧藏作《破大乘論》，並以「以聲聞形得度者」說明隨機現形。","p":["開示悟入佛知見須有真如佛性","空性如來藏與空相蘊處界同時存在","妙音菩薩即第八識如來藏","批評安慧將阿賴耶識歸入識蘊","菩薩出家是出三界家，發四宏誓願"],"k":["妙音菩薩","如來藏","佛知見","空性與空相","六識論","破邪顯正"]},"7393-a29_084":{"s":"本集說明佛教衰微源於誤以「一切法空」為佛法；《法華經》指出阿羅漢入無餘涅槃仍有本識常住，佛果常樂我淨。辨析空相與空性，強調緣起背後須有如來藏；批評六識論者稱「第七意識、第八意識」，引玄奘「愚者難分識與根」說明意根與意識之別，並將六識論溯源至部派與密宗中觀。","p":["學佛究竟是常樂我淨，非一切法空","無餘涅槃非斷滅空，仍有本識常住","緣起性空背後須有如來藏為根本因","第七、八識非意識細分，駁第八意識說","意根恆時現行，是意識所依"],"k":["一切法空","空性","八識論","六識論","意根","常樂我淨"]},"7383-a29_085":{"s":"本集依「以辟支佛形得度者」說明修因緣觀須先修十因緣，觀「齊識而還，不能過彼」，確認名色由第八識出生，十二因緣的還滅門才能成立。批評以緣起性空為核心、以物質或暗能量為萬法根源之說，引《大緣方便經》講十二因緣逆推順推，並批評帶此世意識「活著往生」之說。","p":["辟支佛須先修十因緣，再修十二因緣","齊識而還：名色由第八識出生","物質不能生心，三界唯心萬法唯識","無如來藏只是緣生法，非真緣起","學佛最大障礙是執意識為常住我"],"k":["十因緣","十二因緣","辟支佛","如來藏","緣起","我見"]},"7398-a29_086":{"s":"本集從舍利弗疑悔永盡、受記為華光佛談「無上法輪」：法義首尾相接無疏漏，即「此經」如來藏，法法相通。說明無上指諸佛境界、無下指阿鼻地獄，批評密宗雙身法自稱「無上瑜伽」實為無下；並主張西藏密宗是喇嘛教而非佛教，八識論才是佛教正法。","p":["舍利弗疑悔盡，受記成華光佛","無上法輪即此經如來藏，法法相通","無上是諸佛境界，無下是阿鼻地獄","批評密宗雙身法妄稱無上瑜伽","證如來藏與經相應才是無上瑜伽"],"k":["無上法輪","如來藏","無上瑜伽","授記","八識論","喇嘛教"]},"7396-a29_087":{"s":"本集進入〈妙音菩薩品〉華德菩薩問妙音菩薩住何三昧、佛答「現一切色身三昧」一段。為說明「一切色身」，先依《大寶積經》「眾生無量故」，從人類、傍生、細菌，到《長阿含經》的三千大千世界一佛剎、《華嚴經》華藏莊嚴世界海（娑婆在第十三層），說明世界與眾生無量無邊。","p":["華德菩薩問三昧，佛答現一切色身三昧","《大寶積經》：眾生無量故諸受無量","一佛剎即三千大千世界，有百億四天下","華藏世界海中，娑婆位於第十三層","十方世界海無量，眾生無量無邊"],"k":["現一切色身三昧","眾生無量","三千大千世界","華藏世界海","世界悉檀","華德菩薩"]},"7387-a29_088":{"s":"本集續說「現一切色身三昧」中「一切色」的範圍：人類男女、二根黃門、年齡膚色差異，傍生與水族形態，三界各道色身粗細大小，乃至共業所變的山河大地與植物。強調父母與飲食只是助緣，同卵雙胞胎亦有差異，色身皆由各自如來藏依業種變現；妙音菩薩證如來藏並多劫修學方能運用此三昧。","p":["人類色身有男女、二根、年齡膚色等差異","父母、飲食只是助緣，色身由如來藏變現","傍生、水族色身依果報而形態萬千","三界各道色身粗細大小各不相同","器世間山河與植物亦為共業所變現"],"k":["現一切色身三昧","如來藏","無量色","器世間","共業","異熟果報"]},"7400-a29_089":{"s":"本集續講〈妙音菩薩品〉現一切色身三昧，並引卷七觀世音菩薩應以何身得度即現何身之經文，說明其中有事有理。再依《大寶積經》「眾生無量故受無量」，說明諸受來自根塵所攝的色法，並以百法中十一色法、色聲香塵的繁複細分為例，指出五塵與法處所攝色皆是自心如來所變現的內相分，勉勵學人求證如來藏。","p":["觀世音現種種身說法，事上神通、理上自心示現","眾生諸受依根塵而有，仍屬一切色範圍","百法五位次第與阿含識緣生說並無矛盾","以色卡、電腦色階說明色塵可無限細分","六塵皆如來藏變現內相分，自心取自心"],"k":["現一切色身三昧","如來藏","五塵","百法明門","內相分","妙音菩薩品"]},"7391-a29_090":{"s":"本集探討眾生與如來藏是一是異，引《大般若經》卷四舍利子問行般若一段，解說「不見有菩薩」「不見行，不見不行」「色自性空，不由空故」及色即是空之義，並以依他起、遍計執、圓成實說明菩薩不滅五蘊而清淨遍計執。批評月稱、宗喀巴誤解空性，最後以《不增不減經》「眾生界即如來藏」回扣妙音菩薩品。","p":["行般若是悟後轉依如來藏的事修","五蘊色受想行識與色識受想行兩種次序","色自性空屬空性心，非滅色而得空","評月稱、宗喀巴把蘊處界空相當空性","眾生界即如來藏，二者非一非異"],"k":["色即是空","大般若經","如來藏","三自性","眾生空","五陰與五蘊"]},"7394-a29_091":{"s":"本集進入〈觀世音菩薩普門品〉「一心稱名，即時觀其音聲，皆得解脫」，說明須聽見自家實際理地的觀世音菩薩。接著介紹觀音傳入中國的歷史：最早見於支曜譯《成具光明定意經》稱明士、安玄《法鏡經》譯闚音，並述迦膩色伽王、馬鳴菩薩與大乘弘傳，駁斥避唐太宗諱改名說及學者稱觀音地位低之說。","p":["稱名得解脫指聽見自性觀世音菩薩","批評六識論者否定如來藏卻供奉觀音","最早漢譯稱觀音為明士、闚音","觀音名非因避李世民諱而省字","觀音弘化四類角色，本為正法明如來"],"k":["觀世音菩薩普門品","觀音由來","譯名","迦膩色伽王","如來藏","大乘非佛說批判"]},"7407-a29_092":{"s":"本集說明觀音在般若法會不發言是尊重法主，並引《無量壽經》說觀音、勢至為阿彌陀佛脅士且曾為釋迦佛弟子，駁斥觀音非真實存在之說。再解說一心稱名須證無觀無所不觀的真如心，四字已是四心；介紹竺法護譯「光世音」，以維摩詰經比對見聞覺知，並舉德光論師因慢心不禮彌勒而求法不得為誡。","p":["觀音不發言是尊重法主、佛教倫理","觀音勢至為西方脅士，真實存在","無生法忍須先證無生忍、真見道","一心稱名非專心唸四字，須證真心","德光論師慢心不禮彌勒，疑問終未解"],"k":["一心稱名","光世音","無生法忍","西方三聖","慢心","善知識"]},"7415-a29_093":{"s":"本集解說導師所說的一行三昧，即法界一相的真如如來藏，指出〈普門品〉以實相般若為基礎，觀音本質無形無相、應緣而現種種身。並從考古與文獻說明觀音信仰早已存在，駁斥觀音晚出、大乘與《法華經》晚出之說，介紹早期犍陀羅、秣菟羅造像中觀音與彌勒形像相同，以及蓮華手、西方三聖像。","p":["一行三昧即法界一相、真如如來藏","普門品以實相般若為基礎","觀音本質無相，隨眾生所需現身","文獻考古顯示觀音、淨土信仰甚早","早期觀音彌勒造像相同皆持水瓶"],"k":["一行三昧","實相般若","普門","觀音造像","大乘非佛說批判"]},"7411-a29_094":{"s":"本集介紹觀音信仰在印度與各地的演變：笈多王朝出現度母、馬頭觀音及密教四系觀音，東南亞、西藏以國王或達賴為觀音化身，講者視之為政治手段；中國則自唐起轉為女相。從如來藏義說一切有情皆可謂觀音化身。再述觀音譯名由闚音、光世音至觀世音、觀自在的演變，及玄奘稱舊譯訛謬，並鋪陳印度宗教史背景。","p":["笈多王朝後出現度母與密教觀音","國王自稱觀音化身屬政治統治手段","如來藏義下一切有情皆可稱觀音化身","闚音、光世音、觀世音皆指如來藏知一切","玄奘主觀自在，涉及梵語與印度宗教史"],"k":["觀音譯名","觀自在","密教觀音","如來藏","印度宗教史"]},"7401-a29_095":{"s":"本集解說〈普門品〉「臨當被害，刀杖段段壞」，導師開示應自害五陰、他害不如自害。引《大寶積經》〈神通證說品〉「勿得害我」「我必被害，為善被害」，辨明前者為不可違逆的真我如來藏，後者為五陰妄我。再以趙州「只為老僧好殺」、圜悟「護生須殺，雖殺無傷」說明殺我見是善害，禪師殺人刀背後即是活人劍。","p":["害死五陰我見，法身慧命才能活轉","勿得害我指如來藏，為善被害指五陰","世間殺人、自殺皆是殺不盡的惡害","二乘殺盡色身，菩薩殺我見留身修道","殺人刀背後是活人劍，擊大法鼓"],"k":["殺人刀活人劍","我見","五陰","大寶積經","善害","禪宗"]},"7405-a29_096":{"s":"本集以「內心起時，彼已害我」說明證見自身第八識觀世音菩薩即能否定五蘊我，故參禪是天下第一大善事，其證悟種子世世相隨。引圜悟「蠟人已冰，其功歷爾」，說禪宗頓超、擒賊先擒王、不斷煩惱證菩提，是實相般若之門與教外別傳；並批評學術界以緣起性空解般若，強調善知識是大因緣。","p":["內心起時即證見第八識觀世音","參禪證悟是三界最大的善事","禪宗單刀直入，擒賊先擒王","禪宗是實相般若之門、教外別傳","緣起性空只是意識概念，非法界實相"],"k":["參禪","明心","教外別傳","實相般若","善知識","如來藏"]},"7409-a29_097":{"s":"本集闡釋「不應造逆，勿得害我」之我即如來藏，信受大乘非佛說者法身慧命已死於非命。以永嘉《證道歌》「宗亦通、說亦通」及達摩付《楞伽》、五祖講《金剛經》印心，駁宗門與教下無關之說。並述大乘非佛說源自部派、日本學界與釋印順，指出否定第八識即否定三寶，六識論者亦無法實證解脫。","p":["勿得害我之我是如來藏，不可違逆","宗教俱通：宗門所悟即經教所說之心","大乘非佛說源自部派、日本及釋印順","三歸依一體，否定第八識即否定三寶","六識論者不肯否定意識，難斷我見"],"k":["如來藏","宗教俱通","大乘非佛說批判","三歸依","六識論"]},"7420-a29_098":{"s":"本集講轉依第八識的如如法性，解說〈普門品〉「若有罪、若無罪，杻械枷鎖檢繫其身」：有罪指欲界、無罪指色界，杻械為貪、枷鎖為瞋，稱觀世音名即轉依真如而解脫。引達摩三毒六賊、六祖無相懺悔偈說明實相懺悔，並解說怨賊為惡見之怨家與貪瞋癡慢疑之法賊，批評六識論學者與密宗喇嘛教。","p":["不可違逆如來藏的真實性與如如性","有罪指欲界、無罪指色界有情","杻械是貪、枷鎖是瞋，轉依真如即解脫","實相懺悔：向心中除罪緣","怨家是惡見五利使，法賊是貪瞋癡慢疑"],"k":["轉依","真如法性","實相懺悔","怨賊","五利使","普門品"]},"7413-a29_099":{"s":"本集解說〈普門品〉「三千大千國土滿中怨賊，商主將諸商人齎持重寶經過嶮路」：三千大千喻欲界人間，商主是意根，諸商人是前六識。重寶為五遍行、五別境、十一善心所與六無為法。逐一講解五遍行（並及見性）、五別境唯意識具足，以及信、慚、愧、無貪、無瞋、無癡、精進、輕安等善法。","p":["欲界人間怨賊最多，成佛路充滿嶮路","商主是作主的意根，非第八識","重寶：遍行、別境、善十一、六無為","修行須靠意識正知見引導意根","信為道源，輕安代表未到地定"],"k":["齎持重寶","心所法","意根","善十一","五遍行","普門品"]},"7403-a29_100":{"s":"本集續講善心所的不放逸、行捨、不害，以及六無為法，指出真如無為是見道第一關與未來關卡的金鑰匙。引《瓔珞經》舍利弗等悟後退轉之例強調善知識的攝受。並將修道險路分為瓶頸（如不肯布施、受戒）、岔路（錯悟大師所說）、危途（密宗）及學術研究，批評退轉者與釋印順依文解義。","p":["不放逸、行捨、不害三種善法重寶","真如無為是見道關卡的金鑰匙","悟後無善知識攝受易退轉","嶮路分瓶頸、岔路、危途","學術研究依文解義，無法實證"],"k":["嶮路","六無為","真如無為","善知識","退轉","布施"]},"7427-a29_101":{"s":"本集以《西遊記》比喻八識：意根為商主沙悟淨、意識為孫悟空、前五識為豬八戒、第八識為唐僧、五色根為龍馬，說明「其中一人作是唱言」是意識依正知見呼籲歸命觀世音。遇貪瞋怨賊時轉依無貪無瞋的如來藏即得解脫，入地後怨賊為習氣與塵沙惑；「俱發聲言」表八識和合，並強調要知恩才有交情。","p":["滿中怨賊指根本煩惱與隨煩惱","西遊記喻八識，意根作主依意識分別","唱言者是意識，呼籲歸命觀世音","遇貪瞋嶮路，轉依如來藏即解脫","知恩才有交情，親證是見道關卡"],"k":["一心歸命","八識","意根","怨賊","轉依","普門品"]},"7434-a29_102":{"s":"本集說證悟者應知恩感恩自家觀世音，批評退轉者另求第九識真如無為之誤。引並語譯「多於婬欲，常念恭敬便得離欲」、離瞋、離癡、求男求女及受持名號一段，說明理上一切有情皆有觀世音，事上觀音為正法明如來示現。並舉信眾漸離欲瞋、禪師「方外之交」接引、夢中指引與擲筊等事例。","p":["知恩不否定自家觀音，感恩則廣為人說","真如無為是第八識所顯法性，不離心體","理上一切有情皆有觀世音菩薩","事上觀音為正法明如來倒駕慈航","禪師方外之交與夢中指引等事例"],"k":["常念恭敬","離三毒","事理雙具","真如無為","觀世音信仰"]},"7421-a29_103":{"s":"本集強調十信具足是學佛首要，引《大寶積經》讚信之偈，並說不可以出家相判斷善知識（維摩詰、善財五十三參），引《證契大乘經》說持如來藏者為大導師，謗法者具根本、方便、成已三罪。事上舉求子事例及導師自述破參經過；理上解說觀世音觀五陰心聲、不捨眾生、從不生氣，故為摩訶薩。","p":["信為道元功德母，十信具足最重要","勿以出家與否判斷善知識","謗法具根本、方便、成已三罪","導師自述得菩薩指點而明心見性","理上觀世音觀心聲、不捨眾生為摩訶薩"],"k":["十信","觀世音菩薩摩訶薩","善知識","謗法","明心見性"]},"7423-a29_104":{"s":"本集從理上解說「多於婬欲，常念恭敬觀世音便得離欲」：自身觀世音無始離欲，轉依後可漸離欲乃至發初禪。借《華嚴經·入法界品》婆須蜜多菩薩說明：其「離欲實際清淨法門」中的「我」指如來藏；並解說若天見我我為天女、離欲得無著境界三昧、見我得歡喜三昧、與語得無礙妙音三昧，以禪師應答為例。","p":["自身觀世音無始離欲，轉依漸離欲","婆須蜜多以如幻智入方便門度眾","經中處處說的「我」指第八識如來藏","離欲得無著境界三昧，見我得歡喜三昧","與語得無礙妙音三昧，如禪師隨手拈答"],"k":["婆須蜜多","離欲","如來藏","華嚴經","三昧"]},"7431-a29_105":{"s":"本集續講婆須蜜多其餘方便門：執手得詣一切佛剎三昧、共宿得行解脫光明三昧、目視得寂靜諸行三昧、顰申得壞散外道三昧、觀察得一切佛境界光明三昧、擁抱得攝一切眾生三昧、親吻得諸功德密藏三昧，並舉雲門、趙州、雪峰古鏡公案說明。總結證知自己觀世音即離欲，常心念可離三毒；並開始從理上解釋求男。","p":["每種方便皆令人見到如來藏這個我","攝一切眾生三昧：知一切有情皆此我","諸功德密藏三昧，舉雪峰古鏡等公案","轉依本離三毒的觀世音，事修亦離三毒","理上的好男兒是雙具福德智慧的菩薩"],"k":["婆須蜜多","三昧","禪宗公案","離三毒","如來藏"]},"7438-a29_0106":{"s":"本集解說「福德智慧之男」與「端正有相之女」的理上意義：新學菩薩福慧不足，須修六度至六住滿心、證第八識入七住，才是第一層次的福德智慧之男，女眾亦然。端正有相之女指持戒端正、五蘊用以修道與心性調柔，引《華嚴·十地品》鍊金喻。並說悟前應禮拜供養觀音、福有事福理福，且須隱覆密意說法。","p":["新學菩薩福慧不足，不算好男兒","六度圓滿證第八識入七住為福德智慧之男","所依第八識有大丈夫相，女眾亦是","端正有相之女即持戒端正、心性調柔","福有事福與理福，須依正確法義"],"k":["福德智慧之男","端正有相之女","六度","七住位","心性調柔","福不唐捐"]},"7436-a29_107":{"s":"本集解說經文：受持六十二億恒河沙菩薩名字並盡形供養，與受持觀世音名號一時禮拜供養，二人福等無異。指出從表相難以理解，真實義是實證自身第八識如來藏，即禪宗開悟，所得為世出世間福德，故無量無邊。並說入火不燒、家家阿彌陀戶戶觀世音皆須從實際理地理解，最後邀請參加正覺共修。","p":["語譯六十二億恒河沙菩薩供養之喻","表相上難說二人福德相等","受持觀世音即實證第八識如來藏","火不能燒指第八識體性如金剛","所得世出世間福德無量無邊"],"k":["受持名號","如來藏","福德","實際理地","開悟","普門品"]},"7429-a29_108":{"s":"本集講無盡意問觀音如何遊娑婆說法，引三十二應身經文，以《維摩詰經》「佛以一音演說法」說明根器不同而理解各異，並批評只靠觀音本尊示現化身的理解與一神教無異。理上舉兩例：應以佛身得度者，其第八識為其示現佛身說法，以釋迦降魔、明星見性為證；辟支佛身亦然，並以胎兒由第八識出生說明。","p":["佛以一音演說法，眾生隨根器得解","只依賴觀音化身度化，類似一神教","應以佛身得度：第八識示現佛身說法","釋迦見明星眼見佛性，成所作智現前","胎兒由自身第八識出生，非母親所造"],"k":["三十二應身","如來藏","事理雙具","眼見佛性","辟支佛","普門品"]},"7441-a29_109":{"s":"本集續講〈觀世音菩薩普門品〉「應以聲聞身、梵王身、帝釋身……乃至執金剛身得度者，即現之而為說法」等經文，從理上說明是各人第八識「觀世音菩薩摩訶薩」依其願與業變生相應色身並不斷說法；並引《長阿含經》愚比丘問大梵天王的記載，說明大梵天王並非造物主。","p":["聲聞身得度：第八識為其示現聲聞身並說法","因內有恐怖、因外有恐怖：須信有內識方能斷我見","大梵天王三次答非所問，於佛前承認未造世界","真正造物主是各有情自己的第八識","天大將軍、毘沙門、小王乃至執金剛身皆由第八識變現"],"k":["普門品","第八識","應身說法","造物主","聲聞身","執金剛神"]},"7439-a29_0110":{"s":"本集說明經中所舉觀世音化身只從初禪天下至人間，因二禪以上住等至位、無色界無形色、三惡道受苦無心聞法，故不說為其說法；接著講解無盡意菩薩以寶珠瓔珞供養，觀世音分作二分奉釋迦牟尼佛與多寶佛塔的經文，先作事相解說，並留下「自在神力」之問待下集。","p":["化身範圍只從初禪天到人間的原因","二禪以上禪悅一念不生，無色界無形色可示現","三惡道苦逼或無智，雖有觀世音說法而聽不見","無盡意先稟白佛陀再供養瓔珞，並為大眾請受","瓔珞分奉釋迦牟尼佛與多寶佛塔，世尊讚自在神力"],"k":["普門品","三十二應身","施無畏","無盡意菩薩","瓔珞供養","多寶佛塔"]},"7452-a29_0111":{"s":"本集講「應當一心供養觀世音菩薩摩訶薩」，先釋慈為與樂、悲為拔苦，以悲為體、以慈為用；再從理上說自性觀世音以種種形為初禪以下至人間有情說法；並分別說明禪師、法師、論師、戒師、居士、師父、徒弟及未來法主各應如何作法供養。","p":["慈與樂、悲拔苦，以悲為體以慈為用","如來藏普為初禪以下有情及有福鬼神說法","禪師以「南無觀世音菩薩」答問，如禾山解打鼓","批評以聲聞戒為正解脫戒，正覺傳戒歸依大乘三寶","居士送書、徒弟學神贊、法主須廣開福田"],"k":["法供養","觀世音菩薩","如來藏","慈悲","禪宗公案","菩薩戒"]},"7425-a29_112":{"s":"本集從理上解釋觀世音何以稱施無畏，並釋無盡意為「歸命之意無盡」；說明自性觀世音寸絲不掛而不受瓔珞，經佛勸請後分奉「能仁寂靜」第八識與五蘊身多寶佛塔，於不受中成就法供養；後講重頌「汝聽觀音行……能滅諸有苦」，兼述正法明如來倒駕慈航。","p":["怖畏急難中依自家觀世音得以脫離","諸佛皆依自己第八識成佛，故歸命無盡","實際理地寸絲不掛，故觀世音不肯受供","釋迦牟尼喻第八識，多寶佛塔喻五蘊身","聞名見身結緣，終能證悟或往生滅諸有苦"],"k":["施無畏","無盡意菩薩","法供養","多寶佛塔","如來藏","正法明如來"]},"7449-a29_0113":{"s":"本集依事相講解重頌中火坑、巨海、須彌峰、怨賊、王難、枷鎖、毒藥、惡獸等諸難得解脫的經文，舉玄奘遇盜、《高王觀世音經》為例；隨後進入「觀音法門與外道聽音法門的差異」，說明觀音法門是聞思修入三摩地，並批評清海聽聲音法門屬聲論外道。","p":["念觀音力可避火坑、海難、推墮、怨賊等諸難","玄奘遇盜，盜賊歸還財物並受三歸","惡獸之難若有往世因果，菩薩不干預","觀音法門是聞思修證佛菩提，非修定或聽聲","入流亡所、所入既寂、聞所聞盡、覺所覺空"],"k":["觀音法門","聞思修","入流亡所","普門品偈頌","聽音法門","三摩地"]},"7459-a29_114":{"s":"本集比較外道無所有處定、非想非非想定與觀音法門的「覺所覺空」，說明觀音法門是保留覺知心、離五浮塵根而與如來藏妙真如性相應，終至寂滅現前、超越世出世間、獲二種殊勝；並從理上講先聞熏正確般若、思惟成相似般若，再參究證如來藏而入般若三摩地。","p":["非想非非想定仍有能覺所覺，非真二覺空","觀音法門離五浮塵根而與妙真如性相應","寂滅現前、超越世出世間、獲二種殊勝","先理上入流亡所斷我見，再事修觀音法門","需先明心、眼見佛性，否則盲修瞎練"],"k":["觀音法門","聞思修","如來藏","非想非非想定","入流亡所","般若三昧"]},"7455-a29_115":{"s":"本集講重頌「真觀清淨觀……是故應頂禮」，說明真觀是觀真實常住法而非緣起性空觀，並釋清淨觀、廣大智慧觀、悲觀慈觀；講解三災三劫、悲體戒雷、甘露法雨、諍訟與軍陣之難，舉道信、弘忍退賊為例；最後指出此段前讚「觀」、後讚「音」，為普門品事說的總結。","p":["真觀觀真實常住法，非緣起性空的如幻觀","清淨觀：五蘊附屬清淨如來藏","風火之災泛指壞劫火水風三劫","道信吉州、弘忍蘄州皆有賊兵退散的記載","妙音菩薩與觀世音菩薩同是一類如來藏"],"k":["普門品偈頌","真觀","清淨觀","悲體戒雷","妙音觀世音","感應"]},"7447-a29_116":{"s":"本集開始從理上解釋普門品重頌，先講「聞名及見身，心念不空過，能滅諸有苦」：聞名即聽聞自身有如來藏，引「現前立少物」說明建立正見，見身即實證；再講前六句的理說；並將「推落大火坑」解為密宗樂空雙運的邪見火坑，以及二乘的涅槃貪。","p":["聞名即聽聞自性觀世音即如來藏","現前立少物：先建立有真如的正知見","見身即實證，從理上滅三有諸苦","密宗樂空雙運被視為推人落入的大火坑","對菩薩而言，二乘涅槃貪才是最大火坑"],"k":["理說","如來藏","心念不空過","火坑之難","樂空雙運","涅槃貪"]},"7467-a29_117":{"s":"本集理說「漂流巨海，龍魚諸鬼難」與「須彌峰為人所推墮」：巨海喻自性大海，落於五陰自性者即自性見外道，練禪功、執幻境皆屬龍魚鬼難；須彌峰喻證真如的境界，無明惡人令人疑真如太易證而頭上安頭；念自己的觀世音菩薩即能如日虛空住。","p":["不承認第八識者皆漂流於自性見大海","禪功、打通任督二脈、幻覺被視為龍魚鬼難","須彌峰喻證真如，全球證者極稀有","無明惡人令人疑真如太平凡而另求真如","比對如來藏常住真如，即能如日虛空住"],"k":["理說","自性見外道","證真如","退轉","無明","如來藏"]},"7451-a29_0118":{"s":"本集理說「惡人逐墮金剛山」、「怨賊繞」與「王難苦」：惡人指愛樂追逐境界，七金山喻七轉識境界，應令境界為我所用；怨賊指由宿命通、天眼通所生的六十二種邪見；王難指佛教界大山頭與密宗法王對正法的抵制，念自己的觀世音菩薩即能化解。","p":["惡人是心中愛樂追逐六塵境界","七金山喻七轉識境界，不被牽走即不墮落","娑婆持戒一日勝極樂修行百年，不必遠離五欲","怨賊即六十二見，歸結於如來藏所生即降伏","王難指大山頭與法王抵制及師父否定如來藏"],"k":["理說","六十二見","七轉識","王難","如來藏","法身慧命"]},"7461-a29_0119":{"s":"本集理說枷鎖杻械、咒詛毒藥、惡羅剎毒龍諸鬼等句：枷鎖喻一念無明與無始無明，咒詛喻相似像法，毒藥喻「大乘非佛說」等邪見，羅剎、毒龍、諸鬼喻貪瞋、執聲聞涅槃與邪見；最後依《大唐西域記》敘述清辨論師欲與護法辯論、求觀自在菩薩及入阿修羅宮的故事。","p":["枷鎖杻械喻無明及空有二邊的繫縛","相似像法生則正法滅，舉各山頭說法為例","色法不能生心，以此破無因唯緣論","惡羅剎、毒龍、諸鬼各喻修道中的煩惱邪見","清辨誦咒三年得觀自在指示，入阿修羅宮"],"k":["相似像法","理說","邪見","清辨論師","觀自在菩薩","無明"]},"7457-a29_120":{"s":"本集分析清辨論師的故事，指其錯過護法菩薩、不向觀世音請法只求保留色身，顯示慢心、身見未斷且修行繞遠路，不足以承繼龍樹中觀；接著理說惡獸、蚖蛇蝮蠍、雲雷降雹等句，分喻五欲、嫉妒毒害心與末法邪說，並開始引達賴喇嘛著作加以批評。","p":["清辨與摩訶迦葉等待彌勒的性質不同","不肯拜見護法菩薩，被評為慢過慢","只求保身待彌勒，被評為身見具足","惡獸喻五欲；在家人不行出家法，出家人不行在家法","雲雷降雹喻末法邪說，引達賴書批評雙身法"],"k":["清辨論師","護法菩薩","身見","五欲","雙身法","末法邪說"]},"7469-a29_121":{"s":"本集逐段辨正達賴喇嘛《西藏佛教的修行道》中以貪欲、精液與明妃交合結合空性的說法，指其為有相有為的想像法並違背苦聖諦；接著理說「觀音妙智力」的自受用與他受用、如來藏「具足神通力」與「無剎不現身」，並說惡趣源於異生性。","p":["空性指如來藏體性，非雙修所得之樂","拙火、氣脈屬有為法，與無相空性心相違","藏密樂空之說被指違背苦聖諦與欲為不淨","觀音妙智力：證如來藏可自利亦可救人","如來藏依業變現各道之身，即具足神通力"],"k":["雙身法","空性","如來藏","觀音妙智力","神通","異生性"]},"7473-a29_122":{"s":"本集說明二乘與大乘應斷異生性的廣狹，悟後仍可能遇惡緣退轉，須依如來藏漸修滅除；再理說真觀清淨觀、無垢清淨光、悲體戒雷、諍訟經官等偈，並引《雜寶藏經》離越阿羅漢因往世誣謗辟支佛而受誣入獄十二年的故事，說明因果記錄於如來藏。","p":["大乘異生性至初地入地心方斷盡","假觀、真觀、清淨觀至悲觀慈觀的次第","災火喻欲界貪愛，災風喻心中躁動","悲體戒雷震：道共戒震壞不善念","離越阿羅漢因往世誣謗辟支佛而受報"],"k":["異生性","真觀","道共戒","因果","離越阿羅漢","如來藏"]},"7463-a29_123":{"s":"本集講「妙音觀世音，梵音海潮音」與「念念勿生疑……能為作依怙」，說明如來藏運作恆發清淨、不間斷的法音，應常念以增長轉依；分析生疑源於慧力、定力、福德不足或慢心，強調五停心觀、無相念佛與未到地定能使悟後證轉不退；並說如來藏為苦惱死厄中的依怙。","p":["妙音、梵音即清淨音，海潮音喻恆常法音","生疑因慧力、定力、福德不足或有慢心","證轉：證悟後須能現觀運轉才有受用","無相念佛與未到地定可降伏欲界惑而不退","如來藏無三毒，為生死舟航與依怙"],"k":["如來藏","海潮音","無相念佛","證轉","未到地定","依怙"]},"7480-a29_0124":{"s":"本集講「具一切功德，慈眼視眾生，福聚海無量，是故應頂禮」，說明如來藏生一切身、收藏一切福德；再釋持地菩薩總結與八萬四千眾發無上心，以如來藏如大地持一切；並回顧常不輕、藥王、妙音等諸菩薩品，指出各品法義皆依如來藏相通，並批評印順「佛偶然出現」之說。","p":["如來藏具一切功德，涅槃亦由祂而有","慈眼視眾生、福聚海無量，故應頂禮","持地菩薩出場：如來藏猶如大地持一切","諸菩薩品橫跨久遠時空，批評佛偶然出現說","見釋迦牟尼與多寶如來，喻第一義法智與類智"],"k":["如來藏","持地菩薩","福德","法智類智","妙音菩薩","一佛乘"]},"7477-a29_0125":{"s":"本集總結普門品後的感觸：善知識難遇、佛法須三大阿僧祇劫修證；進入〈陀羅尼品〉，講藥王菩薩問受持法華經之福德及佛答受持一四句偈功德甚多，藥王說咒護持說法者；並引《雜阿含經》說明法師的定義在說法內容而非外相，兼述誦咒宜專持一咒。","p":["善財言善知識出世難、值遇難、得其意難","批評視佛法僅為四聖諦而斥如來藏者","藥王菩薩說咒，護持演說法華經的法師","佛說法師：說五陰生厭離欲滅盡寂靜者","每咒各有部族護持，誦咒專持一種即可"],"k":["陀羅尼品","藥王菩薩","法師定義","善知識","陀羅尼","如來藏"]},"7471-a29_126":{"s":"本集續講〈陀羅尼品〉，說明誦藥王咒可得其部族護持；解釋讀誦通利與不用筆墨的真書寫，藥王故意請問以取得佛陀認可；比較布施各類對象的福德，指出受持一四句偈而讀誦解義、如說修行，功德勝過供養無數諸佛；並說此咒為六十二億恆河沙諸佛所說，含佛法僧三寶。","p":["誦藥王咒可與其部族相應而得護持","通利指如實理解密意，真書寫不用筆墨","布施對象不同，所得福德倍數不同","受持一四句偈並如說修行，勝供養無數佛","咒含佛馱、達磨、僧伽，侵毀法師即侵毀諸佛"],"k":["陀羅尼品","四句偈","受持","福德","藥王菩薩","陀羅尼"]},"7483-a29_0127":{"s":"本集講〈陀羅尼品〉中勇施菩薩、毘沙門天王、持國天王、十羅剎女與鬼子母相繼說咒，擁護演說及受持法華經者；說明護持說法者之咒多由諸佛所說，鼓勵受持並弘傳；並說明鬼子母已證初果、十羅剎女皆為證果的佛弟子，及其偈中對惱亂法師者的警示。","p":["法華經、金剛經、此經同指第八識如來藏","勇施咒為恆河沙諸佛所說，亦護受持一偈者","毘沙門天王護持經者百由旬內無衰患","說法者之咒多由諸佛說，鼓勵受持並弘傳","十羅剎女與鬼子母說咒，鬼子母已證初果"],"k":["陀羅尼品","陀羅尼","護法","羅剎女","鬼子母","法師"]}};
